const CORPUS_PAIRS = [
  { k:'seg_1_决赛_1', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'China plans to abolish all ownership limits for foreign firms in its financial sector by 2020, a year earlier than previously stated.', mt:'中国计划在 2020 年之前取消对外国公司在其金融领域的所有权限制，比之前声明的提前一年。', ref:'中国将在 2020 年全面取消金融业外资股比限制， 比原计划提前一年。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_2', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'The country is expected to further open its manufacturing sector, including the auto industry.', mt:'预计中国将进一步开放制造业，包括汽车业。', ref:'中国有望深化在制造业领域的开放举措，其中包括汽车行业。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_3', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Additionally, it will reduce its negative investment list that restricts foreign investment in some areas.', mt:'此外，它还将减少在某些领域限制外商投资的负面投资清单。', ref:'此外，还将缩减旨在限制外商投资领域的负面清单。', tags:["准确性"] },
  { k:'seg_1_决赛_4', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'This move comes after the Presidents of both China and the United States recently decided to resume trade negotiations, in an effort to sign a deal.', mt:'在此之前，中美两国主席最近都决定恢复贸易谈判，以期签署一项协议。', ref:'中美两国元首于近期决定重启中美贸易谈判，以努力达成贸易协议，这一举措随之而来。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_5', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'The U.S.-China trade war- related tensions have been having an adverse impact on the economies of both countries for the past few months.', mt:'过去几个月，美中贸易战相关紧张局势对两国经济都产生了不利影响。', ref:'过去几个月来，中美贸易战引发的紧张局势对两国的经济产生了不利影响。', tags:["准确性"] },
  { k:'seg_1_决赛_6', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'In order to prop up growth internally, China has been taking some measures, of late.', mt:'为了在国内支撑增长，中国最近已经采取了一些措施。', ref:'近来，中国已采取了一系列措施促进国内经济增长。', tags:["准确性"] },
  { k:'seg_1_决赛_7', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'To aid credit growth (which has remained soft over the past few quarters) within the country, the People\'s Bank of China has already reduced the amount of cash that banks need to hold as reserve, six times since early 2018.', mt:'为了帮助国内信贷增长(过去几个季度信贷增长一直保持疲软)，中国人民银行(PBoC)已经降低了银行需要作为准备金的现金量，这是自 2018 年初以来的 6 次。', ref:'自 2018 年初以来，中国人民银行已经六次减少金融机构存款准备金，以刺激国内信贷（在过去几个季度里持续疲软）。', tags:["语言规范","准确性","风格"] },
  { k:'seg_1_决赛_8', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Moreover, additional reductions in banks\' reserve requirement ratios are likely to take place in the coming months.', mt:'此外，未来几个月可能会进一步下调银行存款准备金率。', ref:'另外，银行存款准备金率有望在未来几个月中再次迎来下调。', tags:["准确性"] },
  { k:'seg_1_决赛_9', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'While these efforts have helped its financial markets to grow, China has not been able to achieve significant economic growth as of now.', mt:'虽然这些努力帮助了其金融市场的增长，但到目前为止，中国还没有能够实现显著的经济增长。', ref:'尽管这些努力有助于国内金融市场的增长，到目前为止，中国仍未能实现经济的大幅增长。', tags:["准确性"] },
  { k:'seg_1_决赛_10', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'For a long time, companies in the United States and other countries have been complaining that Beijing has been blocking foreign access to its fast-growing financial markets.', mt:'很长一段时间以来，美国和其他国家的公司一直在抱怨北京一直在阻止外国投资者进入其快速增长的金融市场。', ref:'长期以来，美国和其他国家的公司都在抱怨北京当局阻止外资进入其飞速发展的金融市场。', tags:["准确性"] },
  { k:'seg_1_决赛_11', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Due to the restrictions imposed on ownership, global investment banks’ expansion has been limited in China for the past few years.', mt:'由于对所有权的限制，过去几年来， 全球投资银行在中国的扩张受到了限制。', ref:'由于针对外资股比的限制，过去数年里，全球投资银行在华扩张受阻。', tags:["准确性"] },
  { k:'seg_1_决赛_12', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'However, under the liberalized rules announced in 2017, China eased restrictions in its financial markets, allowing greater foreign participation.', mt:'然而，根据 2017 年公布的自由化规则，中国放松了对金融市场的限制， 允许更多的外国参与。', ref:'但是，自 2017 年宣布金融业自由化规则后，中国放宽了对国内金融市场的投资限制，允许更多的境外资金参与进来。', tags:["准确性"] },
  { k:'seg_1_决赛_13', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Indicating its readiness to allow greater access to global banks into the country’s financial markets, the China securities regulator allowed foreign companies to increase their stake to 51% in securities joint ventures, up from 49%.', mt:'中国证券监管机构允许外国公司将其在证券合资企业中的股份从 49% 增加到 51%，这表明它准备允许全球银行更多地进入中国的金融市场。', ref:'中国证监会允许外资公司在境内证券合资公司的股权持有比例上限从 49% 提高至 51%，表明其已准备好让全球的银行进一步投资国内金融市场。', tags:["准确性"] },
  { k:'seg_1_决赛_14', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'In response to this, many foreign investment firms have either set up new businesses onshore or expanded their presence through majority ownership in domestic joint ventures.', mt:'对此，许多外国投资公司要么在国内设立新的业务，要么通过在国内合资企业的多数股权扩大业务。', ref:'面对这种形势，多家外国投资公司或在中国境内设立新公司，或通过获得境内合资公司的多数股权实现扩张。', tags:["准确性"] },
  { k:'seg_1_决赛_15', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Notably, JPMorgan JPM and Nomura Holdings Inc.', mt:'值得注意的是，摩根大通(JPMorgan JPM)和野村控股(Nomura Holdings)。', ref:'值得注意的是，摩根大通 (JPM) 和野村控股 (NMR)', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_16', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'NMR have already received regulatory nod for setting up brokerage joint ventures in China, while Citigroup C is planning to establish a majority-owned securities joint venture.', mt:'NMR 已获得监管部门的批准，在中国设立经纪合资企业，而花旗集团 C(Citigroup C)正计划成立一家多数股权的证券合资企业。', ref:'已经得到了监管当局对其在华设立合资券商的批准，而花旗集团 (C) 正在计划组建由其拥有多数股权的证券合资公司。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_17', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Last December, UBS Group AG UBS became the first foreign bank to receive the regulator’s consent, since the rules on foreign investment in brokerages were announced in 2017.', mt:'去年 12 月，瑞银集团(UBS Group AG) 成为首家获得监管机构同意的外资银行，这是自 2017 年出台有关外资投资券商的规定以来。', ref:'去年十二月，瑞银集团 (UBS) 成为了自 2017 年中国宣布外商投资券商的政策以来首家获得证监会批准的外资银行。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_18', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Furthermore, Morgan Stanley MS, which has two joint ventures in China — Morgan Stanley Huaxin Fund Management Co and a securities joint venture with Huaxin Securities — seeks to acquire majority ownership of one of these.', mt:'此外，摩根士丹利在中国有两家合资企业-摩根士丹利华新基金管理有限公司 (Morgan Stanley Huaxin Fund Management Co) 和与华新证券 (Huaxin Securities)成立的一家证券合资企业-寻求收购其中一家的多数股权。', ref:'此外，摩根士丹利 (MS) 在华有两家合资公司，即， 摩根士丹利华鑫基金管理有限公司和与华鑫证券合资的证券公司。摩根士丹利也在寻求获得其中一家合资公司的多数股权。', tags:["准确性","术语"] },
  { k:'seg_1_决赛_19', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Recently, the Chinese partner of Morgan Stanley’s securities joint venture said that it is ready to sell 2% stake and Morgan Stanley has until July 29 to submit a bid.', mt:'最近，摩根士丹利证券合资公司的中国合作伙伴表示，准备出售 2%的股份，摩根士丹利必须在 7 月 29 日之前提交报价。', ref:'最近，摩根士丹利的证券合资公司的中方合伙人表示已经准备出售 2% 的股权，而摩根士丹利需要在 7 月 29 日之前提交报价。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_20', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Thus, once foreign banks are allowed to conduct business in China without any restrictions, it will help these banks in expanding geographically, which will boost revenues.', mt:'因此，一旦允许外资银行在中国不受任何限制地开展业务，这将有助于这些银行在地理上进行扩张，这将增加收入。', ref:'因此，一旦外资银行获准在中国不受限制地开展业务，将有助于这些银行实现地域扩张，从而推动收入增长。', tags:["准确性"] },
  { k:'seg_1_决赛_21', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Moreover, the current global operating backdrop looks challenging.', mt:'此外，当前的全球运营背景看起来具有挑战性。', ref:'加之，当前的全球营商环境充满挑战。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_22', ed:'1', stage:'决赛', dir:'英译汉', eng:'腾讯翻译君', src:'Once foreign firms establish and expand businesses in China, it is likely to further support their financials.', mt:'一旦外国公司在中国建立和扩大业务，很可能会进一步支持他们的财务状况。', ref:'当外资企业建立和扩大在华业务时，其财务状况很有可能得到进一步改善。', tags:["准确性"] },
  { k:'seg_1_决赛_23', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'Dubai ruler\'s wife, Princess Haya, goes into hiding in UK and hires divorce lawyer', mt:'迪拜统治者的妻子哈亚公主躲在英国，聘请离婚律师', ref:'迪拜王妃哈雅公主藏身英国，与迪拜酋长离婚官司即将上演', tags:["准确性"] },
  { k:'seg_1_决赛_24', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'Princess Haya, always considered a free spirit in the world of Middle Eastern royalty, where protocol and obscurity are expected of women, has fled her husband, the ruler of Dubai, and reportedly gone into hiding in England.', mt:'哈亚公主一直被认为是中东皇室世界的自由精神，在这里，礼仪和默默无闻是妇女的责任，她逃离了她的丈夫，迪拜的统治者，并据报道躲在英国。', ref:'在认为女性应该循规蹈矩且默默无闻的中东王室中，哈雅公主一直被视为自由精神的象征。哈雅公主已从其丈夫迪拜酋长身边逃离，而且据报道称， 藏身于英国。', tags:["准确性","风格","语言规范"] },
  { k:'seg_1_决赛_25', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'She also has hired a divorce lawyer who has worked for the British royal family, according to Business Insider.', mt:'据 Business Insider 报道，她还聘请了一位曾为英国皇室工作的离婚律师。', ref:'据 Business Insider 报道，哈雅公主还雇用了曾为英国皇室效力的离婚律师。', tags:["准确性"] },
  { k:'seg_1_决赛_26', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The decision to leave her husband and Dubai arose from disturbing details the princess reportedly learned concerning one of the sheik’s daughters, who herself tried to flee Dubai last year.', mt:'离开她的丈夫和迪拜的决定是因为据报道公主获悉了关于酋长的一个女儿的令人不安的细节，她本人去年试图逃离迪拜。', ref:'据报道，去年酋长的一个女儿曾爆出逃离迪拜的事件，哈雅王妃正是得知这一事件后才最终决定离开她的丈夫。', tags:["准确性"] },
  { k:'seg_1_决赛_27', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The daughter, Sheikha Latifa, appeared in a 40-minute video saying she had been imprisoned on and off for several years and had been abused.', mt:'女儿 Sheikha Latifa 出现在一段 40 分钟的视频中，说她断断续续地被监禁了几年，并受到虐待。', ref:'拉蒂法公主是迪拜酋长的女儿之一，她在一段 40 分钟的视频中称自己多年来断断续续遭到监禁，并且受到虐待。', tags:["准确性"] },
  { k:'seg_1_决赛_28', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'Her friends say she was forcibly returned after commandos stormed a boat carrying her off the coast of India when she tried to flee the Emirates.', mt:'她的朋友说，突击队员在她试图逃离阿联酋时袭击了一艘载着她离开印度海岸的船只，随后她被强行遣返。', ref:'她的朋友称，拉蒂法公主试图从阿联酋出逃，但其乘坐的游艇在印度海岸附近被突击队拦截，随后公主被强行带回迪拜。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_29', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'Princess Haya’s escape was brought to light, ironically, by her husband, a poet who penned a few lines to lash out at his wayward bride – one of six and the most high-profile.', mt:'具有讽刺意味的是，哈亚公爵小姐的逃跑被她的丈夫揭露了，她的丈夫是一位诗人，他写了几行诗猛烈抨击他任性的新娘——这是六个新娘中最引人注目的一个。', ref:'颇有讽刺意味的是，哈雅公主的此番逃离是由其丈夫公诸于世的。酋长为此还写诗公开谴责他这位任性的妻子，也是他六位妻子中最引人关注的一位。', tags:["准确性"] },
  { k:'seg_1_决赛_30', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The poem, titled “You Lived and You Died” and posted by the Dubai ruler\'s son, is about disloyalty, leading to speculation it is about Princess Haya.', mt:'这首诗的题目是“你活着，你死了”， 由迪拜统治者的儿子张贴，是关于不忠，导致猜测，这是关于哈亚公主。', ref:'这首名为《你活着，你死了》的诗由酋长的儿子发布，以不忠为主题，不免令人猜测是在影射哈雅公主。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_31', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'"You betrayed the most precious trust, and your game has been revealed," the poem says.', mt:'这首诗说:“你背叛了最珍贵的信任， 你的游戏被揭露了。”', ref:'“你背叛了最宝贵的信任，你的伎俩已经败露，”诗 中写道。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_32', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'"Your time of lying is over and it doesn\'t matter what we were nor what you are."', mt:'“你撒谎的时代已经结束了，不管我们是什么人，也不管你是什么人。”', ref:'“你的谎言已被戳穿，不管我们曾经如何，不管你以后是谁，我都不在乎了。”', tags:["准确性"] },
  { k:'seg_1_决赛_33', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The Oxford-educated princess, who is the daughter of the late King Hussein of Jordan, has been quite the rebel even before her very public act of “good riddance” to her billionaire racehorse owner husband, Sheikh Mohammed bin Rashid Al Maktoum.', mt:'这位受过牛津大学教育的公主是已故约旦国王侯赛因的女儿，甚至在她公开“摆脱”她的亿万富翁赛马主人丈夫谢赫·穆罕默德·本·拉希德·马克图姆之前，她就一直是一个叛逆者。', ref:'毕业于牛津大学的哈雅公主是约旦老侯赛因国王的女儿，在此番公开“摆脱”亿万身家的赛马主酋长丈夫谢赫·穆罕默德·本·拉希德·阿勒马克图之前就相当叛逆。', tags:["准确性"] },
  { k:'seg_1_决赛_34', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The princess, who is 45, is an accomplished Olympic equestrian and is friends with Queen Elizabeth II.', mt:'这位 45 岁的公主是一位出色的奥运马术运动员，也是伊丽莎白女王二世的朋友。', ref:'哈雅公主现年 45 岁，是技艺高超的奥运会马术选手，也是伊丽莎白女王的好友。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_35', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'She married Sheik Mohammed, who is 69, in 2004.', mt:'她于 2004 年嫁给了 69 岁的酋长穆罕默德。', ref:'2004 年，哈雅公主与谢赫·穆罕默德结婚。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_36', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The Dubai ruler is said to have 23 children by different women.', mt:'据说这位迪拜统治者有 23 个孩子， 都是由不同的妇女生的。', ref:'迪拜酋长谢赫·穆罕默德现年 69 岁，据称与不同女性育有 23 个子女。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_37', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'Princess Haya’s flight paves the way for a showdown in a London courtroom later this month.', mt:'哈亚公主的飞行为本月晚些时候在伦敦法庭的摊牌铺平了道路。', ref:'哈雅公主的出逃为本月晚些时候这对王室夫妻在伦敦法院的最后摊牌做了铺垫。', tags:["准确性"] },
  { k:'seg_1_决赛_38', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The family division court hearing scheduled on July 30 is expected to focus on who will have custody of their two young children now that the princess has left Dubai.', mt:'预计 7 月 30 日举行的家庭法庭听证会将集中讨论公主离开迪拜后，由谁来监护他们的两个年幼的孩子。', ref:'哈雅公主既已逃离迪拜，计划于 7 月 30 日举行的伦敦高等法院家事法庭听证会预计将聚焦两个孩子的监护权。', tags:["准确性"] },
  { k:'seg_1_决赛_39', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The sheikh, who is the vice president and prime minister of the United Arab Emirates in addition to being the ruler of Dubai, is among the most influential figures in the Middle East.', mt:'谢赫是阿拉伯联合酋长国副总统兼总理，同时也是迪拜的统治者，他是中东最有影响力的人物之一。', ref:'穆罕默德不仅是迪拜的现任酋长，也是阿联酋的副总统兼总理，是中东地区最有影响力的人物之一。', tags:["准确性"] },
  { k:'seg_1_决赛_40', ed:'1', stage:'决赛', dir:'英译汉', eng:'小牛翻译', src:'The harsh words of his poem about the princess caused reverberations and speculation throughout royal circles in the Middle East and beyond.', mt:'他那首诗中关于公主的严厉言辞在中东和其他地区的王室圈子里引起了反响和猜测。', ref:'其诗中苛责哈雅公主的字眼在整个中东王室乃至外界都引发了强烈反响和种种猜测。', tags:["准确性"] },
  { k:'seg_1_决赛_41', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'I wish 5G, with its 490 Mbit/sec speeds and download latency times of 17 milliseconds, was just around the corner.', mt:'我希望 5G 490 Mbit/s 的速度和 17 毫秒的下载延迟，就在拐角处。', ref:'我真希望速度高达每秒 490 兆、下载延迟时间仅 17 毫秒的 5G 时代已经来临。', tags:["语言规范","准确性"] },
  { k:'seg_1_决赛_42', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'It’s not.', mt:'不是的。', ref:'但它并没有如期而至。', tags:["准确性"] },
  { k:'seg_1_决赛_43', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'I know, I know.', mt:'我知道，我知道。', ref:'我知道，我知道。', tags:[] },
  { k:'seg_1_决赛_44', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'AT&T Mobility, Verizon Wireless, and the pairing of T-Mobile and Sprint are all promising 5G real soon now.', mt:'AT&T Mobility，Verizon Wireless，以及 T-Mobile 和 Sprint 的配对，现在都很快就有了 5G 的希望。', ref:'AT&T Mobility、Verizon Wireless 以及合并的 T- Mobile 和 Sprint 都曾许诺 5G 真的近在咫尺。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_45', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'They’re … fibbing.', mt:'他们在捣鬼。', ref:'然而，他们食言了。', tags:["准确性"] },
  { k:'seg_1_决赛_46', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'There are a host of technical, business and even political reasons why I think we’ll be lucky to see 5G by 2021, never mind later this year.', mt:'我认为我们很幸运能在 2021 年前看到 5G，这是有很多技术、商业甚至政治原因的，今年晚些时候再也不会介意了。', ref:'由于大量的技术、商业甚至政治因素，我认为到 2021 年我们能迎来 5G 就已经很幸运了，就别提今年晚些时候了。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_47', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'First, on the tech side, we don’t have any common understanding of what 5G is.', mt:'首先，在技术方面，我们对什么是 5G 没有任何共同的理解。', ref:'首先，从技术方面来看，我们对于 5G 的概念并没有达成共识。', tags:["准确性"] },
  { k:'seg_1_决赛_48', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'The Next Generation Mobile Networks Alliance has one 5G definition, 3GPP has another one and the International Telecommunications Union (ITU) has yet another one, which has just passed first- stage approvals.', mt:'下一代移动网络联盟有一个 5G 的定义， 3GPP 有另一个，国际电信联盟 (ITU) 也有另一个，它刚刚通过第一阶段的批准。', ref:'下一代移动网络联盟 (NGMNA) 对 5G 提出了一个定义，3GPP 则有另一番说法，而国际电信联盟 (ITU) 也有自己关于 5G 的界定，而它刚刚通过第一阶段的审批。', tags:["准确性","术语","语言规范"] },
  { k:'seg_1_决赛_49', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Then there’s what the vendors are actually doing, which bears some resemblance to all these proposals.', mt:'然后是供应商实际上正在做的事情， 这与所有这些提议都有一些相似之处。', ref:'接着就是供应商们真正需要做的事情，它与所有这些方案有些相似。', tags:["准确性"] },
  { k:'seg_1_决赛_50', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Then there are purely practical matters such as, say, 5G’s range.', mt:'那就有纯粹的实际问题，比如说，5G 的范围。', ref:'再者就纯粹是实际问题，比如说 5G 的范围。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_51', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Enhanced Mobile Broadband (eMBB), which is only one of three flavors of 5G, is the one you’ll be using with your smartphone.', mt:'增强型移动宽带（eMBB），这是 5G 的三种风格之一，是你将使用的智能手机。', ref:'增强移动宽带 (eMBB) 只是 5G 的三大应用场景之一，就是 5G 在手机方面的应用。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_52', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'It makes use of multiple- input and multiple-output, (MIMO) and millimeter wave (mmWave) to, in theory, deliver up to gigabit speeds as you walk down the street and watch Star Wars: Chewy’s Story in 3D and try not to walk in front of a self- driving truck.', mt:'它利用多输入多输出（MIMO）和毫米波（mmWave）理论上，当你沿着街道走着观看《星球大战：在 3D 中的咀嚼的故事》（Chwy\'s Story in 3D）时，可以提供高达千兆位的速度，并且尽量不要在自驾车的卡车前面走。', ref:'它利用多输入多输出 (MIMO) 和毫米波 (mmWave)，在理论上可以提供高达千兆位的速度， 让你可以边走在街上边观看 3D 版的《星球大战： 丘巴卡外传》，但要留神不要走到自动驾驶的卡车前面。', tags:["语言规范","准确性"] },
  { k:'seg_1_决赛_53', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'While a seminal research paper boldly proclaimed, “Millimeter Wave Mobile Communications for 5G Cellular: It Will Work!” there are still real doubts.', mt:'当一篇重要的研究论文大胆地宣布， “毫米波移动通信的 5G 蜂窝：它会工作！”仍然存在着真正的怀疑。', ref:'尽管有一份开创性的研究报告果断宣称毫米波可以应用于 5G 移动通信 —— 《 Millimeter Wave Mobile Communications for 5G Cellular: It Will Work!》，但怀疑确实依然存在。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_54', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'The real range of mmWave appears to be about a third of a mile.', mt:'毫米波的实际射程似乎是一英里的三分之一。', ref:'毫米波的实际应用范围貌似只有三分之一英里。', tags:["准确性"] },
  { k:'seg_1_决赛_55', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'4G?', mt:'4G？', ref:'而 4G 呢？', tags:["准确性"] },
  { k:'seg_1_决赛_56', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'It ranges from three to 30 miles.', mt:'它从三英里到 30 英里不等。', ref:'它的应用范围可以从三英里到 30 英里。', tags:["准确性"] },
  { k:'seg_1_决赛_57', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Think about that for a minute.', mt:'考虑一下。', ref:'花一分钟思考一下。', tags:["准确性"] },
  { k:'seg_1_决赛_58', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'That’s a heck of a lot of new cell towers, isn’t it?', mt:'那是一堆新的细胞塔，是不是？', ref:'那将需要非常非常多新的蜂窝基站，不是吗？', tags:["准确性"] },
  { k:'seg_1_决赛_59', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Now, in 5G’s new, shiny future, cell “towers” will be much smaller femtocells, about the size of microwave ovens, and they’ll be pretty much everywhere: on power poles, buses (no, really!) and signs.', mt:'现在，在 5G 的新的、闪亮的未来， 蜂窝“塔”将是更小的毫微微蜂窝，大约是微波炉的大小，它们将几乎到处都是：在电源杆上，公共汽车（不， 真的！)和标志。', ref:'在 5G 闪闪发亮的崭新未来里，蜂窝基站将是小得多的微蜂窝基站。它大概只有微波炉大小，而且将几乎无处不在，电线杆、巴士（不是吧，真的！）还有标志牌上随处可见。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_60', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Which reminds me of another 5G headache.', mt:'这让我想起了另一个 5G 的头痛。', ref:'这让我想起了 5G 的另一个令人头痛的问题。', tags:["准确性"] },
  { k:'seg_1_决赛_61', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'mmWave is really easy to block.', mt:'mmWave 真的很容易阻塞。', ref:'毫米波很容易被阻断。', tags:["准确性"] },
  { k:'seg_1_决赛_62', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'How easy?', mt:'多容易?', ref:'有多容易呢？', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_63', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'That stop sign in front of your car?', mt:'你的车前面有停车标志吗？', ref:'看到你汽车前面的停车标志了吗？', tags:["准确性"] },
  { k:'seg_1_决赛_64', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Bleck!', mt:'布莱克!', ref:'宾果！', tags:["准确性"] },
  { k:'seg_1_决赛_65', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'There went your signal.', mt:'有你的信号。', ref:'信号马上消失了。', tags:["准确性"] },
  { k:'seg_1_决赛_66', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Then there’s the little problem of getting enough bandwidth to all those 5G femtocells so you can stream your video.', mt:'那么有一个小问题，就是要给所有的 5G 毫微微蜂窝网提供足够的带宽， 这样你就可以流畅地传输你的视频了。', ref:'还有一个小问题就是所有这些 5G 微蜂窝基站要有足够的带宽才能实现视频流播。', tags:["准确性","语言规范"] },
  { k:'seg_1_决赛_67', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'While some of that will be delivered by the new femtocells sharing with each other, at the end of the day you need fiber.', mt:'虽然其中的一些将由新的女性细胞相互分享，但在一天的结束时，你需要纤维。', ref:'虽然其中一部分带宽将由新的微蜂窝基站通过彼此分享来提供，到最后还是需要光纤。', tags:["准确性"] },
  { k:'seg_1_决赛_68', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Lots and lots of fiber.', mt:'大量的纤维。', ref:'很多很多的光纤。', tags:["准确性"] },
  { k:'seg_1_决赛_69', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Deploying high-speed fiber doesn’t come cheap.', mt:'部署高速光纤并不便宜。', ref:'部署高速光纤可不便宜。', tags:["准确性"] },
  { k:'seg_1_决赛_70', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'In addition, one of the reasons why 5G femtocells will be so small is that the brains behind the network will no longer be on the towers, but on the cloud.', mt:'此外，5G 毫微微细胞之所以如此小的原因之一是网络后面的大脑不再在塔上，而是在云端。', ref:'此外，5G 微蜂窝基站尺寸能够这么小的一个原因是网络背后的大脑将不再位于基站上，而是在云端。', tags:["准确性","风格"] },
  { k:'seg_1_决赛_71', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'On the cloud, software- defined networks (SDN) and network function virtualization (NFV) will manage 5G with Network Slicing, which will create multiple dedicated end-to- end virtual networks.', mt:'在云端，软件定义网络 (SDN) 和网络功能虚拟化 (NFV) 将通过网络分片管理 5G ，从而创建多个专用的端到端虚拟网络。', ref:'在云端，软件定义网络 (SDN) 和网络功能虚拟化 (NFV) 将利用网络切片管理 5G，由其创建多个专用的端对端虚拟网络。', tags:["准确性"] },
  { k:'seg_1_决赛_72', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'The hitch here is that there are multiple SDNs and NFVs.', mt:'这里的关键是有多个 SDN 和 NFV。', ref:'这里的问题在于会有多个 SDN 和 NFV。', tags:["准确性"] },
  { k:'seg_1_决赛_73', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'The Linux Foundation is bringing some rhyme and reason to SDN and NFVs, but it’s still very much a work in progress.', mt:'Linux 基金会给 SDN 和 NFV 带来了一些押韵和理由，但它仍是一项非常重要的工作。', ref:'Linux 基金会将给 SDN 和 NFV 带来一些章法和条理，但仍有非常多的工作需要做。', tags:["准确性"] },
  { k:'seg_1_决赛_74', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'Beginning to get the picture?', mt:'开始拍照片了吗？', ref:'现在了解状况了吗？', tags:["准确性"] },
  { k:'seg_1_决赛_75', ed:'1', stage:'决赛', dir:'英译汉', eng:'云译科技', src:'We have all these technologies, none of them fully mature, and all of them will cost their vendors lots and lots and — one more time, with feeling — lots of money.', mt:'我们拥有所有这些技术，没有一个是完全成熟的，而且所有这些技术都会花费他们的供应商很多，很多，而且 ——再一次，感觉——大量的钱。', ref:'所有这些技术我们都有，却都不完全成熟，而且它们都将让供应商耗费非常非常巨大的成本。这是个悲伤的故事。', tags:["准确性"] },
  { k:'seg_1_初赛_1', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'11 December 2018', mt:'2018 年 12 月 11 日', ref:'2018 年 12 月 11 日', tags:[] },
  { k:'seg_1_初赛_2', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'PRIVATE & CONFIDENTIAL', mt:'私密', ref:'私密信息', tags:["准确性"] },
  { k:'seg_1_初赛_3', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'BY POST, A.R.', mt:'邮寄，A.R.', ref:'通过邮寄', tags:["准确性"] },
  { k:'seg_1_初赛_4', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'REGISTERED POST AND/OR COURIER', mt:'挂号信和/或快递', ref:'挂号信和/或快递送达', tags:["准确性"] },
  { k:'seg_1_初赛_5', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'XXX', mt:'某某', ref:'XXX', tags:["准确性"] },
  { k:'seg_1_初赛_6', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'Strictly to be opened by addressee only', mt:'严格只由收件人开启', ref:'由收件人亲启', tags:["准确性"] },
  { k:'seg_1_初赛_7', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'Dear Sir', mt:'亲爱的先生', ref:'敬启者：', tags:["准确性"] },
  { k:'seg_1_初赛_8', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'CLAIM BY BBBBB AGAINST MR XXX', mt:'bbbbb 对 XXX 先生的索赔', ref:'此为 BBBBB 针对 XXX 先生的付款要求函。', tags:["准确性"] },
  { k:'seg_1_初赛_9', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'1.We act for BBBBB', mt:'1.我们代表 bbbbb', ref:'1.我方受委托代表 BBBBB 作如下要求。', tags:["准确性"] },
  { k:'seg_1_初赛_10', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'2.Pursuant to a credit agreement between you and our client dated 20 February 2018 (“Agreement”), you obtained credit from our client in the total sum of S$ XXXX.', mt:'2.根据阁下与吾等客户于 2018 年 2 月 20 日订立的信贷协议(“协议”)，阁下从吾等客户处取得总额为新元 XXXX 的信贷。', ref:'2.根据阁下与我方客户于 2018 年 2 月 20 日订立的信贷协议(“协议”)，阁下从我方客户处取得总额为 XXXX 新元的信贷。', tags:["准确性"] },
  { k:'seg_1_初赛_11', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'3.As of 20 February 2018, you were indebted to our client for the principal sum of S$ XXXX (“Outstanding Amount”), as evidenced by the markers dated 20 February 2018(“Markers”).', mt:'3.截至 2018 年 2 月 20 日，您欠我们客户的本金为 XXXX 新元(“未清金额”)，日期为 2018 年 2 月 20 日的标记(“标记”)即为明证。', ref:'3.截至 2018 年 2 月 20 日，阁下欠我方客户的本金为 XXXX 新元(“未清金额”)，日期为 2018 年 2 月 20 日的借据(“借据”)即为明证。', tags:["准确性"] },
  { k:'seg_1_初赛_12', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'4.The aforesaid credit from our client to you is governed by the terms and conditions set out in the Agreement.', mt:'4.我们的客户向您提供的上述信用证受协议中规定的条款和条件的约束。', ref:'4.我方客户向阁下提供的上述信贷受“协议”中规定的条款和条件约束。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_13', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'5.Pursuant to the terms of the Agreement, the Outstanding Amount fell due and payable by you to our client on 20 February 2018(“Maturity Date”).', mt:'5.根据协议条款，阁下于 2018 年 2 月 20 日(“到期日”)须向吾等客户支付未清款项。', ref:'5.根据协议条款，阁下于 2018 年 2 月 20 日(“到期日”)须向我方客户支付“未清金额”。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_14', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'6.We are also instructed that the HSBC Bankcheque number X,which you had provided to our client, was dishonoured when our client presented the cheque for payment on 10 September 2018.On 30 October 2018, our client notified you of the dishonour of the cheque.', mt:'6.吾等亦获指示，阁下提供予吾等客户之汇丰银行第 X 号支票于二零一八年九月十日向吾等客户出示该支票时遭拒付，吾等之客户于 2018 年 10 月 30 日通知阁下该支票已遭拒付。', ref:'6.我方亦了解到，2018 年 9 月 10 日，我方客户向银行出示阁下提供予我方客户之汇丰银行第 X 号支票时遭拒付，我方客户于 2018 年 10 月 30 日通知阁下该支票已遭拒付。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_15', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'7.Despite our client’s requests to you for payment, including its letter to you dated 14 September 2017, you have, to date, failed and refused to make payment of the Outstanding Amount, or any part thereof.', mt:'7. 尽管我们的客户向您提出付款要求，包括其 2017 年 9 月 14 日给您的信，但您至今仍未支付或拒绝支付未清款项或其任何部分。', ref:'7.尽管我方客户向阁下多次提出付款要求，包括 2017 年 9 月 14 日发给阁下的函件，但阁下至今仍未支付并拒绝支付“未清金额”或其部分金额。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_16', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'8.By reason of the aforesaid, our client is entitled to payment of the total sum of S$ XXXX by you, comprising the following:', mt:'8.由于上述原因，我方客户有权要求贵方支付总额为 XXXX 新元的款项， 其中包括：', ref:'8.由于上述原因，我方客户有权要求阁下支付总额为 XXXX 新元的款项，其中包括：', tags:["准确性"] },
  { k:'seg_1_初赛_17', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'(i)Outstanding Amount:', mt:'(1)未清数额：', ref:'(i)未清金额：', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_18', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'S$ XXXX', mt:'S$XXXX', ref:'XXXX 新元', tags:["准确性"] },
  { k:'seg_1_初赛_19', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'(ii)Interest at 12% per annum on the Outstanding Amount, from 28 May 2017, being 90 days after the Maturity Date, to 11December 2018 (XX days) pursuant to the terms of the Agreement and the terms of the Markers', mt:'(Ii) 根据协议条款及标记条款，由 2017 年 5 月 28 日(即到期日后 90 天) 至 2018 年 12 月 11 日(XX 天)，未缴款额年息 12%', ref:'(ii)利息：根据协议条款及借据条款，从 2017 年 5 月 28 日(即到期日后 90 天)至 2018 年 12 月 11 日 (XX 天)这段时间，阁下需按每年 12%的利率支付利息。', tags:["准确性"] },
  { k:'seg_1_初赛_20', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'S$ XXXX', mt:'S$XXXX', ref:'XXXX 新元', tags:["准确性"] },
  { k:'seg_1_初赛_21', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'(iii)Legal costs pursuant to clause 10 of the Agreement', mt:'(Iii)根据“协定”第 10 条支付的法律费用', ref:'(iii)根据“协议”第 10 条阁下应付的法律费用', tags:["准确性"] },
  { k:'seg_1_初赛_22', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'S$ XXXX', mt:'S$XXXX', ref:'XXXX 新元', tags:["准确性"] },
  { k:'seg_1_初赛_23', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'9.Further, interest on the Outstanding Amount or any unpaid portion thereof shall continue to accrue, pursuant to the terms of the Agreement, at the rate of 10% per annum, or S$ XXX per day, from the date of this letter until such time that you make full repayment of the Outstanding Amount.', mt:'9.此外，根据本协议的条款，未付金额或其任何未付部分的利息应继续按年利率 10%或每日$XXX 计算，从本信之日起计算，直至您全额还款为止。', ref:'9.此外，根据“协议”条款，“未清金额”或其任何未付部分的利息应继续按年利率 10%或每日 XXX 新元自本要求函之日起计算，直至阁下全额还清为止。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_24', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'10.TAKE NOTICE that our client requires that you make full payment of the sum of S$ XXXX and interest as described in paragraph 9 to our client within ten (10) daysfrom the date of this letter, failing which our client has instructed us to commence court proceedings against you for the same, without further reference to you.', mt:'10.请注意，我们的客户要求您在本信发出之日起十(10)天内，向我们的客户全额支付第 9 段所述的新元 XXXX 和利息，否则，我们的客户已指示我们就此开始向您提起诉讼，而无需进一步与您联系。', ref:'10.请注意，我方客户要求阁下在本要求函之日起十 (10)天内，向我方客户全额支付上述第 9 段所述的 XXXX 新元和利息，否则，我方客户已指示我们就此开始向阁下提起诉讼，而无需进一步与阁下联系。', tags:["准确性"] },
  { k:'seg_1_初赛_25', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'11.In the meantime, our client’s rights against you remain fully reserved.', mt:'11.在此期间，我们的客户对你方的权利仍然是完全保留的。', ref:'11.在此期间，我方客户保留所有针对阁下的权利。', tags:["准确性"] },
  { k:'seg_1_初赛_26', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'These rights include, without limitation, the right to claim for costs of any court proceedings which it subsequently commences against you.', mt:'这些权利包括(但不限于)就其随后对您提起的任何法院诉讼的费用提出索赔的权利。', ref:'这些权利包括(但不限于)要求阁下支付后续因此发生的任何法庭诉讼费用的权利。', tags:["准确性"] },
  { k:'seg_1_初赛_27', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'Yours faithfully', mt:'你忠实的', ref:'此致', tags:["准确性"] },
  { k:'seg_1_初赛_28', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'XXXX', mt:'某某', ref:'XXXX', tags:["准确性"] },
  { k:'seg_1_初赛_29', ed:'1', stage:'初赛', dir:'英译汉', eng:'腾讯翻译君', src:'cc client', mt:'CC 客户端', ref:'抄送：客户', tags:["准确性"] },
  { k:'seg_1_初赛_30', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'The world\'s largest economies took a big step closer this weekend to agreeing an overhaul of global corporate tax rules that experts say would be the most significant in over a century.', mt:'本周末，世界上最大的经济体又向前迈进了一大步，同意对全球公司税规则进行全面改革。专家们表示，这将是一个多世纪以来最重要的一次改革。', ref:'本周末，世界上最大的几个经济体推出了一项更加紧密的合作计划，同意对全球企业税规则进行全面改革。专家们表示，这将是一个多世纪以来最重要的一次改革。', tags:["准确性"] },
  { k:'seg_1_初赛_31', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'G20 finance ministers discussed a plan developed by the Organization for Economic Cooperation and Development during a meeting on Saturday in Japan.', mt:'20 国集团财长周六在日本举行的一次会议上讨论了经济合作与发展组织制定的一项计划。', ref:'20 国集团财长周六在日本举行的一次会议上讨论了经济合作与发展组织制定的一项计划。', tags:[] },
  { k:'seg_1_初赛_32', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'The proposal is designed with digital companies in mind, but also has major implications for traditional multinational corporations.', mt:'该提案的设计考虑到了数字公司，但也对传统的跨国公司产生了重大影响。', ref:'该计划的提案主要针对数字公司，但对传统的跨国公司也将产生重大影响。', tags:["准确性"] },
  { k:'seg_1_初赛_33', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'"We welcome the recent progress on addressing the tax challenges arising from digitalization and endorse the ambitious work program that consists of a two-pillar approach," the ministers said in a statement Sunday.', mt:'部长们周日在一份声明中表示:“我们欢迎最近在应对数字化带来的税收挑战方面取得的进展，并赞同由两大支柱组成的雄心勃勃的工作计划。”', ref:'部长们周日在一份声明中表示:“我们很高兴看到最近在应对数字化带来的税收挑战方面取得的进展， 并赞同通过两大举措推进这项目标远大的计划。”', tags:["准确性","风格"] },
  { k:'seg_1_初赛_34', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'"We will redouble our efforts for a consensus-based solution with a final report by 2020."', mt:'“我们将加倍努力，争取在 2020 年前提交一份最终报告，达成一个基于共识的解决方案。”', ref:'“我们将加倍努力，争取在 2020 年前提交一份最终报告，达成一个基于共识的解决方案。”', tags:[] },
  { k:'seg_1_初赛_35', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'US Treasury Secretary Steven Mnuchin, speaking earlier at the meeting, said there was broad support for the plan but more work needed to be done.', mt:'美国财政部长史蒂文•姆努钦在早些时候的会议上表示，该计划得到了广泛支持，但还需要做更多的工作。', ref:'美国财政部长史蒂文•姆努钦在早些时候的会议上表示，该计划得到广泛支持，但我们需要做更多的工作。', tags:["准确性"] },
  { k:'seg_1_初赛_36', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'"Sounds like we have a strong consensus so now we need to just take the consensus that\'s across here and deal with the technicalities of how we turn this into an agreement," he said.', mt:'他说 :“ 听起来我们有一个很强的共识，所以现在我们只需要把这里的共识，并处理如何把这变成一个协议的技术问题。”', ref:'他说:“看起来我们已达成高度共识，所以现在我们只需要把握好这个共识，并解决如何把它转化成协议的技术问题。”', tags:["准确性","风格"] },
  { k:'seg_1_初赛_37', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'The overhaul seeks to address shortcomings in global taxation via two main avenues.', mt:'此次改革旨在通过两个主要途径解决全球税收方面的缺陷。', ref:'此次改革旨在通过两个主要途径解决全球税收方面的缺陷。', tags:[] },
  { k:'seg_1_初赛_38', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'The first is a framework that would help resolve questions over when tax ought to be paid, and whether it should be collected where buyers or sellers are located.', mt:'第一个是一个框架，它将有助于解决何时应纳税的问题，以及是否应在买方或卖方所在地征税的问题。', ref:'第一个是建立一个框架，它将有助于解决何时应纳税的问题，以及是否应在买方或卖方所在地征税的问题。', tags:["准确性"] },
  { k:'seg_1_初赛_39', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'The second would ensure that multinational companies pay a minimum level of tax, thereby discouraging them from shifting profits to countries with lower levels of taxation.', mt:'第二种办法将确保跨国公司缴纳最低税率，从而阻止它们将利润转移到税率较低的国家。', ref:'第二个途径是确保跨国公司缴纳最低税率，从而阻止它们将利润转移到税费较低的国家。', tags:["准确性"] },
  { k:'seg_1_初赛_40', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'If a business pays less than the minimum, countries where it operates might be able to demand more tax.', mt:'如果一个企业支付的税款低于最低标准，那么它所经营的国家可能会要求更多的税收。', ref:'如果一个企业支付的税款低于最低标准，那么其经营所在地国家就可能要求征收更多的税费。', tags:["准确性"] },
  { k:'seg_1_初赛_41', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'Changes in both areas would help modernize the global tax infrastructure.', mt:'这两个领域的变化将有助于全球税收基础设施的现代化。', ref:'这两个领域的变化都将有助于构建一个现代的全球税收基础架构。', tags:["准确性"] },
  { k:'seg_1_初赛_42', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'The benefits of going global', mt:'走出去的好处', ref:'全球化带来的好处', tags:["准确性"] },
  { k:'seg_1_初赛_43', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'Yet there are powerful incentives for both companies and governments to work towards a new global tax framework.', mt:'然而，公司和政府都有强大的动力推动建立一个新的全球税收框架。', ref:'目前，企业和政府都有强烈的愿望去推动建立一个新的全球税收框架。', tags:["准确性"] },
  { k:'seg_1_初赛_44', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'If that doesn\'t happen, Morris said that individual countries would implement their own rules, creating a patchwork system of regulations that would be "terrible" for trade and investment.', mt:'莫里斯说，如果不这样做，个别国家就会执行自己的规则，建立一个杂乱无章的规则体系，对贸易和投资来说将是“可怕的”。', ref:'莫里斯表示，如果不这样做，个别国家就会执行自己的规则，建立一个杂乱无章的规则体系，那对贸易和投资来说将是“可怕的”。', tags:["准确性"] },
  { k:'seg_1_初赛_45', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'UK Finance Minister Philip Hammond said in a tweet ahead of the G20 meeting, which will have representatives of the most powerful economies in the world, that he plans "to push for changes to global tax rules so they reflect how digital businesses create value."', mt:'英国财政大臣菲利普•哈蒙德在 G20 峰会召开前的推特上表示，他计划“推动全球税收规则的改革，以反映数字企业如何创造价值。”G20 峰会将有全球最强大经济体的代表参加。', ref:'英国财政大臣菲利普•哈蒙德在 G20 峰会召开前曾在推特上表示，他将“推动全球税收规则的改革，以真实反映数字企业所创造的价值。”G20 峰会上来自全球最强经济体的代表们将如数出席。', tags:["准确性"] },
  { k:'seg_1_初赛_46', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'"The digital economy has brought great benefits but it is moving at pace and international rules must be updated," Hammond wrote.', mt:'哈蒙德写道:“数字经济带来了巨大的好处，但它的发展速度很快，国际规则必须更新。”', ref:'哈蒙德写道:“数字经济带来了巨大的效益，但它的发展速度很快，国际规则必须更新。”', tags:["准确性"] },
  { k:'seg_1_初赛_47', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'If progress isn\'t made on global changes, several countries including the United Kingdom may choose to move forward with their own taxes.', mt:'如果在全球变化方面没有取得进展， 包括英国在内的几个国家可能会选择自己征税。', ref:'如果在全球变革方面没有取得进展，包括英国在内的几个国家可能会选择采用自己税收规则。', tags:["准确性"] },
  { k:'seg_1_初赛_48', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'Britain, for example, wants a 2% levy on sales of digital services in the United Kingdom starting in April 2020.', mt:'例如，英国希望从 2020 年 4 月起对英国的数字服务销售征收 2%的税。', ref:'例如，英国计划从 2020 年 4 月起对英国的数字服务销售征收 2%的税。', tags:["准确性"] },
  { k:'seg_1_初赛_49', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'"We all have to hope this will work.', mt:'“我们都希望这能奏效。', ref:'“我们都希望这项计划能奏效。', tags:["准确性"] },
  { k:'seg_1_初赛_50', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'Because the alternative is chaos," said Morris.', mt:'因为另一种选择是混乱。“莫里斯说。', ref:'因为其它选择将带来混乱。”莫里斯说：', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_51', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'"This could have huge impacts on the way business is done, it could have huge impacts on countries, could have impacts on growth.', mt:'“这可能对商业运作方式产生巨大影响，可能对各国产生巨大影响，可能对增长产生影响。', ref:'“这可能对商业运作方式产生巨大影响，可能对各国产生巨大影响，甚至对全球增长产生影响。', tags:["准确性"] },
  { k:'seg_1_初赛_52', ed:'1', stage:'初赛', dir:'英译汉', eng:'小牛翻译', src:'I think people really need to be paying attention to this."', mt:'我认为人们真的需要注意这一点，“', ref:'我认为大家需要予以重视。”', tags:["准确性","风格"] },
  { k:'seg_1_初赛_53', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Contracts, transactions, and the records of them are among the defining structures in our economic, legal, and political systems.', mt:'合同、交易和它们的记录是我们经济、法律和政治制度中的定义结构之一。', ref:'在定义我们经济、法律和政治体系的框架中，合同、 交易及其记录是一个重要组成部分。', tags:["准确性"] },
  { k:'seg_1_初赛_54', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'They protect assets and set organizational boundaries.', mt:'它们保护资产并确定组织边界。', ref:'它们保护资产并设定组织边界。', tags:["准确性"] },
  { k:'seg_1_初赛_55', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'They establish and verify identities and chronicle events.', mt:'他们建立和核实身份和记录事件。', ref:'它们建立并验证身份信息和历史事件。', tags:["准确性"] },
  { k:'seg_1_初赛_56', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'They govern interactions among nations, organizations, communities, and individuals.', mt:'它们管理国家、组织、社区和个人之间的互动。', ref:'它们管理国家、组织、社区和个人之间的往来。', tags:["准确性"] },
  { k:'seg_1_初赛_57', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'They guide managerial and social action.', mt:'它们指导管理和社会行动。', ref:'它们指导我们的管理工作和社会活动。', tags:["准确性"] },
  { k:'seg_1_初赛_58', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'And yet these critical tools and the bureaucracies formed to manage them have not kept up with the economy’s digital transformation.', mt:'然而，这些重要的工具和管理它们的官僚机构并没有跟上经济的数字化转型。', ref:'然而，这些重要工具以及为管理这些工具而建立的政府机构并没有跟上经济的数字化转型。', tags:["准确性"] },
  { k:'seg_1_初赛_59', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'They’re like a rush-hour gridlock trapping a Formula 1 race car.', mt:'他们就像一个忙碌时间的锁扣，困住了一辆方程式 1 赛车。', ref:'它们就像在高峰时段被堵在路上的一辆一级方程式赛车。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_60', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'In a digital world, the way we regulate and maintain administrative control has to change.', mt:'在一个数字化的世界里，我们调整和维持行政控制的方式必须改变。', ref:'在数字世界中，我们必须改变这种管理和管控的方式。', tags:["准确性"] },
  { k:'seg_1_初赛_61', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Blockchain promises to solve this problem.', mt:'区块链有望解决这个问题。', ref:'区块链为我们解决这些问题带来了希望。', tags:["准确性"] },
  { k:'seg_1_初赛_62', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'The technology at the heart of bitcoin and other virtual currencies, blockchain is an open, distributed ledger that can record transactions between two parties efficiently and in a verifiable and permanent way.', mt:'比特币和其他虚拟货币的核心技术， 区块链是一个开放、分布式的分类账，能够以可核查和永久的方式有效地记录双方之间的交易。', ref:'区块链是比特币和其他虚拟货币的核心技术，是一种开放式、分布式账本技术，能够以可验证且永久的方式记录双方之间的交易。', tags:["准确性"] },
  { k:'seg_1_初赛_63', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'The ledger itself can also be programmed to trigger transactions automatically.', mt:'也可对分类帐本身进行编程，以自动触发交易。', ref:'此外，通过对该账本进行编程还可以自动触发交易。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_64', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'With blockchain, we can imagine a world in which contracts are embedded in digital code and stored in transparent, shared databases, where they are protected from deletion, tampering, and revision.', mt:'使用区块链，我们可以想象一个世界，在这个世界中，合同嵌入数字代码并存储在透明的共享数据库中，在那里，合同不会被删除、篡改和修改。', ref:'有了区块链，我们可以想象一个这样的世界——所有合同都以数字代码的形式存储于透明的共享数据库中，而且，这些合同不会被删除、篡改和修订。', tags:["准确性"] },
  { k:'seg_1_初赛_65', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'In this world every agreement, every process, every task, and every payment would have a digital record and signature that could be identified, validated, stored, and shared.', mt:'在这个世界上，每一个协议、每一个过程、每一个任务和每一笔付款都有一个数字记录和签名，可以被识别、 验证、存储和共享。', ref:'在这个世界里，每一项协议、每一个流程、每一项任务和每一笔付款都配有一个可供识别、验证、存储和共享的数字记录和签名。', tags:["准确性"] },
  { k:'seg_1_初赛_66', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Intermediaries like lawyers, brokers, and bankers might no longer be necessary.', mt:'律师、经纪人和银行家等中间人可能不再需要了。', ref:'我们可能不再需要诸如律师、经纪人和银行家这样的中间人。', tags:["准确性"] },
  { k:'seg_1_初赛_67', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Individuals, organizations, machines, and algorithms would freely transact and interact with one another with little friction.', mt:'个人、组织、机器和算法可以在很少摩擦的情况下自由地进行交易和交互。', ref:'个人、组织、机器和算法之间将实现自由的交易和交互，出现摩擦的几率极小。', tags:["准确性"] },
  { k:'seg_1_初赛_68', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'This is the immense potential of blockchain.', mt:'这就是大块链的巨大潜力。', ref:'这便是区块链的巨大潜力。', tags:["准确性"] },
  { k:'seg_1_初赛_69', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Indeed, virtually everyone has heard the claim that blockchain will revolutionize business and redefine companies and economies.', mt:'实际上，几乎每个人都听到了一个说法，即封锁链将使企业革命化，并重新定义公司和经济。', ref:'事实上，几乎每个人都听到过这样的说法，即区块链将带来一次商业革命，并重新定义公司和经济体。', tags:["准确性"] },
  { k:'seg_1_初赛_70', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Although we share the enthusiasm for its potential, we worry about the hype.', mt:'尽管我们对它的潜力有着共同的热情，但我们担心这种炒作。', ref:'尽管我们对它的潜力抱有同样的热情，但我们担心那种过度的宣传。', tags:["准确性"] },
  { k:'seg_1_初赛_71', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'It’s not just security issues (such as the 2014 collapse of one bitcoin exchange and the more recent hacks of others) that concern us.', mt:'不仅仅是安全问题（比如 2014 年一家比特币交易所的崩溃和其他公司最近的黑客），关系到我们。', ref:'它不仅仅关系着我们的安全问题，例如，2014 年一家比特币交易所倒闭，以及最近其它交易所遭遇黑客攻击的事件。', tags:["准确性","语言规范","风格"] },
  { k:'seg_1_初赛_72', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Our experience studying technological innovation tells us that if there’s to be a blockchain revolution, many barriers—technological, governance, organizational, and even societal—will have to fall.', mt:'我们研究技术创新的经验告诉我们， 如果要发生一场连锁革命，许多障碍 ——技术、治理、组织甚至社会—— 将不得不崩溃。', ref:'研究技术创新的经验告诉我们，如果真的发生区块链革命，技术、治理、组织甚至社会方面的许多壁垒都将不复存在。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_73', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'It would be a mistake to rush headlong into blockchain innovation without understanding how it is likely to take hold.', mt:'如果不了解它可能会采取什么样的态度，就会错误地仓促地进行大块链式的创新。', ref:'在不知道如何驾驭它的情况下就一头扎进区块链创新，将是一个错误。', tags:["准确性"] },
  { k:'seg_1_初赛_74', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'True blockchain-led transformation of business and government, we believe, is still many years away.', mt:'我们认为，真正的连锁经营和政府转型仍需要多年的时间。', ref:'我们相信，真正由区块链引领的企业和政府转型还需要多年才能实现。', tags:["准确性"] },
  { k:'seg_1_初赛_75', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'That’s because blockchain is not a “disruptive” technology, which can attack a traditional business model with a lower-cost solution and overtake incumbent firms quickly.', mt:'这是因为区块链不是一种“颠覆性”技术，它可以以较低的成本解决方案攻击传统的商业模式，并迅速超越现有企业。', ref:'这是因为区块链不是一种“颠覆性”技术，它不能利用低成本的解决方案打击传统商业模式并快速超越现有公司。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_76', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Blockchain is a foundational technology: It has the potential to create new foundations for our economic and social systems.', mt:'封锁链是一项基础技术：它有潜力为我们的经济和社会制度建立新的基础。', ref:'区块链是一项基础性技术——它有潜力为我们的经济和社会体系构建新基础。', tags:["准确性","语言规范"] },
  { k:'seg_1_初赛_77', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'But while the impact will be enormous, it will take decades for blockchain to seep into our economic and social infrastructure.', mt:'但是，尽管这种影响将是巨大的，但要让封锁链渗透到我们的经济和社会基础设施需要几十年的时间。', ref:'然而，尽管这种影响将是巨大的，但区块链还需要几十年的时间才能渗透到我们的经济和社会基础设施中。', tags:["准确性"] },
  { k:'seg_1_初赛_78', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'The process of adoption will be gradual and steady, not sudden, as waves of technological and institutional change gain momentum.', mt:'随着技术和体制变革的浪潮，收养进程将是渐进和稳定的，而不是突如其来的。', ref:'区块链的应用过程将是渐进的、稳定的，而不是突如其来的，同时酝酿着技术和制度变革的浪潮。', tags:["准确性"] },
  { k:'seg_1_初赛_79', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'That insight and its strategic implications are what we’ll explore in this article.', mt:'这种洞察力及其战略意义是我们将在本文中探讨的问题。', ref:'我们将在本文中探讨这一见解及其战略意义。', tags:["准确性"] },
  { k:'seg_1_初赛_80', ed:'1', stage:'初赛', dir:'英译汉', eng:'云译科技', src:'Source: https://hbr.org/2017/01/the- truth-about-blockchain', mt:'资料来源：https://hbr.org/2017/01/真实性@ - @关于区块链', ref:'资料来源： https://hbr.org/2017/01/the-truth-about- blockchain', tags:["准确性"] },
  { k:'seg_2_决赛_1', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Self-Driving Cars Likely to Spur Solo Occupancy and Paradoxically Undercut True Ridesharing', mt:'自动驾驶汽车可能会刺激单人驾驶，矛盾的是会削弱真正的驾驶体验', ref:'自动驾驶汽车非但不能促进共享出行，反而会推高独享乘坐率', tags:["准确性","风格"] },
  { k:'seg_2_决赛_2', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Today’s ridesharing via Uber and Lyft is supposed to get more people to share rides and therefore cut down on the number of trips made, along with making more efficient use of cars and roadways, plus saving the earth by knocking down the volume of harmful exhaust emissions.', mt:'今天通过优步和 Lyft 的出行应该会让更多的人分享乘车体验，从而减少出行次数，同时更有效地利用汽车和道路，并通过降低有害废气排放量来拯救地球。', ref:'今天，Uber（“优步”）和 Lyft （“来福车”）本应让越来越多的人开始习惯共享出行，令出行数量大幅下降，实现汽车和道路的有效利用，并通过减少有害废气的排放很好地保护地球。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_3', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Unfortunately, contemporary ridesharing is more akin to ride- hailing than it is to actual ride sharing.', mt:'不幸的是，现代拼车更像是打车，而不是真正的拼车。', ref:'遗憾的是，与实际意义上的共享出行相比，当前的拼车服务更像是一种叫车服务。', tags:["准确性"] },
  { k:'seg_2_决赛_4', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'By-and-large, people using present-day ridesharing services are taking trips that encompass just one passenger, themselves.', mt:'总的来说，使用当今乘客共享服务的人们正在进行只包含一名乘客的旅行。', ref:'基本上，目前的拼车服务全程仅向一名乘客提供。', tags:["准确性"] },
  { k:'seg_2_决赛_5', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'They are hailing a ride that will transport themselves, only, and not sharing the ride with any other passengers (a scant one-fifth of the time they opt for sharing a ride).', mt:'他们在欢呼一次只能自己运输的旅程，而不与任何其他乘客分享旅程(不到五分之一的时间他们选择分享旅程)。', ref:'乘客都选择独享自己所约到的车，而非与他人共享。当他们选择叫车服务时，只有在不到五分之一的时间里会选择与他人共享拼车。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_6', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Of course, there is another person in the car, the driver, but that person is not a passenger per se and resides in the car for the purpose of driving the vehicle.', mt:'当然，车里还有另一个人，司机，但这个人本身不是乘客，他住在车里是为了开车。', ref:'当然，车里还有另外一个人—— 司机，但司机本身并不是乘客； 他/她呆在车里的目的是为了驾驶汽车。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_7', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Various industry stats suggest that the number of occupants in ridesharing cars is around 1.5, which includes the driver.', mt:'各种行业统计数据显示，乘坐公共汽车的人数约为 1.5 人，其中包括司机。', ref:'各种行业统计数据表明，共享出行汽车内的平均乘员人数约为 1.5 人，包括司机。', tags:["准确性"] },
  { k:'seg_2_决赛_8', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'This is a disheartening number and raises uncomfortable questions about the promises of ridesharing.', mt:'这是一个令人沮丧的数字，并对摆脱困境的承诺提出了令人不安的问题。', ref:'这个不尽如人意的数字引发了各界对于共享出行初衷的尖锐质疑。', tags:["准确性"] },
  { k:'seg_2_决赛_9', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Worse too is the aspect that a significant percentage of the travelers have reported via surveys that they would have walked or ridden a bike (around 10% of riders say so), but they were wooed instead to use a ‘ridesharing’ option due to the ease of doing so.', mt:'更糟糕的是，很大一部分旅行者通过调查报告说，他们会步行或骑自行车(大约 10%的骑手这样说)，但由于这样做很容易，他们反而被争取使用“骑自行车”选项。', ref:'更糟的是，各种调查显示有相当比例的出行者原本打算走路或者骑自行车（大约有 10%的乘客是这样说的），但是由于“拼车”太过方便，因此他们纷纷选择了拼车。', tags:["准确性","语言规范","风格"] },
  { k:'seg_2_决赛_10', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'And, worse upon worse, nearly one-third to almost one-half reported that they would have taken a form of mass transit if the ridesharing (ride-hailing) approach wasn’t so readily available and relatively inexpensive.', mt:'更糟糕的是，近三分之一到近一半的人报告说，如果乘坐公共交通工具(搭车)的方法不是那么容易获得并且相对便宜的话，他们会采取公共交通的形式。', ref:'糟糕透顶的是，约三分之一到一半的出行者表示：若非拼车（叫车）服务如此便捷和低廉，他们原本打算乘坐公共交通工具。', tags:["准确性"] },
  { k:'seg_2_决赛_11', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Originally, it was believed that ridesharing might be the so-called “last mile” mechanism to connect people from their homes to mass transit.', mt:'起初，人们认为乘车共享可能是将人们从家中连接到公共交通工具的所谓“最后一英里”机制。', ref:'原本，大家都以为共享出行就是所谓的“最后一英里”机制—— 打通出行者从家中到公共交通站点之间的连接。', tags:["准确性"] },
  { k:'seg_2_决赛_12', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'The idea was that you would have a ridesharing car take you to a bus stop or train station, and you’d continue the remainder of your journey via mass transit.', mt:'这个想法是，你会有一辆拼车带你到公共汽车站或火车站，然后你会通过公共交通继续你剩下的旅程。', ref:'最初的设想是让出行者使用拼车服务抵达公交车站或者火车站， 然后乘坐公共交通工具继续完成剩下的行程。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_13', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'That is not a noticeable outcome of today’s ridesharing services.', mt:'这并不是今天共享服务的显著结果。', ref:'只是，在今天看来，结果并不如人所愿。', tags:["准确性"] },
  { k:'seg_2_决赛_14', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'People are instead undertaking transit substitution, opting toward using ridesharing cars in lieu of other modes of transit.', mt:'相反，人们正在进行交通替代， 选择使用拼车代替其他交通方式。', ref:'大家开始改变自己的出行方式， 纷纷使用拼车服务来取代其他出行工具。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_15', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Who can blame them?', mt:'谁能责怪他们？', ref:'谁又能责怪他们呢？', tags:["准确性"] },
  { k:'seg_2_决赛_16', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'We all relish the single occupancy aspects of driving our own cars, and the next best thing is being the sole passenger in a ridesharing car.', mt:'我们都喜欢驾驶自己的汽车的单人驾驶方面，其次是成为乘坐同一辆车的唯一乘客。', ref:'我们都喜欢一个人独享自己的汽车，而除此之外的第二大美事就是约了拼车服务，但却是车内的唯一乘客。', tags:["准确性"] },
  { k:'seg_2_决赛_17', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'As a result of catering to our desire to travel in our own bubble, the ride-hailing tsunami has not reduced the number of trips that people make, it has not gotten more people to take trips together, and it isn’t saving the earth by polluting less.', mt:'由于迎合了我们在自己的泡泡里旅行的欲望，冰雹海啸并没有减少人们的旅行次数，也没有让更多的人一起旅行，也没有通过减少污染来拯救地球。', ref:'为了满足自己在出行之时享有私人空间的愿望，海量的叫车需求非但没有减少人们的出行数量， 亦没有促使更多的乘客拼车出行，更谈不上减少污染、拯救地球了。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_18', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Arguments are often made that ride-hailing has done the reverse of those good things.', mt:'人们经常争论说打车做了与那些好事相反的事情。', ref:'一个普遍看法是：叫车服务与其美好初衷背道而驰。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_19', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'People are making more trips via cars than they did before (as mentioned, avoiding walking, biking, and mass transit).', mt:'人们开车旅行的次数比以前多了 (如上所述，避免步行、骑自行车和公共交通)。', ref:'大家不再步行、骑自行车或者乘坐公共交通工具。相反，大家乘坐汽车出行的次数比以前更频繁了。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_20', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Short trips that once were done via another mode are now done via a car.', mt:'曾经通过另一种方式进行的短途旅行现在是通过汽车进行的。', ref:'过去通过另一种模式完成的短途出行现在均由汽车代劳了。', tags:["准确性"] },
  { k:'seg_2_决赛_21', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'There is also the sneaky aspect of induced demand too.', mt:'诱导需求也有偷偷摸摸的一面。', ref:'除此之外，更有诱导需求在作祟。', tags:["准确性"] },
  { k:'seg_2_决赛_22', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'With induced demand, people can be induced into traveling more than they would have otherwise traveled before.', mt:'有了诱导需求，人们可以被诱导比以前更多地旅行。', ref:'诱导需求催生了远甚于以往的更多出行需求。', tags:["准确性"] },
  { k:'seg_2_决赛_23', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Suppose you usually went to the grocery store on a once per week basis.', mt:'假设你通常每周去一次杂货店。', ref:'假设你平常每周才去一趟杂货店，', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_24', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'You only went once a week because getting there was a hassle.', mt:'你一周只去一次，因为去那里很麻烦。', ref:'而一周只去一次是因为去那里实在是麻烦得很。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_25', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Now, via the easy of using your smartphone, you can seamlessly request a ridesharing car and travel to the grocery store numerous times per week.', mt:'现在，通过简单易用的智能手机，你可以无缝地申请一辆拼车，每周去杂货店很多次。', ref:'现在，你可以轻轻松松使用智能手机叫来一辆车，每周多次前往杂货店。', tags:["准确性"] },
  { k:'seg_2_决赛_26', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Thus, your one trip per week blossoms to say three or four trips per week.', mt:'因此，你每周一次的旅行可以说是每周三四次。', ref:'如此一来，原本每周一次的出行变成了每周三次或四次的出行。', tags:["准确性"] },
  { k:'seg_2_决赛_27', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'The congestion produced by all these added trips is rather noticeable on our roads, particularly in popular places that are constrained such as a crowded downtown area or an airport pick-up lane.', mt:'所有这些额外的旅行所造成的拥堵在我们的道路上相当明显，特别是在受限制的受欢迎的地方， 如拥挤的市区或机场接送车道。', ref:'所有这些新增的出行次数给道路带来了显而易见的交通拥堵，尤其是在一些通行能力有限的热门目的地，比如车水马龙的市区或者机场的接送车道。', tags:["准确性"] },
  { k:'seg_2_决赛_28', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'From an infrastructure perspective, some analysts indicate that the heightened volume of essentially single- occupancy (just one passenger) of ride-hailing is going to savage our streets and highways, tearing them up by the increased traffic flow, doing so at a faster pace than ever before.', mt:'从基础设施的角度来看，一些分析师指出，基本上单人(只有一名乘客)打车量的增加将会破坏我们的街道和高速公路，使它们被不断增加的交通流量撕裂，速度比以往任何时候都要快。', ref:'一些分析师从基础设施的角度指出：单人独享网约车（仅有一名乘客）现象的日益增长将大量占用我们的街道和公路资源，交通流量激增将令其不堪重负，并且这种形势的恶化速度远甚于以往。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_29', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'All in all, this kind of false ridesharing (merely ride-hailing) is a downer, and something should be done about it.', mt:'总的来说，这种虚假搭车(仅仅是搭车)令人沮丧，应该对此采取措施。', ref:'总而言之，这种虚假的共享出行（目前这种共享方式仅仅算得上是叫车）方式让人深感不安。是时候要采取行动了。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_30', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Voila, one might exclaim, pundits tell us that a solution is indeed on the horizon.', mt:'瞧，有人可能会惊呼，专家们告诉我们，一个解决方案确实在地平线上。', ref:'有人可能会兴奋地提出：那什么，不是有专家说已经有一种近在眼前的解决方案了么？', tags:["准确性","风格"] },
  { k:'seg_2_决赛_31', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Here’s the solution and a probing question about it:', mt:'这是解决办法，也是一个探索性的问题:', ref:'下面我们来讨论这个所谓的解决方案并探讨这样一个问题：', tags:["准确性","语言规范","风格"] },
  { k:'seg_2_决赛_32', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Will true self-driving cars finally bring about ridesharing and overcome the tendency of riders to do only ride-hailing?', mt:'真正的自动驾驶汽车最终会带来搭车并克服骑车人只打车的倾向吗？', ref:'真正的自动驾驶汽车能否最终实现共享出行并化解乘客们喜欢独享网约车的难题？', tags:["准确性","风格"] },
  { k:'seg_2_决赛_33', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Let’s unpack the matter.', mt:'让我们解开这个问题。', ref:'让我们来好好分析一下。', tags:["风格"] },
  { k:'seg_2_决赛_34', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'What Happens With Autonomous Cars', mt:'无人驾驶汽车会发生什么', ref:'自动驾驶汽车会有哪些变化', tags:["准确性"] },
  { k:'seg_2_决赛_35', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'A true self-driving car will not have a human driver since it is instead being driven by the AI system.', mt:'一辆真正的自动驾驶汽车不会有人类驾驶员，因为它是由人工智能系统驱动的。', ref:'真正的自动驾驶汽车没有配备司机，因为它将由人工智能系统负责驾驶。', tags:["准确性"] },
  { k:'seg_2_决赛_36', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Yay!', mt:'耶。', ref:'哇塞！', tags:["准确性"] },
  { k:'seg_2_决赛_37', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'We will henceforth be able to keep track of the number of passengers as its own measure and not need to include any accounting for a human driver.', mt:'从今以后，我们将能够跟踪乘客数量，作为自己的衡量标准，而不需要包括任何对人类驾驶员的统计。', ref:'从今往后，我们将可以直接按乘客人数来追踪客运量情况，根本无需考虑司机这项因素。', tags:["准确性"] },
  { k:'seg_2_决赛_38', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'You might be wondering why the pundits believe that driverless cars will boost the number of passengers per trip.', mt:'你可能想知道为什么专家认为无人驾驶汽车会增加每次旅行的乘客数量。', ref:'你可能会好奇：为什么专家们认为无人驾驶汽车可以增加每趟行程的乘客人数？', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_39', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'One aspect often cited involves the interior space availability of a true self-driving car.', mt:'经常提到的一个方面是真正的自动驾驶汽车的内部空间可用性。', ref:'其中一个最经常提及的原因是自动驾驶汽车的内部可用空间。', tags:["准确性"] },
  { k:'seg_2_决赛_40', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Currently, the tryouts of driverless cars tend to involve a conventional car that has been augmented with self-driving tech capabilities.', mt:'目前，无人驾驶汽车的试用往往涉及一种传统汽车，这种汽车已经通过自动驾驶技术能力得到了增强。', ref:'目前，无人驾驶汽车试验往往采用的是增加了自动驾驶技术功能的传统汽车。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_41', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'There is still a steering wheel, even though the AI doesn’t need it, and likewise there are pedals for braking and acceleration that aren’t needed either (the AI handles the driving controls under-the-hood, one might say).', mt:'尽管人工智能不需要方向盘，但仍然有方向盘，同样也不需要刹车和加速踏板(有人可能会说，人工智能在车下操纵驾驶控制)。', ref:'此类汽车都配备了方向盘以及制动和油门踏板，尽管有人可能会说，人工智能系统可以直接完成驾驶操作，根本不需要这些装置。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_42', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Future designs of driverless cars are envisioned to rip out the driver’s seat and all the driving controls, freeing up the interior of soon to be high-tech cars.', mt:'未来无人驾驶汽车的设计被设想为撕裂驾驶员座椅和所有驾驶控制装置，解放即将成为高科技汽车的内部空间。', ref:'未来，无人驾驶汽车的设计可能会去除司机座椅以及所有的驾驶操控装置，从而将此类即将到来的高科技汽车的内部空间充分释放出来。', tags:["准确性","语言规范","风格"] },
  { k:'seg_2_决赛_43', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'You could put swivel seats into the opened-up space, allowing passengers to face each other or swivel in whatever direction they cared to look.', mt:'你可以把旋转座椅放在敞开的空间里，让乘客面对面，或者朝他们想看的任何方向旋转。', ref:'比如我们可以将旋转座椅安装到释放出来的空间里，让乘客们可以相对而坐，或者随便想看哪个方向就转向哪个方向。', tags:["准确性"] },
  { k:'seg_2_决赛_44', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'In theory, the redesigned seating and openness will encourage more people to ride together.', mt:'理论上，重新设计的座位和开放度将鼓励更多的人一起骑车。', ref:'从理论上讲，重新设计的座椅以及更加宽敞的空间将促使更多人一同乘车。', tags:["准确性"] },
  { k:'seg_2_决赛_45', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'I’ll be skeptical about that because even if you can build it, you can’t assume that people will use it in the manner you dream of.', mt:'我对此持怀疑态度，因为即使你能建造它，你也不能假设人们会以你梦想的方式使用它。', ref:'不过对此我持怀疑态度，因为就算造出了这样的汽车，也不能保证乘客一定就会按你设想的方式去使用它。', tags:["准确性"] },
  { k:'seg_2_决赛_46', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'All that openness could potentially go to waste.', mt:'所有这些开放都可能被浪费掉。', ref:'如此一来，这些腾出来的空间就被白白浪费掉了。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_47', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Furthermore, some designs are incorporating seats that layout into beds, allowing you to catch a nap while heading to work.', mt:'此外，一些设计将座椅布局整合到床上，让你在上班时小睡一会儿。', ref:'此外，有些设计可以将座椅变成床，让你在上班路上可以小憩片刻。', tags:["准确性"] },
  { k:'seg_2_决赛_48', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'The seat-into-bed aspect could make a single occupant that much happier to have the space to stretch out and catch some needed shuteye.', mt:'坐在床上的姿势可以让一个单独的居住者更乐意有空间伸展出去，睡上一觉。', ref:'座椅变床的这个功能可以让独乘的乘客更为满意，因为这样他/她可以有地方舒展手脚，补上一觉。', tags:["准确性"] },
  { k:'seg_2_决赛_49', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'If so, you certainly don’t want a noisy or annoying fellow passenger that’s going to undermine your catnap.', mt:'如果是这样的话，你当然不希望一个吵闹或烦人的乘客会破坏你的午睡。', ref:'倘若如此，你肯定不希望车上还有一位吵闹或烦人之士扰了你的清梦。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_50', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Some believe that you’ll be working in your driverless car, doing so throughout the day.', mt:'有些人相信你会整天开着无人驾驶汽车工作。', ref:'还有一些人认为我们届时可以全天都呆在无人驾驶汽车里工作，', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_51', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'You’ll do so with work colleagues, all of you sitting in the swivel seats, perhaps arrayed around a small worktable, and be heading to various company offices, warehouses, and other locales.', mt:'你将和同事们一起这样做，你们都坐在旋转的座位上，也许排列在一个小工作台周围，前往公司的各个办公室、仓库和其他地方。', ref:'比如与同事一起坐在舒适的旋转座椅上，或许还可以配上一个小小的工作台，然后一起坐车前往不同的公司办公室、仓库或者其他地方。', tags:["准确性"] },
  { k:'seg_2_决赛_52', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'One question to ask about these changes in passenger habits is whether this is going to take the place of existing trips or will it be more akin to induced demand that expands the number of trips?', mt:'关于乘客习惯的这些变化，有一个问题要问，这是将取代现有的旅行，还是更类似于增加旅行次数的诱导需求？', ref:'针对乘客出行习惯上的这些变化，有一个重要的问题是：这种出行方式究竟是将取代现有的出行方式，还是更像是诱导需求从而推高了人们的出行次数？', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_53', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Nobody knows.', mt:'没人知道。', ref:'没有人知道答案。', tags:["准确性"] },
  { k:'seg_2_决赛_54', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Conclusion', mt:'结论', ref:'结论', tags:[] },
  { k:'seg_2_决赛_55', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'An especially significant factor concerning the conundrum of ridesharing versus ride-hailing for self-driving cars will be the cost of riding in the driverless car.', mt:'对于无人驾驶汽车来说，乘坐公交车和打车这两个难题中一个特别重要的因素是乘坐无人驾驶汽车的成本。', ref:'决定人们是采用拼车还是叫车形式来使用自动驾驶汽车的重要因素无疑是无人驾驶汽车的乘坐成本。', tags:["准确性"] },
  { k:'seg_2_决赛_56', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Today’s human-driven ridesharing services are relatively inexpensive, partially due to the ridesharing services eating a chunk of the cost and wanting to build market share over profit right now.', mt:'今天的人工驾驶共享服务相对便宜，部分原因是共享服务消耗了很大一部分成本，并且希望现在就在利润之上建立市场份额。', ref:'眼下，人工驾驶的拼车服务相对低廉，部分原因在于拼车服务提供商自己承担了一大部分成本， 他们希望赢得更多市场份额，而非急着马上盈利。', tags:["准确性"] },
  { k:'seg_2_决赛_57', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Nobody is sure what the cost per ride or per mile will be to use a true self-driving car.', mt:'没有人知道使用一辆真正的自动驾驶汽车每骑一程或每英里要花多少钱。', ref:'没有人知道在乘坐真正的自动驾驶汽车之时，每趟出行或者每英里的成本是多少。', tags:["准确性"] },
  { k:'seg_2_决赛_58', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'If the cost is relatively high, it would presumably shift people toward sharing rather than riding alone.', mt:'如果成本相对较高，人们可能会转向分享而不是独自骑车。', ref:'如果成本相对较高，则乘客们将会倾向于共享乘坐，而非独享。', tags:["准确性"] },
  { k:'seg_2_决赛_59', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Passengers might be willing to put up with the lack of privacy and the doldrums of being around other people, doing so to share the cost of using a driverless car.', mt:'乘客可能愿意忍受缺乏隐私和与他人相处的沉闷，这样做是为了分担使用无人驾驶汽车的费用。', ref:'乘客们届时可能愿意为了分担乘车费用，而忍受没有隐私以及周边塞满陌生人的乘车环境。', tags:["准确性"] },
  { k:'seg_2_决赛_60', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'There is an interesting calculus involved in this matter.', mt:'这件事牵涉到一个有趣的演算。', ref:'这个选择将涉及到一项颇有意思的数学运算：', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_61', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'It is important to realize that self- driving cars will not suddenly overtake the existing population of cars.', mt:'重要的是要认识到自动驾驶汽车不会突然超过现有的汽车数量。', ref:'自动驾驶汽车的数量不会一下子超过现有汽车的数量，意识到这点很重要。', tags:["准确性"] },
  { k:'seg_2_决赛_62', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'In the United States alone there are 250 million conventional cars, and those cars aren’t going to disappear overnight.', mt:'仅在美国就有 2.5 亿辆传统汽车，这些汽车不会在一夜之间消失。', ref:'仅在美国就有 2.5 亿辆传统的人工驾驶汽车，这些汽车不会在一夜之间消失殆尽。', tags:["准确性"] },
  { k:'seg_2_决赛_63', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'In short, there will be a mixture of human-driven cars and driverless cars, which will gradually and inexorably likely shift over time toward more and more driverless cars.', mt:'简而言之，人类驾驶的汽车和无人驾驶的汽车将会混合在一起， 随着时间的推移，这种混合可能会逐渐不可阻挡地转向越来越多的无人驾驶汽车。', ref:'简而言之，届时人工驾驶汽车和自动驾驶汽车将会在路上并驾齐驱，直至随着时间的推移，前者不可避免地被后者所渐渐取代。', tags:["准确性"] },
  { k:'seg_2_决赛_64', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Meanwhile, you’ll be able to make a reasoned choice, namely do you use the self-driving car or a human-driven car for your ridesharing trips?', mt:'与此同时，你将能够做出一个合理的选择，那就是你是使用自动驾驶汽车还是人力驾驶汽车出行？', ref:'同时，你将能够做出合理的选择：在拼车出行之时，究竟是选择自动驾驶的汽车，还是选择人工驾驶的汽车？', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_65', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'At first, people might be enamored of self-driving cars and seek to use a driverless car whenever they utilize ridesharing.', mt:'起初，人们可能会迷恋自动驾驶汽车，并在使用无人驾驶汽车时寻求使用无人驾驶汽车。', ref:'一开始，大家可能会对自动驾驶汽车趋之若鹜，在使用拼车服务之时尽可能地选择无人驾驶汽车。', tags:["准确性","风格"] },
  { k:'seg_2_决赛_66', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'My guess is that the initial excitement and novelty will wear- off.', mt:'我猜想最初的兴奋和新奇感将会消失。', ref:'我的猜测是：在最初的兴奋劲和新鲜感褪去之后，', tags:["准确性"] },
  { k:'seg_2_决赛_67', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'At that point, the cost will loom as the crucial factor (in essence, at first, the cost might be acceptably high, since people are getting the thrill of being inside a driverless car, part of the bargain for the heightened price).', mt:'到那时，成本将成为关键因素(本质上，首先，成本可能高得可以接受，因为人们正从无人驾驶汽车中获得快感，这是提高价格的一部分)。', ref:'乘坐成本将成为一项重要的考虑因素。实质上，最初的乘坐成本可能会居高不下，因为大家都争先恐后地要去体验一把无人驾驶汽车，导致价格水涨船高。', tags:["准确性"] },
  { k:'seg_2_决赛_68', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Passengers will eventually be considering the day-to-day trade- off aspects of using an AI-driven car versus a human-driven car and assuming all else being equal, the cost might be the final arbiter.', mt:'乘客们最终会考虑使用人工智能汽车和人工驾驶汽车的日常权衡，假设所有其他因素都相同， 成本可能是最终的仲裁者。', ref:'最终，乘客每天将不得不在自动驾驶汽车与人工驾驶汽车之间加以权衡。在所有其他乘坐条件并无二致的前提下，乘坐成本将可能成为最终的决定因素。', tags:["准确性"] },
  { k:'seg_2_决赛_69', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Indeed, some pundits decry that self-driving cars will be only used by elites that can afford to do so.', mt:'事实上，一些专家谴责自动驾驶汽车只会被有能力的精英使用。', ref:'正如一些专家所批判的，最终可能只有一些精英群体才能坐得起自动驾驶汽车。', tags:["准确性"] },
  { k:'seg_2_决赛_70', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'If we wave a magic wand and get people to behave and ride in driverless cars with their fellow humans, it might be possible to arrive at a vaunted modernized Average Vehicle Occupancy (AVO) of say 2, meaning that the average number of passengers has reached two (no drivers, two actual passengers).', mt:'如果我们挥动一根魔杖，让人们和他们的同伴一起驾驶无人驾驶汽车，就有可能达到一个吹嘘的现代化平均车辆占用率，比如说 2，这意味着平均乘客人数已经达到两人(没有司机，只有两个真正的乘客)。', ref:'假如我们可以挥动魔法棒，让所有人都规规矩矩地与他人共享无人驾驶汽车，则我们的平均车辆占用率（AVO）将达到 2，即宣传的现代化水平，这表示车辆平均乘员人数达到 2 人（不含驾驶员，而是实际搭载两名乘客）。', tags:["准确性","语言规范","术语","风格"] },
  { k:'seg_2_决赛_71', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'This would be astounding since it would mean that in the aggregate, we would have to also counterbalance the rides of solo passengers by a like number of rides with three or more passengers.', mt:'这将是令人震惊的，因为这将意味着，总的来说，我们还将不得不通过同样数量的三个或更多乘客的乘坐来平衡单人乘客的乘坐。', ref:'这一结果是惊人的，因为从总体上讲，为了平衡那些独享汽车的乘客，我们需要在同等数量的共享出行汽车内塞入三位或三位以上乘客。', tags:["准确性"] },
  { k:'seg_2_决赛_72', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Can we do it?', mt:'我们能做到吗？', ref:'我们能做到吗？', tags:[] },
  { k:'seg_2_决赛_73', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'I’d like to hope so, but it’s probably not worth holding your breath over, since people will be people, and unless we undergo a dramatic cultural shift, it sure seems that people like to ride on their own.', mt:'我很希望如此，但这可能不值得你屏住呼吸，因为人就是人，除非我们经历一场戏剧性的文化转变，否则人们似乎肯定喜欢自己骑车。', ref:'但愿如此！不过，人类的习惯是很难改变的，我们不必对此抱有太大的期望。除非我们经历了一场翻天覆地的文化变革，否则大家肯定还是喜欢独享汽车。', tags:["准确性","语言规范"] },
  { k:'seg_2_决赛_74', ed:'2', stage:'决赛', dir:'英译汉', eng:'搜狗翻译', src:'Just them and their friendly AI driver.', mt:'只有他们和他们友好的人工智能驱动。', ref:'也就是说，车上只有他们自己以及那位十分友好的人工智能“司机”。', tags:["准确性"] },
  { k:'seg_3_决赛_1', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Addressing E-Payment Challenges in Global E-Commerce', mt:'', ref:'纾解全球电子商务中的电子支付难题', tags:[] },
  { k:'seg_3_决赛_2', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Digital trade is more important than ever.', mt:'', ref:'线上贸易比以往任何时候都更为重要。', tags:[] },
  { k:'seg_3_决赛_3', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'While the COVID-19 crisis has cast a long shadow over the future of international trade in traditional goods and services, it has also demonstrated the resilience of a digitized economy and will accelerate the digital transformation of the global economy in the coming years.', mt:'', ref:'虽然新冠疫情令传统商品和服务的国际贸易前景黯淡，但它亦彰显出数字化经济的韧性， 将在未来几年加快全球经济的数字化转型。', tags:[] },
  { k:'seg_3_决赛_4', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Digital payments are at the centre of this transformation, connecting merchants and consumers around the world and enabling new avenues for global commerce.', mt:'', ref:'作为这一转型的核心所在，数字支付将把全球商家和消费者紧密地联系在一起，为全球商贸开辟崭新的舞台。', tags:[] },
  { k:'seg_3_决赛_5', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Digital payments are at the centre of digital trade', mt:'', ref:'数字支付是数字贸易的重头戏', tags:[] },
  { k:'seg_3_决赛_6', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Today, merchants of varying sizes caneasily sell products to consumers around the world.', mt:'', ref:'如今，大大小小的商家都可以轻轻松松将商品卖给世界各地的消费者。', tags:[] },
  { k:'seg_3_决赛_7', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As cross-border e-commerce expands rapidly, it is increasingly becoming an important component of international trade.', mt:'', ref:'风生水起的跨境电商正在日益成为国际贸易领域的生力军。', tags:[] },
  { k:'seg_3_决赛_8', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The current COVID-19 crisis will likely accelerate this expansion, as trade in goods and physical commerce retreat and digital services advance.', mt:'', ref:'当前的新冠疫情导致商品贸易和实体商业陷入困境，而各种数字服务却如雨后春笋般涌现，从而进一步促进了跨境电商的发展与壮大。', tags:[] },
  { k:'seg_3_决赛_9', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Digital payments are at the centre of digital trade growth and serve as the key enabling factor for digital commerce.', mt:'', ref:'在数字贸易的发展之路上，数字支付无疑是重中之重，是数字商务的关键增长引擎。', tags:[] },
  { k:'seg_3_决赛_10', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The rapid expansion of access to digital payments has made it possible for consumers to conveniently make purchases for goods and services from merchants globally – and for merchants to sell to the world far more easily and cheaply than ever before.', mt:'', ref:'各种数字支付方式的迅速普及令消费者可以十分便利地从全球商家手中购买琳琅满目的商品和服务，而商家亦能以比过去更轻松的方式以及更便宜的价格向全世界的消费者兜售他们的商品和服务。', tags:[] },
  { k:'seg_3_决赛_11', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'With a few clicks and identity verification, consumers and merchants can set up accounts to send or receive money worldwide.', mt:'', ref:'无论是消费者还是商家，都只需几步点击即可完成身份验证，创建“汇通全球”的付款或收款账户。', tags:[] },
  { k:'seg_3_决赛_12', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In addition to enabling cross-border digital commerce, a growing body of research suggests digital payments are important to the health of the broader domestic economy.', mt:'', ref:'除了促进跨境电商的蓬勃发展以外，越来越多的研究表明数字支付亦有助于维持整个国内经济的健康发展。', tags:[] },
  { k:'seg_3_决赛_13', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Recent studies have shown that digital payments overall increase economic efficiency, reduce crime and corruption, and support transitions away from the informal economy.', mt:'', ref:'最近的几项研究表明数字支付总体上提高了经济效率，减少了犯罪和腐败，促进了非正规经济的转型。', tags:[] },
  { k:'seg_3_决赛_14', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For instance, a 2017 Moody’s Analytics study estimates that digital payment usage “contributed an additional $296 billion to consumption between 2011 and 2015, or a 0.1% cumulative increase in global GDP during the sample time period”.', mt:'', ref:'例如，根据穆迪分析 2017 年开展的一项研究 ， 数字支付的应用“在 2011 年至 2015 年期间贡献了额外 2,960 亿美元的消费额，相当于同一时期内全球 GDP 累计增长了 0.1%”。', tags:[] },
  { k:'seg_3_决赛_15', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Despite the importance of digital payments to cross-border commerce, significant logistical and governance challenges persist.', mt:'', ref:'虽然数字支付对于跨境电商的重要性不言而喻，但种种重大的组织和治理挑战仍未得到解决。', tags:[] },
  { k:'seg_3_决赛_16', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As more businesses and consumers adopt digital payments, policy-makers and regulators have an important role in ensuring payment services remain competitive, seamless and secure.', mt:'', ref:'随着越来越多的商家和消费者使用数字支付，决策者和监管机构在确保支付服务的竞争力、无缝性和安全性方面所发挥的重要作用开始日益凸显。', tags:[] },
  { k:'seg_3_决赛_17', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'While the digital world is theoretically borderless, national and regional boundaries have not gone away.', mt:'', ref:'虽然理论上数字世界并无疆界，但国家和地区之间的边界犹在。', tags:[] },
  { k:'seg_3_决赛_18', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Restrictions on the international supply, use and availability of e-payment services are among the challenges to global e-commerce.', mt:'', ref:'电子支付服务在国际化发展、使用以及可及性方面受到的限制是全球电商行业所面临的挑战之一。', tags:[] },
  { k:'seg_3_决赛_19', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Increasingly, governments are establishing significant market barriers affecting payment service providers, often in the name of security and privacy concerns.', mt:'', ref:'越来越多的国家正在以安全和隐私问题为由筑起一道道意在钳制支付服务提供商的重大市场壁垒。', tags:[] },
  { k:'seg_3_决赛_20', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'WTO member commitments under GATS on payment services are limited and patchy.', mt:'', ref:'在《服务贸易总协定》当中，世贸组织成员国针对支付服务给出的承诺不仅颇为有限， 而且还参差不齐。', tags:[] },
  { k:'seg_3_决赛_21', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This report analyses three key types of barriers to payment services before providing best practices and recommendations for policy-makers on how to improve the role of payment services in global trade.', mt:'', ref:'本报告首先分析了支付服务所面对的三大主要壁垒，随后就如何改善支付服务在全球贸易中所发挥的作用向决策者提供了各种优质实践和建议。', tags:[] },
  { k:'seg_3_决赛_22', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Domestic infrastructure / processing requirements', mt:'', ref:'国内平台基建/处理规则', tags:[] },
  { k:'seg_3_决赛_23', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Many countries are enacting indirect barriers to foreign payment providers via rules about how and where payment transactions can (or cannot) be processed.', mt:'', ref:'许多国家都通过制定与支付交易处理方式及处理地点相关的种种规则对外国支付服务商构筑起间接壁垒。', tags:[] },
  { k:'seg_3_决赛_24', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Some countries are enacting laws that require all domestic transactions to be processed by a single local “switch”, which is a processer that facilitates communication between various providers involved in processing a transaction.', mt:'', ref:'一些国家正在颁布有关法律，要求所有的国内交易都必须通过一个境内“交换平台”处理由， 该平台负责转发交易处理过程中所涉及的各家服务商之间的通信数据。', tags:[] },
  { k:'seg_3_决赛_25', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Often these requirements are motivated by the belief that these barriers are necessary to support the domestic financial services sector, to provide lower cost options to expand access, or to increase security through direct regulatory oversight of the payment system.', mt:'', ref:'通常而言，各国构筑该等壁垒的目的在于扶持本国金融服务部门，提供更低成本的准入选择，或者通过直接监管支付系统的方式来提高支付安全性。', tags:[] },
  { k:'seg_3_决赛_26', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Similarly, some countries require that all domestic transactions be processed onshore.', mt:'', ref:'同样，还有一些国家要求所有的国内交易都必须在境内处理。', tags:[] },
  { k:'seg_3_决赛_27', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This, like forcing firms to use local switches, is another way to create an unlevel playing field, as these regulations force international payment networks to duplicate their global capabilities in-market by building a local data centre or simply exclude them from processing domestic transactions.', mt:'', ref:'就像强迫国际支付服务商使用本国“交换平台”一样，此举亦是另一种创建不公平竞争环境的手段，因为这些规定强迫国际支付服务商建立本地数据中心，以便在本土市场复制其全球业务，或者干脆不允许国际支付服务商处理国内交易。', tags:[] },
  { k:'seg_3_决赛_28', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Examples of countries enacting local processing requirements are far-reaching.', mt:'', ref:'要求在本国处理交易的国家为数不少。', tags:[] },
  { k:'seg_3_决赛_29', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2011, Nigeria’s Central Bank introduced a measure that requires all domestic point-of-sale, ATM and digital transactions to be processed locally.', mt:'', ref:'2011 年尼日利亚中央银行就公布了一项举措，要求所有通过国内 POS 机、ATM 以及互联网实施的交易都必须在境内处理。', tags:[] },
  { k:'seg_3_决赛_30', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2014 and 2016, the Russian Federation enacted new payment system laws that force international payment providers that want to operate in the country to transfer their processing capabilities with respect to their domestic operations to a local state-owned operator.', mt:'', ref:'俄罗斯联邦分别于 2014 年和 2016 年颁布了新的支付体系法律，强迫那些有意在俄罗斯开展业务的国际支付服务商将其在俄交易处理业务转移给一家本土国有运营商。', tags:[] },
  { k:'seg_3_决赛_31', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Indonesia has enacted new rules that effectively prohibit foreign firms from playing a role in domestic payments, as part of its initiative for a domestic payment gateway.', mt:'', ref:'为了促进本土支付网关的使用，印度尼西亚亦颁布了新的规则，', tags:[] },
  { k:'seg_3_决赛_32', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The new rules require all domestic electronic (i.e. non-cash) transactions to be stored locally and processed through this domestic gateway provider.', mt:'', ref:'要求所有的境内电子交易（即非现金交易）都必须在境内存档并通过一家本土支付网关运营商进行处理，从而有效封上了外国公司进军本国支付市场的通道。', tags:[] },
  { k:'seg_3_决赛_33', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Forced data localization', mt:'', ref:'强制性数据本地化存储', tags:[] },
  { k:'seg_3_决赛_34', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Local data storage requirements – known as data localization – act as a barrier to market entry and operations for payment service providers.', mt:'', ref:'数据本地化存储要求（简称“数据本地化”）已成为支付服务提供商进军各国市场以及拓展业务之路上的绊脚石。', tags:[] },
  { k:'seg_3_决赛_35', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'These requirements hinder cross-border payment services because data is essential in every step of transaction processing.', mt:'', ref:'跨境支付服务因此项要求而备受掣肘，因为在交易处理的每个步骤，数据都是不可或缺的。', tags:[] },
  { k:'seg_3_决赛_36', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The supply of payment services often requires the cross-border flow of data, not only in settling cross-border transactions, but also in purely domestic transactions, when both the merchant and the consumer are located in the same market but the processing of the transaction (or parts of it) are carried out elsewhere.', mt:'', ref:'支付服务的提供通常都涉及到数据的跨境传输，不仅跨境交易的结算是如此，纯国内交易的结算亦然如是。在后一种情形下，虽然商家和消费者都来自同一个国家，但整个交易（或其一部分）的处理则需要在其他国家进行。', tags:[] },
  { k:'seg_3_决赛_37', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Countries enact data localization in response to technological innovation for a variety of well-intentioned but misguided reasons, such as to address privacy and cybersecurity concerns, to allow their government’s access to payment data, and to encourage domestic industries and economic growth.', mt:'', ref:'各国施行数据本地化规定的原因不一而足， 例如为了化解隐私和网络安全难题、为了让本国政府可以访问支付数据，以及为了促进国内产业和经济的增长等等 —— 虽然初衷良好，但或有被误导之虞。', tags:[] },
  { k:'seg_3_决赛_38', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'However, a growing body of research suggests that data localization fails to achieve many of these goals and adds significant costs to the local economy, reduces data security and does not improve consumer privacy.', mt:'', ref:'然而，越来越多的研究表明，数据本地化并不能帮助各国政府实现其所预期的多项目标，反而会给本国经济陡增出巨大的成本， 降低数据安全性，并且无助于改善消费者的隐私。', tags:[] },
  { k:'seg_3_决赛_39', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Some recent examples of data localization illustrate how countries are restricting the movement and storage of data.', mt:'', ref:'近年来颁布的一些数据本地化规定就可以让我们一窥各国如何限制数据的流动和存储。', tags:[] },
  { k:'seg_3_决赛_40', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2013, Turkey enacted a law requiring firms to maintain documents, records, data storage and processing facilities in Turkey for 10 years.', mt:'', ref:'2013 年，土耳其颁布了一项法律，要求企业在土耳其境内维持十年的文件、记录及数据存储和处理设施。', tags:[] },
  { k:'seg_3_决赛_41', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Turkey refused to grant a licence to foreign payment firms that failed to store data locally, subsequently causing some to withdraw their services from Turkey.', mt:'', ref:'土耳其拒绝向那些未能在本地存储数据的外国支付公司发放牌照，进而导致一些支付公司从土耳其撤出。', tags:[] },
  { k:'seg_3_决赛_42', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2018, the Reserve Bank of India issued rules that required payment service firms to store all transaction data locally.', mt:'', ref:'2018 年，印度储备银行发布了有关规定，要求支付服务公司在印度境内存储所有的交易数据。', tags:[] },
  { k:'seg_3_决赛_43', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For cross-border transactions, a copy of the domestic component may also be stored abroad but, if data is processed outside of India, the data will only be stored in India afterwards.', mt:'', ref:'对于跨境交易，国内交易方的副本允许在国外存储；但是，如果数据是在印度境外处理的话，则该等数据以后只能在印度存储。', tags:[] },
  { k:'seg_3_决赛_44', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Licensing and equity requirements for foreign firms', mt:'', ref:'外国公司的牌照和持股比例要求', tags:[] },
  { k:'seg_3_决赛_45', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Countries are also using restrictive licensing and equity requirements to limit the cross-border supply of payments in their markets.', mt:'', ref:'各国亦会采取限制性牌照以及持股比例要求等手段来限制本国市场中的跨境支付。', tags:[] },
  { k:'seg_3_决赛_46', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Policy-makers do this for many reasons, such as to use forced joint ventures to help local firms become more competitive and as an outdated way to ensure oversight of local firms.', mt:'', ref:'决策者做出此举往往出于各种各样的原因， 例如强制成立合资企业以帮助本土公司提高竞争力，而此举亦是一种确保对本土公司进行有效监管的老套路。', tags:[] },
  { k:'seg_3_决赛_47', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'However, these requirements often have unintended consequences, including reduced foreign direct investment and access to products and services from payment companies, both of which have implications for cross-border payment efficiency.', mt:'', ref:'然而，这些要求通常会导致各种意想不到的后果，包括外国直接投资的下滑以及获得外国支付公司提供的产品和服务的机会减少， 这两者都会影响到跨境支付的效率。', tags:[] },
  { k:'seg_3_决赛_48', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Equity regulations requiring that a local entity maintain a majority share are particularly obstructive to cross-border payment services.', mt:'', ref:'要求本国股东拥有多数股份的持股比例规定更是严重阻碍了跨境支付服务的发展。', tags:[] },
  { k:'seg_3_决赛_49', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'A few recent examples demonstrate the extent of equity requirements and their level of severity.', mt:'', ref:'我们可以通过各国近年来颁布的一系列相关法规了解到具体的持股比例要求及其严苛程度。', tags:[] },
  { k:'seg_3_决赛_50', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2019, Ghana enacted the Payment Systems and Services Act, which among other things sets out the requirements to obtain a payment systems operator licence.', mt:'', ref:'加纳于 2019 年颁布了《支付系统和服务法》 ， 对取得支付系统运营商牌照的先决条件做出了具体规定，', tags:[] },
  { k:'seg_3_决赛_51', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In particular, it calls for firms to establish a local entity, at least 30% local ownership, and a board of directors that includes at least three Ghanaians (one of which must be the CEO).', mt:'', ref:'尤其是要求支付公司成立一家加纳籍股东至少持有 30%股权的当地实体，并且董事会至少包含三名加纳籍董事（其中一名董事必须是首席执行官）。', tags:[] },
  { k:'seg_3_决赛_52', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Similarly, in Indonesia, critical players in the payment network must be appointed or approved by the central bank and must be 80% domestically owned.', mt:'', ref:'同样，在印度尼西亚，支付市场中的关键主体必须由中央银行指定或批准，并且印尼籍股东必须持有 80%的股权。', tags:[] },
  { k:'seg_3_决赛_53', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Recommendations:', mt:'', ref:'建议：', tags:[] },
  { k:'seg_3_决赛_54', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Best practices, initiatives and next steps', mt:'', ref:'最佳做法、举措以及下一步', tags:[] },
  { k:'seg_3_决赛_55', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Current market barriers need to be reduced to improve cross-border payment efficiency and decrease costs and access constraints for local markets.', mt:'', ref:'我们亟需放宽眼下的入市壁垒，以便提高跨境支付效率、降低相关成本、减少各国市场的准入限制。', tags:[] },
  { k:'seg_3_决赛_56', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'New trade rules for digital payments could make this happen, and safeguarding the cross-border supply of payments in order to help innovative FinTech companies to scale globally will be critical for future trade discussions.', mt:'', ref:'与数字支付相关的全新贸易规则有望帮助我们实现以上目标。保障跨境支付服务的提供极有可能成为未来贸易谈判的重心，籍此帮助创新型金融科技企业进入全球市场。', tags:[] },
  { k:'seg_3_决赛_57', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Provide, reinforce and/or extend “national treatment” for digital payment service providers', mt:'', ref:'为数字支付服务商提供、加强以及/或者拓展“国民待遇”', tags:[] },
  { k:'seg_3_决赛_58', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'At the most fundamental level, countries should provide (or reinforce) the basic WTO principle that they treat domestic and foreign payment services and service suppliers the same – known as national treatment – and ensure that this applies to the various modes of supply in their payment services commitments in trade agreements.', mt:'', ref:'在最基本的层面上，各国应当在贸易协议中的支付服务承诺部分体现（或者加强）世界贸易组织的以下基本原则——对本土和外国支付服务以及服务提供商一视同仁（即提供“国民待遇”），并确保此种国民待遇亦适用于各种服务提供模式。', tags:[] },
  { k:'seg_3_决赛_59', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This is in addition to the even more foundational step that countries should take in providing meaningful payment service market access.', mt:'', ref:'这应当是各国在提供有意义的支付服务市场准入过程中所采取的更为基础性举措之外的补充。', tags:[] },
  { k:'seg_3_决赛_60', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As more countries make these commitments, it will be more difficult for local markets to establish discriminatory measures that undermine the competitiveness of the payment sector.', mt:'', ref:'随着越来越多的国家做出此项承诺，各国政府将更加难以出台那些有损支付公司竞争力的歧视性政策。', tags:[] },
  { k:'seg_3_决赛_61', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Furthermore, the WTO dispute settlement system has demonstrated that current agreements provide protection against discriminatory measures on the cross-border supply of financial services, such as the GATS Annex on Financial Services, and therefore should be enforced.', mt:'', ref:'此外，世界贸易组织的争端解决制度表明， 现有协定大都禁止针对跨境金融服务制定歧视性的政策（例如《服务贸易总协定》的金融服务附件），因此该等规定都应得到执行 。', tags:[] },
  { k:'seg_3_决赛_62', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Support commitments to protect the free flow of data while ensuring regulatory access to data', mt:'', ref:'做出关于保护数据自由流动、同时确保对数据具有监管访问权的具体承诺', tags:[] },
  { k:'seg_3_决赛_63', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'To upend data localization and reduce cross-border payment friction, specific commitments prohibiting data localization requirements are needed in future WTO and regional trade agreements.', mt:'', ref:'为了彻底消灭数据本地化并减少跨境支付摩擦，在未来的世界贸易组织协定以及各个区域性贸易协议当中，各国需要做出关于摒除数据本地化规定的具体承诺。', tags:[] },
  { k:'seg_3_决赛_64', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The United States–Mexico–Canada (USMCA) trade agreement, which provides explicit, detailed protections for the free flow of data and prohibitions on data localization in the financial services chapter, serves as a model for agreements on digital trade.', mt:'', ref:'《美国、墨西哥和加拿大贸易协定》在“金融服务”一章中为数据自由流动提供了明确而详尽的保护，并禁止协约国出台任何数据本地化规定，堪称所有数字贸易协议可仿效之样板。', tags:[] },
  { k:'seg_3_决赛_65', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The USMCA’s financial services chapter also applies explicit national treatment to payments and market access to firms from other parties.', mt:'', ref:'该《协定》在“金融服务”章节中还规定各协约国应当对其他两国企业提供支付活动和市场准入方面的国民待遇，', tags:[] },
  { k:'seg_3_决赛_66', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'These include payments via credit cards, charge cards, debit cards, travelers cheques and bankers drafts, but not securities transactions.', mt:'', ref:'包括通过信用卡、记账卡、借记卡、旅行支票以及银行汇票进行付款（证券交易除外） 。', tags:[] },
  { k:'seg_3_决赛_67', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The USMCA also provides a clear framework to allow the free flow of data, while ensuring parties have regulatory access to data.', mt:'', ref:'《协定》亦提供了一个清晰的框架—— 允许数据自由流动，同时确保各协约国对数据具有监管访问权。', tags:[] },
  { k:'seg_3_决赛_68', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This is an important development as many policy-makers try to justify data localization on the belief that it is necessary to ensure a government’s access to the data.', mt:'', ref:'这是一项重要的进步，因为多个国家出台数据本地化规定的共同理由之一就是为了确保政府对数据的访问权。', tags:[] },
  { k:'seg_3_决赛_69', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Explore creating regional payment councils to bring the public and private sectors together', mt:'', ref:'探索成立区域性支付委员会，以促进公私部门之间的合作', tags:[] },
  { k:'seg_3_决赛_70', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The barriers outlined above start as well intentioned policies but have many unintended consequences.', mt:'', ref:'上述种种壁垒虽然一开始都是初衷甚好，但往往导致了各种意想不到的后果。', tags:[] },
  { k:'seg_3_决赛_71', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'To address some of these barriers’ initial policy goals, such as ensuring local economic development and data privacy and security, some countries and regions are establishing payment councils to create a public-private dialogue on payment policy issues.', mt:'', ref:'为了实现其中某些壁垒的最初政策目标（例如确保本国经济发展以及保护数据隐私和安全），一些国家和地区正在成立各种支付委员会，以便就支付政策问题展开公私对话。', tags:[] },
  { k:'seg_3_决赛_72', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Moving beyond domestic payment councils, recent public- and private-sector collaboration in ASEAN could be a good model for regional cooperation on payments.', mt:'', ref:'除了在本国成立支付委员会以外，东盟新近开展的公私合作亦可谓是区域性支付合作的优秀典范。', tags:[] },
  { k:'seg_3_决赛_73', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN is a dynamic and techsavvy region, but its members have differential and sometimes conflicting rules and regulations for payments.', mt:'', ref:'东盟是一个充满活力并且科技氛围浓厚的地区，但其成员国制定的支付法律和法规却是五花八门，有时甚至相互冲突。', tags:[] },
  { k:'seg_3_决赛_74', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Like most other regions, there is no cross-border payment system in ASEAN.', mt:'', ref:'与大多数其他地区一样，东盟亦没有任何跨境支付系统。', tags:[] },
  { k:'seg_3_决赛_75', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'However, ASEAN has made the integration of the region’s digital market a top economic priority and has recognized the importance of improving cross-border payments.', mt:'', ref:'但是，东盟已将本地区的数字市场整合视为第一经济要务，并已充分认识到改善跨境支付的重要性。', tags:[] },
  { k:'seg_3_决赛_76', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'To assist the ASEAN Secretariat in these efforts, the World Economic Forum launched a public-private initiative called the ASEAN e-Payments Coalition, which is working with the ASEAN Working Committee on Payment and Settlement Systems (made up of central bank representatives) to develop a regional payment framework that improves user payment experiences, promotes regional integration, increases trust and security, and improves the livelihoods of the underbanked.', mt:'', ref:'为了协助东盟秘书处开展此项工作，世界经济论坛发起了一项名为“东盟电子支付联盟”的公私合作倡议。东盟电子支付联盟目前正在与由东盟各国央行代表组成的东盟支付和结算系统工作委员会共同起草一份区域性支付框架。该框架将有望改善用户的支付体验促、 进区域融合、加强信任度和安全性、改善银行服务低覆盖群体的生计。', tags:[] },
  { k:'seg_3_决赛_77', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This model could also be adopted internationally, especially for intergovernmental organizations focused on financial services, such as the Bank for International Settlements (BIS).', mt:'', ref:'该模式亦可以在国际上推广，并且尤其适用于那些专注于金融服务的政府间组织，例如国际清算银行（BIS）。', tags:[] },
  { k:'seg_3_决赛_78', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Together, these proposals reinforce the basic foundations and architecture of the WTO, while adding new rules and regulatory best practices for an updated, open and competitive payment services framework.', mt:'', ref:'所有这些建议将进一步巩固世界贸易组织的基石和架构，同时为一个日新月异、开放包容以及无出其右的支付服务框架添加新的规则以及监管方面的最佳实践。', tags:[] },
  { k:'seg_3_决赛_79', ed:'3', stage:'决赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Beyond new and meaningful market access commitments, the goal of these regulatory cooperative initiatives is to build interoperable regulatory systems that support digital trade and build trust between respective systems on cross-border payments and e-commerce.', mt:'', ref:'除了提出真正有意义的全新市场准入承诺之外，这些监管合作倡议的目标就是建立具备互操作性的监管体系，籍此为数字贸易提供有力支撑，并在各国的跨境支付和电子商务系统之间建立互信。', tags:[] },
  { k:'seg_3_初赛_1', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'COVID-19:Resilience and Trust in the Face of Dramatic Uncertainties', mt:'', ref:'新冠病毒：危局之下的韧性和信任', tags:[] },
  { k:'seg_3_初赛_2', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'COVID-19 is a disease caused by a specific virus (SARS-CoV-2) and labeled in the press “coronavirus” or “novel coronavirus.”', mt:'', ref:'COVID-19 是一种由特殊病毒（SARS-CoV-2）所引发的疾病；媒体普遍称之为“冠状病毒”或“新型冠状病毒”。', tags:[] },
  { k:'seg_3_初赛_3', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Much about the disease is not currently known.', mt:'', ref:'目前，该疾病尚有很多未解之迷有待深入研究。', tags:[] },
  { k:'seg_3_初赛_4', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'While public health officials are still determining the medical impacts of the virus along with certain key characteristics, such as the incubation period, we believe the economic impact will in part depend on how the public reacts to the virus.', mt:'', ref:'尽管公共卫生官员仍在明确新冠病毒的医学影响及其某些关键特征（例如潜伏期），但我们认为其所带来的经济影响在一定程度上取决于公众如何应对。', tags:[] },
  { k:'seg_3_初赛_5', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Economic impact', mt:'', ref:'经济影响', tags:[] },
  { k:'seg_3_初赛_6', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'COVID-19 could affect the global economy through three channels:', mt:'', ref:'新冠病毒疫情可能会通过三大途径影响全球经济：', tags:[] },
  { k:'seg_3_初赛_7', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Direct impact on production.', mt:'', ref:'对工业生产的直接影响。', tags:[] },
  { k:'seg_3_初赛_8', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Chinese production has already been substantially affected by the shutdown in Hubei province and other areas.', mt:'', ref:'湖北省以及其他地区的停工停产令中国的工业生产哀鸿遍野。', tags:[] },
  { k:'seg_3_初赛_9', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Some other countries are also beginning to feel a direct impact as their authorities put in place similar measures.', mt:'', ref:'随着各国政府纷纷采取类似举措，其他一些国家亦开始受到新冠病毒疫情的直接影响。', tags:[] },
  { k:'seg_3_初赛_10', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The slowdown in China has effects on exporters to China.', mt:'', ref:'中国经济的放缓亦会殃及某些对华出口国家。', tags:[] },
  { k:'seg_3_初赛_11', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'China’s largest sources of imports are Korea, Japan, and other Asian countries, according to the World Bank.', mt:'', ref:'世界银行的数据显示，韩国、日本以及其他一些亚洲国家是中国最大的进口来源国。', tags:[] },
  { k:'seg_3_初赛_12', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Thus, even without new outbreaks of the disease, these areas will likely experience slow growth in the first half of 2020.', mt:'', ref:'因此，即便新冠病毒疫情不会卷土重来， 这些国家在2020 年上半年仍将举步维艰。', tags:[] },
  { k:'seg_3_初赛_13', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Supply chain and market disruption.', mt:'', ref:'扰乱供应链及市场。', tags:[] },
  { k:'seg_3_初赛_14', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Many manufacturing firms rely on imported intermediate inputs from China and other countries affected by the disease.', mt:'', ref:'许多制造企业严重倚赖中国以及其他受疫情影响国家所出口的半成品原材料，', tags:[] },
  { k:'seg_3_初赛_15', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Many companies also rely on sales in China to meet financial goals.', mt:'', ref:'此外还有很多公司依靠中国市场的销量来实现其财务目标。', tags:[] },
  { k:'seg_3_初赛_16', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The slowdown in economic activity—and transportation restrictions—in affected countries will likely have an impact on the production and profitability of specific global companies, particularly in manufacturing and in raw materials used in manufacturing.', mt:'', ref:'受疫情影响国家经济活动的放缓及其所施行的各种交通禁令极有可能会影响到某些全球性企业的产能和盈利，尤其是制造业以及制造业中使用的各种原材料。', tags:[] },
  { k:'seg_3_初赛_17', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For companies that rely on intermediate goods from affected regions, and that are not able to easily switch sourcing, the size of the impact may depend on how quickly the outbreak fades.', mt:'', ref:'对于那些需要从受影响地区进口半成品原材料、并且无法轻易更换供应商的企业而言，影响的轻重只能寄望于这波疫情的消退速度。', tags:[] },
  { k:'seg_3_初赛_18', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Small and medium-sized firms may have greater difficulty surviving the disruption.', mt:'', ref:'中小型企业可能更加难以为继。', tags:[] },
  { k:'seg_3_初赛_19', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Businesses tied to travel and tourism are facing losses that are likely not recoverable.', mt:'', ref:'而那些出行及旅游相关企业将面临着无可挽回的亏损。', tags:[] },
  { k:'seg_3_初赛_20', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Financial impact on firms and financial markets.', mt:'', ref:'对企业以及金融市场的财务影响。', tags:[] },
  { k:'seg_3_初赛_21', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Temporary disruptions of inputs and/or production might stress some firms, particularly those with inadequate liquidity.', mt:'', ref:'原材料供应及/或生产的暂时停摆可能会令一些企业承压不小，尤其是那些流动性匮乏的企业。', tags:[] },
  { k:'seg_3_初赛_22', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Traders in financial markets may or may not correctly anticipate or understand which firms might be vulnerable.', mt:'', ref:'金融市场中的交易者或许能够（抑或无法）准确预测或洞悉哪些企业存在着较大风险。', tags:[] },
  { k:'seg_3_初赛_23', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The resulting rise in risk might reveal that one or more key financial market players have taken investment positions that are unprofitable under current conditions, further weakening trust in financial instruments and markets.', mt:'', ref:'随之而来的风险飙升可能意味着一家或多家金融大鳄所持的投资在当前条件下无利可图，从而进一步削弱了投资者对于各种金融工具和市场的信心。', tags:[] },
  { k:'seg_3_初赛_24', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'A possible (likely low-probability) event would be a significant financial market disruption as participants become concerned about counterparty risk.', mt:'', ref:'随着市场参与者开始顾虑交易对手风险，重大金融市场动荡事件将有发生之可能（虽然概率甚微）。', tags:[] },
  { k:'seg_3_初赛_25', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'A somewhat more likely possibility is a significant decline in equity markets and corporate bond markets, with investors preferring to hold government securities (particularly US treasuries) because of the uncertainty created by the pandemic.', mt:'', ref:'大概率会发生的事情是股票市场以及企业债市场双双暴跌——由于疫情带来的不确定性，投资者更倾向于持有政府证券（尤其是美国国债）。', tags:[] },
  { k:'seg_3_初赛_26', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'COVID-19 potential implications for the banking and capital markets sector', mt:'', ref:'新冠病毒疫情对银行业及资本市场的潜在影响', tags:[] },
  { k:'seg_3_初赛_27', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In addition to the effects on the supply and demand side, COVID-19 has already jolted financial markets.', mt:'', ref:'除了给供需两侧皆造成显著影响之外， 新冠病毒疫情亦对金融市场带来了巨大冲击。', tags:[] },
  { k:'seg_3_初赛_28', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Since February 21, 2020, bond yields, oil, and equity prices have sharply fallen, and trillions of dollars, across almost all asset classes, have sought safety.', mt:'', ref:'自2020 年2 月21 日以来，债券收益率、 石油和股票价格持续暴跌；几乎所有的资产类别（总市值达数万亿美元）都在避险。', tags:[] },
  { k:'seg_3_初赛_29', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In the United States, 10-year bond yields have tumbled below 0.5 percent, and equity prices on major stock indices around the world have fallen.', mt:'', ref:'在美国，10 年期债券收益率已跌至0.5% 以下，全球主要股指价格亦纷纷下挫。', tags:[] },
  { k:'seg_3_初赛_30', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'It appears, as of now, that the markets are trying to price using the worst-case scenario, which has increased volatility recently.', mt:'', ref:'截止目前，各大市场似乎正试图基于最糟糕的情景预测来估值；这种情况进一步加剧了近期的市场波动。', tags:[] },
  { k:'seg_3_初赛_31', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'With ongoing shocks to the supply and demand side, there is potential for further market disruption.', mt:'', ref:'疫情给供需两侧造成的持续性冲击可能会进一步拖累市场。', tags:[] },
  { k:'seg_3_初赛_32', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Institutions and individuals may be experiencing liquidity stress, including limited access to credit.', mt:'', ref:'机构及个人可能正面临着巨大的流动性压力，包括信贷获取渠道受到限制。', tags:[] },
  { k:'seg_3_初赛_33', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This might, in turn, increase the probability of default, especially near or in the speculative grade of corporate debt.', mt:'', ref:'这种状况进而推高了违约概率，尤其是那些接近或属于投机级的公司债券。', tags:[] },
  { k:'seg_3_初赛_34', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Private debt, including corporate and household debt, has reached record levels recently, and approximately one-half of the investment-grade market currently holds a triple-B rating.', mt:'', ref:'近期，包括企业债及家庭债在内的私债规模已达创纪录水平；目前约半数投资级债券属于BBB 评级。', tags:[] },
  { k:'seg_3_初赛_35', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Central banks around the world, meanwhile, have already proactively intervened to calm markets and show commitment to using all possible measures.', mt:'', ref:'与此同时，全球各大央行纷纷出手干预， 以便安抚市场并放言将采取一切必要手段。', tags:[] },
  { k:'seg_3_初赛_36', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In its first emergency move since the recession in 2008, the US Federal Reserve (the Fed) recently cut the federal funds rate by 50 basis points.', mt:'', ref:'美联储近期将联邦基金利率下调了50 个基点；这是美联储自2008 年金融危机以来首次采取的紧急举措。', tags:[] },
  { k:'seg_3_初赛_37', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The Fed has also actively intervened in the repo market to add further liquidity.', mt:'', ref:'美联储亦积极干预回购市场，以便增加流动性。', tags:[] },
  { k:'seg_3_初赛_38', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The Bank of Japan (BoJ), meanwhile, issued an emergency statement signaling that it would inject liquidity into the market by increasing asset purchases.', mt:'', ref:'日本央行发表紧急声明，表示将增加资产回购力度，向市场注入流动性。', tags:[] },
  { k:'seg_3_初赛_39', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The People’s Bank of China (PBoC) has also pumped more than US$240 billion of liquidity into the financial system as a countermeasure to the virus.', mt:'', ref:'为了纾解此番疫情带来的影响，中国人民银行亦向金融系统投放了逾2,400 多亿美元的流动性。', tags:[] },
  { k:'seg_3_初赛_40', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Additionally, the Bank of England and the European Central Bank (ECB) have announced various plans to counter COVID-19 in the coming days.', mt:'', ref:'此外，英格兰银行和欧洲央行亦公布了下一阶段应对新冠病毒疫情的多项计划。', tags:[] },
  { k:'seg_3_初赛_41', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'But as the situation develops, more action may be required by central banks, regulators, and governments, which would necessitate quick coordination at the national and international levels.', mt:'', ref:'但是，随着情况的进一步恶化，各国的央行、监管机构以及政府将需要采取更多的应对之策。在此情况下，国家和国际层面的快速协调势在必行。', tags:[] },
  { k:'seg_3_初赛_42', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Meanwhile, banking and capital markets firms around the world are mobilizing and taking steps to minimize COVID-19’s effects on day-to-day operations.', mt:'', ref:'同时，全球各地的银行以及资本市场相关企业正在积极行动，采取各种措施以便最大限度地纾解新冠病毒疫情对其日常业务的影响。', tags:[] },
  { k:'seg_3_初赛_43', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Firms are testing and implementing business continuity/contingency plans, which include alternate workplace arrangements such as split work sites, working from home, and rotating shifts for all types of employees, even traders.', mt:'', ref:'这些企业正在试行各类业务连续性/应急计划，其中包括面向所有员工甚至是交易员的替代性办公安排，例如分散办公地点、居家办公、轮流上班等等。', tags:[] },
  { k:'seg_3_初赛_44', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Many have also instituted universal travel bans beyond the countries experiencing the most severe effects, and have canceled large events.', mt:'', ref:'许多企业亦禁止所有员工前往受疫情影响最严重的国家，并取消了各种大型活动。', tags:[] },
  { k:'seg_3_初赛_45', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Institutions have also heightened measures to ensure the safety and health of their employees through various means.', mt:'', ref:'同时，各机构亦加强了有关举措的执行力度，通过各种手段来确保员工的安全与健康。', tags:[] },
  { k:'seg_3_初赛_46', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Banks have also requested that regulators ease capital requirements.', mt:'', ref:'各银行亦纷纷请求监管机构放宽资本金要求。', tags:[] },
  { k:'seg_3_初赛_47', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Some regulators, such as the US Securities and Exchange Commission (SEC), have proactively granted relief for regulatory financial reporting to companies affected by COVID-19.', mt:'', ref:'对于受到本次疫情影响的企业，包括美国证券交易监督委员会（SEC）在内的某些监管机构主动放宽了该等企业的财务披露要求。', tags:[] },
  { k:'seg_3_初赛_48', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Many banks are also acting as responsible citizens by extending loans to hard-hit borrowers, renegotiating credit terms, and even donating face masks to their clients.', mt:'', ref:'通过向受疫情重创人士发放贷款、重新协商信贷条款甚至向客户捐赠口罩等方式，众多银行亦正在积极承担公共责任。', tags:[] },
  { k:'seg_3_初赛_49', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Beyond the operational actions already underway, banks and capital markets must remain hypervigilant.', mt:'', ref:'除了正在推行的运营举措之外，银行业和资本市场亦须保持高度警惕，', tags:[] },
  { k:'seg_3_初赛_50', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'They need to also actively consider the short- and medium-term financial, risk, and regulatory compliance implications that are resulting from the continuing uncertainty around COVID-19.', mt:'', ref:'积极分析新冠病毒疫情的持续不确定性给中短期财务、风险以及监管合规性所带来的影响。', tags:[] },
  { k:'seg_3_初赛_51', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Scenarios', mt:'', ref:'情景预测', tags:[] },
  { k:'seg_3_初赛_52', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'These potential scenarios are purely descriptive ideas about possible paths that the disease outbreak, and the global economy, might take.', mt:'', ref:'以下情景设想预测了此次疫情以及全球经济的潜在演变。', tags:[] },
  { k:'seg_3_初赛_53', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The worst is over.', mt:'', ref:'最糟糕的日子已经过去。', tags:[] },
  { k:'seg_3_初赛_54', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Transmission in China has slowed already.', mt:'', ref:'新冠病毒的传播在中国得到了控制。', tags:[] },
  { k:'seg_3_初赛_55', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Although some isolated outbreaks occur elsewhere, these do not create a massive spread of the disease.', mt:'', ref:'虽然某些地方发现了零星的确诊病例， 但这些病例并未造成大范围传播。', tags:[] },
  { k:'seg_3_初赛_56', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As the global number of cases stabilizes, China’s economy returns to normal, and there is little impact outside of some areas such as Iran that are not important for the global economy.', mt:'', ref:'随着全球确诊病例数量趋于稳定，中国经济亦开始重归正轨，除伊朗等地区外， 其他地区几乎不受什么影响，而诸如伊朗这样的地方对全球经济并不重要。', tags:[] },
  { k:'seg_3_初赛_57', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'China’s GDP takes a big hit in Q1 2020 but bounces back in Q2 and Q3—although some of the lost production is never replaced.', mt:'', ref:'虽然在2020 年第一季度遭受重创，但中国的GDP 在第二季度和第三季度迎来反弹，只是部分生产损失将永远无法得到弥补。', tags:[] },
  { k:'seg_3_初赛_58', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Specific companies outside China experience short-term supply disruptions, but the impact on the global economy is small and temporary.', mt:'', ref:'中国境外的某些企业经历了短期的供应中断，但此种中断对全球经济的影响微乎其微，并且没有持续太长时间。', tags:[] },
  { k:'seg_3_初赛_59', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Year of the virus.', mt:'', ref:'病毒肆虐之年。', tags:[] },
  { k:'seg_3_初赛_60', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Although the spread of the disease in China slows, outbreaks occur on a rolling basis around the world.', mt:'', ref:'尽管新冠病毒在中国的传播速度有所减缓，但疫情在全球范围内轮番爆发。', tags:[] },
  { k:'seg_3_初赛_61', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Each outbreak requires slowing production in that area, and in a globalized world, that means rolling disruptions to different regions and industries as outbreaks occur and are controlled.', mt:'', ref:'每次爆发都会拖累受影响国家的工业生产。在这个日益全球化的世界，疫情将在不断的爆发和受控之间重创不同的地区和行业。', tags:[] },
  { k:'seg_3_初赛_62', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The overall impact is to disrupt economic activity enough to slow global growth substantially.', mt:'', ref:'新冠疫情的总体影响是破坏经济活动， 并进而严重拖累全球经济增长。', tags:[] },
  { k:'seg_3_初赛_63', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Businesses that are nimble enough to manage switching suppliers and that have enough liquidity to survive periods of low sales and revenue will have a competitive advantage.', mt:'', ref:'那些能够灵活更换供应商并有充足流动性熬过艰难时局的企业将会涅槃重生、 鹤立鸡群。', tags:[] },
  { k:'seg_3_初赛_64', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Global pandemic response.', mt:'', ref:'全球共同应对新冠大流行。', tags:[] },
  { k:'seg_3_初赛_65', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Economic centers around the world are subject to Wuhan-style shutdowns as people panic over the spread of the virus.', mt:'', ref:'由于担心疫情蔓延，全球各大经济中心纷纷效仿武汉闭境封城。', tags:[] },
  { k:'seg_3_初赛_66', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Uncoordinated decisions on a country-by-country basis disrupt the movement of both people and goods.', mt:'', ref:'各国政府有欠协调的迥异决策令人员和商品的流动几近停滞。', tags:[] },
  { k:'seg_3_初赛_67', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Global manufacturing declines, as businesses with international supply chains can operate only intermittently.', mt:'', ref:'那些供应商遍布全球的企业只能间歇性地开展经营，导致全球制造业应声而落。', tags:[] },
  { k:'seg_3_初赛_68', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Tourism and related businesses decline sharply, and tourism-based businesses and regions suffer.', mt:'', ref:'旅游及相关业务的大幅下滑令依赖旅游业的企业及各大旅游目的地损失惨重。', tags:[] },
  { k:'seg_3_初赛_69', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'It takes more than a year for the World Health Organization and the United Nations to develop an accepted global response that prioritizes health measures based on effectiveness and cost to the economy, and for this response to be accepted in the major world economies.', mt:'', ref:'世界卫生组织和联合国需要一年多的时间才能制定出一套广受认可的全球应对之策（根据对策的有效性以及经济代价列出各种卫生举措的优先顺序），并让该对策被全球主要经济体所接受。', tags:[] },
  { k:'seg_3_初赛_70', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Global GDP stagnates, international trade falls, and a global recession is a distinct possibility.', mt:'', ref:'全球GDP 停滞不前；国际贸易严重下滑； 全球经济衰退几成定局。', tags:[] },
  { k:'seg_3_初赛_71', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Financial crisis.', mt:'', ref:'金融危机。', tags:[] },
  { k:'seg_3_初赛_72', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Delayed shipments and production schedules create financial problems for companies with heavy debts, especially in the United States.', mt:'', ref:'发货以及生产计划的一再推迟令那些早已负债累累的企业财竭力尽，尤其是美国企业。', tags:[] },
  { k:'seg_3_初赛_73', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The decline in global equity markets and flight from risk—investors selling assets such as high-yield bonds and volatile stocks—exposes investors who have underpriced risk.', mt:'', ref:'全球股市的暴跌再加上避险情绪的蔓延（投资者纷纷抛售高收益债券以及大幅动荡的股票）令那些风险估计不足的投资者进退无路。', tags:[] },
  { k:'seg_3_初赛_74', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Concern about counterparty risk accelerates the decline and dries up liquidity in financial markets.', mt:'', ref:'对交易对手风险的担忧加剧了跌势，导致金融市场上的流动性陷入枯竭。', tags:[] },
  { k:'seg_3_初赛_75', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Central banks scramble to manage the problem.', mt:'', ref:'各国央行纷纷出手。', tags:[] },
  { k:'seg_3_初赛_76', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Financial markets—and the global economy—recover after a V-shaped recession.', mt:'', ref:'在经历了V 字型衰退之后，金融市场以及全球经济最终得以恢复。', tags:[] },
  { k:'seg_3_初赛_77', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Resilience is a way of being', mt:'', ref:'韧性乃是生存之道', tags:[] },
  { k:'seg_3_初赛_78', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Resilient leaders shift organizational mindsets, navigate uncertainties, and invest in building trust in order to develop a recovery playbook that serves as a solid foundation for the post-COVID future.', mt:'', ref:'富有韧性的领导者善于转变组织思路， 精于驾驭各种不确定性，着力于构建信任，在运筹帷幄之中谋划出一套可在疫情过后帮助企业稳步复苏的生存之道。', tags:[] },
  { k:'seg_3_初赛_79', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'WHEREAS organizations used to describe agile change as “fixing the plane while it flies,” the COVID-19 pandemic has rewritten the rules of upheaval in modern times.', mt:'', ref:'尽管众多组织曾经将敏捷应变能力描述为“在飞行过程中修理飞机”，但新冠病毒的大流行已重新改写了当今时代背景之下的应变之道。', tags:[] },
  { k:'seg_3_初赛_80', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Those of us leading any organization—from corporations to institutions to our own families—are not fixing the plane in midair, we’re building it.', mt:'', ref:'作为各种组织的掌门人——无论是企业、机构还到我们自己的小家庭——我们并不是在空中修理飞机，而是在建造一架飞机。', tags:[] },
  { k:'seg_3_初赛_81', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Times like these need leaders who are resilient in the face of such dramatic uncertainties.', mt:'', ref:'今天这样的时代需要众多在巨大的不确定性面前依旧保持着一股韧劲的领导者。', tags:[] },
  { k:'seg_3_初赛_82', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Resilient leaders are defined first by five essential qualities of who they are, and then by what they do across three critical time frames:', mt:'', ref:'欲称某位领导者富有韧性，首先要看其是否具备五大基本品质，', tags:[] },
  { k:'seg_3_初赛_83', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Respond, Recover, and Thrive.', mt:'', ref:'然后再观察其在“应对”、“恢复”以及“复兴”三个关键阶段的工作表现。', tags:[] },
  { k:'seg_3_初赛_84', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As we progress into the Recover phase of the crisis, resilient leaders recognize and reinforce critical shifts from a “today” to a “tomorrow” mindset for their teams.', mt:'', ref:'在步入危机的“恢复”阶段之时，富有韧性的领导者往往能够高识远见，力促自身团队完成从“今日”思维到“明日”思维的重大转变。', tags:[] },
  { k:'seg_3_初赛_85', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'They perceive how major COVID-19-related market and societal shifts have caused substantial uncertainties that need to be navigated—and seized as an opportunity to grow and change.', mt:'', ref:'他们会注意到与新冠病毒疫情相关的主要市场以及社会剧变如何催生了各种亟需驾驭的巨大不确定性，并会将此种危局转变为壮大和改革自身组织的良机。', tags:[] },
  { k:'seg_3_初赛_86', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Amid these uncertainties, resilient leadership requires even greater followership, which must be nurtured and catalyzed by building greater trust.', mt:'', ref:'面对着这些不确定性，富有韧性的领导者需要更忠心的追随者，而此种忠心需要通过建立更大的信任来培育和深化。', tags:[] },
  { k:'seg_3_初赛_87', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'And resilient leaders start by anticipating what success looks like at the end of recovery—how their business will thrive in the long term—and then guide their teams to develop an outcomes-based set of agile sprints to get there.', mt:'', ref:'富有韧性的领导者首先要能预见恢复期结束之时自身组织将取得何种成就（例如业务迈上长青之路），然后指导其团队拟定出一套以结果为导向的灵活的“冲刺”计划，籍此实现这些目标。', tags:[] },
  { k:'seg_3_初赛_88', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'A “resilient organization” is not one that is simply able to return to where it left off before the crisis.', mt:'', ref:'相反，真正富有韧性的组织应当是一个危机之后脱胎换骨的组织。', tags:[] },
  { k:'seg_3_初赛_89', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Rather, the truly resilient organization is one that has transformed, having built the attitudes, beliefs, agility, and structures into its DNA that enable it to not just recover to where it was, but catapult forward—quickly.', mt:'', ref:'它的基因之中早已融入了坚韧的态度、 信念、变通以及结构，以至于其不仅能够快速恢复原状，更能快速腾飞。', tags:[] },
  { k:'seg_3_初赛_90', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Trust as a catalyst of recovery', mt:'', ref:'信任是复苏的催化剂', tags:[] },
  { k:'seg_3_初赛_91', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'During the Recover phase, resilient leaders need to inspire their teams to navigate through these significant COVID-related uncertainties.', mt:'', ref:'在“恢复”阶段，富有韧性的领导者需要激励其团队披荆斩棘，共同应对与新冠病毒疫情相关的各种重大不确定性。', tags:[] },
  { k:'seg_3_初赛_92', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'But great leadership requires even greater followership—and followership is nurtured by trust.', mt:'', ref:'但是，出色的领导者往往需要更为忠心的追随者，而此种忠心正是通过信任来哺育的。', tags:[] },
  { k:'seg_3_初赛_93', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Indeed, many leaders have built a significant bank of trust from deftly navigating through the early frenzied unpredictable stages of the crisis.', mt:'', ref:'实际上，许多领导者以高明手段撑过了危机前期阶段的狂风骤雨，从而赢得追随者对自己的绝对信任。', tags:[] },
  { k:'seg_3_初赛_94', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Although some may think of trust as an abstract, ethereal concept, it is, in fact, a quite tangible foundation that is essential to successfully reaffirming a strong relationship with stakeholders through the recovery.', mt:'', ref:'尽管某些人可能会将信任视为一个抽象、空洞的概念，但是，领导者如果希望通过复苏来成功巩固与各种利益相关方之间建立的密切关系，那么信任就是一个有形的前提。', tags:[] },
  { k:'seg_3_初赛_95', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Two attributes of trust are particularly relevant in this regard.', mt:'', ref:'在这方面，信任的两个属性殊为重要。', tags:[] },
  { k:'seg_3_初赛_96', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'First, trust is a tangible exchange of value.', mt:'', ref:'首先，信任是一种有形的价值交换。', tags:[] },
  { k:'seg_3_初赛_97', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'It has no value in isolation, but represents value only in an interaction with others—for example, customers, suppliers, employees, investors, and team members.', mt:'', ref:'对于孤立的个体，信任毫无价值；信任的价值只能在与他人（例如客户、供应商、员工、投资者以及团队成员）的互动之中体现。', tags:[] },
  { k:'seg_3_初赛_98', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Likewise, trust is only built in relationships, where a real, genuine give-and-take provides mutual value.', mt:'', ref:'同样，信任是在各种关系的培养过程中建立起来的；这个过程中的真实及真正的互惠互利创造了共同的价值。', tags:[] },
  { k:'seg_3_初赛_99', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Trust is also accretive:', mt:'', ref:'信任亦有增值作用：', tags:[] },
  { k:'seg_3_初赛_100', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Invested wisely and prudently, it grows through repeated affirming experiences; when invested poorly, it rapidly depreciates.', mt:'', ref:'当以睿智、谨慎的方式去培养信任之时， 信任会因反复经历的正面体验而与日俱增；当培养信任的方式欠佳之时，信任亦将一落千丈。', tags:[] },
  { k:'seg_3_初赛_101', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Further, research demonstrates that trust also yields results such as economic growth and shareholder value, increased innovation, greater community stability, and better health outcomes.', mt:'', ref:'此外，有关研究表明信任亦有助于促进经济增长、提升股东价值、鼓励创新、 增强社区稳定性以及改善健康情况等等。', tags:[] },
  { k:'seg_3_初赛_102', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Second, trust is actionable, and human, along multiple dimensions.', mt:'', ref:'其次，信任源于多个维度的行为举止以及待人之道。', tags:[] },
  { k:'seg_3_初赛_103', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Trust is nurtured and built among stakeholders along four different dimensions: physical, emotional, financial, and digital.', mt:'', ref:'不同的利益相关方在四个不同维度培育并建立起信任：身体、情感、财务和数字。', tags:[] },
  { k:'seg_3_初赛_104', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'And trust starts at the human, interpersonal level.', mt:'', ref:'信任始于人与人之间的赤诚相待。', tags:[] },
  { k:'seg_3_初赛_105', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'COVID-19 has heightened stakeholder sensitivity across these four dimensions, which offers greater opportunities to act to build—or lose—trust.', mt:'', ref:'新冠病毒疫情提高了不同利益相关方在这四个维度的敏感性，从而令信任变得更易于建立或失去。', tags:[] },
  { k:'seg_3_初赛_106', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For example, trust may be built among employees when leaders thoughtfully consider how to reengage the workforce in the office (such as by reconfiguring the space to honor social distancing), or when they go to great lengths to preserve as many jobs as possible rather than just preserving profits.', mt:'', ref:'例如，如若领导者在让员工重返办公室之时能够考虑周全（例如重新分配办公空间，以保持社交距离），或如果领导者能够竭力保留尽可能多的工作岗位、 而非只看重眼前的利润，则员工心中自然会对领导者生出万般信任。', tags:[] },
  { k:'seg_3_初赛_107', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Similarly, trust may be built among customers when organizations add extra security measures to protect customer data from cyber threats.', mt:'', ref:'同样，如果各个组织能够主动采取额外的安全措施，以保护客户数据免受网络攻击，则客户心中亦会对该等组织生出无限信任。', tags:[] },
  { k:'seg_3_初赛_108', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN’s Present and Future Outlook on Consumption', mt:'', ref:'东盟消费现状和未来展望', tags:[] },
  { k:'seg_3_初赛_109', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In the bustling cities of Jakarta, Ho Chi Minh City and Manila, green-helmeted motorbike taxi drivers whizz past warung or sari-sari stores.', mt:'', ref:'在雅加达、胡志明市和马尼拉等繁华都市，戴着绿色头盔的摩的司机从小餐馆和杂货店门前呼啸而过。', tags:[] },
  { k:'seg_3_初赛_110', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The presence of homegrown technology decacorns – new businesses like Go-Jek or Grab worth more than $10 billion – alongside thriving traditional mom-and-pop stores best illustrates Southeast Asia’s vibrant growth story.', mt:'', ref:'本土孕育的科技十角兽公司（例如两家出行平台Go-Jek和Grab等市值超过100 亿美元的年轻企业）和热火朝天的传统夫妻店是东南亚经济繁荣的最佳写照。', tags:[] },
  { k:'seg_3_初赛_111', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As a market bloc, the 10 member states of the Association of Southeast Asian Nations (ASEAN) are on the cusp of a tremendous leap forward in socio-economic progress, but on their own terms.', mt:'', ref:'作为一个统一市场，东南亚国家联盟（东盟）的10 个成员国正以自己的方式迎来社会经济的跨越式发展。', tags:[] },
  { k:'seg_3_初赛_112', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN will not simply be the next China or India.', mt:'', ref:'东盟将不仅仅是下一个中国或印度。', tags:[] },
  { k:'seg_3_初赛_113', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The economic and cultural backgrounds of each ASEAN market are heterogeneous, and while the region will see abundant opportunities, each country will take its own distinct path to growth.', mt:'', ref:'在遍地机遇的东南亚地区，各个国家的经济和文化背景各不相同，因此每一个国家都将走出属于自己的发展道路。', tags:[] },
  { k:'seg_3_初赛_114', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN is the world’s third most populous economy and over the next decade is expected to become the world’s fourth largest.', mt:'', ref:'作为一个经济体，东盟的人口在世界上排名第三，预计十年后将发展成为全球第四大经济体。', tags:[] },
  { k:'seg_3_初赛_115', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Domestic consumption, which powers roughly 60% of GDP today, is estimated to double to $4 trillion.', mt:'', ref:'目前，东盟的国内消费约占GDP 的60%， 预计十年后将翻一番，达到4 万亿美元。', tags:[] },
  { k:'seg_3_初赛_116', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Yet, as this growth story plays out, public and private-sector organizations will first need to address the immediate COVID-led health and humanitarian crisis and its implications, while finding longer-term solutions to structural problems of income inequality, ease of doing business, sustainability and job creation.', mt:'', ref:'然而，面对巨大的发展机遇，公共和私营部门的当务之急是克服新冠肺炎疫情造成的卫生和人道主义危机及其后续影响，同时还要为收入不均、经商便利度不高、可持续发展欠缺和就业岗位不足等结构性问题找到长期解决方案。', tags:[] },
  { k:'seg_3_初赛_117', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'It would be an understatement to describe 2020 as a challenging year.', mt:'', ref:'说2020 年是充满挑战的一年一点儿也不为过。', tags:[] },
  { k:'seg_3_初赛_118', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Like their counterparts around the world, government and business leaders in ASEAN face uncertainty as the COVID-19 pandemic disrupts economic activities and causes drastic changes in consumer behavior.', mt:'', ref:'和世界其他国家一样，东盟成员国的政界和商界领袖也面临着新冠肺炎大流行带来的不确定性，包括经济活动停滞、 消费行为剧变等。', tags:[] },
  { k:'seg_3_初赛_119', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As a sign of the huge impact, the Asian Development Bank (ADB) adjusted South-East Asian growth projections down to 1% for 2020, although annual growth is expected to rebound to 5% in 2021, supported by positive macroeconomic fundamentals.', mt:'', ref:'亚洲开发银行（ADB）将东盟2020 年的经济增长预期下调至1%，由此可见疫情带来的巨大影响。不过，有积极的宏观经济基本面作支撑，预计2021 年的经济增长率将恢复至5%。', tags:[] },
  { k:'seg_3_初赛_120', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As we look further into the future, ASEAN growth will be propelled by four mega-forces: favorable demographics; rising income levels; geopolitical shifts; and digital tailwinds.', mt:'', ref:'展望未来，东盟经济将在四大因素的推动之下持续增长：人口条件优越；收入水平日益提高；地缘政治变化；以及数字经济助力。', tags:[] },
  { k:'seg_3_初赛_121', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Over the next decade, ASEAN will see 140 million new consumers, representing 16% of the world’s consumers – many of whom will make their first online purchase and buy their first luxury product.', mt:'', ref:'未来十年，东盟的消费人口将增加1.4 亿，约占全世界消费人口的16%，其中不少人将初次尝试网购并消费他们的第一件奢侈品。', tags:[] },
  { k:'seg_3_初赛_122', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Income levels are rising, with regional GDP per capita expected to grow by an annual 4% (similar to the US) to $6,600 in 2030, causing many product categories to reach inflection points where consumption takes off.', mt:'', ref:'随着居民收入水平不断提高，预计地区人均GDP 将以每年4%的速度增长（与美国接近），2030 年将达到6,600 美元。 届时，许多产品类别都将迎来消费拐点， 获得迅猛增长。', tags:[] },
  { k:'seg_3_初赛_123', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN will be a popular destination for foreign investment as multinationals rebalance supply chains to diversify geopolitical risk and make the most of the region’s low-cost labour.', mt:'', ref:'东盟还将成为外资的热门目的地，因为跨国企业需要重新平衡供应链以规避地缘政治风险并充分利用该地区的劳动力成本优势。', tags:[] },
  { k:'seg_3_初赛_124', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The ASEAN macro-context', mt:'', ref:'东盟宏观背景', tags:[] },
  { k:'seg_3_初赛_125', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The world’s next economic powerhouse.', mt:'', ref:'下一个世界经济增长引擎。', tags:[] },
  { k:'seg_3_初赛_126', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'With a GDP growth rate that is third only to India and China, ASEAN is expected to grow by an annual 4% over the next decade, making this region the world’s fourth-largest economy.', mt:'', ref:'东盟的经济增速仅次于印度和中国，在全世界排名第三。未来十年，预计东盟经济将以每年4%的速度增长，成为全球第四大经济体。', tags:[] },
  { k:'seg_3_初赛_127', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'By 2030, ASEAN’s GDP will stretch to $4.5 trillion and the population will reach 723 million.', mt:'', ref:'到2030 年，东盟的GDP 将达到4.5 万亿美元，人口将达到7.23 亿。', tags:[] },
  { k:'seg_3_初赛_128', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'One in six households entering the world’s consuming class will come from ASEAN.', mt:'', ref:'届时，全世界进入消费阶层的家庭将有六分之一来自东盟。', tags:[] },
  { k:'seg_3_初赛_129', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Five million people will move into cities every year.', mt:'', ref:'每年将有500 万人迁入城市，', tags:[] },
  { k:'seg_3_初赛_130', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Urbanization will sustain through 2050 and extend to Tier 2 cities.', mt:'', ref:'城市化的进程将持续到2050 年并覆盖二线城市。', tags:[] },
  { k:'seg_3_初赛_131', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As these developments suggest, the dynamic ASEAN states are on the verge of becoming a massive consumer opportunity close behind China and India.', mt:'', ref:'这些发展趋势表明，充满活力的东盟市场即将成为仅次于中国和印度的另一大消费市场。', tags:[] },
  { k:'seg_3_初赛_132', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'However, while the region’s huge population and powerful economic momentum offer great potential, there are a host of complicating factors.', mt:'', ref:'不过，虽然庞大的人口基数和强劲的经济增长蕴藏了巨大的潜力，但是东盟国家仍然面临着一系列复杂的因素。', tags:[] },
  { k:'seg_3_初赛_133', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Among the fundamental issues are the absence of a common currency, no open borders and, despite many recent ASEAN trade advances, each country maintains separate regulations.', mt:'', ref:'其中，最根本的问题包括缺乏统一的货币和开放的边境、各国保留独立的法律制度，尽管近年来东盟在贸易领域取得了不小的进步。', tags:[] },
  { k:'seg_3_初赛_134', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Understanding the basics:', mt:'', ref:'了解基本事实：', tags:[] },
  { k:'seg_3_初赛_135', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN’s three economic groups.', mt:'', ref:'东盟的三个经济梯队。', tags:[] },
  { k:'seg_3_初赛_136', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The 10 member states represent a wide disparity in the levels and speed of development; it is thus best to view them in three groups.', mt:'', ref:'10 个成员国在发展水平和发展速度方面差异巨大，因此有必要把它们分成三个梯队来分别看待。', tags:[] },
  { k:'seg_3_初赛_137', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'At one end of the spectrum are the three developed nations:', mt:'', ref:'第一梯队包括三个发达国家：', tags:[] },
  { k:'seg_3_初赛_138', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Singapore, Malaysia and Thailand.', mt:'', ref:'新加坡、马来西亚和泰国。', tags:[] },
  { k:'seg_3_初赛_139', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Singapore is the region’s most developed economy, with a GDP per capita similar to the US.', mt:'', ref:'新加坡是东南亚地区最发达的经济体， 人均GDP 与美国接近。', tags:[] },
  { k:'seg_3_初赛_140', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The Singaporean population is fully or almost fully urbanized, banked and online; the country ranks second of 190 countries for ease of doing business and is one of the least corrupt in the world.', mt:'', ref:'新加坡人口几乎全部居住在城市，银行账户和互联网的普及率也非常高。经商便利度方面，新加坡在全世界190 个国家当中排名第二。另外，新加坡也是世界上最清廉的国家之一。', tags:[] },
  { k:'seg_3_初赛_141', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'On the other end of the spectrum are the four frontier economies of Cambodia, Myanmar, Laos and Brunei.', mt:'', ref:'柬埔寨、缅甸、老挝和文莱四国属于东盟的第三梯队。', tags:[] },
  { k:'seg_3_初赛_142', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The first three countries have massive prospects for growth but significantly smaller economies, with GDP levels below $100 billion and GDP per capita below the ASEAN average of $4,747.', mt:'', ref:'前三个国家拥有广阔的发展前景，但是经济体量明显较小。它们的GDP 不足 1000 亿美元，且人均GDP 低于东盟平均水平4,747 美元。', tags:[] },
  { k:'seg_3_初赛_143', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'They have the same dominant religion – Buddhism – but differences remain.', mt:'', ref:'它们的主流宗教都是佛教，但彼此之间存在一些差异。', tags:[] },
  { k:'seg_3_初赛_144', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For example, 76% of Cambodians use the internet, roughly double that of Myanmar and Laos.', mt:'', ref:'例如，柬埔寨有76%的人口使用互联网， 几乎是缅甸和老挝的两倍。', tags:[] },
  { k:'seg_3_初赛_145', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'While Brunei has a high GDP per capita fuelled by the national oil and gas industry, the sultanate resembles an emerging market socio-economically.', mt:'', ref:'在油气产业的推动下，文莱的人均GDP 很高，但是这个苏丹制国家的社会经济发展水平总体接近新兴市场。', tags:[] },
  { k:'seg_3_初赛_146', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In a frontier nation like Myanmar, only 31% of the population live in urban areas, 26% have a bank account and 38% use the internet.', mt:'', ref:'而位于东盟边境的缅甸仅有31%的人口居住在城市，26%拥有银行账户，38%使用互联网。', tags:[] },
  { k:'seg_3_初赛_147', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The country ranks 165th and 132nd in ease of doing business and corruption respectively.', mt:'', ref:'在经商便利度和清廉度方面，缅甸分别排在第165 位和第132 位。', tags:[] },
  { k:'seg_3_初赛_148', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In the middle lie the three emerging economies of Indonesia, the Philippines and Viet Nam.', mt:'', ref:'处于中间梯队的是三个新兴经济体：印度尼西亚、菲律宾和越南。', tags:[] },
  { k:'seg_3_初赛_149', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This is where 70% of the ASEAN population lives, contributing to more than 50% of the region’s GDP.', mt:'', ref:'这三个国家的人口约占东盟总人口的 70%，对地区GDP 的贡献率达到50%以上。', tags:[] },
  { k:'seg_3_初赛_150', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Emerging ASEAN will be the engine of growth over the next decade, driving 98% of the increase in working population and contributing 70% to 80% of the new consumer population.', mt:'', ref:'它们将成为东盟未来十年的经济增长引擎，推动劳动人口增长98%，贡献70% 到80%的新增消费人口。', tags:[] },
  { k:'seg_3_初赛_151', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'This explosion of the working middle-class will materially boost productivity and spending to the point that the GDP growth rate of emerging ASEAN is expected to overtake China.', mt:'', ref:'劳动中产阶级的爆炸性增长将大幅提高生产力和消费能力，预计东盟新兴经济体的GDP 增速将超过中国。', tags:[] },
  { k:'seg_3_初赛_152', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In addition to being heterogeneous, geography poses challenges to growth in many ASEAN markets.', mt:'', ref:'除了发展不平衡，地理环境也为不少东盟国家的发展带来了挑战。', tags:[] },
  { k:'seg_3_初赛_153', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The Indonesian and Filipino populations are spread across 17,500 and 7,100 islands, respectively, making distribution a major obstacle in industries as diverse as communications, financial services and consumer products.', mt:'', ref:'印度尼西亚和菲律宾分别由17,500 个和7,100 个岛屿组成，这种独特的地理条件使得市场分布成为阻碍通信、金融服务和消费品等行业发展的一大障碍。', tags:[] },
  { k:'seg_3_初赛_154', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Four mega-forces will drive the future of consumption in ASEAN', mt:'', ref:'推动东盟未来消费增长的四大因素', tags:[] },
  { k:'seg_3_初赛_155', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Despite the market differences and geographic challenges, ASEAN is a tremendous consumer opportunity, with four mega-forces determining the pace and scale of the region’s growth.', mt:'', ref:'尽管面临市场差异和地理环境方面的困难，东盟仍然蕴藏着巨大的消费机遇， 而该地区的增长速度和规模将取决于四大推动因素。', tags:[] },
  { k:'seg_3_初赛_156', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'1.Favorable demographics', mt:'', ref:'1.人口条件优越', tags:[] },
  { k:'seg_3_初赛_157', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'A young, tech-savvy population, entering the workforce and migrating to big and small cities, will spur consumption in Indonesia, Viet Nam and the Philippines.', mt:'', ref:'精通技术的年轻人口进入劳动力市场并迁入大小城市，他们将刺激印度尼西亚、 越南和菲律宾的消费增长。', tags:[] },
  { k:'seg_3_初赛_158', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Emerging ASEAN is young and increasingly urbanized.', mt:'', ref:'东盟新兴经济体拥有年轻的人口和不断提高的城市化水平。', tags:[] },
  { k:'seg_3_初赛_159', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2030, the median age in the Philippines will be 29 while Indonesia’s will be 32.', mt:'', ref:'到2030 年，菲律宾人口的中位数年龄将为29 岁，印度尼西亚为32 岁。', tags:[] },
  { k:'seg_3_初赛_160', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Young consumers are tech-savvy, likely to discover products on social media, comfortable spending online and concerned about health and sustainability.', mt:'', ref:'这个年轻的消费群体精通技术，善于通过社交媒体发现产品，习惯便利的在线消费，关注健康和可持续发展。', tags:[] },
  { k:'seg_3_初赛_161', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN’s working-age population will increase by 40 million by 2030, with Indonesia contributing more than half of that army of workers.', mt:'', ref:'到2030 年，东盟将增加4000 万劳动人口，其中超过一半来自印度尼西亚。', tags:[] },
  { k:'seg_3_初赛_162', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'By comparison, China is expected to reduce its working-age population by 30 million in the same period.', mt:'', ref:'相比之下，同一时间中国的劳动人口预计将减少3000 万。', tags:[] },
  { k:'seg_3_初赛_163', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Labour costs in emerging ASEAN are significantly lower than in many other parts of Asia.', mt:'', ref:'东盟新兴经济体的劳动力成本远低于其他亚洲国家。', tags:[] },
  { k:'seg_3_初赛_164', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Consider that Viet Nam’s labour costs are 50% that of China.', mt:'', ref:'以越南为例，该国的劳动力成本仅为中国的50%。', tags:[] },
  { k:'seg_3_初赛_165', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Moreover, there is headroom to increase productivity.', mt:'', ref:'另外，生产力也有提升的空间。', tags:[] },
  { k:'seg_3_初赛_166', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Annual productivity in Viet Nam is $4,000 per employee compared to $128,000 in the US and $95,000 in Singapore.', mt:'', ref:'越南的年生产力是每名员工4,000 美元，而美国是128,000 美元，新加坡是 95,000 美元。', tags:[] },
  { k:'seg_3_初赛_167', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The combination of an expanding workforce, low labour costs and the potential for productivity gains is highly attractive for investment and growth.', mt:'', ref:'迅速增长的劳动人口、低廉的劳动力成本和生产力发展潜力相叠加，使得该地区成为极具吸引力的投资和发展热土。', tags:[] },
  { k:'seg_3_初赛_168', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Meanwhile, ASEAN populations will continue to migrate to cities at a sustained pace.', mt:'', ref:'与此同时，东盟的城市化水平也将稳步提升。', tags:[] },
  { k:'seg_3_初赛_169', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Through 2050, an estimated 5 million people a year will move to urban areas, with the growth extending beyond Tier-1 cities like Jakarta, Manila and Ho Chi Minh City to Tier-2 cities like Surabaya, Pampanga and Can Tho.', mt:'', ref:'到2050 年，预计每年将有500 万人迁入城市，城市化的版图也将从雅加达、马尼拉和胡志明市等一线城市延伸到泗水、邦板牙和芹苴等二线城市。', tags:[] },
  { k:'seg_3_初赛_170', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In contrast, the rate of urbanization in China is decelerating, with fewer people moving to urban areas by 2040 compared to ASEAN.', mt:'', ref:'与之相反，中国的城市化速度呈现放慢趋势，到2040 年迁入城市的人口将少于东盟。', tags:[] },
  { k:'seg_3_初赛_171', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Other demographic factors also come into play.', mt:'', ref:'其他人口因素也不容忽视，', tags:[] },
  { k:'seg_3_初赛_172', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For example, decreasing household size and increasing female workforce participation will further shape consumer behavior by contributing to an increase in purchasing frequency and boosting demand for convenience.', mt:'', ref:'例如家庭规模缩小和女性劳动人口增加。这些因素将促进购买频率提高并推动便利性需求增长，进而塑造该地区的消费者行为。', tags:[] },
  { k:'seg_3_初赛_173', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'2.Rising income levels', mt:'', ref:'2.收入水平日益提高', tags:[] },
  { k:'seg_3_初赛_174', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Income levels will grow annually by 6%-8% in emerging ASEAN, creating economies powered by the middle class.', mt:'', ref:'东盟新兴市场的收入水平将以每年 6%-8%的速度增长，形成多个以中产阶级为发展动力的经济体。', tags:[] },
  { k:'seg_3_初赛_175', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'The highest increase in income will happen in Viet Nam.', mt:'', ref:'收入增长最快的国家将是越南。', tags:[] },
  { k:'seg_3_初赛_176', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'There, the average disposable income per capita will rise from $2,000 to $4,000 by 2030, growing at an annual rate of 8%.', mt:'', ref:'到2030 年，该国的人均可支配收入将从 2,000 美元增长到4,000 美元，年均增速8%。', tags:[] },
  { k:'seg_3_初赛_177', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'That is twice the rate of the US.', mt:'', ref:'这个速度是美国的两倍。', tags:[] },
  { k:'seg_3_初赛_178', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'By comparison, Indonesia’s incomes will grow from $3,000 to $8,000 and the Philippines’ from $3,000 to $6,000 by 2030.', mt:'', ref:'同样以2030 年为限，印度尼西亚的收入水平将从3,000 美元增长到8,000 美元， 菲律宾将从3,000 美元增长到6,000 美元。', tags:[] },
  { k:'seg_3_初赛_179', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'By 2030, ASEAN will contribute 140 million new consumers, representing 16% of the world’s new consumer class.', mt:'', ref:'到2030 年，东盟将贡献1.4 亿新增消费人口，约占全世界新增消费阶层的16%。', tags:[] },
  { k:'seg_3_初赛_180', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Many of these new consumers will be making their first online purchase and buying their first affordable luxury good.', mt:'', ref:'其中不少新增消费人口将初次尝试网购并消费第一件他们负担得起的奢侈品。', tags:[] },
  { k:'seg_3_初赛_181', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Further fuelling consumption will be a substantial expansion in the number of emerging ASEAN’s high- and upper-middle income households, which will nearly double from 30 million to 57 million from 2019 to 2030.', mt:'', ref:'刺激消费增长的另一个因素是东盟新兴市场的高收入和中等收入家庭大幅增加 ——这个群体将从2019 年的3000 万增长到2030 年的5700 万，几乎翻番。', tags:[] },
  { k:'seg_3_初赛_182', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Overall, GDP per capita across ASEAN will grow by 4% annually to reach $6,600 in 2030.', mt:'', ref:'总体来看，东盟国家的人均GDP 将以每年4%的速度增长，预计2030 年将达到 6,600 美元。', tags:[] },
  { k:'seg_3_初赛_183', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'As a result, product categories as diverse as confectionery and diapers will soon approach inflection points where consumption takes off.', mt:'', ref:'得益于此，甜食和纸尿裤等多个产品类别很快将迎来消费拐点，实现大幅增长。', tags:[] },
  { k:'seg_3_初赛_184', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'3.Shifts in global geopolitics and local regulations', mt:'', ref:'3.全球地缘政治和地方法规变化', tags:[] },
  { k:'seg_3_初赛_185', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Geopolitics and local regulations can be a boon or a bane.', mt:'', ref:'地缘政治和地方法规可以是优势，也可以是缺点。', tags:[] },
  { k:'seg_3_初赛_186', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'They will open the door for foreign direct investments and other opportunities while also creating challenges such as rising protectionism.', mt:'', ref:'它们将为外国直接投资和其他机会打开大门，同时也将带来保护主义抬头等挑战。', tags:[] },
  { k:'seg_3_初赛_187', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN will become a popular destination for foreign direct investment (FDI) as multinationals rebalance supply chains to diversify geopolitical risk and make the most of low-cost labour.', mt:'', ref:'东盟将成为外国直接投资（FDI）的热门目的地，因为跨国企业需要重新平衡供应链以规避地缘政治风险并充分利用劳动力成本优势。', tags:[] },
  { k:'seg_3_初赛_188', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2018, FDI inflows reached $155 billion, exceeding China by 1.2 times and India by 3.7 times.', mt:'', ref:'2018 年，东盟吸引的FDI 达到1550 亿美元，是中国的1.2 倍、印度的3.7 倍。', tags:[] },
  { k:'seg_3_初赛_189', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'With a labour force that is 50% cheaper than China, Viet Nam is well-placed to benefit.', mt:'', ref:'越南的劳动力比中国便宜50%，这是一个极为有利的条件。', tags:[] },
  { k:'seg_3_初赛_190', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'To ensure that it can accommodate the growth, Viet Nam needs to continue to invest to develop skilled and semi-skilled labour and build a stronger technological manufacturing base.', mt:'', ref:'为确保自身能够适应增长，越南需要继续加大投入培养熟练和半熟练劳动力， 打造一个更加坚实的技术制造基础。', tags:[] },
  { k:'seg_3_初赛_191', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'However, geopolitics could also be a challenge for ASEAN markets.', mt:'', ref:'然而，地缘政治也可能给东盟市场带来挑战。', tags:[] },
  { k:'seg_3_初赛_192', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'For example, the European Union’s ban on the use of palm oil to produce biofuels has had a negative effect on ASEAN palm-oil producers.', mt:'', ref:'例如，欧盟禁止使用棕榈油生产生物柴油，这条禁令对东盟的棕榈油制造商产生了负面影响。', tags:[] },
  { k:'seg_3_初赛_193', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Another big question mark involves regulatory challenges.', mt:'', ref:'监管挑战也是一个巨大的问号。', tags:[] },
  { k:'seg_3_初赛_194', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Protectionist measures make it difficult for foreign companies to operate in places like the Philippines.', mt:'', ref:'保护主义措施导致外国企业难以在菲律宾等国开展经营活动。', tags:[] },
  { k:'seg_3_初赛_195', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Such regulations led the country’s Ease of Doing Business rank to fall from 95 to 124 (from 2015 to 2019).', mt:'', ref:'由于此类法规的存在，该国的经商便利度排名从95 位下降到124 位（2015 年到2019 年）。', tags:[] },
  { k:'seg_3_初赛_196', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'However, regulations are now beginning to shift in favor of commerce.', mt:'', ref:'但是，法规正在朝着有利于商业发展的方向倾斜。', tags:[] },
  { k:'seg_3_初赛_197', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'In 2019, Indonesia removed a regulation requiring 80% of modern trade sales to come from domestic products and the anti-corruption commission has been actively cracking down on corruption.', mt:'', ref:'2019 年，印度尼西亚废除了一项要求 80%的现代贸易额必须来自国产商品的规定，该国反腐败委员会也开始加大力度打击腐败。', tags:[] },
  { k:'seg_3_初赛_198', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Viet Nam drafted a law to remove the 49% foreign ownership limit on listed companies.', mt:'', ref:'越南也起草了一部法律，旨在取消上市公司中的外资股比限制不得超过49%的规定。', tags:[] },
  { k:'seg_3_初赛_199', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'4.Digital tailwinds', mt:'', ref:'4.数字经济助力', tags:[] },
  { k:'seg_3_初赛_200', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ASEAN’s digital economy will become truly inclusive, as consumers adopt digital, investors fund innovative digital businesses and governments support key digital transformation programs.', mt:'', ref:'随着消费者采用数字技术、投资者资助创新数字企业、政府为重点数字化转型项目提供支持，东盟的数字经济将真正实现包容性。', tags:[] },
  { k:'seg_3_初赛_201', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Digital tailwinds that propelled development in much of the rest of the world will be felt across this region.', mt:'', ref:'推动全球其他国家发展的数字化浪潮也将席卷东南亚地区。', tags:[] },
  { k:'seg_3_初赛_202', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Digital adoption is reaching an inflection point, fueled by consumer behavioral changes, investor funding in digital innovations as well as government programs to accelerate the digital transformation process.', mt:'', ref:'随着消费者行为的改变、投资者资助数字化创新以及政府加快推进数字化转型项目，数字技术的应用即将迎来拐点。', tags:[] },
  { k:'seg_3_初赛_203', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Yet digitalization will come at a cost.', mt:'', ref:'但是，实现数字化需要付出代价。', tags:[] },
  { k:'seg_3_初赛_204', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'While entirely new jobs will be created, automation will reduce employment in labour-intensive sectors, reducing wages and displacing low-skilled jobs.', mt:'', ref:'虽然将出现全新的就业岗位，但是自动化将降低劳动密集型产业的就业率和工资水平，并导致低技能就业岗位被取代。', tags:[] },
  { k:'seg_3_初赛_205', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'ADB estimates that up to 30% of activities in 60% of occupations could be automated.', mt:'', ref:'ADB 预测，60%的工作岗位有多达30%的活动可实现自动化。', tags:[] },
  { k:'seg_3_初赛_206', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'By comparison, high-skilled jobs will be in demand and at least 43 million people will need to be reskilled in Indonesia, Malaysia, the Philippines, Singapore, Thailand and Viet Nam (collectively, “ASEAN-6”) by 2030.', mt:'', ref:'相比之下，高技能劳动力将供不应求， 而印度尼西亚、马来西亚、菲律宾、新加坡、泰国和越南（统称为“东盟六国”）至少有4300 万人需要学习新技能。', tags:[] },
  { k:'seg_3_初赛_207', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'These four mega-forces will deliver a new ASEAN consumption picture, with confident, informed and explorative millennial and Gen Z consumers shaping future consumption trends and behavior.', mt:'', ref:'上述四大因素将为东盟描绘一幅崭新的消费图景，而未来的消费趋势和行为将由信心满满、见多识广、乐于探索的千禧一代和Z 世代消费者共同塑造。', tags:[] },
  { k:'seg_3_初赛_208', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'They will leapfrog consumers in many larger economies in digital adoption.', mt:'', ref:'他们的数字技术应用能力将超越许多大型经济体的消费者，', tags:[] },
  { k:'seg_3_初赛_209', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'They will strive to be modern while preserving local identity.', mt:'', ref:'他们在努力拥抱现代化的同时也将保留自己的地方特色。', tags:[] },
  { k:'seg_3_初赛_210', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Millennials and Gen Z consumers will demand convenience, well-being and sustainability, and seek value for money as well as integrative experiences across online and offline channels.', mt:'', ref:'千禧一代和Z 世代消费者的需求包括便利、健康和可持续发展。他们追求物有所值，同时也注重线上和线下渠道的综合体验。', tags:[] },
  { k:'seg_3_初赛_211', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Achieving ASEAN’s full potential growth in 2030 requires that all stakeholders deeply understand each market, build strong public-private partnerships and strike a hard balance between technology advancement and job creation, economic development and sustainability, as well as scale advantages and concentration of power.', mt:'', ref:'要在2030 年之前充分发掘东盟的增长潜力，所有利益相关方必须深入了解每一个市场、建立稳固的公私合作关系， 还需要在技术进步和增加就业岗位之间、经济进步和可持续发展之间以及规模优势和权力集中之间艰难地取得平衡。', tags:[] },
  { k:'seg_3_初赛_212', ed:'3', stage:'初赛', dir:'英译汉', eng:'腾讯TranSmart', src:'Businesses and governments have a unique opportunity to shape ASEAN’s exciting growth story if they thoughtfully steer the region towards inclusive and sustainable consumption while also navigating the turbulence of the next decade.', mt:'', ref:'如果政商两界能够深思熟虑地引导这个地区向着包容和可持续的消费方向发展并克服下一个十年带来的种种挑战，东盟将有机会写下振奋人心的发展新篇章。', tags:[] },
  { k:'seg_4_决赛_1', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Politics, Otto Von Bismarck is supposed to have said, is the art of the possible.', mt:'奥托·冯·俾斯麦应该说过，政治是可能性的艺术。', ref:'奥托·冯·俾斯麦 (Otto Von Bismarck) 似曾说过，政治是“将一切变为可能”的艺术。', tags:["准确性","术语","语言规范"] },
  { k:'seg_4_决赛_2', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And one of the most depressing features of discussions about global warming is their tendency to take place in a fantasy land of the politically impossible.', mt:'关于全球变暖的讨论最令人沮丧的特征之一是，它们倾向于发生在政治上不可能的幻想之地。', ref:'但是关于全球变暖的讨论却往往是政治上不可能实现的幻想，这也是相关讨论令人沮丧的一大特征。', tags:["准确性"] },
  { k:'seg_4_决赛_3', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Few people in those parts of the world made rich by carbon- dioxide-emitting enterprise are going to volunteer for a cut in living standards.', mt:'在世界上那些靠二氧化碳排放企业致富的地区，很少有人会自愿降低生活水平。', ref:'在世界上因二氧化碳排放而过上富足生活的地区，很少有人会自愿降低生活质量。', tags:["准确性"] },
  { k:'seg_4_决赛_4', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And it is hard to ask those from parts of the world that are not yet rich to sacrifice the chance to become so.', mt:'很难要求那些来自世界上还不富裕地区的人牺牲成为富人的机会。', ref:'要让那些还不富裕地区的人们放弃成为富人的机会也很难。', tags:["准确性"] },
  { k:'seg_4_决赛_5', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That being the case, it makes sense to concentrate on doing things which affect neither the comforts of the former nor the aspirations of the latter.', mt:'在这种情况下，集中精力做既不影响前者的舒适，也不影响后者的愿望的事情是有意义的。', ref:'因此，集中精力做些实事，既不影响富人的舒适生活，也不打击不富裕的人们追求富裕生活的愿望，这样才有意义。', tags:["准确性"] },
  { k:'seg_4_决赛_6', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Technological change that shifts economies away from using fossil fuels as their principal energy sources may be able to achieve this in the long term.', mt:'从长远来看，改变经济体不再使用化石燃料作为主要能源的技术变革可能能够实现这一目标。', ref:'从长期来看，推动技术变革，促使经济不再依赖化石燃料作为主要能源，或许能够实现这一目标。', tags:["准确性"] },
  { k:'seg_4_决赛_7', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But some sort of effective action is also needed now.', mt:'但是现在也需要采取某种有效的行动。', ref:'但是，目前仍然有待采取一些有效的行动。', tags:["准确性","风格"] },
  { k:'seg_4_决赛_8', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A study published in Science in 2018 measured leaks from a third of America’s natural-gas supply chain and oil-production sites.', mt:'幸运的是，可能确实有这样一种行动方案。', ref:'幸运的是，目前的有些行动是行之有效的。', tags:["准确性"] },
  { k:'seg_4_决赛_9', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'For carbon dioxide is not the only cause of global warming.', mt:'因为二氧化碳不是全球变暖的唯一原因。', ref:'因为二氧化碳并非是全球变暖的唯一原因。', tags:["准确性"] },
  { k:'seg_4_决赛_10', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'About a quarter of the effect is a consequence of a different gas, methane.', mt:'大约四分之一的影响是由另一种气体甲烷造成的。', ref:'气候变暖的成因有四分之一在于另外一种气体——甲烷。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_11', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And the methane problem looks a lot more tractable in the short term than does the carbon- dioxide one.', mt:'甲烷问题在短期内看起来比二氧化碳问题更容易解决。', ref:'短期来看，甲烷要比二氧化碳更容易对付。', tags:["准确性"] },
  { k:'seg_4_决赛_12', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'CO2 v CH4', mt:'CH4 中的CO2', ref:'二氧化碳（CO2）对甲烷（CH4）', tags:["术语","语言规范"] },
  { k:'seg_4_决赛_13', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Going after methane, a compound of one carbon atom with four hydrogens, makes sense, for it is a potent greenhouse agent.', mt:'寻找甲烷是一种由一个碳原子和四个氢组成的化合物，这是有意义的，因为它是一种强有力的温室气体制剂。', ref:'致力于解决甲烷的问题是有道理的，因为这种由一个碳原子和四个氢原子组成的化合物是一种强效温室气体。', tags:["准确性"] },
  { k:'seg_4_决赛_14', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Over the 20 years subsequent to its emission a tonne of methane causes 86 times more warming than does a tonne of CO2.', mt:'在排放后的20 年里，一吨甲烷导致的变暖是一吨二氧化碳的86 倍。', ref:'有一项研究对甲烷进行了20 多年的跟踪，研究结果发现，一吨甲烷所造成的全球变暖效果是一吨二氧化碳的86 倍。', tags:["准确性"] },
  { k:'seg_4_决赛_15', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Also, it does not hang around.', mt:'此外，它不会徘徊。', ref:'此外，甲烷不会长久停留在大气中。', tags:["准确性"] },
  { k:'seg_4_决赛_16', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'It has a half-life in the atmosphere of about a decade, so what is released soon vanishes.', mt:'它在大气中有大约十年的半衰期， 所以释放出来的东西很快就消失了。', ref:'甲烷在大气中的半衰期大约为十年，因此，甲烷一释放出来不久就会消失。', tags:["准确性"] },
  { k:'seg_4_决赛_17', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'By contrast, CO2 lingers for hundreds, or even thousands, of years.', mt:'相比之下，二氧化碳会持续数百年甚至数千年。', ref:'相比之下，二氧化碳会在大气中存在几百年甚至几千年。', tags:["准确性"] },
  { k:'seg_4_决赛_18', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The Climate and Clean Air Coalition, a collaboration of governments and environmental lobby groups, therefore reckons that halving anthropogenic methane emissions over the next 30 years could shave 0.18°C off the average global temperature in 2050.', mt:'因此，由政府和环境游说团体合作的气候和清洁空气联盟认为，未来 30 年将人为甲烷排放减半，可能会使2050 年全球平均气温下降 0.18 摄氏度。', ref:'气候和清洁空气联盟（Climate and Clean Air Coalition）是由各国政府和环保组织共同组建的环保组织，该联盟认为，如果未来 30 年间人为甲烷排放量减半，到 2050 年就可能使全球平均温度降低0.18 摄氏度。', tags:["准确性","语言规范","术语"] },
  { k:'seg_4_决赛_19', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That may not sound much, but it is between 20% and 45% of the gap between current temperatures and the goal, agreed on in Paris in 2015 by most of the world’s countries, of stabilising temperatures between 1.5°C and 2°C above pre-industrial averages.', mt:'这听起来可能不多，但目前的气温与2015 年世界上大多数国家在巴黎达成的将气温稳定在比工业化前平均水平高出1.5 摄氏度至2 摄氏度的目标之间的差距在20%至 45%之间。', ref:'这个降幅似乎并不多，但已相当于当前气温和2015 年巴黎气候大会上大多数国家达成一致的目标之间差值的20%-45%；巴黎气候大会确定的目标是将气温稳定在比工业化前平均气温高1.5-2 摄氏度之间。', tags:["准确性","语言规范","风格"] },
  { k:'seg_4_决赛_20', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Moreover, in many cases the cost of stopping emissions of methane can be offset against the fact that, unlike carbon dioxide, it is a valuable commodity.', mt:'此外，在许多情况下，停止甲烷排放的成本可以抵消这一事实，即与二氧化碳不同，甲烷是一种有价值的商品。', ref:'此外，在许多情况下，停止甲烷排放的成本可被抵消，因为它与二氧化碳不同，是一种有价值的商品。', tags:["准确性"] },
  { k:'seg_4_决赛_21', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The International Energy Agency (IEA, an intergovernmental organisation based in Paris) estimates that 75% of emissions from the oil and gas sector—some 16.5% of total human emissions—could be avoided with technologies available today, and that 40% (9% of total human emissions) could be eliminated at no net cost.', mt:'国际能源署（IEA，一个总部设在巴黎的政府间组织）估计，石油和天然气部门75%的排放——约占人类总排放的16.5%——可以用现在可用的技术来避免，40%（人类总排放的9%）可以免费消除。', ref:'据国际能源署（IEA，一家总部位于巴黎的政府间组织）估计，油气行业75%的甲烷排放（约占人类总排放量的16.5%）可以利用现有的技术消除，40%的排放（占人类总排放量的9%）可以采用净成本为零的方式消除。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_22', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The importance of tackling methane has become more apparent in the past decade and a half.', mt:'在过去的15 年里，处理甲烷的重要性变得更加明显。', ref:'十五年来，解决甲烷问题的重要性逐渐显现。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_23', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'After a plateau which began in 1999, concentrations of the gas in the atmosphere started rising again in 2007, a trend that continues to this day.', mt:'在1999 年开始的高原之后，大气中的气体浓度在2007 年又开始上升，这一趋势一直持续到今天。', ref:'大气中的甲烷浓度自1999 年起一直保持稳定，从2007 年开始上升，一直延续至今。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_24', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'At the moment, more than 300 million tonnes are emitted every year as a consequence of human activity, and that rate is growing.', mt:'目前，由于人类活动，每年排放超过3 亿吨，这一比率正在上升。', ref:'目前，每年人类活动会排放3 亿吨甲烷，而且这一数量还在不断增长。', tags:["准确性"] },
  { k:'seg_4_决赛_25', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'As a result, methane concentrations are now more than two-and-a-half times what they were before the Industrial Revolution, and are rising faster than allowed for in all but the most pessimistic climate projections for the 21st century.', mt:'因此，甲烷浓度现在是工业革命前的两倍半以上，而且除了对21 世纪最悲观的气候预测之外，上升速度都超过了允许的范围。', ref:'因此，当今的甲烷浓度已经是工业革命前的2.5 倍以上，而且增长速度接近对21 世纪气候变化最悲观的估测。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_26', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The rise after 2007 prompted a rush to understand methane’s sources and how it degrades in the atmosphere.', mt:'2007 年后的上升促使人们急于了解甲烷的来源以及它是如何在大气中降解的。', ref:'2007 年后的甲烷排放上升趋势， 迫使人们亟需尽快了解甲烷的源头及其在大气中的降解方式等问题。', tags:["准确性"] },
  { k:'seg_4_决赛_27', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That rise was originally seen as an anomaly, says Marielle Saunois of France’s Climate and Environmental Sciences Laboratory, “but now that it has been going on for 13 or 14 years, we see the plateau as the anomaly”.', mt:'法国气候与环境科学实验室的 Marielle Saunois 表示，这种上升最初被视为异常现象，“但现在它已经持续了13 或14 年，我们认为高原是异常现象”。', ref:'法国气候与环境科学实验室的玛丽埃勒·索诺伊斯（Marielle Saunois ）表示，“甲烷排放量的上升最初被当成了反常现象，但是，至今这种上升趋势已经持续了十三、四年了，我们认为2007 年以前的稳定期才是反常现象。”', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_28', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Both ground-based and aerial studies show that leaky natural- gas pipes are one culprit.', mt:'地面和空中研究都表明天然气管道泄漏是罪魁祸首之一。', ref:'地面及空中的监测研究均表明，天然气管道泄漏是罪魁祸首之一。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_29', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In 2018, for example, instruments mounted on planes flying downwind of Washington, Baltimore, Philadelphia, New York and Boston found that 850,000 tonnes of methane a year was wafting from these cities.', mt:'例如，2018 年，安装在华盛顿、 巴尔的摩、费城、纽约和波士顿顺风飞行的飞机上的仪器发现，每年有85 万吨甲烷从这些城市飘出。', ref:'例如，2018 年，在华盛顿、巴尔的摩、费城、纽约和波士顿下风向飞行的飞机上的检测仪器显示，每年会有85 万吨的甲烷从这些城市逸出。', tags:["准确性"] },
  { k:'seg_4_决赛_30', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That is roughly ten times the official estimate of the American government’s Environment Protection Agency (EPA).', mt:'这大约是美国政府环境保护局（环保局）官方估计的十倍。', ref:'这大约是美国环境保护局（EPA）官方估测的十倍。', tags:["准确性"] },
  { k:'seg_4_决赛_31', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A bigger source of emissions, though, is further up the fossil- fuel supply chain—at the points where natural gas, oil and coal are extracted from Earth’s crust, processed and moved around the globe.', mt:'然而，一个更大的排放源是化石燃料供应链的上游——在那里天然气、石油和煤炭从地壳中提取出来，加工并在全球运输。', ref:'更大的排放源可以追溯到化石燃料供应链的上游：从地壳中开采天然气、石油、煤，经过加工后运输到世界各地。', tags:["准确性","语言规范","风格"] },
  { k:'seg_4_决赛_32', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A study published in Science in 2018 measured leaks from a third of America’s natural-gas supply chain and oil-production sites.', mt:'2018 年发表在《科学》杂志上的一项研究测量了美国三分之一天然气供应链和石油生产基地的泄漏。', ref:'2018 年发表在《科学》杂志的一项研究监测了美国三分之一的天然气供应链以及石油生产场所的泄漏情况。', tags:["准确性"] },
  { k:'seg_4_决赛_33', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Extrapolating from this sample, the team involved estimated that some 13 million tonnes of methane escaped from these facilities each year, approximately 60% more than the EPA’s official figures.', mt:'根据这个样本推断，参与的团队估计每年约有1300 万吨甲烷从这些设施中逸出，比环境保护局的官方数据高出约60%。', ref:'该研究团队根据采样分析推测，这些设施每年大约泄漏1300 万吨的甲烷，约比美国环境保护局的官方数值高60%。', tags:["准确性"] },
  { k:'seg_4_决赛_34', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The IEA, meanwhile, estimates that each year the world’s coal mines liberate roughly 40 million tonnes of methane that was once trapped in the coal being extracted.', mt:'与此同时，国际能源署估计，世界煤矿每年释放大约4000 万吨甲烷，这些甲烷曾经被困在被开采的煤炭中。', ref:'同时，国际能源署估计，全球煤矿每年大约释放出4000 万吨甲烷， 而这些气体原本存储在煤矿之中， 挖矿时会释放出来。', tags:["准确性","风格"] },
  { k:'seg_4_决赛_35', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'As a source of power, coal is on its way out, but not fast enough.', mt:'作为一种能源，煤炭正在消失，但速度不够快。', ref:'燃煤发电正在逐渐被淘汰，但速度还不够快。', tags:["准确性"] },
  { k:'seg_4_决赛_36', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'It maintains a stronghold in Asia, and in China in particular, where it could stymie efforts to stabilise the climate.', mt:'它在亚洲，特别是在中国保持着一个据点，在那里它可能会阻碍稳定气候的努力。', ref:'亚洲，尤其是中国，仍然大量采用燃煤发电，这会妨碍稳定气候变化的努力。', tags:["准确性"] },
  { k:'seg_4_决赛_37', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Researchers at Global Energy Monitor, an environmental lobby group that maintains a log of coal-related operations around the world, estimate that planned new mines will emit a further 13.5 million tonnes a year.', mt:'全球能源监测组织的研究人员估计，计划中的新煤矿每年将再排放 1350 万吨煤炭。该组织是一个环境游说团体，在世界各地维护一份煤炭相关运营日志。', ref:'全球能源监测组织（Global Energy Monitor)是一个监测全球煤炭产业日常运营的环保组织，该组织的研究人员预测，每年计划新建煤矿的排放量将达1350 万吨。', tags:["准确性","术语"] },
  { k:'seg_4_决赛_38', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Their report, published in March, surveyed 432 mining projects, more than 100 of which are already under construction in China.', mt:'他们在3 月份发表的报告调查了 432 个采矿项目，其中100 多个已经在中国建设中。', ref:'该组织在三月份发布的报告调查了 432 个采矿项目，其中，100 多个项目已经在中国开工建设。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_39', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'As soon as a seam is opened it starts to emit methane.', mt:'接缝一打开就开始排放甲烷。', ref:'只要打开煤层，就会开始排放甲烷。', tags:["准确性"] },
  { k:'seg_4_决赛_40', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'While a mine is active its methane is vented deliberately into the atmosphere to avoid explosions.', mt:'当矿井处于活跃状态时，它的甲烷会被故意排放到大气中以避免爆炸。', ref:'一旦开始生产，为避免爆炸，煤矿就要有意地把甲烷排放到大气中。', tags:["准确性"] },
  { k:'seg_4_决赛_41', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But even once it has been closed it can carry on leaking the gas for decades.', mt:'但即使关闭了，它也可能会持续泄漏气体几十年。', ref:'即使煤矿关停之后，仍会继续泄漏甲烷几十年。', tags:["准确性"] },
  { k:'seg_4_决赛_42', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The task of putting together all the data on sources of methane has fallen to an international collaboration called the Global Methane Budget, led by Dr Saunois.', mt:'汇集所有甲烷来源数据的任务已经落到了由索诺斯博士领导的名为全球甲烷预算的国际合作肩上。', ref:'由索诺伊斯博士领导的国际合作组织项目全球甲烷预算（Global Methane Budget)承担收集甲烷源头数据的任务。', tags:["准确性","术语"] },
  { k:'seg_4_决赛_43', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This seeks to understand what might be called the methane cycle, by tracing how much CH4 makes its way into and out of the atmosphere every year, and developing a model that describes this.', mt:'通过追踪每年有多少CH4 进入和离开大气层，并开发一个描述这一点的模型，这试图理解什么可能被称为甲烷循环。', ref:'通过跟踪每年进出大气的甲烷量， 该项目开发了描述所谓“甲烷循环”过程的模型。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_44', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Gas pains', mt:'气体疼痛', ref:'甲烷之伤', tags:["准确性"] },
  { k:'seg_4_决赛_45', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Besides leaky wells and pipelines, and gassy coal mines, methane is also emitted by belching cattle, rice paddies, forest fires, slash-and-burn agriculture, rubbish dumps, wastewater-treatment plants, cars and lorries, and natural ecosystems such as swamps, rivers and lakes.', mt:'如图所示，除了漏水的井和管道以及瓦斯煤矿，甲烷还由喷气的牛、 稻田、森林火灾、刀耕火种农业、 垃圾场、废水处理厂、汽车和卡车以及沼泽、河流和湖泊等自然生态系统排放。', ref:'除了矿井、管道、瓦斯煤矿会泄漏甲烷，牲畜、稻田、林火、刀耕火种、垃圾堆场、污水处理、汽车卡车以及诸如湿地、河湖等自然生态系统都会释放甲烷。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_46', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A perfect inventory would require knowledge of the size, nature and locations of all such sources around the globe— currently an impossible undertaking.', mt:'一个完美的清单需要了解全球所有此类来源的规模、性质和位置—— 目前这是一项不可能的任务。', ref:'厘清上述源头的全球性规模、性质以及位置，才能获得一份堪称完美的源头清单，但目前这是一项无法完成的任务。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_47', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Instead, researchers at the Global Methane Budget combine two methods, one bottom-up, the other top-down, to arrive at the best estimate they can.', mt:'相反，全球甲烷预算的研究人员结合了两种方法，一种自下而上，另一种自上而下，以尽可能得出最佳估计。', ref:'因此，全球甲烷预算（Global Methane Budget)项目研究人员采用了自下而上和自上而下相结合的方法，以求达到最精准的估值。', tags:["准确性","术语"] },
  { k:'seg_4_决赛_48', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The bottom-up approach is to scrape national and international sets of data for information on all possible sources of the gas, and then combine this with estimates of how much methane each type of source emits.', mt:'自下而上的方法是收集国家和国际数据集，以获取所有可能的天然气来源的信息，然后将其与每种来源排放的甲烷估计值结合起来。', ref:'自下而上的方法，就是收集所有国家和国际甲烷来源数据，然后将这些数据与每种来源的甲烷排放量估值相结合。', tags:["准确性"] },
  { k:'seg_4_决赛_49', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The top-down approach employs direct satellite and ground-based measurements of methane concentrations.', mt:'自上而下的方法采用直接的卫星和地面甲烷浓度测量。', ref:'自上而下的方法，就是直接采用卫星及地面监测装置收集甲烷浓度信息。', tags:["准确性"] },
  { k:'seg_4_决赛_50', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The two are reconciled by plugging the list of sources into a computer model intended to simulate the flow of methane from its sources and the way it is broken down in the atmosphere.', mt:'这两者是通过将来源列表插入一个计算机模型来协调的，该模型旨在模拟甲烷从其来源的流动及其在大气中分解的方式。', ref:'这两种方法得出的数据相结合，制成源头清单并录入计算机模型，模仿甲烷从源头释放的情况及其在大气中的降解方式。', tags:["准确性"] },
  { k:'seg_4_决赛_51', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This produces hypothetical atmospheric concentrations which can be checked against the real measurements.', mt:'这产生了假设的大气浓度，可以对照实际测量值进行检查。', ref:'这样就可以得出假设的甲烷浓度， 可与真实测量数据进行比对。', tags:["准确性"] },
  { k:'seg_4_决赛_52', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Mismatches are reduced by adjusting the modelled flows to arrive at a best estimate of what is actually happening.', mt:'通过调整建模流以获得对实际发生情况的最佳估计，可以减少不匹配。', ref:'通过调整释出数据，可得出接近真实情况的最精准估值，因此估值同实际数值不符的情况就会减少。', tags:["准确性","风格"] },
  { k:'seg_4_决赛_53', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Dr Saunois’s team published their first results in July 2020.', mt:'索诺伊斯博士的团队在2020 年7 月发表了他们的第一个结果。', ref:'2020 年7 月，索诺伊斯博士团队发布了他们的第一阶段研究成果。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_54', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'They found that between 550 million and 880 million tonnes of methane per year were emitted between 2008 and 2017— roughly 9% more than the average between 2000 and 2006.', mt:'他们发现，在2008 年至2017 年期间，每年排放5.5 亿至8.8 亿吨甲烷——比2000 年至2006 年的平均水平高出约9%。', ref:'他们发现，2008 年至2017 年，每年的甲烷排放量在5.5 亿到8.8 亿吨之间，比2000 年到2006 年间的均值高出9%。', tags:["准确性"] },
  { k:'seg_4_决赛_55', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Between 50% and 60% of this came from human activities, depending on whether the bottom-up or top-down method was used.', mt:'其中50%到60%来自人类活动， 这取决于是使用自下而上还是自上而下的方法。', ref:'其中的50%-60%来自人类活动， 区间的波动在于自下而上和自上而下两种研究方法的差别。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_56', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Of these, roughly speaking, fossil fuels and agriculture each account for a third, with the remainder coming from a combination of emissions from things like cars, fires, landfills and waste-water processing.', mt:'粗略地说，其中化石燃料和农业各占三分之一，其余来自汽车、火灾、垃圾填埋场和废水处理等排放物的组合。', ref:'在化石燃料和农业排放大约各占三分之一，剩余部分来自汽车、明火、垃圾堆场以及废水处理等环节的排放。', tags:["准确性"] },
  { k:'seg_4_决赛_57', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The post-2007 uptick in methane levels, the team found, was caused by extra human emissions, though there may also be some diminution in the atmosphere’s ability to destroy the gas.', mt:'该小组发现，2007 年后甲烷水平的上升是由额外的人类排放造成的，尽管大气破坏气体的能力也可能有所下降。', ref:'该团队发现，2007 年后甲烷浓度的上升主要是由额外的人类排放所致，而大气分解甲烷的能力可能也有所减弱。', tags:["准确性"] },
  { k:'seg_4_决赛_58', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Thankfully, there was little sign of increased release of methane from Arctic tundra, which some fear may happen as the tundra warms.', mt:'谢天谢地，北极苔原释放的甲烷几乎没有增加的迹象，一些人担心这可能会随着苔原变暖而发生。', ref:'有人担心，北极苔原带变暖会释放出更多的甲烷，但幸运的是，目前还没有这个迹象。', tags:["准确性"] },
  { k:'seg_4_决赛_59', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Fossil-fuel emissions increased a lot in China over the decade that followed 2007, and to a lesser extent in other Asian countries, America, Africa and the Middle East.', mt:'在2007 年之后的十年里，中国的化石燃料排放量大幅增加，其他亚洲国家、美国、非洲和中东的排放量则有所下降。', ref:'在2007 年后的十年间，中国的化石燃料排放量大幅增加，其他亚洲国家、美洲、非洲以及中东地区也有增加，只是增幅较小。', tags:["准确性"] },
  { k:'seg_4_决赛_60', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'China, indeed, is the world’s largest methane emitter, an accolade it owes partly to its continued exploitation of coal.', mt:'事实上，中国是世界上最大的甲烷排放国，这一荣誉部分归功于它对煤炭的持续开采。', ref:'实际上，中国是世界上甲烷排放量最大的国家，该国持续不断地开采煤矿是部分原因。', tags:["准确性"] },
  { k:'seg_4_决赛_61', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In spite of regulations brought in to encourage mine operators to use methane from their mines for such purposes as power generation, rather than venting it into the atmosphere, a study published in Nature, in 2019, found that the sector’s activities were still driving China’s methane emissions up.', mt:'尽管出台了鼓励矿山运营商将矿山甲烷用于发电等目的的法规，而不是将其排放到大气中，但2019 年发表在《自然》杂志上的一项研究发现，该行业的活动仍在推高中国的甲烷排放。', ref:'虽然中国出台了相关规定，鼓励煤矿经营者回收矿井中的甲烷发电， 而不是直接将甲烷排放到大气中， 但2019 年发表在《自然》杂志的一项研究发现，煤炭产业的活动仍在推高中国的甲烷排放量。', tags:["准确性"] },
  { k:'seg_4_决赛_62', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Europe was the only region to achieve a drop in emissions, in part thanks to policies to reduce the amount of biodegradable waste that is sent to landfill.', mt:'欧洲是唯一实现排放下降的地区， 部分原因是减少送往垃圾填埋场的可生物降解废物数量的政策。', ref:'欧洲是唯一实现甲烷排放量下降的地区，部分得益于欧洲出台了减少送往垃圾堆场的可降解废弃物数量的政策。', tags:["准确性"] },
  { k:'seg_4_决赛_63', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The largest increases in agricultural emissions came from Asia, Africa and the Middle East—and agricultural sources, specifically livestock and rice paddies, are the most difficult of all to deal with.', mt:'农业排放的最大增长来自亚洲、非洲和中东——农业来源，特别是牲畜和稻田，是最难处理的。', ref:'农业排放增幅最大的地区分别为亚洲、非洲和中东地区，农业排放源头是最难解决的，尤其是牲畜和稻田。', tags:["准确性","语言规范","风格"] },
  { k:'seg_4_决赛_64', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In both cases, the gas is produced by methanogenic microbes that live, respectively, in the animals’ guts and decomposing excrement, and in oxygen-poor waterlogged soil.', mt:'在这两种情况下，气体都是由产甲烷微生物产生的，这些微生物分别生活在动物的肠道和分解的排泄物中，以及缺氧的积水土壤中。', ref:'牲畜和稻田排放的甲烷气体都源自于产甲烷微生物，而在动物的内脏、腐烂的排泄物或缺氧的渍水土壤中都含有这种微生物。', tags:["准确性","风格"] },
  { k:'seg_4_决赛_65', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Paddies account for 8% of man- made methane emissions.', mt:'稻田占人为甲烷排放的8%。', ref:'稻田甲烷排放占人为排放总量的 8%。', tags:["准确性"] },
  { k:'seg_4_决赛_66', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Varieties of rice that yield more grain for the same amount of methane could help reduce this, but a technologically simpler approach would be to switch to irrigating paddies for less time, which comes with the added bonus of saving water too.', mt:'用同样数量的甲烷生产更多谷物的水稻品种可能有助于减少这种情况，但技术上更简单的方法是在更短的时间内转向灌溉稻田，这也带来了节水的额外好处。', ref:'种植甲烷排放量相同而产量更高的水稻品种，有助于降低这一占比， 更简单易行的技术方法则是减少稻田的灌溉时间，这样还可以节约用水。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_67', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The lion’s share of agricultural methane, though, comes from ruminant livestock—cows and sheep, mainly.', mt:'然而，农业甲烷的大部分主要来自反刍动物——奶牛和绵羊。', ref:'大部分的农业甲烷源自于反刍牲畜，主要是牛和羊。', tags:["准确性","风格"] },
  { k:'seg_4_决赛_68', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Such husbandry generates 79% of the sector’s contribution.', mt:'这种畜牧业产生了该部门79%的贡献。', ref:'牲畜养殖业占农业甲烷排放量的 79%，', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_69', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That amounts to 30% of all anthropogenic emissions.', mt:'这相当于所有人为排放的30%。', ref:'占人为排放总量的30%。', tags:["准确性"] },
  { k:'seg_4_决赛_70', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Asking people to eat less meat and drink less milk, while fashionable at the moment in rich countries, probably goes against the Bismarckian principle of realism in the wider, middle-income world where discretionary spending is rising and diets are improving.', mt:'在富裕国家，要求人们少吃肉、少喝牛奶虽然现在很流行，但在更广泛的中等收入国家，这可能违背了俾斯麦式的现实主义原则，在这些国家，自由支配支出正在增加，饮食也在改善。', ref:'少吃肉、少喝奶，虽然在富裕国家已成为时尚潮流，但可支配支出持续增长、饮食条件不断改善的中等收入国家，这可能违背了俾斯麦式的现实主义原则。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_71', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But another option is to attack the methanogens themselves.', mt:'但是另一个选择是攻击甲烷菌本身。', ref:'消灭产甲烷菌则是另外一个选择。', tags:["准确性"] },
  { k:'seg_4_决赛_72', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This is now being investigated experimentally, to see if changing what the animals eat can damp down methanogenic activity.', mt:'这正在进行实验研究，看看改变动物吃的东西是否能抑制产甲烷活动。', ref:'目前有实验研究正在求证是否可以通过改变动物饲料来抑制产甲烷菌的活性。', tags:["准确性"] },
  { k:'seg_4_决赛_73', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Though it is probably not a practical solution at scale, some studies suggest a diet rich in certain seaweeds can decrease an animal’s methane emissions by as much as 80%.', mt:'尽管这可能不是一个大规模的实际解决方案，但一些研究表明，富含某些海藻的饮食可以减少动物 80%的甲烷排放。', ref:'这也许不是一种可以大规模适用的解决方案，但有研究表明，采用富含某些海藻的饲料可以将动物甲烷排放减少80%。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_74', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A compound called bromoform, abundant in these algae, inhibits the chemical reactions that produce methane inside the animals’ rumens.', mt:'这些藻类中富含一种叫做溴仿的化合物，抑制动物瘤胃内产生甲烷的化学反应。', ref:'这些藻类含有大量名为三溴甲烷的化合物，它会抑制动物瘤胃中产生甲烷的化学反应。', tags:["准确性","风格"] },
  { k:'seg_4_决赛_75', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Unfortunately, cattle fed enough seaweed to experience the 80% cut produce less meat or milk than they otherwise would.', mt:'不幸的是，牛喂了足够多的海藻， 经历了80%的切割，产生的肉或奶比其他情况下要少。', ref:'很不幸的是，给牛喂食足够量的此类海藻，甲烷排量可下降80%， 但产肉量、产奶量均有所下降。', tags:["准确性"] },
  { k:'seg_4_决赛_76', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But another, more benign, dietary change does seem to help without side-effects.', mt:'但是另一种更良性的饮食改变似乎没有副作用。', ref:'另一种更为良性的新饲喂方式似乎更胜一筹，而且没有副作用。', tags:["准确性"] },
  { k:'seg_4_决赛_77', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This is to add vegetable oils to ruminants’ diets.', mt:'这是在反刍动物的饮食中添加植物油。', ref:'就是在反刍动物的饲料中添加植物油。', tags:["准确性"] },
  { k:'seg_4_决赛_78', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'These are calorie-rich, but do not ferment in the rumen and therefore do not encourage methanogens.', mt:'这些富含卡路里，但不在瘤胃中发酵，因此不鼓励产甲烷。', ref:'植物油富含卡路里，但不会在瘤胃中发酵，因此不会促进产甲烷菌的生长。', tags:["准确性"] },
  { k:'seg_4_决赛_79', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This approach can cut emissions by 11-18%.', mt:'这种方法可以减少11-18%的排放。', ref:'这一方法可以减少11-18%的甲烷排放量。', tags:["准确性"] },
  { k:'seg_4_决赛_80', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'More radically, methanogen activity can be disrupted by adding synthetic chemicals to animals’ diets.', mt:'更根本的是，甲烷原活性可以通过在动物饮食中添加合成化学物质来破坏。', ref:'此外，在动物饲料中添加合成化学物质可以破坏产甲烷菌的活性。', tags:["准确性"] },
  { k:'seg_4_决赛_81', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'One such is 3-nitrooxypropanol, which gums up an enzyme the bugs use to generate methane.', mt:'其中之一是3-硝基氧丙醇，它会破坏昆虫用来产生甲烷的酶。', ref:'上述合成化学物质之一是3-硝基氧基丙醇，它可以和菌群用以合成甲烷的酶相结合。', tags:["准确性"] },
  { k:'seg_4_决赛_82', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'DSM, a Dutch firm, has turned this into a product, now awaiting approval for use in Europe, which it claims can reduce the amount a cow emits by 27-40%.', mt:'荷兰帝斯曼公司已经将其转化为一种产品，目前正在等待欧洲的使用批准，该公司声称这种产品可以将奶牛的排放量减少27-40%。', ref:'荷兰帝斯曼公司（DSM）已开发了3-硝基氧基丙醇产品，目前正在欧洲等待批准使用，该公司称可将奶牛的甲烷排放量减少27%- 40%。', tags:["准确性","语言规范","术语"] },
  { k:'seg_4_决赛_83', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Just do it', mt:'就这么做吧', ref:'说做就做', tags:["准确性"] },
  { k:'seg_4_决赛_84', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That methane emissions are a prime target for reduction is an idea which has caught on with politicians, at least in rich countries.', mt:'甲烷排放是减排的主要目标，这一想法已经被政治家们所接受，至少在富裕国家是如此。', ref:'减少甲烷排放是减排的主要目标之一，这已成政治家们的共识，至少在富裕国家是这样。', tags:["准确性"] },
  { k:'seg_4_决赛_85', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In October, the European Commission adopted a “European methane strategy”, the implementation of which will be thrashed out this year.', mt:'今年10 月，欧盟委员会通过了一项“欧洲甲烷战略”，该战略的实施将在今年进行讨论。', ref:'今年十月，欧盟委员会发布“欧洲甲烷战略”，具体实施办法将在年内出台。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_86', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The previous plan had been to cut the EU’s emissions in 2030 to a level 29% below those of 2005.', mt:'此前的计划是在2030 年将欧盟的排放量削减到比2005 年低29%的水平。', ref:'此前，欧盟计划到2030 年将甲烷排放量降至比2005 年低29%的水准。', tags:["准确性"] },
  { k:'seg_4_决赛_87', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That target has now been increased to 35-37%.', mt:'这一目标现已提高到35-37%。', ref:'新计划的减排目标提高到35%- 37%。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_88', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In 2020 Donald Trump, who was then the president, repealed regulations on monitoring and plugging methane leaks introduced by his predecessor, Barack Obama.', mt:'2020 年，时任总统唐纳德·特朗普废除了他的前任巴拉克·奥巴马提出的监测和堵塞甲烷泄漏的法规。', ref:'2020 年，时任美国总统唐纳德·特朗普（Donald Trump）废除了其前任巴拉克·奥巴马（Barack Obama）颁布的监测和堵塞甲烷泄漏的相关法规。', tags:["准确性","术语"] },
  { k:'seg_4_决赛_89', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Mr Trump’s successor, Joe Biden, says he will reverse this reversal, but is also under pressure from environmental lobby groups to go further, by setting a target of reducing emissions by as much as 65% by 2025.', mt:'特朗普的继任者乔·拜登表示，他将扭转这一逆转，但也受到环境游说团体的压力，要求他更进一步， 设定到2025 年减排高达65%的目标。', ref:'特朗普先生的继任者乔·拜登（Joe Biden）表示，他将恢复该项已被撤销的法规，即便如此，环保团体仍然在不断向他施压，要求他更进一步，设定到2025 年减排65%的目标。', tags:["准确性","术语"] },
  { k:'seg_4_决赛_90', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Such lofty goals are worth little, though, if their consequences are not measured.', mt:'然而，如果不衡量其后果，这些崇高的目标毫无价值。', ref:'但是，如果结果得不到衡量，设定远大的目标就毫无意义可言。', tags:["准确性"] },
  { k:'seg_4_决赛_91', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Fossil-fuel companies naturally gather their own data privately.', mt:'化石燃料公司自然会私下收集自己的数据。', ref:'化石燃料公司自然会收集各自的数据。', tags:["准确性"] },
  { k:'seg_4_决赛_92', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And several environmental organisations hunt for leaks in pipelines and so on using instruments mounted on cars and planes.', mt:'一些环保组织利用安装在汽车和飞机上的仪器寻找管道泄漏等。', ref:'一些环境组织会利用安装在汽车或飞机上的设备，搜寻管道上的泄漏点。', tags:["准确性"] },
  { k:'seg_4_决赛_93', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Their goal is to shine a light on the issue, but their data are also frequently fed back to oil and gas operators, to help them patch up their pipelines.', mt:'他们的目标是揭示这个问题，但他们的数据也经常反馈给石油和天然气运营商，以帮助他们修补管道。', ref:'他们的目标是曝光问题，他们的数据通常也会反馈给油气运营商，帮助他们及时修补管道。', tags:["准确性"] },
  { k:'seg_4_决赛_94', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The Environmental Defence Fund says responses vary, but many firms are grateful for the additional feedback.', mt:'环境保护基金表示，回应各不相同，但许多公司对额外的反馈表示感谢。', ref:'美国环保协会（Environmental Defence Fund）表示，油气公司对此的反应不尽相同，但许多公司对这种反馈充满感激。', tags:["准确性","术语"] },
  { k:'seg_4_决赛_95', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The Oil and Gas Methane Partnership (OGMP), a UN-led project, standardises methods for measuring and reporting methane emissions in the fossil- fuel industry.', mt:'石油和天然气甲烷伙伴关系（OGMP）是一个由联合国领导的项目，它对化石燃料行业测量和报告甲烷排放的方法进行了标准化。', ref:'由联合国主导的油气甲烷伙伴关系（OGMP）项目提供标准化的方法监测和报告化石燃料行业的甲烷排放情况。', tags:["准确性"] },
  { k:'seg_4_决赛_96', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'At the last count, it had recruited 66 companies which, collectively, produce 30% of the world’s oil and gas.', mt:'根据最近的统计，它招募了66 家公司，这些公司总共生产了世界上 30%的石油和天然气。', ref:'最新数据显示，该项目已招募了 66 家油气企业，这些公司的石油和天然气产量总和占世界产量的 30%。', tags:["准确性","语言规范"] },
  { k:'seg_4_决赛_97', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Data collected through the OGMP will be fed into a new International Methane Emissions Observatory being cooked up by the UN Environment Programme and the European Commission.', mt:'通过OGMP 收集的数据将被输入一个新的国际甲烷排放观测站，该观测站正由联合国环境规划署和欧盟委员会筹备。', ref:'油气甲烷伙伴关系项目收集的数据会提供给国际甲烷排放观测项目， 该项目是联合国环境规划署同欧盟委员会共同策划成立的新机构。', tags:["准确性"] },
  { k:'seg_4_决赛_98', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This will combine them with other measurements, including from the growing number of satellites that measure methane sources from above, to verify national and corporate accounting.', mt:'这将把它们与其他测量结合起来， 包括从越来越多的卫星上测量甲烷来源，以核实国家和公司的核算。', ref:'该项目将联合其他监测手段，包括监测上文所述甲烷源头的日益增多的卫星，核实国家及公司的相关统计数据。', tags:["准确性"] },
  { k:'seg_4_初赛_1', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Work Imitates Life', mt:'工作模仿生活', ref:'工作生活两不误', tags:["准确性"] },
  { k:'seg_4_初赛_2', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Few companies could announce a new office in the messianic way that Google did last February.', mt:'很少有公司能像谷歌去年2 月那样以救世主般的方式宣布新办公室。', ref:'很少有公司发布过像谷歌去年 2 月发布的那种雄心勃勃的新办公园区建设计划。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_3', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then again, few companies have ever built this sort of office.', mt:'话说回来，很少有公司建造过这种办公室。', ref:'同样，很少有公司建设过那样的办公园区。', tags:["准确性"] },
  { k:'seg_4_初赛_4', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'‘Google’s presence in Mountain View is simply so strong that it can’t be the fortress that shuts away… the neighbours. It really needs to become a neighbourhood in Mountain View,’ intones the lead architect Bjarke Ingels of the Danish firm Bjarke Ingels Group (BIG) in the introductory video.', mt:'丹麦Bjarke Ingels 集团首席建筑师比亚克• 英格斯（Bjarke Ingels Group）在介绍视频中吟诵道：“谷歌在山景城的影响力如此之大，以至于它不可能成为关闭...邻居的堡垒。它真的需要成为山景城的一个街区。”', ref:'丹麦比亚克•英厄尔斯集团 (Bjarke Ingels Group) 的首席建筑师比亚克•英厄尔斯 (Bjarke Ingels) 在视频陈述中表示：“谷歌在山景城的范围实在太大，不可能成为隔绝外人的孤堡。谷歌想要在山景城打造一个社区。”', tags:["准确性","语言规范","术语","风格"] },
  { k:'seg_4_初赛_5', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The camera sweeps high over an edenic Mountain View in the San Francisco Bay Area.', mt:'摄像机高高地扫过旧金山湾区的一个伊甸园山景。', ref:'高空摄像机扫过旧金山湾区伊甸园般的山景城。', tags:["准确性"] },
  { k:'seg_4_初赛_6', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It pulls back to reveal Google’s proposed new office: a neighbourhood nested beneath glittering glass domes.', mt:'它向后拉，展示了谷歌提议的新办公室：一个嵌套在闪闪发光的玻璃穹顶下的街区。', ref:'然后，镜头切到谷歌即将兴建的新办公园区，那是一个坐落在金碧辉煌的玻璃穹顶之下的社区。', tags:["准确性"] },
  { k:'seg_4_初赛_7', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'On approximately 3.5 million square feet of commercial land, Google intended to build a campus office that might best be described as a new part of town.', mt:'在大约350 万平方英尺的商业用地上，谷歌打算建造一个校园办公室，这个办公室最好被描述为城镇的一个新部分。', ref:'谷歌计划在一块大约350 万平方英尺的商业用地上建造办公园区，与其说是办公园区，倒不如说是山景城的一个新城区。', tags:["准确性"] },
  { k:'seg_4_初赛_8', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Beneath the glass canopies, a thriving neighbourhood hosts stores, bike paths and modular office spaces.', mt:'在玻璃雨棚下面，一个繁荣的社区里有商店、自行车道和模块化办公空间。', ref:'玻璃穹顶的下面是一个繁华的社区，有商店，有自行车道，还有模块化办公空间。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_9', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In building this new neighbourhood, Google hoped to expand their working space while accommodating the Mountain View population inclined to view them as a ‘fortress’.', mt:'通过建造这个新社区，谷歌希望扩大他们的工作空间，同时容纳倾向于将他们视为“堡垒”的山景城居民。', ref:'通过建设这个新社区，谷歌意在扩大工作空间，同时纳入一向将谷歌视为“孤堡”的山景城人。', tags:["准确性"] },
  { k:'seg_4_初赛_10', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The utopian campus was meant to assuage fears that spiking numbers of Google employees would create a Google voting bloc, according to The New York Times.', mt:'据《纽约时报》报道，乌托邦式的校园旨在缓解人们的担忧，即谷歌员工数量激增会形成一个谷歌投票集团。', ref:'据《纽约时报》分析，之所以建设这个乌托邦式的办公园区， 是为了缓解人们的担忧，人们担心谷歌员工数量激增，最终会形成一个选票集团。', tags:["准确性"] },
  { k:'seg_4_初赛_11', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Such fears are understandable.', mt:'这种担忧是可以理解的。', ref:'这种担忧是可以理解的。', tags:[] },
  { k:'seg_4_初赛_12', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As of 2013, the company employed roughly 10 per cent of Mountain View’s workforce and owned approximately the same proportion of taxable property.', mt:'截至2013 年，该公司雇佣了约 10%的山景城员工，拥有约同等比例的应税财产。', ref:'截至2013 年，谷歌的员工占山景城职工总数的约10%，并拥有约同等比例的应税财产。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_13', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Despite promises that the campus would be open to all, in May 2015 the Mountain View City Council denied Google the majority of the land they’d requested.', mt:'尽管承诺校园将对所有人开放， 但在2015 年5 月，山景市议会拒绝了谷歌申请的大部分土地。', ref:'尽管谷歌承诺办公园区将对所有人开放，但在2015 年5 月， 山景城议会拒绝了谷歌的大部分土地申请。', tags:["准确性"] },
  { k:'seg_4_初赛_14', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google submitted a similar but smaller plan to the city later that month.', mt:'谷歌在当月晚些时候向该市提交了一份类似但规模较小的计划。', ref:'当月晚些时候，谷歌向山景城提交了一份类似但占地规模较小的新计划。', tags:["准确性"] },
  { k:'seg_4_初赛_15', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'This one proposes to treat its own water supply and expand the suite of amenities that, anecdotally, have enabled at least a few Google employees to forgo private housing ‒ sometimes by sleeping in trucks and vans while otherwise living on campus.', mt:'该计划提议处理自己的供水，并扩大配套设施。有趣的是，这些设施使至少一些谷歌员工能够放弃私人住房⸺有时他们住在校园里，睡在卡车和货车里。', ref:'在新计划中，谷歌提出自行解决供水问题，并扩大配套设施， 有了这些设施，某些谷歌员工就不需要私有住宅，有时可以住在园区里，有时甚至可以睡在卡车或货车里。', tags:["准确性"] },
  { k:'seg_4_初赛_16', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It’s a life many want.', mt:'这是许多人想要的生活。', ref:'这是许多人想要的生活。', tags:[] },
  { k:'seg_4_初赛_17', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google boasts more than 2 million job applicants a year.', mt:'谷歌以每年有200 多万求职者而自豪。', ref:'谷歌每年有200 多万名求职者。', tags:["准确性"] },
  { k:'seg_4_初赛_18', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'National media hailed its office plans as a ‘glass utopia’.', mt:'全国性媒体称赞其办公计划是“玻璃乌托邦”。', ref:'有美国媒体将这个园区开发计划称为“玻璃穹顶下的乌托邦”。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_19', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There are hosts of articles for businesspeople on how to make their offices more like Google’s workplace.', mt:'有大量文章面向商界人士，讲述如何让他们的办公室更像谷歌的工作场所。', ref:'随后涌现了大量面向商界人士的文章，向他们讲述如何将办公场所打造得像谷歌一样。', tags:["准确性"] },
  { k:'seg_4_初赛_20', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A 2015 CNN Money survey of business students around the world showed Google as their most desired employer.', mt:'美国有线电视新闻网2015 年对世界各地商科学生的一项调查显示，谷歌是他们最渴望的雇主。', ref:'2015 年，美国有线电视新闻网财经频道 (CNN Money)面向世界各地的商科学生做了一项调查，调查结果表明谷歌是商科学生最愿意效力的雇主。', tags:["准确性","术语","语言规范"] },
  { k:'seg_4_初赛_21', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Its campus is a cultural symbol of that desirability.', mt:'它的校园是这种渴望的文化象征。', ref:'谷歌的办公园区便是这种吸引力的文化象征。', tags:["准确性"] },
  { k:'seg_4_初赛_22', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The specifics of Google’s proposed Mountain View office are unprecedented, but the scope of the campus is part of an emerging trend across the tech world.', mt:'谷歌拟议中的山景城办公室的具体细节是前所未有的，但园区的范围是整个科技界新兴趋势的一部分。', ref:'谷歌的办公园区计划世所罕见，但建设大型园区已经成为整个科技界的一股新潮流。', tags:["准确性"] },
  { k:'seg_4_初赛_23', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Alongside Google’s neighbourhood is a recent Facebook open office on their campus that, as the largest open office in the world, parallels the platform’s massive online community.', mt:'在谷歌附近，最近在他们的园区设立了一个Facebook 开放办公室，作为世界上最大的开放办公室，与该平台庞大的在线社区相当。', ref:'除了谷歌园区，脸书 (Facebook) 也在自己的园区新建了开放式办公空间，这是世界上面积最大的开放型办公空间，与其庞大的在线社区相匹配。', tags:["准确性","术语"] },
  { k:'seg_4_初赛_24', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Both offices seem modest next to the ambitious and fraught effort of Tony Hsieh, CEO of the online fashion retailer Zappos, to revitalise the downtown Las Vegas area around Zappos’ office in the old City Hall.', mt:'与在线时尚零售商Zappos 首席执行官谢长廷雄心勃勃、令人担忧的努力相比，这两个办公室似乎都不大。谢长廷希望振兴 Zappos 位于旧市政厅办公室周围的拉斯维加斯市中心地区。', ref:'在线时尚零售商美捷步 (Zappos) 首席执行官谢家华也发布了一项雄心勃勃的计划，旨在重建美捷步拉斯维加斯办公楼附近的老城区，与此相比，谷歌和脸书的园区开发计划就相形见绌了。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_25', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Such offices symbolise not just the future of work in the public mind, but also a new, utopian age with aspirations beyond the workplace.', mt:'这样的办公室不仅象征着公众心目中工作的未来，也象征着一个超越工作场所的乌托邦新时代。', ref:'这些办公园区计划不仅代表公众对于未来工作的期待，也象征着一个乌托邦式的新时代的来临，工作场所不仅仅是工作的场所。', tags:["准确性"] },
  { k:'seg_4_初赛_26', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The dream is a place at once comfortable and entrepreneurial, where personal growth aligns with profit growth, and where work looks like play.', mt:'梦想是一个既舒适又有企业家精神的地方，在这里个人成长与利润增长相一致，工作看起来像玩耍。', ref:'人们畅想，办公场所应是一个既舒服又有利于开创事业的地方，在这里，个人成长与企业盈利增长目标相一致，工作轻松愉快。', tags:["准确性","语言规范","风格"] },
  { k:'seg_4_初赛_27', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Yet though these tech campuses seem unprecedented, they echo movements of the past.', mt:'然而，尽管这些科技园区似乎是前所未有的，但它们呼应了过去的运动。', ref:'不过，这样的科技园区看似前所未有，但并非没有先例。', tags:["准确性"] },
  { k:'seg_4_初赛_28', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In an era of civic wariness and economic fragility, the ‘total’ office heralds the rise of a new technocracy.', mt:'在一个公民谨慎和经济脆弱的时代，“整体”办公室预示着新技术官僚的崛起。', ref:'在一个全民紧张、经济脆弱的时代，“整体式”的办公园区预示着技术力量的重新崛起。', tags:["准确性"] },
  { k:'seg_4_初赛_29', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In a time when terrorism from abroad provokes our fears, this heavily-planned workplace harks back to the isolationist values of the academic campus and even the social planning of the company town.', mt:'在来自国外的恐怖主义引发我们恐惧的时代，这个精心策划的工作场所让人想起大学校园的孤立主义价值观，甚至公司城的社会规划。', ref:'在这个来自国外的恐怖主义引发国内恐慌的年代，精心打造的工作场所难免会让人联想到孤立主义的价值观，这种价值观不仅存在于大学校园里，还体现在建设“公司城”的社会规划之中。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_30', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As physical offices, they’re exceptional places to work ‒ but while we increasingly uphold these places as utopic models for community, we make questionable assumptions about the best version of our shared life and values.', mt:'作为实体办公室，它们是非凡的工作场所⸺但当我们越来越多地将这些地方视为社区的乌托邦模式时，我们对我们共同生活和价值观的最佳版本做出了可疑的假设。', ref:'作为实体办公场所，企业社区确实无可挑剔，是卓越的工作空间，但是，如果我们逐渐将这些场所视为社区的乌托邦模板，我们对于共享生活和价值观的假想就值得商榷了。', tags:["准确性"] },
  { k:'seg_4_初赛_31', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Just as Google sought to build a new neighbourhood in Mountain View, so did Thomas Jefferson in 1819 intend to make the campus of the University of Virginia an ‘academical village’.', mt:'正如谷歌试图在山景城建立一个新的社区一样，托马斯•杰斐逊在1819 年也打算让弗吉尼亚大学的校园成为一个“学术村”。', ref:'和谷歌计划在山景城建设新办公园区一样，1819 年，托马斯 •杰斐逊 (Thomas Jefferson) 也曾打算将弗吉尼亚大学的校园打造成为一个“学术村”。', tags:["准确性","术语","语言规范"] },
  { k:'seg_4_初赛_32', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The famed architect Le Corbusier once described the US college campus as ‘a world in itself’, and it’s these cloistered worlds that launched our technological ideals.', mt:'著名建筑师勒•柯布西耶曾将美国大学校园描述为“一个独立的世界”，正是这些与世隔绝的世界开启了我们的技术理想。', ref:'著名建筑师勒•柯布西耶 (Le Corbusier) 曾将美国大学校园描述为“一个独立的世界”， 正是这些与世隔绝的世界触发了美国的科技梦。', tags:["准确性","术语"] },
  { k:'seg_4_初赛_33', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Tony Hsieh of Zappos had a formative business experience manning a dormitory diner in Quincy House at Harvard College; David Fincher’s film The Social Network (2010) would have you believe that Mark Zuckerberg’s empire ‒ which earned $12.47 billion in 2014 alone ‒ is still, at its core, a vengeful dorm-room enterprise.', mt:'Zappos 的谢长廷在哈佛学院昆西大厦管理宿舍餐厅时有过形成性的商业经历；大卫•芬奇的电影《社交网络》（2010）会让你相信马克•扎克伯格的帝国⸺仅在2014 年就赚了124.7 亿美元— —本质上仍然是一个复仇的宿舍企业。', ref:'美捷步的CEO 谢家华在哈佛学院昆西之家 (Quincy House) 管理宿舍餐厅时的经历奠定他商业传奇的基础，大卫•芬奇 (David Fincher) 的电影《社交网络》(The Social Network, 2010) 会让你相信马克• 扎克伯格 (Mark Zuckerberg) 的商业帝国（仅在2014 年就赚了124.7 亿美元）本质上还是一个小心眼的宿舍企业。', tags:["准确性","语言规范","术语"] },
  { k:'seg_4_初赛_34', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Tech campuses and college campuses seem ideologically aligned.', mt:'科技校园和大学校园似乎在意识形态上是一致的。', ref:'在意识形态上，科技企业园区和大学校园似乎是一致的。', tags:["准确性"] },
  { k:'seg_4_初赛_35', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Once, those college campuses held as much sway in the US mind as our tech campuses do now.', mt:'曾经，这些大学校园在美国人心目中的影响力和我们现在的科技校园一样大。', ref:'在美国人心目中的影响力，过去的大学校园和当今的科技园区相差无几。', tags:["准确性"] },
  { k:'seg_4_初赛_36', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'According to the architectural historian Paul V Turner’s Campus: An American Planning Tradition (1984), the US college campus was ‘an experiment in urbanism’ ‒ a more open follow-up to European universities such as Oxford, whose individual residential colleges emerged in the 13th century and came to prominence in the 15th as a means of organising the college experience, keeping out the townies, and controlling students prone to whoring.', mt:'建筑历史学家保罗•V•特纳的 《校园：美国规划传统》（Paul V Turner\'s Campus ： An American 规划传统）（1984）认为，美国大学校园是“城市主义的一个实验”⸺这是牛津等欧洲大学更开放的后续。牛津大学的单独寄宿学院出现在13 世纪， 并在15 世纪变得突出，作为组织大学体验、将城镇拒之门外和控制容易嫖娼的学生的一种手段。', ref:'建筑历史学家保罗•V•特纳 (Paul V Turner) 在《校园：美国规划传统》(Campus: An American Planning Tradition, 1984) 一书中指出，美国大学校园是“城市主义的试验田”，因循了牛津等欧洲大学的先例，只不过是更加开放。牛津大学的独立寄宿学院出现于13 世纪，并在15 世纪声名鹊起，成为了组织校园体验、隔绝闲杂人员和管控学生嫖娼的一种手段。', tags:["准确性","语言规范","术语","风格"] },
  { k:'seg_4_初赛_37', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These urban experiments became a vision of US utopia.', mt:'这些城市实验成为美国乌托邦的愿景。', ref:'后来，这些城市主义的试验成了美国对于乌托邦的愿景。', tags:["准确性"] },
  { k:'seg_4_初赛_38', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Campuses are worlds apart; places that address the whole of the student in order to nurture the whole of the student.', mt:'校园是不同的世界；为了培养学生的整体，面向学生的地方。', ref:'校园是独立的世界，注重学生全面发展，培养学生的整体素质。', tags:["准确性"] },
  { k:'seg_4_初赛_39', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Early college campuses were one of the first major architectural undertakings of the new world, and they mapped US values and aspirations.', mt:'早期的大学校园是新世界的首批主要建筑工程之一，它们映射了美国的价值观和抱负。', ref:'早期的大学校园是新世界的首批重大建筑工程，反映了美国的价值观和抱负。', tags:["准确性"] },
  { k:'seg_4_初赛_40', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They were the first of our cities on a hill.', mt:'它们是我们第一个在山上的城市。', ref:'它们是美国的首批“山上之城”。', tags:["准确性","语言规范","风格"] },
  { k:'seg_4_初赛_41', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These offices are seen as utopian partly because ‘they’re more thought-out than most American offices,’ explained Saval.', mt:'萨瓦尔解释说，这些办公室被视为乌托邦，部分原因是“它们比大多数美国办公室更深思熟虑”。', ref:'萨瓦尔 (Saval) 解释说，这些办公园区之所以被称为乌托邦，部分原因在于“与大多数美国办公场所相比，它们的开发计划更加深思熟虑。', tags:["准确性","术语","语言规范"] },
  { k:'seg_4_初赛_42', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'‘The reason they’re more thought-out is that those companies are in some ways obliged to care in a way that other American corporations in other industries aren’t.’', mt:'“他们更深思熟虑的原因是，这些公司在某些方面不得不关心， 而其他行业的其他美国公司却不关心。”', ref:'之所以要深思熟虑，是因为这些公司希望表明他们对员工的关心高于其他行业的其他公司。”', tags:["准确性","风格"] },
  { k:'seg_4_初赛_43', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s because workers with tech skills are in demand.', mt:'这是因为需要具备科技技能的员工。', ref:'这是因为技术人才很抢手。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_44', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As members of a leading cultural and economic paradigm, they have a kind of economic security that those in many other fields now lack.', mt:'作为领先文化和经济范式的成员，他们拥有一种经济保障，而许多其他领域的人现在都缺乏这种保障。', ref:'作为先进文化和自由经济范式的代表，他们具备其他领域的人所不具备的经济安全感。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_45', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Their offices, then, cater to their needs in a rare way.', mt:'因此，他们的办公室以一种罕见的方式满足了他们的需求。', ref:'因此，他们的办公场所必须别具一格，才能满足他们的需求。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_46', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As the architectural critic Alexandra Lange points out in The Dot-Com City (2012), these places keep the surrounding world at bay ‒ often at a cost to the local economy ‒ to keep employees on campus longer.', mt:'正如建筑评论家亚历山德拉•兰格在《网络城市》（The Dot-Com City，2012）中指出的那样，这些地方将周围的世界拒之门外⸺ 通常是以当地经济为代价⸺以延长员工在校园的时间。', ref:'建筑评论家亚历山德拉•兰格 (Alexandra Lange) 在《网络城市》(The Dot-Com City, 2012)一书中指出，这些场所与周围的世界格格不入，这样才能延长员工待在园区的时间， 但通常是以牺牲当地经济为代价的。', tags:["准确性","语言规范","术语"] },
  { k:'seg_4_初赛_47', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Ultimately, school campuses seek to shape rounded and informed citizens.', mt:'归根结底，学校校园寻求塑造全面和知情的公民。', ref:'归根结底，大学校园旨在塑造全面发展、学识渊博的公民，', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_48', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'On corporate campuses, workers are still workers.', mt:'在企业校园里，员工仍然是员工。', ref:'而在企业园区里，员工终究还是员工。', tags:["准确性"] },
  { k:'seg_4_初赛_49', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But in both environments, people are encouraged to bring their whole selves to their work.', mt:'但在这两种环境中，人们都被鼓励把整个自我带到工作中。', ref:'但是，无论是哪种环境，都鼓励人们全身心投入。', tags:["准确性"] },
  { k:'seg_4_初赛_50', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'So the campus culture that seeks to serve, shape and employ the whole worker has as its corollary a boom in positive psychology ‒ management principles centred on things such as mindfulness, perceived autonomy, and the feeling of being part of something bigger than yourself.', mt:'因此，寻求服务、塑造和雇佣整个员工的校园文化的必然结果是积极心理学的繁荣⸺管理原则以正念、感知自主和成为比自己更大事物一部分的感觉为中心。', ref:'因此，要打造一种园区文化，积极服务、塑造、雇佣全面发展的员工，就必然用到积极心理学， 即注重培养员工的正念、自主感和使命感。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_51', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The insight gelled with the burgeoning new field of positive psychology, which, Hsieh felt, confirmed ‘that the combination of physical synchrony with other humans… leads to a greater sense of happiness.’', mt:'谢长廷认为，这一见解与蓬勃发展的积极心理学新领域相结合， 证实了“与其他人的身体同步相结合”...带来更大的幸福感。', ref:'谢家华认为，这种管理原则与积极心理学这个蓬勃发展的新领域相契合，证明“保持与他人行动的一致性，能够带来更大的幸福感。”', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_52', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In his book, he sketched out his vision for ‘a path to profits, passion, and purpose. ’', mt:'在他的书中，他勾勒出了自己对“通往利润、激情和目标的道路”的愿景。', ref:'在自己的书中，他勾勒出了“通往利润、热爱和目标的道路”。', tags:["准确性"] },
  { k:'seg_4_初赛_53', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Soon he had spun off a happiness consultancy called Delivering Happiness, which offered coaching and talks delivered by VHPs (Very Happy Persons) along with a Happy Business Index survey to help companies optimise workforce happiness.', mt:'很快，他剥离了一家名为“传递幸福”的幸福咨询公司，该公司提供由VHP（非常幸福的人）提供的辅导和演讲，以及一项快乐商业指数调查，以帮助公司优化员工的幸福感。', ref:'很快，他创立了一家名为“传递幸福”的幸福咨询公司，由“非常幸福的人”来做辅导和演讲， 同时开展了一项幸福企业指数调查，帮助企业增强员工的幸福感。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_54', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s been the mission at Zappos, too, through core values such as ‘Deliver WOW Through Service’ and ‘Create Fun and a Little Weirdness’.', mt:'通过“通过服务传递魔兽世界”和“创造乐趣和一点怪异”等核心价值观，这也是Zappos 的使命。', ref:'这也正是美捷步的使命，而践行使命的途径是推行“用服务给客户带来惊喜”和“创造乐趣和一点意外”等核心价值观。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_55', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And on a 60-acre patch of land in downtown Las Vegas, not far from the Strip over in Paradise, Nevada, it’s become the guiding vision of a new sort of town ‒ an alchemical effort to revitalise Vegas’ downtrodden downtown by making it a start-up utopia.', mt:'在拉斯维加斯市中心一片60 英亩的土地上，离内华达州天堂大道不远，它已经成为一种新型城镇的指导愿景⸺一种炼金术般的努力，通过使拉斯维加斯成为初创企业乌托邦，来振兴拉斯维加斯受压迫的市中心。', ref:'位于拉斯维加斯市中心、距内华达州天堂城赌城大道不远的一片60 英亩的土地，已经成为建设新型城镇的范例，通过打造初创企业的乌托邦，振兴拉斯维加斯没落的老城区。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_56', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The Downtown Project is a sandbox for start-ups, an umbrella organisation that funds, supports, owns and co-owns around 300 businesses that, according to their website, together employ more than 900 people.', mt:'市中心项目是初创企业的沙盒。 这是一个伞式组织，为大约300 家企业提供资金、支持、拥有和共同拥有。根据这些企业的网站，这些企业总共雇佣了900 多名员工。', ref:'这个老城振兴项目是一个初创企业孵化项目，也是一家伞式组织，该组织控有或持有大约 300 家初创企业的股份，为这些初创企业提供资金和支持。 这些企业的网站资料显示，它们总共有900 多名员工。', tags:["准确性","语言规范","风格"] },
  { k:'seg_4_初赛_57', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Though not technically constituting the Zappos campus, the Zappos company sits at the heart of things in the old City Hall.', mt:'尽管从技术上讲，这家Zappos 公司并不构成Zappos 的园区，但它位于旧市政厅的核心位置。', ref:'从严格意义上讲，这个项目并不等同于美捷步的企业园区， 但公司正好是位于城市的老城区，市政厅所在地。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_58', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'At the Downtown Project, according to a special report by Nellie Bowles for the website Re/code, a preschool trains children in the skills they need for the start-up of life.', mt:'根据内莉• 鲍尔斯为网站 Re/code 撰写的一份特别报告，在市中心项目中，一所学前班培训孩子们开始生活所需的技能。', ref:'而根据内莉•鲍尔斯 (Nellie Bowles) 为Re/code 网站撰写的一份特别报告，这个老城振兴项目就像学前班教会孩子们基本生活技能一样帮助初创企业成长。', tags:["准确性","术语","风格"] },
  { k:'seg_4_初赛_59', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A Downtown Project-funded hospitality-cum-security force called ‘The Rangers’ aims someday to monitor interactions between workers in a search for the coveted innovation-producing encounter.', mt:'一个名为“流浪者”的市中心项目资助的接待和安全部队旨在有一天监控工人之间的互动，寻找令人垂涎的创新机会。', ref:'项目资助了一个名为“游侠”的酒店安保团队，团队的目标是能够不定时监控员工之间的互动，寻找可遇不可求的创新机会。', tags:["准确性"] },
  { k:'seg_4_初赛_60', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'According to Joe Schoenmann of the Las Vegas Weekly, they play ukuleles and hope to create a ‘smile pandemic’ in the city.', mt:'据《拉斯维加斯周刊》的乔•舍曼称，他们演奏四弦琴，希望在这座城市制造“微笑流行病”。', ref:'《拉斯维加斯周刊》(Las Vegas Weekly) 的乔•舍曼 (Joe Schoenmann) 称，他们通过演奏尤克里里，希望在这座城市制造一场“微笑大流行”。', tags:["准确性","术语"] },
  { k:'seg_4_初赛_61', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Yet for all the positivity of the Downtown Project, its surrounding casinos have become an unfortunately fitting landscape.', mt:'然而，尽管市中心项目非常积极， 但它周围的赌场已经成为一个不幸的合适景观。', ref:'然而，尽管该项目有诸多积极的方面，但周围赌场林立，多少显得有些不协调。', tags:["准确性"] },
  { k:'seg_4_初赛_62', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The Project’s combination of high- stress entrepreneurship, a surface emphasis on positivity, and the isolation attendant in an office away from some employees’ homes was a gamble, and the house has often seemed set against them.', mt:'该项目结合了高压力的创业精神、表面上对积极的强调，以及远离一些员工家的办公室里的孤独服务员，这是一场赌博，而房子似乎经常对他们不利。', ref:'而且，面临巨大的创业压力，强调积极乐观却浮于表面，有些员工需要孤身离家前往工作……这一切都使得这一项目宛如一场赌博，而且“庄家”似乎总是跟他们作对。', tags:["准确性","风格"] },
  { k:'seg_4_初赛_63', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Since 2013, the Project has seen major layoffs, a series of suicides, and the loss of faith among many, serving as a cautionary tale.', mt:'自2013 年以来，该项目发生了大规模裁员、一系列自杀事件，许多人失去了信心，这是一个警示故事。', ref:'自2013 年以来，该项目出现了大规模的裁员和一系列自杀事件，许多人失去了信心，这些都是对项目发出的警示。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_64', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Hsieh’s impulse has historical precedent.', mt:'谢长廷的冲动是有历史先例的。', ref:'但是，谢家华并非第一次这样冲动。', tags:["准确性"] },
  { k:'seg_4_初赛_65', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the past, company towns realised a life in line not only with profits but also with certain value systems, and a model of corporate control.', mt:'过去，公司镇的生活不仅与利润一致，还与某些价值体系和企业控制模式一致。', ref:'过去，公司城的建设不仅是为了追求利润，还要契合某些价值体系和企业控制模式。', tags:["准确性"] },
  { k:'seg_4_初赛_66', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the early to mid-19th century at the Lowell Mills in Massachusetts, you could both enjoy a refined intellectual community and be fired for drinking or attending dance classes, notes Hardy Green, a former BusinessWeek associate editor, in his book The Company Town (2010).', mt:'《商业周刊》前副主编哈迪•格林在他的书《公司镇》（The Company Town，2010）中指出， 在19 世纪早期至中期，你既可以享受一个精致的知识社区，也可以因为喝酒或参加舞蹈课而被解雇。', ref:'《商业周刊》(Business Week) 的前副主编哈迪•格林 (Hardy Green) 在他的《公司城》(The Company Town, 2010) 一书中指出，在19 世纪早期至中期马萨诸塞州洛威尔的工厂里，你既可以和高雅的知识分子为伍，也可能因为喝酒或参加舞蹈课而遭到解雇。', tags:["准确性","语言规范","术语"] },
  { k:'seg_4_初赛_67', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Later on, towns such as Hershey, Pennsylvania, built by the chocolate maven Milton S Hershey, combined some of the best living amenities of the early 20th century ‒ a school for orphans, electricity, a free zoo ‒ with the precarious lack of elected government and the chance to have Hershey himself as your mayor.', mt:'后来，像宾夕法尼亚州好时这样的城镇，由巧克力专家米尔顿 •S•好时建造，结合了20 世纪初一些最好的生活设施⸺孤儿学校、电力、免费动物园⸺以及不稳定的民选政府缺乏和让好时本人担任市长的机会。', ref:'后来，有一些城镇，比如巧克力专家米尔顿•S•赫尔希(Milton S Hershey) 建造的宾夕法尼亚州好时镇，配备了20 世纪初最好的一些生活设施，包括孤儿学校、电力设施、免费动物园等，但好时镇缺少民选政府，这给了赫尔希本人担任镇长的机会。', tags:["准确性","风格","术语","语言规范"] },
  { k:'seg_4_初赛_68', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Like other such towns, Hershey had a ‘moral police’ that would enforce clean living by noting homes that weren’t kept up and employees who were alcoholic.', mt:'像其他这样的城镇一样，好时有一个“道德警察”，通过注意没有保持的房屋和酗酒的员工来强制清洁生活。', ref:'跟其他公司城一样，好时镇有“道德警察”，时刻留意各家各户的保洁情况以及是否有员工酗酒，强制推行清洁生活。', tags:["准确性"] },
  { k:'seg_4_初赛_69', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The risk of the company town, of course, is the dependence of a neighbourhood on the originating corporation ‒ one reason that Mountain View rejected Google’s proposal.', mt:'当然，“公司城”的风险在于，一个社区对创立公司的依赖⸺这也是山景城拒绝谷歌提议的一个原因。', ref:'当然，公司城的风险在于，它会造成整个社区对创始公司的依赖，这正是山景城拒绝谷歌办公园区开发的一个原因。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_70', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In part, the company town was an attempt to remake the world in the industrialist’s image, and often stemmed from a separatist urge.', mt:'在某种程度上，“公司城”是为了按照实业家的形象重塑世界， 往往源于分离主义的冲动。', ref:'在某种程度上，公司城是在按照实业家的形象重塑世界，而这往往源于分离主义思想。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_71', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No one embodied the dynamics of those places better than Henry Ford, the poster child of US technology and entrepreneurship.', mt:'没有人比美国科技和企业家精神的典型代表亨利•福特更能体现这些地方的动态。', ref:'没有谁比美国科技和企业家精神的代表人物亨利• 福特 (Henry Ford) 更了解公司城的发展历程了。', tags:["准确性","术语","风格"] },
  { k:'seg_4_初赛_72', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Ford might have made the modern world with the Model T, but he made many smaller worlds with his model towns.', mt:'福特可能用T 型车创造了现代世界，但他用他的模型城镇创造了许多更小的世界。', ref:'如果说福特是用T 型车开启了现代世界，那么，他建造的那些模范公司城相当于开辟了许多小世界。', tags:["准确性"] },
  { k:'seg_4_初赛_73', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the 1920s, according to the historian Greg Grandin, Ford even proposed a ribbon-shaped city in Muscle Shoals, Alabama, that would be five and a half times as long as Manhattan.', mt:'根据历史学家格雷格·格兰丁的说法，20 世纪20 年代，福特甚至提议在阿拉巴马州的肌肉浅滩建造一座丝带状的城市，其长度将是曼哈顿的5.5 倍。', ref:'根据历史学家格雷格•格兰丁 (Greg Grandin) 的说法，在 1920 年代，福特甚至提议在阿拉巴马州的马斯尔肖尔斯市 ( Muscle Shoals) 建造一座带状城市，长度是曼哈顿的5.5 倍。', tags:["准确性","术语","语言规范"] },
  { k:'seg_4_初赛_74', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There, he sought to build a culture of ‘farmer-mechanics’ ‒ industrial workers who spent their summers tending the land ‒ which Ford, a farmboy-turned-mechanic, saw as the industrial future of the US.', mt:'在那里，他试图建立一种“农民机械师”的文化⸺产业工人在夏季打理土地⸺福特把这种文化视为美国的工业未来。福特是一名农家男孩，后来成为机械师。', ref:'他想在那里建立一种“机械师兼农民”的文化，到了夏季，产业工人要去打理土地。由于福特的出身是一名农家男孩，后来才成长为机械师，因此，他把这种文化视为美国工业的未来。', tags:["准确性","语言规范"] },
  { k:'seg_4_初赛_75', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It wasn’t until years later and miles away that he’d succeed at scale.', mt:'直到几年后，在几英里之外，他才取得了大规模的成功。', ref:'直到多年后，他才在千里之外获得成功。', tags:["准确性"] },
  { k:'seg_4_初赛_76', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1927, on a roughly 2.5 million- acre land grant from the state of Pará in Brazil, Ford began to build a rubber plantation.', mt:'1927 年，福特从巴西帕拉州获得了大约250 万英亩的土地，开始建造一个橡胶种植园。', ref:'1927 年，福特在巴西的帕拉州 (Parrá, Brazil) 获批一块大约 250 万英亩的土地，开始建造一座橡胶种植园。', tags:["准确性"] },
  { k:'seg_4_初赛_77', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was a new city on the fresh breast of the verdant Amazon: Fordlandia.', mt:'这是一座新城市，坐落在翠绿的亚马逊河的新怀抱⸺福特兰迪亚。', ref:'这就是后来的福特兰迪亚镇 (Fordlandia)，位于绿树掩映下的亚马逊河畔。', tags:["准确性","术语"] },
  { k:'seg_4_初赛_78', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Throughout his detailed 2009 account of Fordlandia’s halting rise from overrun jungle to town with a Main Street, bakery and perfume store, Grandin highlights how the economic and organisational obstacles of the project turned it into less a business proposition than an ideological battle ground for Ford’s vision of US life versus the primal jungle.', mt:'2009 年，格兰丁详细讲述了福特兰迪亚从一片荒芜的丛林，到拥有一条主街、面包店和香水店的小镇，步履蹒跚。他在书中强调， 福特兰迪亚项目的经济和组织障碍，如何将其变成了一个商业命题，而不是福特关于美国生活与原始丛林愿景的意识形态战场。', ref:'在2009 年出版的书中，格兰丁 (Grandin)详细讲述了福特兰迪亚镇如何从一片荒芜的丛林一步一步发展成为拥有一条主街、面包店和香水店的小镇，他一直在强调，福特兰迪亚镇项目所遭遇的经济和组织障碍， 让它超越了商业项目的范畴， 成为了福特的美国生活愿景与原始丛林进行意识形态较量的战场。', tags:["准确性","术语","风格"] },
  { k:'seg_4_初赛_79', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1941, Walt Disney visited Ford’s city, and in 1955, aged 53, he started Disneyland.', mt:'1941 年，沃尔特•迪斯尼访问了福特的城市。1955 年，53 岁的他创办了迪斯尼乐园。', ref:'1941 年，沃尔特• 迪斯尼 (Walt Disney) 访问福特兰迪亚镇。1955 年，53 岁的他创办了迪斯尼乐园。', tags:["准确性","术语"] },
  { k:'seg_4_初赛_80', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A half-century after that, Disney designers visited Facebook to consult on the company’s campus design, the new world begetting a small world, after all.', mt:'半个世纪后，迪斯尼设计师访问了Facebook，为该公司的园区设计提供咨询。毕竟，新世界开启了一个小世界。', ref:'半个世纪后，迪斯尼的设计师造访脸书公司，为脸书园区设计提供咨询，毕竟那是孕育小世界的新世界。', tags:["准确性","语言规范"] },
  { k:'seg_5_决赛_1', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'静安寺弄堂走走游', mt:'', ref:'Strolling through the Longtang of Jing’an', tags:[] },
  { k:'seg_5_决赛_2', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'说起上海的市井生活，就不能不提上海的弄堂。', mt:'', ref:'One uniquely Shanghainese cultural element is the longtang, or the straight lanes between buildings in a residential quarter.', tags:[] },
  { k:'seg_5_决赛_3', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'从建筑学上说，它本身就是上海中西文化交汇运动的产物，连北京的著名建筑家梁思成先生都称赞上海老弄堂是最优越于其他城市的地方性建筑。', mt:'', ref:'As a cultural fusion of east and west, it is crowned by Liang Sicheng, the “Father of Modern Chinese Architecture”, as the best of architecture in all of China.', tags:[] },
  { k:'seg_5_决赛_4', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'同时，作为上海人主要的生活空间，小弄堂也成为大上海的缩影。', mt:'', ref:'The Shanghainese used to spend most of their time here. The small alley has also become the epitome of Greater Shanghai.', tags:[] },
  { k:'seg_5_决赛_5', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'解放初期，弄堂式建筑约占上海居住建筑总面积的65%，占人口70%多的上海人居住于此，上海的习俗、方言、气质和都市性格的形成都与之息息相关。', mt:'', ref:'In the late 1940s, longtang style houses represented about 65% of Shanghai’s total residences, accommodating more than 70% of the local population. Their tiny living space almost epitomizes everything Shanghainese - traditions, dialects, qualities, and urban cultures.', tags:[] },
  { k:'seg_5_决赛_6', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'通过弄堂这个横切面来了解上海，了解上海的历史和上海人，无疑是一个有趣且很好的角度。', mt:'', ref:'Therefore, it is fair to say whatever’s left of them today offers a glimpse into the history of Shanghai as well as the characteristics of the Shanghainese.', tags:[] },
  { k:'seg_5_决赛_7', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'静安区的静安寺街道不仅保存着上海仅有的较大规模的成片弄堂，而且这里的邨、坊、里、弄历史风貌保护区很好地保留了原生态的生活气息，海派韵味悠远，是老上海风情难得的历史遗存。', mt:'', ref:'Today, the only well-preserved large-scale longtang cluster is located in Jing’an. In this place, you may find lane, alley or village level protection area that best reflects the original life style of Shanghai. It is a rare historical relic of old Shanghai style.', tags:[] },
  { k:'seg_5_决赛_8', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'据悉，静安区将在静安寺周边打造10条老上海风情弄堂，与上海市文联联手，推出特色弄堂游，静安区旅游节还将推出“弄堂风情游”特色项目。', mt:'', ref:'The district government plans to build 10 Shanghai-style Longtang around Jing’an Temple and to create “Special Longtang Tourism” in cooperation with the Shanghai Federation of literary and Art Circles. The Jing\'an District Tourism Festival will also launch a special project of "Longtang Style Tour".', tags:[] },
  { k:'seg_5_决赛_9', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'笔者选取了周边两条有故事的特色老弄堂做一番介绍，让大家先睹为快。', mt:'', ref:'What I\'m about to tell you is the stories of two most exciting Longtang sites, just for a sneak peek.', tags:[] },
  { k:'seg_5_决赛_10', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'文化名人的摇篮——愚园路361弄（愚谷邨）', mt:'', ref:'A Magnet for Scholars and Artists: Longtang 361, Yuyuan Road (Yugucun)', tags:[] },
  { k:'seg_5_决赛_11', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'清光绪十六年（1890年），在千年古刹静安寺的东北，四明张氏在今愚园路常德路创建了私人花园——愚园。', mt:'', ref:'In the sixteenth year of Guangxu in the Qing Dynasty (1890), in the northeast of Jing\'an Temple, the Zhang family from Siming (Ningbo) built a private garden called Yuyuan near the intersection of Changde Road and Yuyuan Road.', tags:[] },
  { k:'seg_5_决赛_12', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'1899年，愚园路由此得名。', mt:'', ref:'And in 1899, Yuyuan Road was officially named after this garden.', tags:[] },
  { k:'seg_5_决赛_13', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'1934年，由广东潮阳人陈楚南先生投资开发，华信建筑设计师事务所杨润玉、杨元麟采用中西合璧的设计构思，在这里建起了煤卫齐全的新式里弄，名曰愚谷邨。', mt:'', ref:'In 1934, an investor from Chaoyang, Guangdong called Chen Chunan commissioned two architects, Yang Runyu and Yang Yuanlin, of Huaxin Architectural Design Studio to build a neighborhood here. Combining Chinese and Western style, it is a modern neighborhood equipped with proper gas supply and sanitation, and is called "愚谷邨" (Yugucun).', tags:[] },
  { k:'seg_5_决赛_14', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'“邨”是“村”的异体字，含有城市里的乡村之意，也有乡村城市化的寓意。', mt:'', ref:'In Chinese characters, "邨"(cun) is a variant of "村", which contains both the meaning of "countryside in the city" and "rural urbanization".', tags:[] },
  { k:'seg_5_决赛_15', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'“愚谷”二字出自中华优秀传统文化，即“大智若愚”（北宋·苏轼）和“虚怀若谷”（战国·《老子》），意指聪明人表面上好像愚笨，而大度的胸怀谦虚得像山谷一样能容纳百川。', mt:'', ref:'The word "愚谷"(Yugu) comes from the Chinese classics, namely "Great wisdom is like foolishness" (by Su Shi in the Northern Song Dynasty) and "Receptive as an echoing canyon" (by Lao Tzu in the Warring States Period), which indicates that although educated individuals initially appear to be foolish, their generous minds are so modest that they can accept a hundred rivers like a valley.', tags:[] },
  { k:'seg_5_决赛_16', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'愚谷邨小区位于静安寺、百乐门西面，在愚园路，乌鲁木齐北路，南京路西端，永源浜路和镇宁路的区域内。', mt:'', ref:'Yugucun is located to the west of Jing\'an Temple and Paramount Gate, to the west of Yuyuan Road, North Urumqi Road and Nanjing Road, and within the intersected area of Yongyuanbang Road and Zhenning Road.', tags:[] },
  { k:'seg_5_决赛_17', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'自东向西依次有愚谷邨、涌泉坊、十样景、牛奶棚，愚园坊、中实新村以及蝶村，其间镶嵌着不少花园洋房别墅。', mt:'', ref:'Several neighborhoods like Yugucun, Yongquanfang, Shiyangjing, Niunaipeng, Yuyuanfang, Zhongshixincun and Diecun, gather here from east to west. There are many garden villas inside these neighborhoods.', tags:[] },
  { k:'seg_5_决赛_18', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'愚谷邨饱经沧桑，沉淀着上海历史文化的风貌， 1994年被上海市政府列为优秀历史建筑。', mt:'', ref:'The history of Yugucun is so long that it witnesses the development of this city. In 1994, Yugucun was designated by the Shanghai Municipal Government as a heritage site.', tags:[] },
  { k:'seg_5_决赛_19', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'在愚谷邨曾居住过许多文化名人，65号先后住过的著名作家就有魏金枝、唐克新、茹志鹃和王啸平夫妇及王安忆；37号曾住过海派著名画家应野平；二十年代影星黎明晖夫妇、著名电影表演艺术家沙莉和凌之浩夫妇、奚美娟、著名口琴演奏家王庆隆也曾在这里居住过。', mt:'', ref:'Many renowned Chinese scholars and artists chose to make their home in Yugucun, including writers Wei Jinzhi, Tang Kexin, Ru Zhijuan, Wang Xiaoping, and Wang Anyi (in Building No. 65); the famous Shanghai-style painter Ying Yeping(in Building No. 37); and movie stars of the 1920s Li Minghui and her husband, famous film artists Sha Li and Ling Zhihao, Xi Meijuan, and famous harmonica player Wang Qinglong also lived here.', tags:[] },
  { k:'seg_5_决赛_20', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'还有中国最早的两栖明星周璇，1936年与严华结合之初就定居于此。', mt:'', ref:'There is also Zhou Xuan, China\'s earliest movie and singing star, who settled here at the beginning of her marriage with Yan Hua in 1936.', tags:[] },
  { k:'seg_5_决赛_21', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'沙莉夫妇曾住在121号，她住二楼亭子间。', mt:'', ref:'Sha Li and her husband used to live at No. 121, and she lived in the tingzijian, a small room on the second floor under the roof- deck.', tags:[] },
  { k:'seg_5_决赛_22', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'在121号有一段足以拍成电视剧的故事，当时一、二楼正房间曾是上海地下党的一个秘密机关，对外以进化药厂做掩护。', mt:'', ref:'Some of the residents even left legendary stories, like the one in Building No. 121. The bedroom on the first and second floors was once a secret agency of the Shanghai Underground Party, and the Evolution Pharmaceutical Factory was used as a cover.', tags:[] },
  { k:'seg_5_决赛_23', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'而令人想不到的是，住在三楼的竟是当时的76号特务，姓陈（解放后被枪毙），敌对阵营同住在这里，居然相安无事，可称奇景。', mt:'', ref:'Surprisingly, the person who lived on the third floor was actually Kuomingtang\'s Agent 76, surnamed Chen (who was shot after China\'s liberation). Two enemies lived here together, and they were at peace with each other, it was truly a spectacle.', tags:[] },
  { k:'seg_5_决赛_24', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'称为胡同的弄堂——华山路229-285弄（大胜胡同）', mt:'', ref:'A Longtang Called Hutong: Longtang 229-285, Huashan Road (Da-sheng Hutong)', tags:[] },
  { k:'seg_5_决赛_25', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'在上海近万条弄堂中，鲜有被称之为“胡同”的，而华山路上却有一组，它位于华山路229—285弄，名为大胜胡同。', mt:'', ref:'There are thousands of Longtangs in Shanghai, few are called "Hutong", a designation for Beijing’s traditional houses. However, there is one unique Longtang on Huashan Road called "Hutong", which is located in Lane 229-285 of Huashan Road. Their full name is Da-sheng Hutong.', tags:[] },
  { k:'seg_5_决赛_26', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'大胜胡同原是天主教会的普爱堂投资经营的产业之一，普爱堂看中了这块邻近静安寺的地方，遂投资，由神父德拉蒙德负责建造了这组规模较大的新式里弄。', mt:'', ref:'Da-sheng Hutong was originally one of the real estates invested and operated by the Catholic Church\'s Pu\'ai Church. The Church chose this place adjacent to Jing\'an Temple and bought it. It was designed as a large modern Longtang by Drummond.', tags:[] },
  { k:'seg_5_决赛_27', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'神父德拉蒙德来自北京，故他将正在建造的民居称之为胡同。', mt:'', ref:'The name was given by its builder Drummond, a priest who had lived in Beijing.', tags:[] },
  { k:'seg_5_决赛_28', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'大胜胡同建于1912年至1936年间，占地52.47亩，建筑面积共22706平方米，为新式里弄住宅，有三层砖木结构房屋116幢，呈行列式排列，另有汽车间21间集中设置，建筑呈现装饰艺术派风格，水泥拉毛外墙，清水红砖饰边。', mt:'', ref:'Da-sheng Hutong began construction in 1912 and finished in 1936, covering an area of 52.47 mu with a construction area of 22,706 square meters. It comprises 116 three-storey brick-and- wood buildings arranged in rows and 21 private garages. The building presents an Art Deco style, with cement brushed exterior walls and red brick trim.', tags:[] },
  { k:'seg_5_决赛_29', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'整个胡同的建筑风格与北京胡同的四合院风格截然不同，它的结构属于法式新式里弄住宅，造型别致，装饰细腻，建筑风格既受到中国传统建筑影响，又糅合了西方巴洛克建筑风格。', mt:'', ref:'The architectural style is part French and part Chinese with a hint of Baroque influences. All houses come with delicate decorations, making them distinct from Beijing’s Hutong. The architectural style is not only influenced by traditional Chinese architecture, but also combined with Western Baroque architectural style.', tags:[] },
  { k:'seg_5_决赛_30', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'而大胜胡同263弄6号上海市农场管理局使用的一幢办公楼，原是胡同建设者神父德拉蒙德的私人住宅。', mt:'', ref:'Today, in Da-sheng Hutong, the No. 6 Building, Lane 263 is used by the Shanghai Farm Administration as an office building. It was originally the private residence of Mr. Drummond.', tags:[] },
  { k:'seg_5_决赛_31', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'这是一幢英国古典式花园住宅，建于1930年，假三层楼，造型别致，装饰细腻，宅前有大花园。', mt:'', ref:'This is a quasi three-story, British classical garden house, built in 1930, with a unique shape and delicate decorations. There is a large garden in front of the house.', tags:[] },
  { k:'seg_5_决赛_32', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'建筑为双坡复式折线型屋顶，上覆红色平瓦。', mt:'', ref:'The rooftop has a double-pitch duplex folded design covered with red flat tiles.', tags:[] },
  { k:'seg_5_决赛_33', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'这位神父是一位迷恋中国传统文化的人，他不但把中国传统装饰的重要构件融入住宅的室内装饰之中，而且花园的造型也颇有中国园林的神韵。', mt:'', ref:'Drummond was passionate about traditional Chinese culture. Not only did he integrate the core components of traditional Chinese decoration into the interior design of the house, but it was also infused with the concept and the charm of Chinese gardens.', tags:[] },
  { k:'seg_5_东部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“There Are No Pianos to Be Had Here”', mt:'', ref:'“岛上无琴”', tags:[] },
  { k:'seg_5_东部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was an odd time to visit Majorca.', mt:'', ref:'此时造访马略卡岛，正值多事之秋。', tags:[] },
  { k:'seg_5_东部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Civil war had flashed throughout Spain since the death five years earlier of King Ferdinand VII, which ignited familial disagreement over whether his successor would be his brother, Carlos, or his infant daughter, Isabella, whose interests were looked after by her mother, Maria Christina, Ferdinand’s widow and regent of Spain.', mt:'', ref:'五年前，国王费尔南多七世去世，谁来继承大统，让王族陷入分歧，是他的弟弟卡洛斯？还是年幼的女儿伊莎贝拉？站在伊莎贝拉背后的，是她的母亲玛丽亚·克里斯蒂娜——国王的遗孀、西班牙的摄政王后。很快，内战在西班牙各地爆发。', tags:[] },
  { k:'seg_5_东部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Refugees and émigrés descended on the island seeking sanctuary, finding instead Carlists and Christinos as partisan there as they were on the mainland.', mt:'', ref:'登岛的难民和迁徙来此的移民都是逃避战祸的，但他们来了才发现，岛上的人们和本土一样，两派对立，有支持卡洛斯的，有支持克里斯蒂娜的。', tags:[] },
  { k:'seg_5_东部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The commander-in-chief issued a dramatic order just three days before Frédéric Chopin and George Sand’s arrival:', mt:'', ref:'就在肖邦和乔治·桑抵岛前三天，总司令突然颁布一项紧急命令：', tags:[] },
  { k:'seg_5_东部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The district of the island of Majorca is declared to be in a state of war.', mt:'', ref:'马略卡岛地区被宣布为战争状态。', tags:[] },
  { k:'seg_5_东部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Henceforth everybody will be subject to military authority, without prejudice to other constituted authorities who will continue in the legal exercise of their respective functions, albeit with the obligations of obeying and complying with whatever may be required of them in the interest of public security.', mt:'', ref:'即日起，任何人都将受军事当局的管辖，其他非军事部门不能例外，这些部门在履行义务服从和遵守出于公共安全考虑而可能对他们提出的任何要求的条件下，将继续合法行使各自的职能。', tags:[] },
  { k:'seg_5_东部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In Palma they took the only habitable accommodation available, semi- furnished rooms in a former military barracks on Calle de la Marina, close to the old Arab Quarter.', mt:'', ref:'在帕尔马，他们找到了唯一可住的空房，这套空房做过基础装修，位于靠近旧阿拉伯区的海军大街的一个先前用作军营的地方。', tags:[] },
  { k:'seg_5_东部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A modern plaque—high up on the stone, its names and dates in perfect order—verifies the street’s most famous inhabitants: THE POLISH MUSICIAN FRÉDÉRIC CHOPIN AND THE FRENCH WRITER GEORGE SAND LODGED IN THIS STREET ON 8 NOVEMBER 1838, THE DAY THEY ARRIVED IN MALLORCA, A VISIT TO THE ISLAND THAT ENDED ON 13 FEBRUARY 1839.', mt:'', ref:'如果今天走到那儿，就会看到一块高悬在石头上的牌匾，上面工整地刻着曾经的两位大名鼎鼎的住客——“波兰音乐家弗雷德里克·肖邦和法国作家乔治·桑于1838年11月8日登马略卡岛，住在这条街上，并于1839年 2月13日离岛。”', tags:[] },
  { k:'seg_5_东部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chopin’s health and mood in these initial days were promising.', mt:'', ref:'头几天，肖邦的健康状况和心情都有所好转。', tags:[] },
  { k:'seg_5_东部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'To his Polish friend and copyist Julian Fontana in Paris he wrote of turquoise skies and lapis lazuli seas, emerald mountains and clear, clean air, palms and cedars, olive and orange trees, figs and pomegranates—everything to be found in the hothouses of Paris’ Jardin des Plantes.', mt:'', ref:'在写给巴黎的波兰朋友、乐谱抄写员朱利安·丰塔纳的信中，他提到了碧绿的天空和青金石色的海洋、翠绿的山脉和清澈洁净的空气、棕榈树和雪松、橄榄树和橘子树、无花果和石榴——应有尽有的景色，就像身临巴黎植物园的温室。', tags:[] },
  { k:'seg_5_东部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He described the sunshine and moderate temperatures, the summer clothes worn by the townsfolk, the guitars at night playing for hours at a time.', mt:'', ref:'他还写到日落、适宜的气温、小镇居民的夏装，还有夏夜那些一弹就是好几个小时的吉他手。', tags:[] },
  { k:'seg_5_东部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Oh, my dear fellow, I am really beginning to live.', mt:'', ref:'“哦，亲爱的朋友，我过上像样的日子了。', tags:[] },
  { k:'seg_5_东部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'I am close to all that is most beautiful.', mt:'', ref:'周围遍布着美丽事物，', tags:[] },
  { k:'seg_5_东部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'I am a better man.”', mt:'', ref:'我的心绪也好转了。”', tags:[] },
  { k:'seg_5_东部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Sand thought the climate as warm as a French June, perfect for exploring the port’s mix of High Gothic splendor and Moorish remnants: ramparts and stone peasant houses; thermal baths; unfamiliar street names; carved lintels and arabesque scrolls; tall windows divided by slender pillars; ornamental staircases leading up to enormous dark, bare rooms; and, beyond the city, the Jardines de Alfabia, nestled into terraced hills and irrigated by waterwheels.', mt:'', ref:'乔治·桑认为，这里的气候像法国六月一样温暖，非常适合探索这个融合了哥特辉煌和摩尔遗迹的港口：城墙和石头农舍、温泉浴场、陌生的街道名称、雕刻的门楣和阿拉伯式卷轴、细长柱子隔开的高窗、通向宽敞而黑暗的空房的饰纹楼梯，还有那坐落在城外，用水车灌溉的一格格梯田上的阿尔法比亚花园。', tags:[] },
  { k:'seg_5_东部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“I dream of music,”', mt:'', ref:'“我渴望音乐，”', tags:[] },
  { k:'seg_5_东部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chopin wrote to Camille Pleyel, his French publisher, soon after arriving, “but I can’t write any because there are no pianos to be had here—in that respect it is a barbarous country.”', mt:'', ref:'登岛后不久，肖邦写信给他的法国出版人卡米尔·普莱耶尔，“但我无法创作，因为这里找不到钢琴——就这点而言，可以说是到了穷乡僻壤了。”', tags:[] },
  { k:'seg_5_东部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was the complaint of an artist thrown from his routine, a composer who habitually wrote his exceptionally original works at the piano and who now found himself without the one tool he needed.', mt:'', ref:'这就是一位艺术大师在工作节奏被全盘打乱后的抱怨，曾经那些杰出的作品都是在钢琴旁一笔笔写下的，但现在，他却找不到趁手的工具。', tags:[] },
  { k:'seg_5_东部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'So after a week of industry at full tilt belowstairs but little of it above, Chopin, Sand, her children, and the maid moved to a house in Establiments, off the Palma road, a small enclave northwest of the port, a property found for them by the French consul, Monsieur Fleury.', mt:'', ref:'他在楼下开足马力忙活了一周，但收获寥寥，于是，他带上乔治·桑和她的两个孩子还有女佣，搬到了港口西北的艾斯塔布里芒的房子里。房子还是法国领事弗勒里先生找来的。', tags:[] },
  { k:'seg_5_东部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Son Vent—the summer house in Establiments, which translates from Mallorquí as House of the Wind—cost Chopin and Sand fifty francs a month and was kitted out with wooden camp beds padded with paper-thin mattresses, straw-bottomed chairs, and rough-cut wooden tables.', mt:'', ref:'这房子是艾斯塔布里芒的避暑别墅，它有个名字叫Son Vent，在马略卡方言里是“风之屋”的意思。屋里布置的是木制行军床，床上垫着薄如纸片的床垫，椅子是稻草底的，木桌则做工粗糙。肖邦和乔治·桑一个月得为它支付50法郎。', tags:[] },
  { k:'seg_5_东部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There were glazed windows in most rooms, though there were neither fireplaces nor chimneys, just a small brazier that filled the house with noxious fumes but little heat, and left the occupants with dry throats and charcoal-smoked eyes.', mt:'', ref:'屋里虽然没有壁炉也没有烟囱，但大多数房间都有玻璃窗。只有一个小火盆在屋里释放有害烟雾，却不放热。住在里面，感觉喉咙干燥，眼圈也被木炭熏黑。', tags:[] },
  { k:'seg_5_东部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chopin, weakened by the stench and suffocating effect of the charcoal smoke, was by no means well in Establiments.', mt:'', ref:'终日面对难闻而令人窒息的炭烟，肖邦变得虚弱不堪，艾斯塔布里芒的日子一点也不好过。', tags:[] },
  { k:'seg_5_东部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And despite temperatures of sixty-four degrees and air outside scented with roses, oranges, and figs, he caught a feverish cold.', mt:'', ref:'当地的气温在18度，室外的空气充满了玫瑰、橙子和无花果的香味，他却感冒发烧了。', tags:[] },
  { k:'seg_5_东部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A succession of doctors (the grandest charging forty-five francs for his advice) prodded him and made dire pronouncements.', mt:'', ref:'他请过几个医生来看，最贵的要价45法郎，诊断结果都不乐观。', tags:[] },
  { k:'seg_5_东部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It is all having a bad effect on the Preludes,” he told Fontana in early December, referring to the collection of piano pieces that had occupied his imagination for some time, the thread of which he was attempting to pick up in Majorca.', mt:'', ref:'“这些事情都对前奏曲产生了负面影响，”他在12月初的信中告诉丰塔纳，前奏曲指的是他构思了好一阵子的钢琴作品集，他本打算在马略卡开始正式的创作。', tags:[] },
  { k:'seg_5_东部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“God knows when you will receive them.”', mt:'', ref:'“天知道你什么时候才能收到了。”', tags:[] },
  { k:'seg_5_东部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Before leaving Paris, Chopin had ordered from Pleyel a pianino, but it reached Marseilles only as he was writing to Fontana at the beginning of December, where it was loaded on to a merchant ship, destined, Chopin feared, to spend the next months in one or other port, hostage to rains and customs bottlenecks, to the lethargy that accompanies the onset of winter.', mt:'', ref:'离开巴黎前，肖邦从普莱耶尔处订购了一台小型立式钢琴，但到12月初他写信给丰塔纳时，钢琴才运到马赛，装到了一艘商船上。肖邦担心，冬天的到来将令万物死气沉沉，面对连月不开的阴雨和层层设卡的海关，接下来的几个月，这台琴得在一个个港口中度过了。', tags:[] },
  { k:'seg_5_东部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“The lack of a piano is a source of great distress to me on the boy’s account,” Sand told Grzymała on December 3, just as Chopin’s health returned.', mt:'', ref:'“没有钢琴让我真替这个小子难过，”乔治·桑在12月3日的信中告诉格日马，此时肖邦的健康状况有所好转。', tags:[] },
  { k:'seg_5_东部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He has hired a local one which gives him more vexation than consolation.', mt:'', ref:'“他在本地租到一台琴，不过这台琴没给他带去什么安慰，反而带来很多烦恼。', tags:[] },
  { k:'seg_5_东部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'All the same he is working.”', mt:'', ref:'不管怎么样，他开始创作了。”', tags:[] },
  { k:'seg_5_东部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The instrument was made by Juan Bauza of Mission Street, Palma.', mt:'', ref:'这台琴是帕尔马的密西恩大街的胡安·鲍扎制造的。', tags:[] },
  { k:'seg_5_东部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Majorca was indeed then a musical backwater, insulated from the pianoforte’s sudden and immense popularity throughout mainland Europe in the 1820s and 1830s, sparked by the achievements of Pleyel (Paris), Conrad Graf (Vienna), John Broadwood and Sons (London), Sébastien Erard and his nephew Pierre (Paris), each firm lodging new patents with a regularity that challenged the others.', mt:'', ref:'当时的马略卡，可谓是音乐文化的沙漠，完全隔绝于19世纪20年代至30 年代风靡欧洲大陆的钢琴文化之外。当时，普列埃尔（巴黎）、康拉德 ·格拉夫（维也纳）、约翰·布罗德伍德父子公司（伦敦）、塞巴斯蒂安· 埃拉尔和侄子皮埃尔（巴黎）的各种创新成就带动了这股潮流，每家公司都希望以新的专利发明确立技术标准与别人竞争。', tags:[] },
  { k:'seg_5_东部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Hélène Choussat de Canut, whose husband Bazile acted as Sand’s banker while she was in Majorca, had bought from a previous French consul a Pape piano—a model Chopin almost certainly knew from his visits to Pape’s showroom and concert hall on the rue des Bons-Enfants in Paris—though an instrument of this quality was a rarity on the island.', mt:'', ref:'乔治·桑在马略卡的银行经理叫巴兹勒，他的夫人海伦·卡努特从一位法国前领事那里买过一架巴贝牌钢琴，肖邦肯定知道这个品牌，因为他参观过巴黎Bons-Enfants大街的巴贝琴行和音乐厅，这种品质的乐器在岛上是罕见的。', tags:[] },
  { k:'seg_5_东部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In Palma, Bauza was completely isolated from these European developments.', mt:'', ref:'在帕尔马，鲍扎完全不了解欧洲大陆的这些发展。', tags:[] },
  { k:'seg_5_东部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He lived less than a kilometer from the artillery barracks.', mt:'', ref:'他住在离炮兵营不到一公里的地方。', tags:[] },
  { k:'seg_5_东部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Apart from his address and this piano, nothing is known of him—not even whether he was responsible for a number of instruments or was merely a hobbyist, a single project on his mind, inspired by something he had seen or read about.', mt:'', ref:'历史上留下的，只有他的住址和这架钢琴，我们甚至不知道他到底是个乐器工匠，还是个一时兴起的爱好者，是不是当时见过或读到过什么受了启发，很想捣鼓一个东西出来。', tags:[] },
  { k:'seg_5_东部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Perhaps he was one of Majorca’s famously slow carpenters, about whom Sand is so rude in Un hiver à Majorque: a good furniture maker would have the skills and tools to build a piano.', mt:'', ref:'他也可能是个木匠，拖沓程度在马略卡当地出了名，乔治·桑在《马略卡的冬季》中对他很不客气：有点水平的家具木匠就应该有造钢琴的技术和工具。', tags:[] },
  { k:'seg_5_东部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Or a clockmaker, schooled in fine machinery and intricate mechanics, self- taught if necessary (as was the horologist John Harrison): a clockmaker too would know how to make a piano if he put his mind to it.', mt:'', ref:'哪怕是钟表匠，无论是接受过精密机械和复杂力学培训的，或是自学成才的（如钟表匠约翰·哈里森）：稍微上点心，也能造出钢琴。', tags:[] },
  { k:'seg_5_东部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There was then no one single way to build one: it was much like the automobile industry at the end of the century, inventors and keen-eyed engineers advancing their own ideas, often their own patents, consensus following only later.', mt:'', ref:'当时的造琴法不止一种，这很像本世纪末的汽车工业，发明家和嗅觉灵敏的工程师提出自己的想法，注册独特的专利，技术上的共识要等上一段时间。', tags:[] },
  { k:'seg_5_东部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Consolidation of sorts came only in the 1860s and subsequently, thanks largely to the craft and innovation of Henry Engelhard Steinway and his five sons in their loft on Varick Street, Manhattan.', mt:'', ref:'直到19世纪60年代，这种技术共识才浮出水面，这在很大程度上要归功于亨利·恩格尔哈德·施坦威和他的五个儿子在曼哈顿瓦里克街阁楼里实践出的工艺和创新。', tags:[] },
  { k:'seg_5_东部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Before Steinway, piano makers simply responded as best they could to the challenges laid down by great composers: Beethoven in his final five sonatas (1816–22); Liszt in his Sonata in B Minor (1853, the year Steinway, Blüthner, and Bechstein were founded); Brahms in his first concerto (1858).', mt:'', ref:'在施坦威之前，钢琴制造商只是尽最大努力应对伟大作曲家提出的挑战：例如，贝多芬的最后五首奏鸣曲（1816-22年）、李斯特的B小调奏鸣曲（1853年，施坦威、布吕特纳和贝希斯坦成立的那一年），以及勃拉姆斯的第一钢琴协奏曲（1858年）。', tags:[] },
  { k:'seg_5_东部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'So the nascent revolution of the 1830s and 1840s—which saw instruments gradually increase in size, and strings and frame in tension—was not solely concerned with the pianos being made: what also now mattered was the way they were played (and by whom), and the music being written for them.', mt:'', ref:'到了19世纪30年代至40年代，乐器逐渐变大，琴弦和铁架间的张力逐渐增加，技术革新就不仅限于造琴了，它还关系到乐器的演奏方式、人员、乐曲创作等各方面的革新。', tags:[] },
  { k:'seg_5_东部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Liszt exploited the possibilities of Sébastien Erard’s double escapement action—whereby a note could be restruck before the hammer had returned to its resting position, a technique that aped Paganini on the violin and which sounded startling on a keyboard—and changed the physicality of piano playing: a pianist’s arms, shoulders, and back were now pressed into service to add weight and heft to the attack.', mt:'', ref:'塞巴斯蒂安·埃拉德的双重擒纵机构技术能让琴槌在回到静止位置之前，弹奏新的音符，这项技术模仿了帕格尼尼的小提琴，用在钢琴上的效果出奇的好。李斯特利用埃拉德的技术，革新了钢琴演奏对身体的要求：钢琴家的手臂、肩膀和背部都要加入演奏，以增加敲击的力度。', tags:[] },
  { k:'seg_5_东部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Pianos and pianists were suddenly required to do far more, as Liszt acknowledged in the late 1830s, writing about instruments that ran from four As below middle C (A0) to four Gs above (G7).', mt:'', ref:'突然间，钢琴和钢琴家就要承担更多的任务，正如李斯特在19世纪30年代末所承认的，那时的乐器音域从中央C开始，向下能延展到四个八度外的A（A0），向上能延展到四个八度外的G（G7）。', tags:[] },
  { k:'seg_5_东部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“In its span of seven octaves [the piano] embraces the range of an orchestra; the ten fingers of a single man suffice to render the harmonies produced by the combined forces of more than one hundred concerted instruments...', mt:'', ref:'“[钢琴]能够横跨七个八度，这样的音域堪比一整支交响乐队；一个人靠十个手指，就能弹出百余件乐器那种整齐、协调的和声……', tags:[] },
  { k:'seg_5_东部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'We make arpeggios like the harp, prolonged notes like wind instruments, staccatos, and a thousand other effects which once seemed the special prerogative of such and such an instrument.”', mt:'', ref:'我们可以弹出竖琴上的琶音、管乐器上的延音和断奏，甚至上千种此般或那般具有某种特色乐器的特殊音效。”', tags:[] },
  { k:'seg_5_东部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Such ready innovation ensured the piano’s quick passage into popular culture.', mt:'', ref:'这种颇具成熟度的革新，让钢琴迅速进入流行文化。', tags:[] },
  { k:'seg_5_东部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A year before Chopin and Sand’s trip to Majorca, Charles Dickens plotted Mr. Pickwick’s escape inside one, removing the innards to make room: consumerism, not solely the advocacy of progressive musicians, was helping drive both industrial and cultural shifts.', mt:'', ref:'就在肖邦和乔治·桑赴马略卡旅行的前一年，查尔斯·狄更斯就在作品中设计了匹克威克先生利用钢琴脱逃的情节——拆除内部机构腾出空间。可以看到，除了进步音乐家的倡导，当时的消费市场也在推动行业和文化的转变。', tags:[] },
  { k:'seg_5_东部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'By the very circumstances of its construction and its place in the not always linear evolution of the modern piano, Bauza’s instrument was out of date before it was completed.', mt:'', ref:'由于现代钢琴制造技术并非平缓演进，加之马略卡岛的物质条件限制，鲍扎先生打造的琴在完工前已经落后于时代了。', tags:[] },
  { k:'seg_5_东部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It possessed no technological pretensions: it was unable to support thicker or longer strings, greater tension, or a larger compass, its wooden frame and iron bracing a hostage to the island’s fierce climate.', mt:'', ref:'技术上，它毫无亮点，既不能支撑更粗更长的琴弦，也无法承受更大的张力，达不到更广的音域。木制框架和铸铁板面对岛上的恶劣气候则存在诸多隐患。', tags:[] },
  { k:'seg_5_东部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Yet it had its own beauty, and was in any case a rare artifact: a pianino in Majorca in the 1830s.', mt:'', ref:'不过，这架琴却有着独特的魅力，而且，它是19世纪30年代马略卡岛原产的小型立式钢琴，无论如何，都算一件罕见的艺术品了。', tags:[] },
  { k:'seg_5_东部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The Majorcan Preludes exploited every aspect of the pianos of the day, squeezed out every last drop of their capacity, and they are spread out fairly evenly through the collection.', mt:'', ref:'马略卡前奏曲充分利用了当时钢琴的各项技术进展，淋漓尽致地将其性能发挥到极致，从作品集的角度来看，这些前奏曲的内容分布较为均匀。', tags:[] },
  { k:'seg_5_东部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In No. 2 (A minor) unmoored harmonies underpin a melody no more sophisticated than something in a medieval psalter (a handful of notes artlessly stretched out), harmonies that ebb with alluring disregard for convention and key, which Chopin defines only in the final cadence when, midstream, he casually drops anchor.', mt:'', ref:'在第二首（A小调）中，无所依托的和声构筑起一段旋律（一组音符毫无雕饰地自然展开），缥缈如一首中世纪的祷告诗。这些和声恍惚地下降，不顾音乐传统和调式，直到结尾，肖邦定下了调式，乐曲也如行至河中央的船，随性地抛下了锚。', tags:[] },
  { k:'seg_5_东部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 4 (E minor) is a brittle piece in which a bland chain of harmonies slips down a note at a time, glueing together as best it can the melody Chopin places above, which he extends almost to breaking point.', mt:'', ref:'第四首（E小调）是一首如泣如诉的曲子，曲中一连串平淡无奇的和声，一次滑下一个半音，尽可能地将肖邦叠在上方的旋律粘连起来，行至结尾时已近愁肠寸断。', tags:[] },
  { k:'seg_5_东部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 5 (D) is built around a lumpy spinning-wheel figuration that sets off immediately and does not let up until the end, its character that of an étude, its tempo and intricacy suggesting that the Bauza’s action was spry enough.', mt:'', ref:'第五首（D大调）就像绕在一个凹凸不平的纺车上，随着纺车转起一下子释放开来直到结束。它拥有练习曲的特质，其节奏和复杂性表明鲍扎造的琴敲击起来非常敏捷。', tags:[] },
  { k:'seg_5_东部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 7 (A) is a gentle music-box waltz that Chopin does not let run down (though he shuts the box’s lid immediately and without warning after the sixteenth bar).', mt:'', ref:'第七首（A大调）是一首来自八音盒的轻柔圆舞曲，肖邦不想让它停下来（不过到16小节后，他没有任何预示就立即关上了八音盒的盖子）。', tags:[] },
  { k:'seg_5_东部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 9 (E) is a gruelling, insistent funeral march in the middle of the keyboard, under which the bass lumbers like organ pedals, the harmonies lurching from one point to the next in double-dotted Baroque figurations.', mt:'', ref:'第九首（E大调）是由琴键中部奏响的令人疲惫却又持续不断的葬礼进行曲，隆隆前行的低音像是由风琴踏板踩出，和声则蹒跚地一步步走向下一个巴洛克风格的双附点音。', tags:[] },
  { k:'seg_5_东部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In No. 10 (C sharp minor) scale patterns from high in the piano alternate with chorale fragments at its centre, an improbable duel that proves surprisingly well matched.', mt:'', ref:'第十首（C小调）中，钢琴高音部奏出的各色音阶与中心的合唱片段交替出现，这是一场不可思议的决斗，也是交相辉映的乐章。', tags:[] },
  { k:'seg_5_东部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 14 (E flat minor) is like a fabulous Bach toccata, with the skeleton of a nursery rhyme or folk song wired into the last three bars, out of place amid such fine, lace-like finger work – out of place too in the dark key of E flat minor.', mt:'', ref:'第十四首（降E小调）像一段绝妙的巴赫托卡塔，而最后三小节注入了童谣或民歌的结构，因此在全曲精致、丝滑的弹奏过程中显得格格不入 ——显得格格不入的还有那个降E小调的黑键。', tags:[] },
  { k:'seg_5_东部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'(It is a little like Mahler’s grim excursions into the same nostalgic territory sixty years later, where nursery tunes are given the bleakest harmonic backdrops.)', mt:'', ref:'（该曲类似60年后马勒在同样的乡愁题材中创作的忧郁作品，童谣在这些作品中被用作让人倍感凄凉的背景和声。）', tags:[] },
  { k:'seg_5_东部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The hypnotic ostinato of No. 15 (D flat) works its magic from the outset and establishes the melodic material of the growling, chromatic storm to come.', mt:'', ref:'第十五首（降D小调）那个让人昏昏欲睡的固定音自乐曲开始就展现出魔力，之后又化身为咆哮而出的半音风暴中的旋律。', tags:[] },
  { k:'seg_5_东部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'(This was Schubert’s device in one of the most exquisite songs he ever wrote, ‘Die liebe Farbe’ in Die schöne Müllerin of 1823, which Chopin must have known, and in which a repeated note runs throughout.)', mt:'', ref:'（这是舒伯特在他写过的最精致的一首歌中用到的技巧，肖邦一定知道 1823年上演的《美丽的磨坊女》中的“被爱的颜色”，歌中始终贯穿着一个重复的音符。）', tags:[] },
  { k:'seg_5_东部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 16 (B flat minor) is another right-hand étude that fills out the upper octaves of the piano with chromatic meanderings while the left hand does its best to stake a claim to the piece’s core tonality.', mt:'', ref:'第十六首（降B小调）是另一首右手练习曲，一堆迂回的半音在钢琴的高音八度区间跑动，而左手则奋力奏出曲子的主调。', tags:[] },
  { k:'seg_5_东部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 18 (F minor) is like someone arguing with himself – interrupting, stuttering, slowly gaining in confidence and fluency, prone to wild coloratura declamations.', mt:'', ref:'第十八首（F小调）就像一个人在和自己争论——打岔、吞吞吐吐、渐渐变得自信流利，甚至雄辩到花腔走板。', tags:[] },
  { k:'seg_5_南部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google Takes Yet Another Run at E-Commerce—and Amazon', mt:'', ref:'对标亚马逊，谷歌再度争取搭上电商快车', tags:[] },
  { k:'seg_5_南部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google executive Prabhakar Raghavan recently had an issue with his rose bushes.', mt:'', ref:'谷歌高级副总裁普拉巴卡尔·拉加万（Prabhakar Raghavan）最近发现家中的玫瑰花簇长势不大好。', tags:[] },
  { k:'seg_5_南部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'His wife took a photo of the plants on her phone, uploaded the image to Google, identified the culprit and followed a link for a fungicide.', mt:'', ref:'拉加万的妻子用手机拍下玫瑰，上传到谷歌，知道了问题所在，并点击了杀菌剂的购买链接。', tags:[] },
  { k:'seg_5_南部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then she bought it.', mt:'', ref:'接下来就是付费等待邮递。', tags:[] },
  { k:'seg_5_南部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A seamless transaction that didn’t involve typing into a search bar, it was a real-life test of sorts for Raghavan’s strategic vision.', mt:'', ref:'这种无需搜索栏输入的无缝交易，正是拉加万的商业愿景。', tags:[] },
  { k:'seg_5_南部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A senior vice president responsible for most of Google’s largest services—search, maps, advertising and more—the 61-year-old executive is determined to crack e-commerce, a market projected to hit $2.27 trillion in 2025 that the Alphabet Inc. division has tried and failed to figure out many times before.', mt:'', ref:'但要在现实层面执行并非易事。现年61岁的拉加万目前管理谷歌搜索、地图以及广告等主体业务。他准备带领谷歌再度进军电商领域。电商市场预估2025年营收可达2.27万亿美元，而此前谷歌的行动屡试屡败。', tags:[] },
  { k:'seg_5_南部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the past, Google has tried emulating Amazon.com Inc.’s online retail and delivery services, with little luck.', mt:'', ref:'过去，谷歌曾试图效仿亚马逊公司的在线零售和送货服务，但并不奏效。', tags:[] },
  { k:'seg_5_南部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Now, under Raghavan, the search giant is positioning itself as a kind of anti-Amazon, a free marketplace for merchants and Amazon rivals that’s designed to get consumers more comfortable shopping with Google.', mt:'', ref:'如今在拉加万的带领下，谷歌一反往日效仿亚马逊的在线零售与送货业务的做法，而是重新将自身定位为一个由零售商和其他亚马逊竞争对手进驻的自由市场，为消费者提高更舒适的网购体验。', tags:[] },
  { k:'seg_5_南部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Last week, at Google’s I/O software conference, Raghavan and his deputies demonstrated new features they hope will achieve that end, including one that lets visitors use photos to search for nearby retail products or find any item in the physical world with the click of a camera.', mt:'', ref:'在上周的谷歌I/O开发者大会上，拉加万团队展示了关于新业务功能的构想，包括允许用户上传照片搜索距离最近的线下零售商，或是通过一键拍照了解到产品线下购买渠道。', tags:[] },
  { k:'seg_5_南部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And on Tuesday, the company unveiled a feature that lets people go from merchant listings on Google search to their checkout pages in one click.', mt:'', ref:'本周二，谷歌推出的新功能是用户一键从正在浏览的产品页面跳转到购买页面。', tags:[] },
  { k:'seg_5_南部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan hopes the various initiatives will persuade millions of people to click buy, prompting sellers to purchase many more Google ads.', mt:'', ref:'拉加万希望这些功能帮助促进消费者的成交率，从而提高商户投放谷歌广告的意愿。', tags:[] },
  { k:'seg_5_南部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'For Amazon, which built a booming business by essentially renting its digital real estate to small sellers, the risk is that Google could give those brands a pathway to thriving outside its marketplace.', mt:'', ref:'亚马逊的营收来源于租赁数字房地产给零售商。谷歌也想在自己的地盘上采取相同的做法，分一杯羹。', tags:[] },
  { k:'seg_5_南部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That in turn could force the Seattle-based company to more aggressively court sellers with discounts on fees, advertising or logistics services.', mt:'', ref:'为了保证客源，亚马逊可能会在产品定价、广告营销、物流送货等方面给客户更大的优惠。', tags:[] },
  { k:'seg_5_南部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Still, Amazon remains a formidable rival, and Google confronts daunting challenges.', mt:'', ref:'无论如何，对于谷歌而言，挑战亚马逊如此强大的竞争对手困难重重。', tags:[] },
  { k:'seg_5_南部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Its renewed push into e-commerce coincides with a slowdown in online shopping as consumers revert to their pre-pandemic habits.', mt:'', ref:'尽管消费水平回升至疫情发生前，但网购依然没有太大的起色，而谷歌选择了这期间重新冲锋电商行业。', tags:[] },
  { k:'seg_5_南部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Amazon and EBay Inc. both recently reported slowing growth and weak profit outlooks.', mt:'', ref:'亚马逊和eBay公司最近的营收前景惨淡、增长放缓。', tags:[] },
  { k:'seg_5_南部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Moreover, Google has always sought to make its technology fade into the background.', mt:'', ref:'谷歌一直希望技术淡出大众视野。', tags:[] },
  { k:'seg_5_南部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Turning the site into a shopping destination risks wrecking the experience and alienating visitors.', mt:'', ref:'网站若纯粹服务于购物，就会严重影响消费者的购物体验，流失用户。', tags:[] },
  { k:'seg_5_南部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Ahead of the I/O presentation, Raghavan took pains to say shopping on Google would be “super smooth.”', mt:'', ref:'在I/O会议作演讲前，拉加万努力宣传，称用户在谷歌的购物体验超级顺利。', tags:[] },
  { k:'seg_5_南部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'If the concept works as advertised, he said, “shoppers won’t have to think: ‘Am I doing a search?', mt:'', ref:'他说，一旦概念落地，消费者认为使用谷歌搜索购物，', tags:[] },
  { k:'seg_5_南部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Am I on Amazon or Google?’”', mt:'', ref:'与使用亚马逊并无差异。', tags:[] },
  { k:'seg_5_南部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan is the first Google executive to oversee the technical operations behind both search and the ads division since Sundar Pichai did in 2014, shortly before he became CEO.', mt:'', ref:'拉加万并非负责管理搜索部和广告部技术运营工作的首位高管。 2014年，现任谷歌首席执行官的桑达尔·皮查伊（Sundar Pichai）也曾负责该业务。', tags:[] },
  { k:'seg_5_南部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan is also one of the company’s best compensated executives, pulling down $28.6 million last year in salary and stock grants.', mt:'', ref:'拉加万是谷歌年薪收入最高的员工之一，去年单是工资和股票分红已进账2860万美元。', tags:[] },
  { k:'seg_5_南部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As such, he has the clout to set an ambitious e-commerce strategy and, at least theoretically, get people who traditionally operated in silos to collaborate instead.', mt:'', ref:'这说明他有足够的信心去制定一个电子商务战略蓝图，理论上能够整合以往关联不大的业务。', tags:[] },
  { k:'seg_5_南部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Those who have worked with Raghavan point to his technical mastery and operational shrewdness—an unusual combination of attributes at a company that has so often coasted on its inventions and profits.', mt:'', ref:'拉加万的同事指出，他精通技术，善于运营，在谷歌这类注重技术与营收的商业公司来说是少见的人才。', tags:[] },
  { k:'seg_5_南部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Google is violently allergic to strategic thinking,” said Sam Ramji, a former executive who worked with Raghavan on Google’s cloud products.', mt:'', ref:'曾与拉加万合作开发谷歌云产品的山姆·拉姆齐（Sam Ramji）评价，拉加万是一个能弥补谷歌缺乏战略思维这一缺点的人。', tags:[] },
  { k:'seg_5_南部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He’s the man who brought strategy to Google.”', mt:'', ref:'他是有全局观的领导者。', tags:[] },
  { k:'seg_5_南部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Adds Martha Welsh, Google’s director of commerce strategy: “He really takes a holistic view of the business.”', mt:'', ref:'谷歌商务战略总监玛莎·威尔士（Martha Welsh）如是称赞道。', tags:[] },
  { k:'seg_5_南部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Since Raghavan’s promotion in mid-2020, he has torn up Google’s e- commerce playbook, scrapping the fees the company levied for online purchases and shuttering the delivery service.', mt:'', ref:'自2020年上任以来，拉加万修改了谷歌在电商方面的发展计划，免除了网购征税费用，取消了快递服务。', tags:[] },
  { k:'seg_5_南部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He has tried poaching merchants irritated with Amazon, reshuffled the leadership ranks, and overhauled Google’s payments operations by dropping its banking plans and narrowing the focus.', mt:'', ref:'实际的操作包括引进不满亚马逊的零售商，调整管理层人事安排，并为了改善谷歌的支付流程，不惜减持理财资金、避免分散资源。', tags:[] },
  { k:'seg_5_南部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He even tasked his search division with catering to people making heady commercial decisions, like buying a home or picking a college.', mt:'', ref:'甚至安排搜索团队为用户意向明确的商业决策需求提供服务，比如购房或择校。', tags:[] },
  { k:'seg_5_南部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He’s willing to make bold moves,” said Bill Ready, Google’s president of commerce, who joined in 2020 as one of Raghavan’s top deputies.', mt:'', ref:'l 2020年加入谷歌，成为拉加万左膀右臂的商务总裁比尔·雷迪（Bill Ready）认为他的上司行事大胆。', tags:[] },
  { k:'seg_5_南部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Boldness is required.', mt:'', ref:'冒进是不得已为之。', tags:[] },
  { k:'seg_5_南部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While Google’s advertising operation continues to print money, the model is under siege from regulators and privacy clampdowns, including Apple’s ban on targeted marketing messages.', mt:'', ref:'谷歌的广告业务在营利的同时也面对监管和隐私保护的双重打压。其中，苹果公司禁止谷歌投放个性化营销信息。', tags:[] },
  { k:'seg_5_南部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Due in part to these headwinds, the growth rate of the ad business is destined to slow, and Google isn’t the only one jumping into e-commerce to goose revenue; Meta Platforms Inc. and TikTok are as well.', mt:'', ref:'因此，广告业务停滞不前。而早在谷歌前，脸书和字节跳动两家公司已经开创了转战电商的先河。', tags:[] },
  { k:'seg_5_南部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Meanwhile, even as Google tries to build an online shopping destination to complement its ad business, Amazon has done the inverse: created a robust advertising operation on top of its enormous online bazaar.', mt:'', ref:'有意思的是，当谷歌选择打造购物网站来开源的同时，亚马逊却反其道而行之，全力投入到广告业务上。', tags:[] },
  { k:'seg_5_南部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s success is hard to gauge because it doesn’t break out e- commerce sales or retail ads.', mt:'', ref:'谷歌的电商与零售商广告业务营收有限，因而无法量化其表现。', tags:[] },
  { k:'seg_5_南部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Amazon’s is easy to see; its ads business posted 23% growth in the first quarter.', mt:'', ref:'但是亚马逊的广告业务在第一季度增长了23%，成绩一目了然。', tags:[] },
  { k:'seg_5_南部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“That seems to be working way better for Amazon than it is for Google,” said Mike Ryan, a portfolio strategist for Smarter Ecommerce GmbH.', mt:'', ref:'奥地利企业Smarter Ecommerce的投资分析师迈克·瑞安（Mike Ryan）认为亚马逊转换赛道的效果比谷歌要好。', tags:[] },
  { k:'seg_5_南部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan has tied Google’s main revenue and profit drivers—search and ads—more tightly to its e-commerce efforts than ever before.', mt:'', ref:'拉加万表现出比以往更强烈的决心，有意将谷歌的主营业务（搜索与广告）与电商捆绑发展。', tags:[] },
  { k:'seg_5_南部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s all put more pressure on him to deliver on his strategy.', mt:'', ref:'这样做的后果是他面临更大的压力去贯彻他的战略目标。', tags:[] },
  { k:'seg_5_南部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Shopping Express', mt:'', ref:'昔日的网购速达', tags:[] },
  { k:'seg_5_南部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s last big e-commerce push involved going at Amazon head-on.', mt:'', ref:'谷歌上次进军电商采取的行动是正面挑战亚马逊。', tags:[] },
  { k:'seg_5_南部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 2013, Google launched Shopping Express, a delivery service with a nifty app and a promise to ship many items on the same day.', mt:'', ref:'2013年，谷歌推出了网购速达的快递服务。用户下单程序的界面优美，且承诺当日送货上门。', tags:[] },
  { k:'seg_5_南部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google had huge retail partners on board, including Target Corp. and Walgreens, and planned an annual subscription model a la Amazon Prime.', mt:'', ref:'谷歌昔日的合作伙伴有塔吉特百货公司和药企沃尔格林公司等零售巨头。当时谷歌计划打造一个类似亚马逊Prime付费订阅会员的制度。', tags:[] },
  { k:'seg_5_南部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Back then, when quick e-commerce delivery was a novelty, Google’s service looked like a natural Amazon contender.', mt:'', ref:'在快速送货上门服务并不多见的年代，谷歌此举无疑表明其是亚马逊的有力竞争者。', tags:[] },
  { k:'seg_5_南部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But it never was.', mt:'', ref:'但实际上谷歌未曾对亚马逊构成真正的威胁。', tags:[] },
  { k:'seg_5_南部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Shopping Express expanded to a few cities outside of the San Francisco Bay Area, but had little appeal for consumers.', mt:'', ref:'网购速达的服务覆盖旧金山湾区及其他几个美国城市，但消费者并不买账。', tags:[] },
  { k:'seg_5_南部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s “Shopping” site, accessible as a tab on its homepage, aggregated listings from online retailers with paid ads at the top, but attracted relatively few visitors compared with the main search page.', mt:'', ref:'主要原因在于，跟搜索主页相比，购物页面的浏览量少得可怜。用户可以在谷歌主页点击其中一个页签进入购物网站，占据购物网页前排位置的是购买付费广告的线上零售商。', tags:[] },
  { k:'seg_5_南部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Former Google employees say managerial indecision and an unwillingness to invest heavily in the margin-thin business undercut the strategy.', mt:'', ref:'谷歌的员工表示管理层认为电商业务利润微博，不愿意重金投资，所以在该领域的决策上权衡许久，导致了第一次进军的失败。', tags:[] },
  { k:'seg_5_南部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then in 2015, Europe hit Google with a massive anti-monopoly suit that argued the search engine unfairly promoted its own shopping service over others.', mt:'', ref:'2015年，谷歌在欧洲折戟，收到反垄断集团诉讼，原因是谷歌搜索推广其购物网站业务这一行为，违背商业公平。', tags:[] },
  { k:'seg_5_南部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That forced the company to spin off the European business and move more cautiously.', mt:'', ref:'因此谷歌的电商业务不得不放弃欧洲市场，并且更加谨慎行事。', tags:[] },
  { k:'seg_5_南部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google brought in consultants from BCG to assess a specific e-commerce strategy, but didn’t follow the firm’s recommendations.', mt:'', ref:'在这种情形下，谷歌邀请波士顿咨询公司（BCG）的专业顾问来为其电商战略进行点评，但最后却没有采纳对方的建议。', tags:[] },
  { k:'seg_5_南部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The company shortened the delivery service’s name (to just Express) and revamped it to center on its digital voice-assistant, another Amazon competitor.', mt:'', ref:'谷歌将“网购速达（Shopping Express）”改名为“速达（Express）”，并着重研发语音助理产品。其语音助理整体解决方案也是亚马逊Alexa的竞品。', tags:[] },
  { k:'seg_5_南部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That effort fizzled, too.', mt:'', ref:'不过这些努力都没有奏效。', tags:[] },
  { k:'seg_5_南部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“For the past 15 years, Google has been trying to figure out commerce,” said Rick Watson, the head of RMW Commerce Consulting.', mt:'', ref:'纽约RMW商业咨询公司首席执行官瑞克·沃森（Rick Watson）评价称谷歌在过去十五年都致力于涉足电商的计划，', tags:[] },
  { k:'seg_5_南部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“And they’ve never really executed.”', mt:'', ref:'但却从未真正落实执行。', tags:[] },
  { k:'seg_5_南部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In early 2020, Google reset its strategy.', mt:'', ref:'2020年初，谷歌重新调整发展战略。', tags:[] },
  { k:'seg_5_南部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Management recruited Ready from PayPal to lead the commerce unit and realigned the search, payments and maps divisions to work more closely with his.', mt:'', ref:'PayPal第三方支付服务商企业的首席运营官雷迪（Bill Ready）加入谷歌，担任商务总裁一职，与负责搜索、支付和地图的业务部门有紧密合作。', tags:[] },
  { k:'seg_5_南部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'To run that entire portfolio, Google picked Raghavan, a veteran of its enterprise division who was put in charge of ads in 2018.', mt:'', ref:'不仅如此，谷歌还选中了拉加万领导电商等业务的发展。他在2018年曾主管广告业务。', tags:[] },
  { k:'seg_5_南部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Retail Leads the Online Ads Blitz', mt:'', ref:'零售促销线上广告', tags:[] },
  { k:'seg_5_南部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google\'s e-commerce strategy banks on getting retailers to buy more ads', mt:'', ref:'谷歌的电商战略在于促使零售商购买更多广告', tags:[] },
  { k:'seg_5_南部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Before joining Google in 2012, Raghavan spent years at tech research labs and in academia, where he became an expert on web search technologies just as they began taking off.', mt:'', ref:'在2012年加入谷歌之前，拉加万的工作场所是技术研究实验室和学术界。在网络搜索技术起步阶段，他已是这方面的专家。', tags:[] },
  { k:'seg_5_南部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He speaks five languages and still carries himself more like a professor than a senior executive.', mt:'', ref:'不仅如此，他还精通五国语言。在他的身上，你更多会看到一位教授，而不是高管的影子。', tags:[] },
  { k:'seg_5_南部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While discussing Google’s decision to emulate the visual, rapid-fire features of TikTok, he said, “It behooves us to also start thinking about those paradigms.”', mt:'', ref:'拉加万认为海外抖音(Tik Tok)的短视频带货是个很好的范例，并在会议上表示谷歌也应该去尝试。', tags:[] },
  { k:'seg_5_南部_66', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He once requested classical music to accompany his entrance onstage at an event before a staffer interceded.', mt:'', ref:'曾经有一次参与活动时，要不是工作人员阻止的话，他希望上台发言时的伴奏是古典音乐。', tags:[] },
  { k:'seg_5_南部_67', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He’s always surprised when he gets more responsibility,” said Jayshree Ullal, a longtime friend who runs Arista Networks Inc.', mt:'', ref:'网络设备企业Arista Networks公司的首席执行官雅什利·乌拉尔（Jayshree Ullal）与拉加万是多年的好友，他直言，“作为谷歌的二号人物，这样的人事任命让拉加万自己也感到惊讶。', tags:[] },
  { k:'seg_5_南部_68', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“You can never tell he’s a high-powered number-two executive at Google.”', mt:'', ref:'他给人的感觉并不像是高高在上、重权在握的管理人员。”', tags:[] },
  { k:'seg_5_南部_69', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Still, Raghavan made his e-commerce ambitions clear during the first year in his new role.', mt:'', ref:'上任第一年，拉加万还是明确表现出进军电商的决心。', tags:[] },
  { k:'seg_5_南部_70', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google, he told colleagues, should think of users being on “journeys”—not simply coming to Google.com for information but to research and, hopefully, buy something.', mt:'', ref:'他对团队的要求是要把用户视为游客——用户不仅是在谷歌上搜索信息，而且是分析产品，最好是能直接购买商品。', tags:[] },
  { k:'seg_5_南部_71', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He and Ready quickly decided to pull the plug on Express.', mt:'', ref:'谷歌迅速决定放弃提供“速达（Express）”快递业务，', tags:[] },
  { k:'seg_5_南部_72', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They dropped the commission Google took for sales on its properties and the fees it charged merchants to list items on its shopping site, a signal to the industry that it wanted to be an open marketplace, not a competitor.', mt:'', ref:'以及数字资产销售提成，还有零售商广告排名的收费。这无疑是向行业释放出谷歌希望成为一个开放的市场，而非零售商的竞争对手。', tags:[] },
  { k:'seg_5_南部_73', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“We’re not trying to put boxes on doorsteps,” Ready explained.', mt:'', ref:'雷迪解释谷歌不想成为快递服务提供商，', tags:[] },
  { k:'seg_5_南部_74', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“What we’re trying to solve is the information part of the problem.”', mt:'', ref:'而是要解决信息不对称问题。', tags:[] },
  { k:'seg_5_南部_75', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'By that, Ready meant making it easier for consumers to find desired products, deals or brands—even those that haven’t bought an ad.', mt:'', ref:'雷迪认为，这样一来，消费者更容易找到想要的产品、服务或品牌—— 无论卖家是否付费推广。', tags:[] },
  { k:'seg_5_南部_76', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Search results now identify discounts and loyalty programs, while new widgets list the shipping costs and hidden fees on specific purchases.', mt:'', ref:'搜索结果自动显示产品折扣和其他优惠政策。新上市的产品会显示运费与价格明细。', tags:[] },
  { k:'seg_5_南部_77', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google cut deals with Shopify Inc., Block Inc. and other commerce companies to make it more compelling for businesses to sell on Google properties.', mt:'', ref:'谷歌与电商Shopify、移动支付Block等企业就此达成一致。此举有望提高零售商购买谷歌数字资产的意愿。', tags:[] },
  { k:'seg_5_南部_78', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Those features are designed for buying products like sneakers and cooking pans.', mt:'', ref:'同样地，消费者在选购运动鞋和平底锅等产品时也更加方便。', tags:[] },
  { k:'seg_5_南部_79', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But the company is also experimenting with items that aren’t on most e- commerce sites—helping consumers buy NFTs via image search or research such big-ticket purchases as real estate.', mt:'', ref:'但是谷歌购物网站上的产品也有一些是普通电商网站所没有的，比如使用图片搜索数字货币NFT，或者房地产等大宗买卖。', tags:[] },
  { k:'seg_5_南部_80', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The company has noticed that searchers in the market for a home, college or car will often return to Google more than 60 times with similar queries before making a decision.', mt:'', ref:'用户在作出购买房屋、学校或汽车等大宗商品的决策前，至少会在谷歌上搜索60余次进行相关查询。', tags:[] },
  { k:'seg_5_南部_81', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The idea is to customize the search experiences for these use cases in ways Google hasn’t before.', mt:'', ref:'于是，谷歌希望可以为这些用户定制化前所未有的搜索体验。', tags:[] },
  { k:'seg_5_南部_82', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google has already done that with certain categories, creating unique features for people searching for jobs or hotels.', mt:'', ref:'在用户搜索职位与酒店这方面，谷歌已经做到了。', tags:[] },
  { k:'seg_5_南部_83', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Companies like Yelp and the online travel industry have complained that these changes buried their sites and forced them to buy more ads to get clicks.', mt:'', ref:'同时，这也引起了点评网站Yelp和一众旅游网站的不满，认为他们网站的曝光率因此降低，从而需要付费购买广告获取点击率。', tags:[] },
  { k:'seg_5_南部_84', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s search team has been quietly working on adding more topics.', mt:'', ref:'谷歌的搜索团队默默增加搜索主题数量。', tags:[] },
  { k:'seg_5_南部_85', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Under the project, codenamed Mercury, the search team has ceded to the advertising group such areas as “shopping, real estate, mortgages, etc,” according to a memo reviewed by Bloomberg.', mt:'', ref:'据彭博社消息，谷歌的会议纪要显示，在一个代号为水星的项目中，广告团队取代搜索团队，负责购物、房地产、抵押贷款业务。', tags:[] },
  { k:'seg_5_南部_86', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The authors of the document prioritized boosting traffic for merchants and creating “oh wow moments!” that would lure searchers back to Google.com and, eventually, a purchase.', mt:'', ref:'谷歌希望优先增加零售商的访问量，追求消费者尖叫度（Wow Moment），提高用户对谷歌的忠诚度，并最后能产生购买行为。', tags:[] },
  { k:'seg_5_南部_87', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google declined to comment on the project, but executives have said the ads division doesn’t influence unpaid search results.', mt:'', ref:'谷歌方面拒绝对这个项目进行评价，但他们可以明确的是，这不会影响到免费商家的搜索结果。', tags:[] },
  { k:'seg_5_南部_88', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan said the company has no plans to rival real estate brokers like Redfin.', mt:'', ref:'根据拉加万的说法，谷歌无意参与包括雷德芬（Redfin）在内的房地产中介公司的竞争。', tags:[] },
  { k:'seg_5_南部_89', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And, so far, Google has resisted using the search history of repeat visitors to tailor results.', mt:'', ref:'谷歌一直以来都拒绝使用重复访客的搜索历史来定制搜索结果。', tags:[] },
  { k:'seg_5_南部_90', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s largely to avoid violating people’s sense of privacy, he explained.', mt:'', ref:'拉加万的解释是这样做可以避免侵犯用户的隐私权。', tags:[] },
  { k:'seg_5_南部_91', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Can you, in these situations, offer the user more support in a long-running journey, without in any way creeping them out?”', mt:'', ref:'因此用户不会弃用谷歌，而谷歌可以长期留存客户，为他们提供更多的支持。', tags:[] },
  { k:'seg_5_南部_92', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan said his teams were still exploring if they could.', mt:'', ref:'这正是拉加万团队致力实现的目标。', tags:[] },
  { k:'seg_5_南部_93', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Some in Silicon Valley have blasted Google for filling search results with too many ads.', mt:'', ref:'部分硅谷人士批评谷歌在搜索结果显示中加入过多广告。', tags:[] },
  { k:'seg_5_南部_94', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan said increased demand from advertisers during the pandemic probably drove the recent uptick in advertising, and he expects it to cool off amid easing restrictions on travel and events.', mt:'', ref:'拉加万称广告数量的攀升是疫情期间商家的广告投放需求增加导致的。随着政府放松对旅游和聚集活动的管制，广告付费将逐渐降温。', tags:[] },
  { k:'seg_5_南部_95', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Early Success', mt:'', ref:'胜利的号角', tags:[] },
  { k:'seg_5_南部_96', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There are signs that Raghavan’s strategy is starting to pay off.', mt:'', ref:'事实证明，拉加万的计划奏效。', tags:[] },
  { k:'seg_5_南部_97', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Earlier this year, Google revealed that e-commerce advertising was a leading contributor to a 43% bump to search revenue in 2021.', mt:'', ref:'今年年初，谷歌披露的消息称2021年搜索业务营收增长43%，其中电商广告功不可没。', tags:[] },
  { k:'seg_5_南部_98', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google also said last year that over a billion people shop on its properties every day, though it hasn’t updated the figure.', mt:'', ref:'根据谷歌截止到当日的统计，去年谷歌网站上的日均消费人数高达十亿以上，而统计数据在更新后只会更多。', tags:[] },
  { k:'seg_5_南部_99', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the fall, Morgan Stanley research showed that consumers were using Google and YouTube to research products and price-shop more often than they used Amazon, EBay or Walmart.', mt:'', ref:'摩根士丹利（Morgan Stanley）在去年秋季的研究显示，消费者分析商品时更倾向使用谷歌、YouTube与平价商店，反而很少选择亚马逊、 EBay或沃尔玛。', tags:[] },
  { k:'seg_5_南部_100', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In April, the bank reported that 59% of survey respondents who are Amazon Prime members said they started researching products on Google, up from 50% in the fall.', mt:'', ref:'今年4月的调查报告表明，59%的受访者是亚马逊Prime付费订阅会员，他们已经使用谷歌来浏览商品。去年秋季这部分人数只有50%。', tags:[] },
  { k:'seg_5_南部_101', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Talley & Twine, an independent watch brand based in Virginia, started getting serious about Google in the past two years and has sometimes seen a fivefold return on its ad spending.', mt:'', ref:'过去两年间，位于弗吉尼亚州的独立品牌手表制造商Talley & Twine开始重视谷歌的价值，因为在谷歌的广告投放会带来五倍的收益回报。', tags:[] },
  { k:'seg_5_南部_102', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It’s been a saving grace for us,” said President Randy Williams.', mt:'', ref:'首席执行官兰迪·威廉姆斯（Randy Williams）感叹这拯救了他们公司的业绩。', tags:[] },
  { k:'seg_5_南部_103', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The other benefit, he added, is that the search engine sends customers to his web store.', mt:'', ref:'不仅如此，谷歌还帮助引流消费者到他们的网上商店。', tags:[] },
  { k:'seg_5_南部_104', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“That’s the roadblock we have with Amazon,” Williams said.', mt:'', ref:'这是亚马逊没法做到的。', tags:[] },
  { k:'seg_5_南部_105', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Amazon’s customers are Amazon customers.”', mt:'', ref:'在他看来，亚马逊网站的消费者不属于零售商自身。', tags:[] },
  { k:'seg_5_南部_106', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Still, some industry insiders say Google’s biggest moves to create a marketplace—cutting commissions and listing fees for merchants—have yet to attract significant numbers of shoppers.', mt:'', ref:'为了建立市场，谷歌降低商品展示的收费和提成。但有业内人士认为，此举未能提高消费者的访问量。', tags:[] },
  { k:'seg_5_南部_107', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When those changes were announced, some merchants braced for a big uptick in traffic and sales, said Ryan, the e-commerce strategist.', mt:'', ref:'例如，投资分析师瑞安认为，许多商家收到消息后期待点击率和销售额能大幅上升，但最后发现希望落空。', tags:[] },
  { k:'seg_5_南部_108', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Then nothing happened,” he said.', mt:'', ref:'谷歌的做法实际上意义不大。', tags:[] },
  { k:'seg_5_南部_109', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“I would describe it as nice, but low-impact.”', mt:'', ref:'但看起来很好。', tags:[] },
  { k:'seg_5_南部_110', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Kirk Williams, head of the online agency Zato Marketing, said Google’s fee adjustments didn’t alter consumer behavior enough to lure in more merchants.', mt:'', ref:'搜索引擎营销Zato Marketing的负责人柯克·威廉姆斯（Kirk Williams）也认为这样做并未改变消费者的网购习惯，因而商家进驻平台的意愿也较低。', tags:[] },
  { k:'seg_5_南部_111', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Not many more people visited Google’s shopping site, where merchants could list for free, and most eyeballs remained on the search page, where merchants still have to buy ads to get in front of consumers.', mt:'', ref:'谷歌的购物网站浏览量不多，因而商家可以免费展示。而为了在流量最高的搜索网站有一席之地，商家必须购买付费广告才能得到曝光。', tags:[] },
  { k:'seg_5_南部_112', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It hasn’t been anywhere near the traffic volume that they were hoping to see,” Williams said.', mt:'', ref:'在柯克看来，这在商家眼里并没什么吸引力。', tags:[] },
  { k:'seg_5_北部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When Did Humans Domesticate the Horse?', mt:'', ref:'马是何时被人类驯化的？', tags:[] },
  { k:'seg_5_北部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Only recently have scientists discovered exactly when and where the animal went from wild to tame', mt:'', ref:'直到最近科学家才成功确定家马的驯化时间和地点', tags:[] },
  { k:'seg_5_北部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Amber Dance, Knowable Magazine', mt:'', ref:'艾波·丹斯，《可知杂志》', tags:[] },
  { k:'seg_5_北部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They say dogs are man’s best friend, but horses could also claim that', mt:'', ref:'人们都知道狗是人类最好的朋友，但马也是人类忠实的朋友。', tags:[] },
  { k:'seg_5_北部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horses gave us a way to transport people and goods — literal', mt:'', ref:'马为人员往来和货物运输提供了一种新的方式——字面上讲的马力。', tags:[] },
  { k:'seg_5_北部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'horsepower They changed warfare: drawing chariots, carrying the cavalry.', mt:'', ref:'它们改变了战争形式：马可以拉战车，可以运送骑兵。', tags:[] },
  { k:'seg_5_北部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They’ve inspired artists from Stone Age cave painters to the makers of “ My Little Pony.”', mt:'', ref:'它们为艺术家的创作提供了灵感，既包括石器时代洞穴画家，也包括《 小马宝莉》的制作人。', tags:[] },
  { k:'seg_5_北部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Their role in industry may have waned in favor of machines, but they still maintain a place in sport, in leisure and in our collective hearts.', mt:'', ref:'随着机器的出现和使用，马在生产中的作用就越来越小了，但它们在运动、休闲和我们心中仍然占有一席之地。', tags:[] },
  { k:'seg_5_北部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horses have been intertwined with human culture since at least 2000 B.C.E. and were associated with certain human groups even earlier.', mt:'', ref:'至少从公元前2000年开始，马就与人类文化交织在一起，它们与某些人类群体的联系可能更早。', tags:[] },
  { k:'seg_5_北部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Horses are the animal that has changed history,” says Ludovic Orlando, a molecular archaeologist at the University of Toulouse III-Paul Sabatier in France.', mt:'', ref:'法国图卢兹第三大学的分子考古学家卢多维克·奥兰多说：“马改变了人类的历史。”', tags:[] },
  { k:'seg_5_北部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Today, horse breeds number in the hundreds, from the high-stepping Lipizzan horses of Austria to the Clydesdale draft horses of Budweiser commercials to the thoroughbreds of the Kentucky Derby.', mt:'', ref:'目前，世界上的马有数百种之多，从奥地利的高脚利比扎马到百威啤酒广告中的克莱兹代尔挽马，再到肯塔基赛马会的纯种马。', tags:[] },
  { k:'seg_5_北部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Despite their differences, these animals are all Equus caballus, joined in the modern equid family by donkeys, zebras and the wild Przewalski’s horses of Central Asia (though some taxonomists prefer the name Equus ferus for wild horses, and classification of Przewalski’s horses can vary).', mt:'', ref:'它们虽有不同，但都是马 (Equus caballus)，现代马科动物还包括驴、斑马和中亚的普氏野马（尽管一些分类学家更喜欢用Equus ferus称呼野马，普氏野马的分类可能会有所不同）。', tags:[] },
  { k:'seg_5_北部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The evolutionary path leading up to Equus is a classic model of evolution — a thoroughly documented history that graces textbooks and museum exhibits.', mt:'', ref:'马的进化之路遵循着经典的进化模式——有着完整的历史记录，为教科书和博物馆陈列增色不少。', tags:[] },
  { k:'seg_5_北部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But until lately, the route to domestication by people has been a black', mt:'', ref:'但是直到最近，马的驯化仍是一个未解之谜。', tags:[] },
  { k:'seg_5_北部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The bones of E. caballus all look pretty much the same, whether wild or domestic, so they couldn’t answer a longstanding question: Where and when did humans first domesticate horses, linking the two species on a road that would lead to horse-drawn carriages, horse-racing and so much more?', mt:'', ref:'无论是野马还是家马，它们的骨头看起来没什么区别，所以也就无法回答一个长期存在的问题：人类在何时何地首次驯化马匹？驯化将人类和马联系在一起，催生了马车、赛马等与马相关的物品和活动，使人类走上了新的发展道路。', tags:[] },
  { k:'seg_5_北部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Today, a revolution in the study of DNA, from both ancient and modern creatures, is providing answers.', mt:'', ref:'目前，对古马和现代家马DNA研究的革命正在破解这个难题。', tags:[] },
  { k:'seg_5_北部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Applying the same approach used in a landmark 2010 study of Neanderthal DNA, scientists have learned much about the history of Equus caballus.', mt:'', ref:'运用2010年对尼安德特人DNA的里程碑式研究中使用的同一方法，科学家对马的历史有了很多了解。', tags:[] },
  { k:'seg_5_北部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They have tracked how ancient wild horses shared genes across the Bering Strait between Asia and North America, and revealed the surprising history of Przewalski’s horse.', mt:'', ref:'他们追踪到古代野马是如何跨越亚洲和北美洲之间的白令海峡共享基因的，并揭示了普氏野马的前世今生。', tags:[] },
  { k:'seg_5_北部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And working with more modern samples, they have observed how recent management by people has undone much of the diversity in horse genomes, while adding a host of breed-specific features.', mt:'', ref:'通过对更多现代样本的研究，他们发现人类驯养马匹增加了不同品种的特性，但也破坏了马基因组的大部分遗传多样性。', tags:[] },
  { k:'seg_5_北部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But there has never been quite enough ancient DNA to answer the question of domestication — until late 2021, when scientists reported their analysis of more than 250 ancient horse genomes.', mt:'', ref:'但是在2021年底之前，一直没有足够的古马DNA用于解答马匹驯化之谜。这年年底，科学家报告了他们对250多个古马基因组的研究结果。', tags:[] },
  { k:'seg_5_北部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It’s great to have this big piece filled in, in the puzzle of where horses actually came from,” says Jessica Petersen, an animal geneticist at the University of Nebraska-Lincoln who wasn’t involved with that particular mystery.', mt:'', ref:'内布拉斯加大学林肯分校的动物遗传学家杰西卡·彼得森说：“在马的起源这个未解之谜中，这么大的一块空白被填补真是了不起。”她本人并没有参与这项研究。', tags:[] },
  { k:'seg_5_北部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But, she adds, the domestication process was a complex series of events, and more intricate details will be difficult to uncover.', mt:'', ref:'但是，她补充道，驯化过程涉及一系列复杂的事件，很难揭示更为复杂的细节。', tags:[] },
  { k:'seg_5_北部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Evolution of the horse', mt:'', ref:'马的进化', tags:[] },
  { k:'seg_5_北部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Sifting through fossil bones and teeth, paleontologists have traced the ancestry of horses back roughly 50 million years to a dog-sized, hoofed animal called Hyracotherium — aka eohippus, the “dawn horse.”', mt:'', ref:'通过对马的骨骼和牙齿化石的筛选研究，古生物学家发现马的祖先可以追溯到大约5000万年前，是一种大小如狗、有蹄的动物，名叫“始祖马”，又名“黎明马”。', tags:[] },
  { k:'seg_5_北部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The genus Equus, as we know it, probably emerged between 4 million and 4.5 million years ago in the continent that would become North', mt:'', ref:'我们了解的马属动物可能出现在距今400万到450万年前的北美大陆上。', tags:[] },
  { k:'seg_5_北部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'(That’s well before the Homo lineage, which wouldn’t hit the scene for at least another million years.)', mt:'', ref:'（远在猿人谱系出现之前，因为至少在一百万年后，猿人谱系才会出现）。', tags:[] },
  { k:'seg_5_北部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Fast forward to the late Pleistocene, 11,700 to 129,000 years ago, and horses were trotting back and forth between Asia and the Americas on the Bering Land Bridge.', mt:'', ref:'快进到更新世晚期，距今1.17万年到12.9万年前。那时，马通过白令陆桥来回穿梭于亚洲和美洲之间。', tags:[] },
  { k:'seg_5_北部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The line leading to modern-day domestic horses and wild Przewalski’s horses split sometime in the middle of that epoch, between 35,000 and 50,000 years ago.', mt:'', ref:'大约在3.5万年到5万年前，现代家马和普氏野马在更新世中期的某个时候进化方向发生了分化。', tags:[] },
  { k:'seg_5_北部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But about 11,000 years ago, around the time the Bering Land Bridge submerged for the last time, the North American horses went extinct, along with many other large species such as mammoths and giant', mt:'', ref:'然而，大约在1.1万年前，也就是白令陆桥最后一次被海水淹没的时候，北美马灭绝了，同时灭绝的还有猛犸象和巨型海狸等许多其他大型物种。', tags:[] },
  { k:'seg_5_北部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While it’s hard to pinpoint a reason, climate, hunting or a combination of the two might have been a factor, says Alisa Vershinina, a geneticist at LifeMine Therapeutics in Cambridge, Massachusetts, who investigated the Bering crossings while working as a researcher at the University of California, Santa Cruz.', mt:'', ref:'马萨诸塞州剑桥市生物制药公司LifeMine Therapetuics的遗传学家阿利莎·韦尔西尼娜说，虽然很难确定北美马灭绝的具体原因，但气候、狩猎或两者的结合可能是其中一个因素。她在加州大学圣克鲁兹分校担任研究员期间曾经调查过白令陆桥通道。', tags:[] },
  { k:'seg_5_北部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Early humans would have seen horses around, and they were clearly interested in the majestic animals: Horses are the top animal depicted in Stone Age, Western European cave art.', mt:'', ref:'早期的人类会在定居点周围看到马，显然他们对这些高大雄壮的动物很感兴趣：马是石器时代西欧洞穴艺术中描绘的最重要的动物。', tags:[] },
  { k:'seg_5_北部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But there’s a big difference between observing the animals for artistic inspiration and harnessing them for horsepower, transport and sport.', mt:'', ref:'但是，观察马匹以获得艺术灵感和驾驭它们以获得马力、便利交通和进行运动之间有很大的区别。', tags:[] },
  { k:'seg_5_北部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When, and where, did the relationship between human and beast undergo a dramatic change?', mt:'', ref:'人类与马之间的关系是在何时何地发生了根本性的变化？', tags:[] },
  { k:'seg_5_北部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horses were a late addition to the barnyard.', mt:'', ref:'马是后来才被驯化的。', tags:[] },
  { k:'seg_5_北部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Dogs were domesticated 15,000 years ago; sheep, pigs and cattle, about 8,000 to 11,000 years ago.', mt:'', ref:'狗在1.5万年前被驯化；羊、猪和牛大约在8000至11000年前被驯化。', tags:[] },
  { k:'seg_5_北部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But clear evidence of horse domestication doesn’t appear in the archaeological record until about 5,500 years ago.', mt:'', ref:'但是考古资料中有明确证据显示马的驯化始于距今约5500年前。', tags:[] },
  { k:'seg_5_北部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horse remains from across Eurasia gave scientists several candidates for the first domestication event.', mt:'', ref:'欧亚大陆各地发现的马的遗骸为科学家们了解马匹首次驯化提供了几个候选遗址。', tags:[] },
  { k:'seg_5_北部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'For example: In 2018, scientists found a frozen, mummified horse in modern-day Siberia.', mt:'', ref:'例如， 2018年，科学家在西伯利亚发现了一匹冰冻木乃伊马，', tags:[] },
  { k:'seg_5_北部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was dated to about 4,600 years ago.', mt:'', ref:'其历史可以追溯到大约4600年前。', tags:[] },
  { k:'seg_5_北部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Might it have been one of the first workhorses?', mt:'', ref:'它有可能是最早的驮马吗？', tags:[] },
  { k:'seg_5_北部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Iberia, the peninsula containing modern-day Spain and Portugal, seemed promising because horses have continuously inhabited the region for the past 50,000 years, and would have been available for potential domestication.', mt:'', ref:'伊比利亚半岛，包括今天的西班牙和葡萄牙，似乎很有希望，因为在过去的5万年里该地区一直有马在活动，所以存在驯化的可能。', tags:[] },
  { k:'seg_5_北部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And in the part of Eastern Europe around the Caspian Sea, archaeologists noticed horse remains appearing alongside those of other domestic animals.', mt:'', ref:'在里海周围的东欧部分地区，考古学家发现马的遗骸与其他家畜的遗骸一起出现。', tags:[] },
  { k:'seg_5_北部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Human burials about 6,000 years ago began to contain maces decorated with horse heads, perhaps indicating some change in human-horse relations.', mt:'', ref:'大约6000年前，人类墓葬中开始出现马头形权杖，这显示人与马的关系可能发生了一些变化。', tags:[] },
  { k:'seg_5_北部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'This area also got attention because of long-term horse presence in the area.', mt:'', ref:'该地区也因为马在附近长期活动而备受关注。', tags:[] },
  { k:'seg_5_北部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But the archaeological site that captivated many horse-domestication researchers was the 3500 B.C.E. settlement at Botai, about 1,000 miles northwest of the Caspian, in modern-day Kazakhstan.', mt:'', ref:'然而，吸引了众多马匹驯化研究人员的考古遗址是公元前3500年的波泰人定居点。波泰遗址位于里海西北约1000英里，在今天的哈萨克斯坦境内。', tags:[] },
  { k:'seg_5_北部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The diet of the people in Botai seems to have been “entirely focused on horses,” says Alan Outram, a zooarchaeologist at the University of Exeter in England.', mt:'', ref:'英国埃克塞特大学的动物考古学家艾伦·奥特拉姆说，波泰人的饮食似乎“完全以马中心”。', tags:[] },
  { k:'seg_5_北部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Aside from a few dog bones, those of horses make up the majority of non-human remains on the site.', mt:'', ref:'在波泰遗址发现的非人类遗骸，除了几根狗骨之外，大部分都是马骨。', tags:[] },
  { k:'seg_5_北部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There’s evidence of fenced yards that might have held herds.', mt:'', ref:'有证据表明，栅栏围起来的场地可能是用来圈养马匹的。', tags:[] },
  { k:'seg_5_北部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Some skulls hint at slaughter by an axlike tool, and some horse teeth exhibit “bit wear,” as if they’d been bridled.', mt:'', ref:'一些头骨显示这些马是用斧状工具宰杀的，而一些马牙有“磨损”的痕迹，就像它们被勒过一样。', tags:[] },
  { k:'seg_5_北部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Pottery shards contain chemical traces of mare’s milk, which Outram says might have been consumed as butter, yogurt or cheese.', mt:'', ref:'陶器碎片上残留着马奶痕迹，奥特拉姆说这些马奶可能被用来制作黄油、酸奶或奶酪供人们食用。', tags:[] },
  { k:'seg_5_北部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Nonetheless, the site’s importance has been hotly debated.', mt:'', ref:'尽管如此，这个遗址的重要性还是引发了激烈的争论。', tags:[] },
  { k:'seg_5_北部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There’s no way to confirm that Botai inhabitants fully domesticated horses.', mt:'', ref:'目前尚无法证实波泰人成功地驯化了马。', tags:[] },
  { k:'seg_5_北部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Outram suspects that the Botai peoples treated the horses somewhat like how modern reindeer herders use their animals: They may have kept the horses near at hand for meat and milk, and maybe even have ridden a few of them to herd others.', mt:'', ref:'奥特拉姆猜测波泰人对待马的方式可能有点像现代驯鹿牧民使用驯鹿那样：他们在定居点附近养马，用来吃肉和喝奶，甚至可能会骑几匹马去放牧其他家畜。', tags:[] },
  { k:'seg_5_北部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But they probably weren’t managing breeding or using the animals extensively as pack or transport animals.', mt:'', ref:'但他们可能没有繁育马匹，也没将其广泛用作驮畜或交通工具。', tags:[] },
  { k:'seg_5_北部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And without enough ancient DNA, there was no way to be sure these were the horses that spread around the world as human-managed', mt:'', ref:'由于没有足够的古马基因，就无法确定这些马是否作为人类驯养的家畜传播到世界各地的。', tags:[] },
  { k:'seg_5_北部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then Orlando, Outram and colleagues analyzed a broad set of horse genomes, from as far back as about 42,800 years ago all the way up to 18 modern breeds, publishing the findings in the journal Science in 2018.', mt:'', ref:'后来，奥兰多、奥特拉姆和同事共同分析了马基因组，涵盖范围很广，从大约4.28万年前一直到18个现代马种，并于2018年在《科学》杂志上发表了研究成果。', tags:[] },
  { k:'seg_5_北部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The result: Today’s ponies, draft horses and their ilk have little in common with the Botai horse bones.', mt:'', ref:'研究发现现代矮马、役马及其同类与波泰马的骨头几乎没有相同之处。', tags:[] },
  { k:'seg_5_北部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They re not the genetic origin for modern domestic horses, says', mt:'', ref:'“这足以说明波泰马不是现代家马的祖先，”奥特拉姆说。', tags:[] },
  { k:'seg_5_北部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Outram The Botai lineage does live on, though.', mt:'', ref:'不过，波泰马的血统确实存在。', tags:[] },
  { k:'seg_5_北部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Unexpectedly, the researchers were able to draw a direct line between those 5,500-year-old bones and modern Przewalski’s horses.', mt:'', ref:'出乎意料的是，研究人员发现这些5500年前的马骨与普氏野马存在着关联。', tags:[] },
  { k:'seg_5_北部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These stocky animals with short, bristly manes live on the steppes of Mongolia, where they’re called takhi, or “spirit,” and considered a national symbol.', mt:'', ref:'普氏野马体型健硕，鬃毛较短而直立，生活在蒙古大草原上，在那里人们称其为“天马”，并将其视为民族的象征。', tags:[] },
  { k:'seg_5_北部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In other words, Przewalski’s horses, once considered the remnants of an eternally wild population, may not be completely wild after all.', mt:'', ref:'换言之，普氏野马曾经一度被认为是永久野生种群的残留，但它们可能并不完全是野生的。', tags:[] },
  { k:'seg_5_北部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Rather, they seem to be the feral descendants of horses that people at Botai might have managed, to some extent, but later lost control of.', mt:'', ref:'相反，它们似乎是曾经由波泰人驯养但后来又逃脱的马的后代。', tags:[] },
  { k:'seg_5_北部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They’d have that in common with other feral populations such as the mustangs of the American West and Australian brumbies.', mt:'', ref:'在这方面，它们与其他野生种群，如美国西部野马和澳大利亚野马，并无不同。', tags:[] },
  { k:'seg_5_北部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Przewalski’s horses aren’t much good for riding, notes Arne Ludwig, an evolutionary geneticist at the Leibniz Institute for Zoo and Wildlife Research in Germany.', mt:'', ref:'德国莱布尼茨动物园和野生动物研究所的进化遗传学家阿恩·路德维希指出，普氏野马不太适合骑乘。', tags:[] },
  { k:'seg_5_北部_66', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Perhaps, he speculates, that’s why they fell out of use.', mt:'', ref:'在他看来，这也许是它们被淘汰的原因。', tags:[] },
  { k:'seg_5_北部_67', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Whatever happened after Botai, Przewalski’s horses had a rough go of it.', mt:'', ref:'在波泰人之后，不管怎样，它们的生存都异常艰难。', tags:[] },
  { k:'seg_5_北部_68', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They nearly went extinct, with the last wild animal disappearing in 1969.', mt:'', ref:'它们几乎灭绝了，1969年最后一匹野外环境下的普氏野马死亡了。', tags:[] },
  { k:'seg_5_北部_69', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Today’s population, all descendants of a handful of animals that persisted in captivity, now number around 2,000 individuals in captivity or natural reserves.', mt:'', ref:'今天的普氏野马种群，都是少数圈养的普氏野马的后代，目前有2000匹被圈养或生活在自然保护区，', tags:[] },
  { k:'seg_5_北部_70', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There are also a few modern domestic horses in their family tree.', mt:'', ref:'其谱系中也有一些现代家马。', tags:[] },
  { k:'seg_5_北部_71', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Domestication rising', mt:'', ref:'驯化提升', tags:[] },
  { k:'seg_5_北部_72', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Despite these advances, when Orlando documented genomic studies of horse domestication for the Annual Review of Genetics in 2020, he was forced to conclude, “The geographic origin of modern domestic horses is presently unknown.”', mt:'', ref:'尽管相关研究取得了一些进展，当奥兰多2020年为学术期刊《遗传学研究进展年鉴》撰文对马匹驯化基因组研究进行综述时，他也不得不承认，“我们目前尚不清楚现代家马的地理起源。”', tags:[] },
  { k:'seg_5_北部_73', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But the clues were building up.', mt:'', ref:'但是证据在不断增加。', tags:[] },
  { k:'seg_5_北部_74', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Scientists had already nixed the Iberia and Siberia candidates: When researchers looked at ancient DNA, they found that those horse populations withered away, contributing little to the modern domestic lineage.', mt:'', ref:'科学家已经否决了家马起源于伊比利亚半岛和西伯利亚的说法：当研究人员观测古马DNA时，发现生活在上述两个地区的马的种群数量越来越少，对现代家马谱系贡献甚微。', tags:[] },
  { k:'seg_5_北部_75', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Getting to the true domestication site was a numbers game, says lead author Orlando.', mt:'', ref:'该研究的主要作者奥兰多说，确定真正的驯化地点是一个数字游戏。', tags:[] },
  { k:'seg_5_北部_76', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“We built the answer by narrowing down the evidence, little by little.”', mt:'', ref:'“我们通过一点一点地缩小证据范围来找到答案。”', tags:[] },
  { k:'seg_5_北部_77', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The more than 150 collaborating scientists, including Outram and Ludwig, kept adding more horse genomes, from across Eurasia and spanning about 50,000 to 200 B.C.E.', mt:'', ref:'包括奥特拉姆和路德维希在内的150多名科学家携手合作不断添加更多的马基因组，这些基因组来自欧亚大陆，时间跨度很大，从5万年前左右到公元前200年。', tags:[] },
  { k:'seg_5_北部_78', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'With 264 ancient horse genomes in hand, the answer was undeniable: The homeland of modern domestic horses was the part of Western Eurasia between and north of the Black and Caspian seas, more specifically known as the lower Volga-Don region.', mt:'', ref:'研究基于现有的264个古马基因组，因此结果是不容置疑的：现代家马起源于西欧亚大陆的某一地区，该地区位于黑海和里海之间及以北，具体来说是伏尔加河和顿河下游地区。', tags:[] },
  { k:'seg_5_北部_79', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The team reported their results in Nature in October 2021.', mt:'', ref:'研究团队于2021年10月在《自然》杂志上发表了他们的研究成果。', tags:[] },
  { k:'seg_5_北部_80', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While the data point to a clear answer, there’s still plenty of room for interpretation and speculation.', mt:'', ref:'尽管数据指向了一个明确的答案，但仍然需要进行大量阐释与探讨。', tags:[] },
  { k:'seg_5_北部_81', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Pinpointing that spot near the Caspian doesn’t mean it was the only place — and time — that people bent horses to the bridle.', mt:'', ref:'确定里海附近的那个地区并不意味着它是人们驯化马匹的唯一地点和时间。', tags:[] },
  { k:'seg_5_北部_82', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The genomic and paleontological evidence from the other candidate regions suggests horses may have been domesticated multiple times, at Botai and elsewhere, without leading to widespread horsemanship.', mt:'', ref:'来自其他候选地区的基因组和古生物学证据表明，马可能曾经在波泰和其他地方被驯化过多次，尽管没有使骑术传播开来。', tags:[] },
  { k:'seg_5_北部_83', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It shows how important horses were to people, that so many groups of people independently domesticated them,” says Beth Shapiro, an evolutionary biologist at the University of California, Santa Cruz, and a coauthor of the Nature study.', mt:'', ref:'加州大学圣克鲁兹分校的进化生物学家、《自然》研究的合作者贝丝· 夏皮罗说：“那么多群体独立进行马匹驯化，这足以表明马对人类有多重要。”', tags:[] },
  { k:'seg_5_北部_84', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The 2021 analysis does suggest that the domestication in the Volga-Don was the only one that “took,” the only one that spread like horse-drawn wildfire.', mt:'', ref:'2021年的研究表明，伏尔加河和顿河地区的马匹驯化是唯一一次“传播开来”的驯化，唯一一次野火般蔓延开来的驯化。', tags:[] },
  { k:'seg_5_北部_85', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Why were horses one of the last animals to be domesticated, and why these horses in particular?', mt:'', ref:'为什么马是最后被驯化的家畜呢？为什么是这些马呢？', tags:[] },
  { k:'seg_5_北部_86', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While it’s impossible to be certain, ancient genomes suggest tantalizing hypotheses.', mt:'', ref:'虽然无法确定最终原因，但古马基因组足以让我们提出诱人的假设。', tags:[] },
  { k:'seg_5_北部_87', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The lineage leading to modern domestic horses included a change near a gene called GSDMC.', mt:'', ref:'现代家马谱系包含一个名为GSDMC的基因，该基因周围发生了的变化。', tags:[] },
  { k:'seg_5_北部_88', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In people, alterations to this gene are linked to back problems.', mt:'', ref:'在人类身上，这种基因的改变与背部问题有关。', tags:[] },
  { k:'seg_5_北部_89', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It’s possible that the domestic horse version gave the animals stronger backs, suitable for long-distance riding.', mt:'', ref:'家马的这种基因变化能够赋予其更加强壮的背部，使其适合长途骑行。', tags:[] },
  { k:'seg_5_北部_90', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The domestic horse line also includes a change near a gene called', mt:'', ref:'家马谱系还包含一个名为ZFPM1的基因，', tags:[] },
  { k:'seg_5_北部_91', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'ZFPM1 This gene is important in mood regulation.', mt:'', ref:'该基因对调节情绪非常重要。', tags:[] },
  { k:'seg_5_北部_92', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Perhaps some domestic version of ZFPM1 made the animals in the region more docile, easier to tame.', mt:'', ref:'也许是某个版本中ZFPM1的基因变化使马变得更温顺，更容易驯化。', tags:[] },
  { k:'seg_5_北部_93', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These changes could have been the key to long-term horse domestication — but that’s all speculation, says Shapiro.', mt:'', ref:'夏皮罗说，这些变化可能是长期驯化马的关键——当然这也只是猜测。', tags:[] },
  { k:'seg_5_北部_94', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As for who did the domesticating, it hasn’t been possible to narrow it down to one culture, says Orlando.', mt:'', ref:'奥兰多说，至于是谁驯养的，目前还无法将其归结到某一文化。', tags:[] },
  { k:'seg_5_北部_95', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Diverse people from the region may have started experimenting with these horses about 4,200 years ago.', mt:'', ref:'生活在该地区的各个民族大约从4200年前就已经开始驯化马了。', tags:[] },
  { k:'seg_5_北部_96', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Domestic horses spread a bit from that point on, but things didn’t really take off until about 2000 B.C.E.', mt:'', ref:'从那时起，家马开始向外传播，但直到公元前2000年左右家马的传播才算真正开始。', tags:[] },
  { k:'seg_5_中西部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The mere thought of Chinese cultural influence on the founding of the United States is unimaginable to some.', mt:'', ref:'对一些人来说，仅仅想一想中国文化对美国建国产生了影响是难以置信的。', tags:[] },
  { k:'seg_5_中西部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Misperceptions—colored by potent, biased assumptions in the West—are partially responsible.', mt:'', ref:'其中部分原因在于他们被西方各种强有力的、带有偏见的假设所影响。', tags:[] },
  { k:'seg_5_中西部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'This book presents evidence—based on investigation and analysis—that the founders of the United States were influenced by many positive elements derived from their study of classical Chinese culture.', mt:'', ref:'本书提出的证据都是基于调查和分析。这些证据表明美国的开国元勋受到了他们研究的中国传统文化中许多积极因素的影响。', tags:[] },
  { k:'seg_5_中西部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Indeed, those same cultural and technological influences on what emerged as an independent, forward-thinking nation started even before the formal Declaration of Independence on July 4, 1776.', mt:'', ref:'确实，这些来自中国文化和技术的影响早在1776年7月4日美国《独立宣言》发布前就存在了。它们影响了美国这个独立的、具有前瞻性的国家的建立。', tags:[] },
  { k:'seg_5_中西部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Although China was geographically far removed from direct contact with the British Empire’s North American colonies, the newly independent, fledgling American republic’s relationship with China started with trade in 1784 via the voyage of the Empress of China.', mt:'', ref:'虽然地理上，中国与远离英国的这块北美殖民地相距甚远，但这个新独立的、羽翼未丰的共和国与中国的关系始于通过1784年中国皇后号进行的贸易往来。', tags:[] },
  { k:'seg_5_中西部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese civilization was the object of intrigue, curiosity, and admiration by Europeans and Americans alike, carried over by Jesuits’ articles and translations of Chinese classics and conveyed via the stories of traders and explorers.', mt:'', ref:'欧美等地的人们对神秘的中华文明感到好奇，非常钦佩。他们对中华文明的了解来自于耶稣会士的文章，或是中国经典作品的翻译，或是商人和探险家的故事。', tags:[] },
  { k:'seg_5_中西部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Influences varied.', mt:'', ref:'中华文明的影响多种多样。', tags:[] },
  { k:'seg_5_中西部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They ranged in the areas of agriculture, architecture, Confucian-based moral and political philosophies, and more as foundations for the new American nation evolved.', mt:'', ref:'这些影响随着新生的美国国家发展，涉及到农业、建筑、基于儒家的道德思想和政治哲学等等诸多方面。', tags:[] },
  { k:'seg_5_中西部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Recognized as one of the world’s most stable and successful classical civilizations, China offered many lessons and precedents that were distinct from the founders’ European heritage.', mt:'', ref:'众所周知，中华文明是世界上最稳定、历史最悠久的文明之一，蕴含许多经验和先例，它们与开国元勋所继承的欧洲传统截然不同。', tags:[] },
  { k:'seg_5_中西部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'To some of the founders, China presented a model for the young nation.', mt:'', ref:'对一些开国元勋来说，中国是这个年轻国家学习的榜样。', tags:[] },
  { k:'seg_5_中西部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They welcomed positive elements from Chinese civilization while integrating those same elements into an authentic, distinctly American culture that in turn had been inspired by the winds of change propelled by the best of the Age of Enlightenment that had emerged in Europe.', mt:'', ref:'他们欢迎来自中华文明的积极元素，同时将这些元素融入到真正的、独特的美国文化中，而这种美国文化又受到了欧洲启蒙运动最佳时期推动的变革浪潮的鼓舞。', tags:[] },
  { k:'seg_5_中西部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In pre-independence America, the founders introduced elements of Chinese agriculture practice to the North American colonies, facilitating advances in social and economic development.', mt:'', ref:'在独立前的美国，开国元勋把中国农业的实践元素引入北美殖民地，促进了社会和经济发展的进步。', tags:[] },
  { k:'seg_5_中西部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese-inspired agriculture and industrial technologies bolstered the colonial economies, resulting in prosperity for the Americans.', mt:'', ref:'受到中国的启发，殖民地的农业和工业技术促进了经济发展，给美国人带来了繁荣。', tags:[] },
  { k:'seg_5_中西部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Personal letters and other records indicate that Benjamin Franklin obtained seedlings of select Chinese plants.', mt:'', ref:'私人信件和其他记录都表明，本杰明·富兰克林（Benjamin Franklin）获得了多种中国植物的精选幼苗。', tags:[] },
  { k:'seg_5_中西部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Washington and Jefferson experimented with Chinese flowers in their personal gardens.', mt:'', ref:'华盛顿和杰斐逊在他们的私人花园中试种了来自中国的花卉。', tags:[] },
  { k:'seg_5_中西部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin—America’s most famous scientist and philosopher—expressed great interest in Chinese industrial technologies, such as milling, heating, shipbuilding, and papermaking.', mt:'', ref:'美国最著名的科学家和哲学家富兰克林对中国的工业技术，比如碾磨、供热、造船、造纸等，都表示出浓厚兴趣。', tags:[] },
  { k:'seg_5_中西部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He and fellow statesman Benjamin Rush promoted silk-making (or sericulture) in North America.', mt:'', ref:'他和另一位政治家本杰明·拉什(Benjamin Rush)在北美推广了丝绸制造（或养蚕）的工艺。', tags:[] },
  { k:'seg_5_中西部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Almost simultaneously, Thomas Jefferson was influenced by classical elements of Chinese architecture where it took form at Monticello.', mt:'', ref:'几乎同时，托马斯·杰斐逊(Thomas Jefferson)受到了中国古代建筑元素的影响，这些元素在他位于蒙蒂塞洛（Monticello）的住所得以呈现。', tags:[] },
  { k:'seg_5_中西部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'George Washington, Alexander Hamilton, and Gouverneur Morris were inspired through published literature by explorers on the Grand Canal of China.', mt:'', ref:'乔治·华盛顿（George Washington）、亚历山大·汉密尔顿（Alexander Hamilton）和古弗尼尔·莫里斯（Gouverneur Morris）都受到来自中国京杭大运河上的探险家的文学作品的启发。', tags:[] },
  { k:'seg_5_中西部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Later, these same Chinese technological innovations would influence the construction of the Erie Canal and spur the development of New York City.', mt:'', ref:'之后，这些同样的技术创新将影响伊利运河的开凿，并且推动纽约的城市发展。', tags:[] },
  { k:'seg_5_中西部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'America’s Founding Fathers modeled efforts toward the self-cultivation of personal virtue.', mt:'', ref:'美国的开国元勋努力培养个人美德，做出了典范。', tags:[] },
  { k:'seg_5_中西部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In turn, younger generations of Americans had free access to published works where traditions associated with Confucian philosophy were articulated.', mt:'', ref:'相应地，一代代的年轻美国人免费阅读各种出版物，了解儒家哲学的传统思想。', tags:[] },
  { k:'seg_5_中西部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The founders frequently drew from Confucian philosophies, embracing a new political framework for the young nation.', mt:'', ref:'开国元勋们经常借鉴儒家哲学思想，为这个年轻的国家制定了全新的政治框架。', tags:[] },
  { k:'seg_5_中西部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Many prominent colonists—Benjamin Franklin, Thomas Jefferson, John Adams, Thomas Paine, John Bartram, and Jedidiah Morse, among others—demonstrated their respect for Confucian moral philosophy, incorporating its principles into American culture.', mt:'', ref:'包括本杰明·富兰克林、托马斯·杰斐逊、约翰·亚当斯（John Adams）、托马斯·潘恩（Thomas Paine）、约翰·巴特拉姆（John Bartram）和杰迪迪亚·莫尔斯（Jedidiah Morse）在内的许多杰出的殖民者，尊重儒家道德哲学，并将其原则融入美国文化。', tags:[] },
  { k:'seg_5_中西部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese culture became important when some of the U.S. founders looked for resources that could be mobilized in their efforts to build a new nation after declaring independence from Great Britain.', mt:'', ref:'随着一部分美国开国元勋在宣布脱离英国独立建国后寻找可用于建设新国家的资源时，中国文化变得重要。', tags:[] },
  { k:'seg_5_中西部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese contributions to early America were varied.', mt:'', ref:'中国对早期美国的贡献是多种多样的。', tags:[] },
  { k:'seg_5_中西部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In their efforts to cultivate personal virtue and to educate the younger generations to be virtuous, several Founding Fathers sought guidance from Confucian philosophy.', mt:'', ref:'几位开国元勋在培养个人美德和教育年轻一代成为有德之士的努力中，寻求获取儒家哲学思想的指导。', tags:[] },
  { k:'seg_5_中西部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The founders also adopted Chinese inventions to facilitate the social and economic development of colonies and introduced elements of Chinese agriculture to North America.', mt:'', ref:'开国元勋还应用了中国的发明，将中国农业经验引入北美，来促进殖民地的社会和经济发展。', tags:[] },
  { k:'seg_5_中西部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The timing of China’s impact on America’s founders is particularly significant.', mt:'', ref:'中国对美国开国元勋产生影响的时机尤为重要。', tags:[] },
  { k:'seg_5_中西部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Why did such American notables as Benjamin Franklin, Thomas Jefferson, George Washington, and John Adams focus their attention and insatiable curiosity on China?', mt:'', ref:'为什么像本杰明·富兰克林、托马斯·杰斐逊、乔治·华盛顿和约翰·亚当斯这样的美国重要人物都对中国充满了好奇，对中国十分关注？', tags:[] },
  { k:'seg_5_中西部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As one of the most stable, and certainly the most long-lived civilization in the world, to the architects of the new, independent American nation China was the subject of intrigue and admiration.', mt:'', ref:'中华文明是世界上最稳定、当然也是历史最悠久的文明之一。对新生的独立的美国国家的开国元勋来说，中国是他们好奇和钦佩的对象。', tags:[] },
  { k:'seg_5_中西部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When the storm clouds of revolution started to gather momentum, Franklin astutely promoted his theory of social progress by combining Confucian political ideas with the Western tradition of social progress.', mt:'', ref:'独立革命蓄势待发时，富兰克林将儒家的政治思想与西方的社会进步传统结合起来，巧妙地推广他的社会进步理论。', tags:[] },
  { k:'seg_5_中西部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin and other statesmen would later apply this theory to craft the U.S.Constitution, thus solidifying the foundations of the nation’s political infrastructure.', mt:'', ref:'他和其他政治家后来应用这一理论制订了美国宪法，从而巩固了美国的政治基础。', tags:[] },
  { k:'seg_5_中西部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese civilization provided an opportunity to fuse its social and political frameworks with notions of the European Enlightenment, supporting the Founding Fathers’ efforts to create a uniquely American tradition.', mt:'', ref:'中华文明提供了一个将美国社会和政治框架与欧洲启蒙运动思想相融合的机会，支持开国元勋努力创造独特的美国传统。', tags:[] },
  { k:'seg_5_中西部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These same founders sought to establish a political identity that was distinct from European aristocratic traditions.', mt:'', ref:'他们寻求建立一种有别于欧洲贵族传统的政治身份。', tags:[] },
  { k:'seg_5_中西部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Facing British trade sanctions after the Revolutionary War, U.S. political leaders initiated efforts to build direct economic connections with China.', mt:'', ref:'独立战争结束后，面对来自英国的贸易制裁，美国的政治领导人开始设法与中国建立直接的经济联系。', tags:[] },
  { k:'seg_5_中西部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Robert Morris and George Washington were directly involved in the opening of trade with China with support from other American founders.', mt:'', ref:'在其他开国元勋的支持下，罗伯特·莫里斯（Robert Morris）和乔治·华盛顿直接参与了对华贸易的开启。', tags:[] },
  { k:'seg_5_中西部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'One important reason behind Thomas Jefferson’s quest for westward expansion through the acquisition of the Louisiana Purchase in 1803 was the search for a shortcut to China, and late in his presidency, he communicated the desirability of creating something like a U.S.-China policy.', mt:'', ref:'托马斯·杰斐逊通过1803年路易斯安那购地案寻求向西扩张的一个重要原因是寻找通往中国的捷径。在他总统任期的后期，他表达了制定类似美中政策的愿望。', tags:[] },
  { k:'seg_5_中西部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'IDEAS FROM THE EAST', mt:'', ref:'东方思想的影响', tags:[] },
  { k:'seg_5_中西部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'During the colonial era, the founders realized the value of Chinese civilization and applied certain Chinese ideas to improve social and economic life in the colonies.', mt:'', ref:'殖民时期，开国元勋意识到中华文明的价值，运用某些中国思想来改善殖民地人们的社会和经济生活。', tags:[] },
  { k:'seg_5_中西部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the wake of the victory of the revolution, some main founders even looked to China as a guide for their new nation.', mt:'', ref:'独立战争胜利后，一些主要的开国元勋甚至把中国视为美国这个新生国家学习的典范。', tags:[] },
  { k:'seg_5_中西部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They regarded China’s long agrarian tradition as a rich resource from which the newborn United States could learn valuable lessons.', mt:'', ref:'他们认为中国悠久的农业传统是一种丰富的资源，新生的美国可以从中汲取宝贵的经验。', tags:[] },
  { k:'seg_5_中西部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese ideas, particularly Confucian moral philosophy, inspired the founders.', mt:'', ref:'开国元勋受到中国思想，尤其是儒家道德哲学的启发。', tags:[] },
  { k:'seg_5_中西部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese ideas that the founders believed to be of great value to North America included certain practices of the Chinese imperial government, the social mobility based on meritocracy, and gentry spirits of community services.', mt:'', ref:'他们认为对北美有重大价值的中国思想包括中国政府的某些措施、基于任人唯贤制度的社会流动和贤德之士的公共服务精神。', tags:[] },
  { k:'seg_5_中西部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin probably read The Morals of Confucius as early as his 1724–1726 stay in London.', mt:'', ref:'可能早在1724年至1726年间，富兰克林就在伦敦读过《孔子的道德》一书。', tags:[] },
  { k:'seg_5_中西部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'From his autobiography, it appears that—partially influenced by Confucius—Franklin focused on the cultivation of personal virtue as early as 1726.', mt:'', ref:'从自传中可以看出，富兰克林在一定程度上受到孔子的影响，早在1726 年他就注重培养个人品德。', tags:[] },
  { k:'seg_5_中西部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius designed the path for virtuous perfection—from oneself to one’s family, to the state, and then to the whole empire.', mt:'', ref:'孔子设计了一条达到道德至善的道路，从个人到家庭，到国家，再到整个天下。', tags:[] },
  { k:'seg_5_中西部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1737, Franklin introduced this notion to American colonists.', mt:'', ref:'1737年，富兰克林向美国殖民者介绍了这一概念。', tags:[] },
  { k:'seg_5_中西部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin agreed with Confucius that a man should not only cultivate personal virtues but also disseminate them to others—including political leaders.', mt:'', ref:'他赞同孔子的观点，即一个人不仅应该培养个人品德，还应该将这些美德传递给他人——包括政治领袖。', tags:[] },
  { k:'seg_5_中西部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In a 1749 letter to George Whitefield, one of the most influential of all colonial American clergy, Franklin advocated that knowledge of Confucian ideas could even foster social tranquility.', mt:'', ref:'1749年，在写给美国殖民地最有影响力的神职人员之一乔治·怀特菲尔德(George Whitefield)的信中，福兰克林主张了解儒家思想甚至可以促进社会安定。', tags:[] },
  { k:'seg_5_中西部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius yearned to see people, especially rulers, adopt better morals and more compassion.', mt:'', ref:'孔子渴望看到人们，尤其是统治者，心怀怜悯，具有良好的道德情操。', tags:[] },
  { k:'seg_5_中西部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'For him, virtue was the foundation of a good and flourishing empire.', mt:'', ref:'对他来说，美德是一个国家长期存在、保持繁荣的基础。', tags:[] },
  { k:'seg_5_中西部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius asserted that rulers should behave appropriately in court and at home because they would certainly be imitated.', mt:'', ref:'孔子主张统治者在朝堂上和家里应该举止得体，因为他们的一举一动都会被效仿。', tags:[] },
  { k:'seg_5_中西部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'During the Revolutionary War, Franklin worked hard to promote this important principle.', mt:'', ref:'独立战争期间，富兰克林努力倡导这一重要原则。', tags:[] },
  { k:'seg_5_中西部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'After the American victory, some veterans wanted permanent recognition for their triumph through formation of an order of hereditary knights.', mt:'', ref:'战争胜利后，一些退伍军人希望通过建立世袭的勋爵制度来永久认可他们的功绩。', tags:[] },
  { k:'seg_5_中西部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin raised objections to this idea by using Confucius’s principle of social promotion.', mt:'', ref:'借用孔子的社会促进原则，他对此表示反对。', tags:[] },
  { k:'seg_5_中西部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius maintained that law and punishment were the minimum requirements for order, but social harmony can only be achieved by virtuous behavior.', mt:'', ref:'孔子认为，法律和惩罚制度是秩序的最低要求，而社会和谐只能通过道德行为来实现。', tags:[] },
  { k:'seg_5_中西部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In his enormously influential Poor Richard’s Almanack, most of Franklin’s advice for readers stresses virtues such as hard work, frugality, and attention to family.', mt:'', ref:'富兰克林的《穷理查德年鉴》一书极具影响力。书中他给读者的大多数建议都强调勤奋、节俭和关注家庭等美德。', tags:[] },
  { k:'seg_5_中西部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Dr. Benjamin Rush, an ardent patriot, in a 1798 essay on education in the new republic, asserted that “the only foundation for a useful education in a republic is to be laid in Religion.', mt:'', ref:'本杰明·拉什博士是一位热情的爱国者。他在1798年发表的一篇关于新共和国教育的文章中断言，“共和国中有效教育的唯一基石是宗教。', tags:[] },
  { k:'seg_5_中西部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Without this there can be no virtue, and without virtue there can be no liberty, and liberty is the object and life of all republican governments.”', mt:'', ref:'没有宗教就没有美德，没有美德就没有自由，而自由是所有共和政府部门的目标和生命。”', tags:[] },
  { k:'seg_5_中西部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Having expressed his veneration for Confucianism that “reveals the attributes of the Deity,” Rush declared that he would rather see the opinions of Confucius “inculcated upon our youth, than see them grow up wholly devoid of a system of religious principles.”', mt:'', ref:'拉什对“揭示神祇的属性”的儒家思想表示崇敬之情，并宣布他宁愿看到孔子的思想“灌输给我们的年轻人，也不愿看到他们在成长过程中完全没有受到宗教原则体系的指引”。', tags:[] },
  { k:'seg_5_中西部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'John Adams, in a letter to Thomas Jefferson, criticized the English theologian and natural philosopher Joseph Priestley for ignoring Confucius in his writing.', mt:'', ref:'在给托马斯·杰弗逊的一封信中，约翰·亚当斯批评英国神学家和自然哲学家约瑟夫·普利斯特列（Joseph Priestley）在他的作品中忽视了孔子及儒家思想。', tags:[] },
  { k:'seg_5_中西部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'James Madison, father of the U.S.Constitution, hung a portrait of Confucius at his home.', mt:'', ref:'美国宪法之父詹姆斯·麦迪逊 (James Madison) 在家中悬挂了孔子的肖像画。', tags:[] },
  { k:'seg_5_中西部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was probably not a historical coincidence that Confucian moral ideals were respected in an era when some U.S. leaders sought to liberate American culture from what they viewed as failed European ideologies.', mt:'', ref:'在美国一些领导人寻求将美国文化从他们认为失败的欧洲意识形态中解放出来的同时，儒家的道德理想受到尊重，这可能不是一个历史巧合。', tags:[] },
  { k:'seg_5_中西部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'CHINESE TECHNOLOGY', mt:'', ref:'中国技术的影响', tags:[] },
  { k:'seg_5_中西部_66', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese innovations in areas such as heating technology, silk production, porcelain ware, manufacturing, navigation, canal construction, and even regarding the construction of the Great Wall of China found their way to North America via Europe.', mt:'', ref:'中国在诸如供暖技术、丝绸加工、瓷器烧制、制造业、航海业、运河开凿等方面的创新，甚至是关于中国长城修建的创新，都通过欧洲传到了北美。', tags:[] },
  { k:'seg_5_中西部_67', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The founders realized this information could be used to promote social and economic development.', mt:'', ref:'开国元勋意识到这些技术都可以用来促进美国社会和经济发展。', tags:[] },
  { k:'seg_5_中西部_68', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1763, Benjamin Franklin, in an effort to promote the creation of a colonial silk industry, sent prominent American academic and Congregationalist minister Ezra Stiles copies of Chinese prints illustrating silk production.', mt:'', ref:'为了促进殖民地丝绸业的发展，1763年本杰明·富兰克林给著名的美国学者和公理会牧师埃兹拉·斯泰尔斯（Ezra Stiles）寄去了一些介绍中国丝绸生产工艺的印刷品。', tags:[] },
  { k:'seg_5_中西部_69', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Scarce energy resources also stimulated Franklin to examine Chinese technology.', mt:'', ref:'能源资源稀缺也刺激富兰克林研究源自中国的技术。', tags:[] },
  { k:'seg_5_中西部_70', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'By the 1740s, the growing colonial population resulted in noticeable diminishment of forests, which supplied fuel.', mt:'', ref:'到十八世纪四十年代，殖民地人口的不断增长导致可以提供燃料的森林面积显著缩小。', tags:[] },
  { k:'seg_5_中西部_71', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The heating of houses was growing more expensive.', mt:'', ref:'房屋的取暖成本也就变得越来越高。', tags:[] },
  { k:'seg_5_中西部_72', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Wood utilization was inefficient, and much of the heat—83 percent, Franklin estimated in many cases—was lost up chimneys.', mt:'', ref:'木材的利用率很低。据富兰克林估计，许多情况下，83%的热量都从烟囱流失了。', tags:[] },
  { k:'seg_5_中西部_73', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin carefully studied the Chinese technology of heating their houses in the cold winters.', mt:'', ref:'富兰克林仔细研究了中国人在寒冬为房屋供暖的技术。', tags:[] },
  { k:'seg_5_中西部_74', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin in part used these principles to invent the Pennsylvania Fireplace, which was later improved upon and became the famous Franklin Stove.', mt:'', ref:'他在一定程度上利用这些技术发明了宾夕法尼亚壁炉，后来加以改进成为著名的富兰克林炉。', tags:[] },
  { k:'seg_5_中西部_75', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Better heating technology made the cold winter less harsh and induced more colonists to move to the North—which later contributed greatly to its development as a manufacturing center.', mt:'', ref:'取暖技术变得更先进，寒冷的冬天也变得不那么难熬，这就吸引了更多的殖民者搬到北方--这为以后大大促进了北方成为制造业中心做出了贡献。', tags:[] },
  { k:'seg_5_中西部_76', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin also carefully studied Chinese ship construction and publicized the Chinese practice of watertight compartment construction.', mt:'', ref:'富兰克林还仔细研究了中国的船舶建造技术，并宣传了中国的水密舱建造方法。', tags:[] },
  { k:'seg_5_中西部_77', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'During the French and Indian War, 1754–1763, Franklin introduced the notion of a defensive wall—similar to the Great Wall of China—into public debate.', mt:'', ref:'在1754-1763年的法国-印第安人战争（French and Indian War）期间，富兰克林在公共辩论中引入了修建类似中国长城的此类防御设施的话题。', tags:[] },
  { k:'seg_5_中西部_78', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He maintained that building an American Great Wall was the most efficient way to protect the thirteen colonies.', mt:'', ref:'他坚持认为，修建美国式长城可以最有效地保护十三个殖民地。', tags:[] },
  { k:'seg_5_中西部_79', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin again raised the notion of the Great Wall during the Revolutionary War.', mt:'', ref:'独立战争期间，他再次提出了修建美式长城的建议。', tags:[] },
  { k:'seg_5_中西部_80', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A few Chinese technological innovations were also used to advance certain economic goals prior to American independence.', mt:'', ref:'美国独立之前，源自中国的一些技术创新也被用于推进某些经济目标。', tags:[] },
  { k:'seg_5_中西部_81', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Some colonial leaders, for example, viewed porcelain manufacturing as essential to national economic self-reliance.', mt:'', ref:'例如，一些殖民地领导人认为瓷器烧制对殖民地发展经济自立极为重要。', tags:[] },
  { k:'seg_5_中西部_82', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese porcelain, like tea, had been a major colonial import.', mt:'', ref:'中国瓷器和茶叶一样，一直是殖民地的主要进口产品。', tags:[] },
  { k:'seg_5_中西部_83', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Benjamin Rush was among the first who advocated building a porcelain factory in North America with the intent of overcoming American dependence on British imports.', mt:'', ref:'本杰明·拉什是主张在北美建立瓷器工厂的最早一批倡导者之一，目的是摆脱美国对英国进口商品的依赖。', tags:[] },
  { k:'seg_5_中西部_84', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Gouverneur Morris, prominent founder of the republic, studied China’s Grand Canal.', mt:'', ref:'著名的共和国缔造者古弗尼尔·莫里斯曾研究过中国的京杭大运河。', tags:[] },
  { k:'seg_5_中西部_85', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'With his encouragement, the New Yorkers built the Erie Canal, connecting New York to the Midwest.', mt:'', ref:'在他的鼓励下，纽约人开凿了伊利运河，将纽约市与中西部地区连接起来。', tags:[] },
  { k:'seg_5_中西部_86', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The canal played a role in New York City’s rise, triggered an explosion in canal building, facilitated economic growth, and linked the Northeast with the Great Lakes region.', mt:'', ref:'这条运河在纽约市的崛起中发挥了作用，促使美国多地迅速开凿运河，促进了经济增长，并将美国东北地区与五大湖区连接起来。', tags:[] },
  { k:'seg_5_中西部_87', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The colonists’ pursuit of domestic Chinese porcelain ware became a powerful call for patriotic support of American economic independence.', mt:'', ref:'殖民者寻求在美国国内烧制瓷器，成为支持美国经济独立的强有力的爱国号召。', tags:[] },
  { k:'seg_5_中西部_88', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin, in London when Rush was promoting colonial porcelain production, echoed this sentiment in a letter to his wife: “I am pleased to find so good progress made in the China Manufactory.', mt:'', ref:'当拉什在伦敦推广殖民地的瓷器生产时，富兰克林在给妻子的信中也表达了同样的感情:“我很高兴看到瓷器制造厂取得了如此巨大的进步。', tags:[] },
  { k:'seg_5_中西部_89', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'I wish it Success most heartily.”', mt:'', ref:'我衷心祝愿它获得成功。”', tags:[] },
  { k:'seg_5_中西部_90', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The American China Manufactory in Philadelphia became noted for its quality, and more importantly, succeeded in cultivating patriotism as it challenged Britain’s monopoly of the product and indirectly contributed to the struggle for independence.', mt:'', ref:'位于费城的美国瓷器制造厂因产品质量而闻名。更重要的是，它成功地激发了爱国主义热情，因为它挑战了英国对瓷器的垄断，并间接地为独立斗争做出了贡献。', tags:[] },
  { k:'seg_5_中西部_91', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Explicit examples of Chinese architectural influences are present in one of America’s most historic buildings.', mt:'', ref:'中式建筑对美国也产生了影响，最典型的例子就是一座最具历史意义的建筑物。', tags:[] },
  { k:'seg_5_中西部_92', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Jefferson developed a new type of architecture by incorporating certain Chinese designs into his famous neoclassical-style home, Monticello.', mt:'', ref:'杰斐逊将某些中国设计元素融入他著名的新古典主义风格的住宅蒙蒂塞洛(Monticello)，从而形成了一种新的建筑风格。', tags:[] },
  { k:'seg_5_中西部_93', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Jefferson used Chinese lattice in many buildings, including Barboursville, the Orange County, Virginia home he designed.', mt:'', ref:'他在许多建筑中都使用了中式格子，其中包括他设计的位于弗吉尼亚州奥兰治县巴伯斯维尔（Barboursville）的住宅。', tags:[] },
  { k:'seg_5_中西部_94', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Jefferson also planned to build a Chinese pavilion when he remodeled Monticello in the last decade of the eighteenth century.', mt:'', ref:'他在十八世纪最后十年改造蒙蒂塞洛时，也计划修建一座中式亭子。', tags:[] },
  { k:'seg_6_决赛_1', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'原来“江湖中人”有颗细腻的心', mt:'The \'people in the rivers and lakes\' originally had a delicate heart.', ref:'My “Swordsman” Father', tags:["术语"] },
  { k:'seg_6_决赛_2', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'在我的童年记忆和道听途说中，爸爸是一个“江湖中人”。', mt:'In my childhood memories and hearsay, my father was a "man of the world".', ref:'From what I heard and remembered as a child, my father was a “swordsman”.', tags:["准确性","术语"] },
  { k:'seg_6_决赛_3', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'据我妈口述，当年隔壁邻居家进了小偷，被发现后，我爸抄起武器，也许是厨房的菜刀，也许是阳台的棍子，和邻居追出去了两里地，最后邻居跑不动了说算了吧，我爸甚为遗憾。', mt:'According to my mother\'s account, a thief broke into our neighbor\'s house years ago. After being discovered, my father grabbed a weapon, perhaps a kitchen knife or a balcony stick, and chased after the thief with the neighbor for two miles. In the end, the neighbor couldn\'t run anymore and gave up, which my father was very regretful about.', ref:'My mother used to tell me a story of how he once confronted a burglar who had broken into our neighbor’s house and pursued him for roughly one kilometer with a “weapon” – probably a kitchen knife or a balcony stick. He only stopped when the neighbor gave up and said it was not worth it, but he regretted letting the thief escape.', tags:["准确性","语言规范","风格"] },
  { k:'seg_6_决赛_4', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'类似的故事我听过很多，足以拼凑出一幅江南小城热血青年的叱咤图景。', mt:'I have heard many similar stories, which can be pieced together to form a scene of hot-blooded young people in a small town in the south of the Yangtze River.', ref:'There were many other stories like that, which portrayed a valiant young man in a small town in southern China.', tags:["准确性","风格"] },
  { k:'seg_6_决赛_5', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'然而，“江湖中人”的人生经历流入那个平静如水的小城，就显得波澜不惊，平平无奇。他虽然不爱念书，但还是高中顺利毕业了；他虽然想当兵去打仗，但还是听家里安排进了工厂；他人生一大梦想是开拖拉机，但还是开起了轿车；', mt:'However, the life experiences of the "people in the rivers and lakes" flow into that calm and watery small town, which appears calm and unremarkable.Although he didn\'t like studying, he still graduated from high school smoothly; Although he wanted to join the army to fight, he still followed his family\'s arrangement and went to work in a factory; His biggest dream in life was to drive a tractor, but he ended up driving a car;', ref:'However, the life of “swordsman” in that peaceful town seemed dull and mundane. He was not fond of studying, but he managed to finish high school; he wanted to join the army, but he followed his parents’ plan and got a job in a factory; his biggest dream in life was to drive a tractor, but he settled for driving a car;', tags:["准确性","术语"] },
  { k:'seg_6_决赛_6', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我想他是希望有个儿子能跟随他继续闯荡江湖的，但我是个从小不爱运动的阿囡……20多年后，他拥有了一只英武的黑色小狗，他简直视若己出——这是后话。', mt:'I think he hoped to have a son who could follow him to continue to explore the world, but I am a girl who has never liked sports since childhood… More than 20 years later, he has a brave black dog that he loves like his own - but that\'s another story.', ref:'I think he wished to have a son who could join him and carry on his intrepid adventures, but I was a girl who hated sports since childhood … More than two decades later, he had a brave black dog, which he cherished as his own child -- but that’s another story.', tags:["准确性","语言规范","风格"] },
  { k:'seg_6_决赛_7', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'就像《流浪地球2》中的那个女孩有一段两分钟的数字人生，我记忆中也有一段可以反复迭代的童年。', mt:'Just like the girl in \'The Wandering Earth 2\' had a two-minute digital life, I also have a childhood memory that can be iterated repeatedly.', ref:'My childhood memory is like a digital clip that plays on repeat, just as the girl in The Wandering Earth II had.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_8', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'那是小城最中心的位置，两条主干道的十字交会处，在20世纪90年代初，仍是一个铺着碎石的大操场。', mt:'That is the most central location in the small town, at the intersection of two main roads. In the early 1990s, it was still a large playground paved with broken stones.', ref:'It takes me back to the heart of a small town, where two main roads crossed. Back in the early 1990s, it was still a vast playground with gravel on the ground.', tags:["准确性"] },
  { k:'seg_6_决赛_9', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'它也许有别的正式名字，但人们都喊它“大操场 ”，简单明了。', mt:'It may have another formal name, but people call it the \'big playground\', simple and clear.', ref:'It might have an official name, but natives simply called it “the big playground”.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_10', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'这儿早已没有了各种集会，于是成为户外运动的好地方，比如，放风筝。', mt:'There are no more gatherings here, so it has become a good place for outdoor activities, such as flying kites.', ref:'It was no longer a place for gatherings, but for outdoor fun, such as kite flying.', tags:["准确性"] },
  { k:'seg_6_决赛_11', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'关于此事的一种记忆是，爸爸每年都兴致勃勃地带我来大操场放风筝，一放就是一下午，我很开心；另一种则是，爸爸每年都带我看他放风筝，全场最嗨的就是他，经常风筝越飞越高，高到我都看不见了，爸爸就索性剪了绳子给它自由。', mt:'One memory about this is that my dad would bring me to the big playground every year to fly kites, and we would spend the whole afternoon there. I was very happy. Another memory is that my dad would bring me to watch him fly kites every year, and he was always the most excited one there. The kite would often fly higher and higher until I couldn\'t see it anymore, and my dad would just cut the string and let it fly freely.', ref:'I remember how my father would eagerly take me there every year to fly a kite. We would fly the kite for the entire afternoon and I was very, very happy. I also remember how he would show off his kite flying skills. He was the most thrilled one on the field. He often sent his kite so high that I couldn’t see it anymore. Then he would just cut the string and let it go.', tags:["准确性","风格"] },
  { k:'seg_6_决赛_12', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我的童年拥有过很多个风筝，无一例外都随风而去。', mt:'My childhood had many kites, all of which flew away with the wind.', ref:'I had many kites in my childhood, and they all flew away with the wind, one by one.', tags:["准确性"] },
  { k:'seg_6_决赛_13', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我一直觉得我妈是个文艺女青年，爱看书爱看电影，教我写作文监督我弹琵琶，而我爸的主职是带我瞎玩。', mt:'I have always felt that my mother is a literary and artistic young woman who loves to read books and watch movies, teaches me to write compositions and supervises me to play pipa, while my father\'s main job is to let me play around.', ref:'I always thought my mother was a literary young woman who relished reading books and watching movies. She taught me how to write essays and supervised me playing the pipa, while my father’s main role was to take me out for fun.', tags:["准确性","风格"] },
  { k:'seg_6_决赛_14', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'小学的一个暑假，妈妈给我在少年宫报了书法班，学费都交了，上了两堂课后，只记得那年夏天好热，西瓜好甜，午觉好香，我说我不想去上课了，我爸说他也不想送我——一拍即合 。', mt:'One summer vacation in elementary school, my mother signed me up for a calligraphy class at the Youth Palace. After paying the tuition and attending two classes, I only remember how hot the summer was, how sweet the watermelon was, and how fragrant the nap was.I said I didn\'t want to go to class anymore, and my dad said he didn\'t want to send me either - we agreed on this.', ref:'One summer vacation in elementary school, my mother enrolled me in a calligraphy class at the Children’s Palace. She paid the tuition fee, but after two classes, I only remembered how hot that summer was, how sweet the watermelon was, and how pleasant the nap was. I said I didn’t want to go to the calligraphy class anymore, and my father said he didn’t want to take me either -- we were on the same wavelength!', tags:["准确性","语言规范","风格"] },
  { k:'seg_6_决赛_15', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'这直接导致我现在的一手字仍停留在小学水平 。', mt:'This directly leads to my current handwriting still being at an elementary school level.', ref:'Quitting the calligraphy class resulted in my handwriting still staying at the elementary school level.', tags:["准确性"] },
  { k:'seg_6_决赛_16', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'本以为“江湖中人”会表里如一地从冲动的青年变成中年，然后我长大，他老去，风采依旧。', mt:'I thought that the \'people in the rivers and lakes\' would be consistent from impulsive youth to middle age, but as I grew up, he aged, and his style remained the same.', ref:'I thought this “swordsman” would naturally turn from an impetuous youth into a calm-minded middle-aged man, and then I grew up, he grew old, but still charming.', tags:["准确性","风格","术语"] },
  { k:'seg_6_决赛_17', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'但有一件事，让我认识到了爸爸的另一面。', mt:'But there is one thing that made me realize another side of my dad.', ref:'But there was one thing that made me realize another aspect of my father.', tags:["准确性"] },
  { k:'seg_6_决赛_18', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'那是小学六年级，我的青春期即将到来。', mt:'That was sixth grade, my adolescence was about to come.', ref:'It was in the sixth grade of elementary school, and my puberty was about to start.', tags:["准确性"] },
  { k:'seg_6_决赛_19', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'在20世纪和21世纪相交的年代，女孩的青春期隐秘而不可言说。', mt:'In the era where the 20th and 21st centuries intersect, the girl\'s adolescence is secretive and unspeakable.', ref:'At the turn of the 21st century, girls’ puberty was secretive and unspeakable.', tags:["准确性","语言规范","风格"] },
  { k:'seg_6_决赛_20', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'学校开设了生理卫生课，却是男生女生分开上，老师播放了科普视频，再多就语焉不详。', mt:'The school has set up a course on reproductive health, but it is taught separately for boys and girls. The teacher played an educational video, but didn\'t provide much explanation beyond that.', ref:'The school offered a health class, but it was separate for boys and girls. The teacher played a popular science video, and then said nothing more.', tags:["准确性","风格"] },
  { k:'seg_6_决赛_21', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'总之，谁也没放在心上，我也照旧理着短发、 穿着运动服，爬高就低。', mt:'Anyway, no one cared, and I continued to wear my short hair and sportswear, climbing high and low.', ref:'In short, no one cared about it. I still had short hair, wore sportswear, and climbed up and down like a boy.', tags:["准确性"] },
  { k:'seg_6_决赛_22', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'一个下午，我去新华书店，让我爸跟着，毕竟他是名副其实的金主爸爸。', mt:'One afternoon, I went to Xinhua Bookstore and had my dad follow me, after all, he is a real gold daddy..', ref:'One afternoon, I went to the Xinhua Bookstore and asked my father to join me -- after all, he was the one who footed my bills.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_23', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我想买一套《还珠格格》小说，我爸递过来一套《成长的烦恼》。', mt:'I want to buy a set of \'Huan Zhu Ge Ge\' novels, but my dad handed me a set of \'Growing Pains\'.', ref:'I wanted to buy a set of novels called My Fair Princess , but my father handed me a set of Growing Pains .', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_24', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我很不高兴，我压根儿没烦恼，但金主爸爸坚持给我买了这套书——青春期性教育丛书—— 这是我过了好几天无聊翻阅后才发现的。', mt:'I am very unhappy. I have no worries at all, but my sugar daddy insisted on buying me this set of books - a series on adolescent sex education - which I only discovered after flipping through them for several days out of boredom.', ref:'I was very displeased. I had no “pains” at all, but my daddy insisted on buying me this set of books - - a series of sex education books for puberty -- which I discovered only after flipping through them casually several days later.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_25', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'从初中到高中，这套书我不知道翻了多少遍， 从生理到心理，答疑解惑。', mt:'From junior high school to high school, I don\'t know how many times I have flipped through this set of books, from physiology to psychology, answering questions and solving doubts.', ref:'From junior high school to high school, I don’t know how many times I perused this set of books. From physiology to psychology, they answered my questions and solved my doubts.', tags:["准确性"] },
  { k:'seg_6_决赛_26', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'20多年前，小城的新华书店以教辅为主，名著为辅，天知道我爸是怎么找到的。', mt:'More than 20 years ago, the Xinhua Bookstore in the small town mainly focused on teaching materials, supplemented by classics. God knows how my dad found it.', ref:'Over two decades ago, the Xinhua Bookstore in that small town sold mainly teaching guidebooks and occasionally literary masterpieces.God knows how my father found those books.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_27', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'来，我离家北上念大学，来到一个更大的花花世界，我爸就更操心了。', mt:'Later, when I went to college in the north and entered a bigger world, my dad became even more worried.', ref:'Later, I left home and went north for college in a bigger city. My father became more worried.', tags:["准确性","风格"] },
  { k:'seg_6_决赛_28', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'当年那个目送风筝远去的青年，其实内心是恋恋不舍的吧。', mt:'The young man who watched the kite fly away that year was actually reluctant to part with it.', ref:'The young man who once watched his kite soar into the distance back in the years must harbor a heart filled with reluctance.', tags:["准确性"] },
  { k:'seg_6_决赛_29', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'一个“江湖中人”，原来有颗如此细腻的心。', mt:'A "person in the arena", originally had such a delicate heart.', ref:'The “swordsman” actually had such a subtle sensibility.', tags:["准确性","术语"] },
  { k:'seg_6_决赛_30', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'最近，爸爸在老家宅基地建房，我作为小股东和全场学历最高者，拥有审美方向的最终决定权。', mt:'Recently, my father has been building a house on our ancestral land. As a minor shareholder and the most educated person present, I have the final say in matters of aesthetics.', ref:'Recently, my father built a house on his homestead land in the countryside. As a minor shareholder and the most learned person in the family, I had the final say on the aesthetic vision.', tags:["准确性","风格"] },
  { k:'seg_6_决赛_31', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'众所周知，农村自建房总是丑得各有千秋，我在千里之外，很担忧前方的爸爸被带跑偏。', mt:'As we all know, self-built houses in rural areas are always uniquely ugly. I am worried that my father ahead may have gone astray, even though he is thousands of miles away.', ref:'We all know how rural self-built houses tend to be unsightly in various ways. I was worried that my father would succumb to the influence of others from afar.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_32', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'让我惊讶的是，他再次显示出了惊人的细致度和宽容度，一切出奇顺利。', mt:'I was surprised that he once again showed amazing meticulousness and tolerance, and everything went surprisingly smoothly.', ref:'To my delight, he once again displayed remarkable meticulousness and open-mindedness, and everything went without a hitch.', tags:["准确性"] },
  { k:'seg_6_决赛_33', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我说喜欢大落地窗，他给我开了个2.4米高的大窗户；经过别人家的窗户，他觉得好看且经我批准后，就记录下布局、尺寸和比例，在几十种方案中反复比对挑选。', mt:'I said I like big floor-to-ceiling windows, and he opened a 2.4-meter-high window for me; when passing by someone else\'s window, he thought it looked good and, with my approval, recorded the layout, size, and proportion, and repeatedly compared and selected among dozens of options.', ref:'I said I fancied large floor-to-ceiling windows, and he made me a grand window that stood 2.4 meters tall! He spotted someone else’s window and liked it. After getting my approval, he noted down the layout, size and proportion, and repeatedly compared and chose among dozens of schemes.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_34', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我说要白墙黑瓦，他找了多种外墙漆供选择； 趁我回家时，全家去现场挑地砖和墙砖，我坚持要黯淡无光的柔光砖，称这是当下流行，且不要过门石要全屋通铺，他虽然没太明白这好看在哪里，但还是信了我……', mt:'I said I wanted white walls and black tiles, and he found many kinds of exterior paint to choose from. While I was away, the whole family went to the site to choose floor tiles and wall tiles. I insisted on using dim and light soft tiles, calling it a current trend, and I didn\'t want a threshold, I wanted the whole house to be paved. Although he didn\'t quite understand why it looked good, he still believed me...', ref:'I said I wanted white walls and black tiles, and he sourced a variety of exterior wall paints for me to pick from. When I returned home, the whole family went to hand-select floor tiles and wall tiles. I insisted on using matte tiles that were dull and dim, saying that this was the latest trend. And I didn’t want a threshold stone but wanted the whole house to be tiled uniformly. He didn’t quite grasp why this might look good, but he still trusted', tags:["准确性","风格"] },
  { k:'seg_6_决赛_35', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'还记得那只英武的小狗吗？', mt:'Do you remember that brave little dog?', ref:'me Didn’t I mention that my father had a brave little dog?', tags:["准确性"] },
  { k:'seg_6_决赛_36', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'它在今年清明节后不久以13岁高龄去世。', mt:'It passed away at the age of 13 shortly after this year\'s Qingming Festival.', ref:'It died at the age of 13 shortly after this year’s Qingming Festival.', tags:["准确性"] },
  { k:'seg_6_决赛_37', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'小狗的一切衣食住行，包括发型，曾经都是我爸一手打理，小狗也因此拥有全小区最时尚的尾巴。', mt:'All aspects of the dog\'s clothing, food, housing, and transportation, including hairstyle, were once taken care of by my father, and the dog therefore has the most fashionable tail in the entire community.', ref:'My father used to pamper it with everything from its outfits and meals to its shelter and transport. The dog also had the most fashionable tail in the neighborhood.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_38', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'小狗去世后，我爸开车载上它和它所有的玩具和零食，在一条小溪边的竹林里，安葬了它， 并用几块石头堆了一个小标记。', mt:'After the puppy died, my dad drove it with all its toys and snacks to a bamboo forest by a small stream, buried it, and piled a small marker with a few stones.', ref:'After the dog died, my father drove it along with all its playthings and treats. He buried it in a bamboo forest by a creek and piled up a small marker with a few stones.', tags:["准确性"] },
  { k:'seg_6_决赛_39', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'今年五一假期，我回家了，爸爸带我来到那条小溪边，去看望小狗。', mt:'During this year\'s May Day holiday, I went home and my father took me to visit the little dog by the creek.', ref:'This May Day holiday, I went home and my father took me to the creek to pay our respects.', tags:["准确性"] },
  { k:'seg_6_决赛_40', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'他从口袋里掏出了饼干和糖果，又在路边摘了一束白色的小野花。', mt:'He took out cookies and candies from his pocket, and also picked a bunch of white wildflowers on the roadside.', ref:'He pulled out some biscuits and candies from his pocket and picked a bunch of white wildflowers from the roadside.', tags:["准确性","语言规范"] },
  { k:'seg_6_决赛_41', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'那天下着江南最常见的蒙蒙细雨，头发已经花白但身材依旧保持良好的爸爸，在如雾一般的水汽中，突然让我看到了细嗅蔷薇的画面。', mt:'That day it was drizzling with the most common misty rain in the south of the Yangtze River. My dad, whose hair had turned white but still maintained a good figure, suddenly showed me a picture of sniffing roses in the misty water vapor.', ref:'It was a drizzly day with the typical rain of the south. My father, whose hair has turned gray but who still keeps a fit figure, stood in the hazy mist, which suddenly reminded me of the verse by Siegfried Sassoon: “In me the tiger sniffs the', tags:["准确性"] },
  { k:'seg_6_初赛_1', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Why Algorithms Can’t Save Us From Trolls And Hate Speech', mt:'为什么算法无法拯救我们免受恶意言论和仇恨言论', ref:'为何算法无法解决喷子和仇恨言论的问题？', tags:["准确性"] },
  { k:'seg_6_初赛_2', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'By making the Internet as weightless and as frictionless as possible, we made our lives easier.', mt:'通过尽可能使互联网无重量和无摩擦，我们使我们的生活更加轻松。', ref:'我们努力把互联网打造成一个尽可能没有重量、没有摩擦的虚拟空间，成就了轻松生活。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_3', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'But now, the whole world is suffering the consequences, says Jaron Lanier.', mt:'但现在，整个世界都在承受后果，贾伦·拉尼尔说。', ref:'但如今，全世界都在承受个中后果！——杰伦·拉尼尔（Jaron Lanier）', tags:["准确性","术语"] },
  { k:'seg_6_初赛_4', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'In the early days of the popularization of the Internet, there was a debate about whether to make online digital experiences seem either casual and weightless or serious with costs and consequences.', mt:'在互联网普及的早期，曾经有一场关于在线数字体验应该是轻松无压力还是严肃有成本和后果的辩论。', ref:'互联网普及之初，有这样一个争论：应该将上网冲浪打造成随意、虚无缥缈的样子，还是严肃、有代价和后果的样子？', tags:["准确性","语言规范"] },
  { k:'seg_6_初赛_5', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'And there ended up being a massive desire to create the illusion of weightlessness.', mt:'最终出现了一种巨大的渴望，希望创造失重的幻觉。', ref:'争论的结果是大家都强烈希望营造上网冲浪虚无缥缈的幻觉。', tags:["准确性"] },
  { k:'seg_6_初赛_6', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'In the service of weightlessness, Internet retailers would not pay the same sales taxes as brick-and- mortar ones.', mt:'在失重服务中，互联网零售商不需要支付与实体店相同的销售税。', ref:'因为互联网是虚无缥缈的，所以网络零售商无需支付跟实体店一样的销售税。', tags:["准确性"] },
  { k:'seg_6_初赛_7', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Cloud companies wouldn’t have the same responsibilities to monitor whether they were making money off copyright violations or forgeries.', mt:'云公司不必承担相同的责任来监测它们是否从侵犯版权或伪造中获利。', ref:'云服务公司不必担责监督互联网零售商是否通过侵权或伪造谋利。', tags:["准确性"] },
  { k:'seg_6_初赛_8', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Accountability was recast as a burden or a friction, and since it costs money, an affront to weightlessness.', mt:'问责被重新解释为负担或摩擦，因为它需要花费金钱，被视为对轻盈的侮辱。', ref:'问责制被重新定义为是一种负担或摩擦，而且由于会产生经济成本，所以更是对虚无缥缈的冒犯。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_9', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The Internet would be designed as minimally as possible, so that entrepreneurs could experiment.', mt:'互联网将被尽可能地设计得简单，以便企业家可以进行实验。', ref:'互联网的设计应当简之又简，这样企业家们大可放手一试。', tags:["准确性"] },
  { k:'seg_6_初赛_10', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It provided no hook for persistent personal identity, no way to conduct transactions and no way to know if anyone else was who they claimed', mt:'它没有提供持久个人身份的钩子，也没有进行交易的方式，也没有办法知道任何人是否是他们声称的人。', ref:'因而，在网络上，人们无需绑定永久个人身份，没有固定的交易方式，也没有办法验证网线那头的那个人自称的身份是不是真的。', tags:["准确性"] },
  { k:'seg_6_初赛_11', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'All of those necessary functions would have to be eventually fulfilled by private business like Facebook.', mt:'所有这些必要的功能最终都必须由像Facebook 这样的私营企业来实现。', ref:'所有这些必要的功能最终都必须由脸书这样的私营企业来实现。', tags:["准确性"] },
  { k:'seg_6_初赛_12', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The result was a mad rush to corral users at any cost, even at the cost of caution and quality.', mt:'结果是不惜一切代价赶集用户，甚至不惜谨慎和质量的代价。', ref:'这个结果引发了一场抢夺用户的疯狂竞赛，即使以牺牲谨慎和质量为代价也在所不惜。', tags:["准确性"] },
  { k:'seg_6_初赛_13', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'We ended up with an uncharted, ad hoc Internet.', mt:'我们最终得到了一个未知的、临时的互联网 。', ref:'最终，我们得到了一个没有规划、毫无秩序的互联网，', tags:["准确性","语言规范"] },
  { k:'seg_6_初赛_14', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'We made our lives easier at the time, but the whole world is paying a heavy price many years later.', mt:'当时我们让生活变得更容易了，但多年后整个世界正在付出沉重的代价。', ref:'也让自己的生活变得更加轻松和惬意。但多年之后，全世界都在为此付出沉重的代价。', tags:["准确性"] },
  { k:'seg_6_初赛_15', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'One of the consequences of the weightless Internet — first emerging in alt.usenet groups — was an explosion of cruel nonsense.', mt:'无重量互联网的一个后果——最初出现在 alt.usenet群组中——是残酷无情的胡言乱语的爆发。', ref:'虚无缥缈的互联网带来的后果之一是各种荒谬言论的大爆炸，这一现象最早出现在alt.usenet新闻组里 。', tags:["准确性","语言规范"] },
  { k:'seg_6_初赛_16', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Nothing could be earned other than attention, and no one had a stake in being civil.', mt:'除了关注之外，没有任何收益，也没有人有兴趣保持礼貌。', ref:'这些言论除了收获关注之外，不会为发言者带来任何其他东西，文明礼貌被置之脑后。', tags:["准确性"] },
  { k:'seg_6_初赛_17', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Today, one of the biggest problems for virtual reality is that the immediately obvious customer base willing to spend money is gamers, and gaming culture has been going through misogynist convulsions.', mt:'如今，虚拟现实面临的最大问题之一是，愿意花钱的显而易见的客户群体是游戏玩家， 而游戏文化一直在经历厌女症的动荡。', ref:'今天的虚拟现实面临的一个最大问题是，最直接的愿意氪金的用户群是游戏玩家，然而游戏文化却在遭受厌女症的冲击。', tags:["准确性","语言规范"] },
  { k:'seg_6_初赛_18', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'This phenomenon is known as Gamergate.', mt:'这种现象被称为Gamergate。', ref:'这种现象被称为“玩家门”。', tags:["准确性"] },
  { k:'seg_6_初赛_19', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Complaints about how women are portrayed in games are drowned out by blithering barrages of hate speech.', mt:'有关女性在游戏中的形象如何被描绘的抱怨被毫无意义的仇恨言论所淹没。', ref:'原本关于女性在游戏中的形象塑造的吐槽，被狂轰滥炸的仇恨言论淹没。', tags:["准确性"] },
  { k:'seg_6_初赛_20', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'When a feminist game design is promoted, the response is bomb threats and personal harassment.', mt:'当推广女权主义游戏设计时，会遭到炸弹威胁和个人骚扰的回应。', ref:'当游戏平台推广女权游戏设计时，得到的回应是炸弹威胁和人身骚扰。', tags:["准确性"] },
  { k:'seg_6_初赛_21', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Women who dare to participate in gaming culture take real risks, unless they can adopt a persona that puts men first.', mt:'敢于参与游戏文化的女性面临真正的风险， 除非她们能够采用一个以男性为先的角色。', ref:'敢于投身游戏文化的女性往往要直面真正的风险， 除非她们愿意戴着一张把男性放在第一位的假面。', tags:["准确性"] },
  { k:'seg_6_初赛_22', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Gamergate has left a trail of ruined lives.', mt:'Gamergate留下了一串毁了生命的痕迹。', ref:'“玩家门”毁掉了很多人的生活，', tags:["准确性"] },
  { k:'seg_6_初赛_23', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'And yet, needless to say, the perpetrators feel they are the victims.', mt:'然而，不用说，肇事者觉得自己是受害者。', ref:'然而，不用说，始作俑者反觉得自己才是受害者。', tags:["准确性"] },
  { k:'seg_6_初赛_24', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'For years, Gamergate was only a plague within digital culture, but by 2016 its legacy was influencing elections, particularly one in the US.', mt:'多年来，Gamergate 只是数字文化中的一种瘟疫，但到了 2016 年，它的遗产影响了选举， 特别是美国的选举。', ref:'“玩家门”在互联网圈子里泛滥数年后，2016年其余波开始影响选举，尤其是当年的美国大选。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_25', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Gamergate turned out to be a prototype, rehearsal and launching pad for the alt-right.', mt:'Gamergate最终成为了alt-right的原型、彩排和发射台。', ref:'“玩家门”俨然成为极右翼势力的原型机、预演场和发射台。', tags:["准确性"] },
  { k:'seg_6_初赛_26', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The kinds of problems that used to inflame only obscure reaches of Usenet now torment everyone.', mt:'曾经只在Usenet的偏远角落引起热议的问题现在困扰着每个人。', ref:'原本只在Usenet论坛上小范围争吵的各种话题变成全民唇枪舌剑的问题。', tags:["准确性"] },
  { k:'seg_6_初赛_27', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'For instance, everyone, including the president, is upset about “fake news.”', mt:'例如，包括总统在内的每个人都对“假新闻”感到不满。', ref:'例如，包括总统在内的每个人都被“假新闻”弄得心烦意乱。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_28', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Even the news of the term itself was quickly made fake; the term “fake news” was deliberately overused to the point that its meaning was reversed within only a few months of its appearance.', mt:'甚至术语本身的消息也很快被伪造了；“假新闻”这个术语被故意过度使用，以至于它的含义在出现几个月后就被颠倒了。', ref:'就连这个词本身的新闻也很快被恶搞。“假新闻”一词被大家过度玩梗，短短数月后，其含义就已发生一百八十度大转变，', tags:["准确性"] },
  { k:'seg_6_初赛_29', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It became the way a grumpy American administration referred to real news.', mt:'它成为一个脾气暴躁的美国政府所指称的真实新闻的方式。', ref:'成为气急败坏的美国政府嘴里真新闻的代名词。', tags:["准确性"] },
  { k:'seg_6_初赛_30', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Fortunately, more precise terms are available.', mt:'幸运的是，有更精确的术语可用。', ref:'不过还好有更准确的词可以描述这一现象。', tags:["准确性"] },
  { k:'seg_6_初赛_31', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'For example, it’s been reported that the founder of the virtual reality company purchased by a social media company for a couple of billion dollars called the planting of sadistic online confabulations engineered to go viral “s—tposting” and “meme magic.”', mt:'例如，据报道，被社交媒体公司收购的虚拟现实公司的创始人购买了一些工程化的令人沮丧的在线谈话，称之为“s—tposting”和“meme magic”，旨在走红。', ref:'比如，据报道，有一家虚拟现实公司以数十亿美元的价格被一家社交媒体公司收购，该虚拟现实公司的创始人把那些为实现疯狂传播目的而故意捏造的弥天大谎称之为“垃圾帖子”和“表情包”。', tags:["准确性"] },
  { k:'seg_6_初赛_32', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It was further reported that he spent serious lucre incentivizing the activity during the 2016 election.', mt:'据报道，他在2016年选举期间花费了大量的钱来激励这项活动。', ref:'据进一步报道，2016年大选期间该创始人正经花费了大量黑金来激励这些行为。', tags:["准确性"] },
  { k:'seg_6_初赛_33', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'S—tposting is clearly distinct from low-quality journalism or dumb opinion.', mt:'S—tposting 明显不同于低质量新闻或愚蠢的观点。', ref:'垃圾帖子与烂新闻或傻观点明显不同。', tags:["准确性"] },
  { k:'seg_6_初赛_34', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It’s one of those rare forms of speech that shuts down speech instead of increasing speech.', mt:'这是一种罕见的言语形式，它不是增加言语，而是关闭言语。', ref:'这是一种不常发生的语言形式，能让对方闭嘴而不是开口说话。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_35', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It’s like playing loud, annoying music in the cell of a captured enemy combatant until he breaks.', mt:'这就像在俘虏敌方战斗人员的牢房里播放大声、恼人的音乐，直到他崩溃为止。', ref:'就好像在被俘的敌方战斗人员的牢房里播放震耳欲聋的音乐，直到他崩溃。', tags:["准确性"] },
  { k:'seg_6_初赛_36', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It clogs conversations and minds so that both truth and considered opinion become irrelevant.', mt:'它阻塞了对话和思维，使得真相和深思熟虑的观点都变得无关紧要。', ref:'垃圾帖子堵塞了对话和思想，使得真相和经过深思熟虑的意见都变得无关紧要。', tags:["准确性"] },
  { k:'seg_6_初赛_37', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'There have been widespread calls — from across the political spectrum — for the tech companies to do something about the prevalence of this kind of speech.', mt:'政治光谱各方纷纷呼吁科技公司采取措施应对此类言论的普遍存在。', ref:'一直以来，整个政坛广泛有一种声音——呼吁科技公司对如此猖獗的此类言论采取行动。', tags:["准确性"] },
  { k:'seg_6_初赛_38', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Google acted first, and despite initial reluctance, Facebook followed.', mt:'谷歌先行动，尽管最初有些不情愿，Facebook 还是跟随了。', ref:'谷歌先行动了，脸书尽管一开始不愿意，但后来也照做了。', tags:["准确性"] },
  { k:'seg_6_初赛_39', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The companies now attempt to flag these posts, and they refuse to pay the sources.', mt:'现在公司试图标记这些帖子，并拒绝支付来源。', ref:'现在这些公司给这些帖子加标签，拒绝向发帖人支付费用。', tags:["准确性"] },
  { k:'seg_6_初赛_40', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It’s worth trying, but I wonder whether this approach addresses the core issues.', mt:'值得一试，但我想知道这种方法是否解决了核心问题。', ref:'这些方法值得一试，但我认为可能治标不治本。', tags:["准确性"] },
  { k:'seg_6_初赛_41', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Consider how odd it is that the whole society, not just in the US but globally, has to beg a few tightly controlled corporations to allow usable space for sincere news reporting.', mt:'考虑一下，整个社会，不仅仅是在美国，而是全球范围内，都必须乞求一些受严格控制的公司提供可用的空间进行真诚的新闻报道，这是多么奇怪的事情。', ref:'想想看，整个社会（不仅仅是美国，而是全世界）要乞求少数几家被严格控制的大公司，请他们为真诚的新闻报道留出一片净土。这有多荒诞！', tags:["准确性","语言规范"] },
  { k:'seg_6_初赛_42', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Isn’t there something strange, perilous and unsustainable about that, even if those corporations are enlightened and respond', mt:'即使这些公司现在很开明并做出积极回应， 但这种情况不是有些奇怪、危险和不可持续吗？', ref:'即使那些大公司暂时良心发现并做出积极响应，但这难道不显得有些奇怪、危险且不可持续吗？', tags:["准确性"] },
  { k:'seg_6_初赛_43', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Do we really want to privatize the gatekeeping of our public space for speech?', mt:'我们真的想要将我们公共言论空间的门户管理私有化吗？', ref:'我们真的希望将守护公共舆论空间这一职责交给私有企业吗？', tags:["准确性","风格"] },
  { k:'seg_6_初赛_44', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Even if we do, do we want to do so irrevocably?', mt:'即使我们这样做，我们是否想要这样不可撤销地做呢？', ref:'即便如此，我们想不可逆转地授予这些公司这样的权力吗？', tags:["准确性"] },
  { k:'seg_6_初赛_45', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Who knows who will be running Facebook when the founder is gone?', mt:'谁知道创始人离开后谁会管理Facebook？', ref:'谁知道创始人离开后，换谁来掌管脸书？', tags:["准确性"] },
  { k:'seg_6_初赛_46', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Do billions of users really have the ability to coordinate a move off a service like that in protest?', mt:'数十亿用户真的有能力协调抵制这样的服务吗？', ref:'数十亿的用户真的有能力团结一致，通过抗议撤销这样的服务吗？', tags:["准确性"] },
  { k:'seg_6_初赛_47', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'If not, what leverage is there?', mt:'如果没有，那么有什么杠杆作用呢？', ref:'如果不能，还有什么筹码？', tags:["准确性"] },
  { k:'seg_6_初赛_48', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Are we choosing a new kind of government by another name, but one that represents us less?', mt:'我们是在选择另一种代表我们更少的新政府吗？', ref:'我们是不是在选择一种新式政府——只是换了个名头，但其代表我们的程度却更低了？', tags:["准确性","风格"] },
  { k:'seg_6_初赛_49', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The attempts by the tech companies to battle s—tposting comprise a fascinating confrontation between the new order of algorithms and the old order of financial incentives.', mt:'科技公司试图打击低质内容构成了算法新秩序和旧的财务激励之间的一场迷人对抗。', ref:'科技公司打击“垃圾帖子”的努力可以看作是算法新秩序和经济激励旧秩序之间的一场精彩对决。', tags:["准确性"] },
  { k:'seg_6_初赛_50', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Old and new have a lot in common.', mt:'新旧有很多共同之处。', ref:'新旧两种秩序有诸多共同点。', tags:["准确性"] },
  { k:'seg_6_初赛_51', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The most enthralled proponents perceive each not merely as technologies invented by people but as superhuman living things.', mt:'最着迷的支持者不仅将每个技术视为人类发明的技术，而且将其视为超人类的生命体。', ref:'两边的铁杆拥趸不仅将它们视为人类发明的技术， 更把它们视为超越人类的生命。', tags:["准确性"] },
  { k:'seg_6_初赛_52', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'In the case of financial incentives, the elevation occurred in the 18th century, when Adam Smith celebrated the “invisible hand.”', mt:'在金融激励方面，提升发生在18世纪，当亚当·斯密赞扬“看不见的手”时。', ref:'在金钱激励这派，这种升华肇始于18世纪，彼时亚当·斯密对那只“看不见的手”赞誉有加。', tags:["准确性"] },
  { k:'seg_6_初赛_53', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'In the case of algorithms, something similar occurred in the late 1950s when the term “artificial intelligence” was coined.', mt:'在算法的情况下，类似的事情发生在20世纪 50年代末，当时创造了“人工智能”这个术语。', ref:'在算法这派，类似的事情发生在20世纪50年代后期，彼时“人工智能”一词横空问世。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_54', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The prevalence of s—tposting and other degradations is fueled by the invisible hand, while the antidote is thought to be divined by artificial intelligence.', mt:'s—tposting和其他降格的普及是由无形之手推动的，而解药被认为是由人工智能预测的。', ref:'看不见的手助长了垃圾帖子和其他堕落行为的泛滥，而人们认为问题的解药掌握在人工智能手里。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_55', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'So we are now witnessing a professional wrestling match between the old made-up god and the new one.', mt:'所以我们现在正在见证一场老虚构神和新虚构神之间的职业摔跤比赛。', ref:'因此我们现在正在见证一场旧造神与新造神之间的巅峰对决。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_56', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'But what if the new demigod cannot knock out the old demigod?', mt:'但是如果新的半神无法击败旧的半神呢？', ref:'但要是新的半神不能打倒旧的半神，怎么办呢？', tags:["准确性"] },
  { k:'seg_6_初赛_57', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Maybe social media companies need to change how they make money.', mt:'也许社交媒体公司需要改变赚钱方式。', ref:'也许社交媒体公司得改变盈利方式。', tags:["准确性"] },
  { k:'seg_6_初赛_58', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Maybe anything short of that is just a hopeless propping up of algorithms that will always be toppled by tides of financial incentives.', mt:'也许除此之外的任何事情都只是对算法的绝望支持，这些算法总是会被金融激励的浪潮所推翻。', ref:'如果做不到这一点，那就只是对算法的一种毫无希望的追捧，最终总会被经济激励的大潮所颠覆。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_59', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Just to be clear, I don’t think ethical algorithms or ethical filtering can work, given the current level of our scientific understanding.', mt:'只是为了明确，我认为在当前科学水平下， 道德算法或道德过滤无法实现。', ref:'首先声明，鉴于当前我们的科学认知水平，我不认为道德算法或道德过滤将会奏效。', tags:["准确性"] },
  { k:'seg_6_初赛_60', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Such fixes will just be gamed and turned into more manipulation, nonsense and corruption.', mt:'这样的修复只会被操纵和转化为更多的操纵 、无意义和腐败。', ref:'这样的解决方法只会被钻空子，导致更多的操纵、 瞎搞、腐败。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_61', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'If the way to protect people from AI is more AI, like supposed algorithms with ethics, then that amounts to saying that nothing will be done, because the very idea is the heart of nonsense.', mt:'如果保护人类免受人工智能侵害的方法是使用更多的人工智能，例如带有伦理道德的算法，那么这等于说什么都不会做，因为这个想法本身就是荒谬的核心。', ref:'如果保护人们不受人工智能影响的方法是引入更多的人工智能，比如将道德加入到算法中，那么这相当于摆明什么也没干，因为这个想法本身就是无稽之谈的核心，', tags:["准确性","语言规范"] },
  { k:'seg_6_初赛_62', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'It’s the fantasy of a fantasy.', mt:'这是一个幻想的幻想。', ref:'是幻想中的幻想。', tags:["准确性"] },
  { k:'seg_6_初赛_63', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'There’s no scientific description of an idea in a brain at this time, so there’s no way to even frame what it would be like to embed ethics into an algorithm.', mt:'目前还没有关于大脑中思想的科学描述，因此甚至无法构思将伦理道德嵌入算法的样子 。', ref:'目前人类还无法科学解释大脑中的思想，所以我们无从得知将道德嵌入到算法之中会是哪般模样。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_64', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'All algorithms can do now is compound what natural people do, as measured by our impressive global spying regime over the Internet.', mt:'现在所有的算法能做的就是将自然人所做的复合起来，就像我们通过互联网的全球监控体系所测量的那样。', ref:'算法现在所能做的只是放大人类所做的事情，典型例子就是互联网上已经发展到令人惊讶的全球间谍机制。', tags:["准确性"] },
  { k:'seg_6_初赛_65', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'But just for the sake of argument, suppose the tech companies’ attempts to fix s—tposting with so- called artificial intelligence turn out to be spectacularly successful.', mt:'但是仅仅为了论证，假设科技公司试图通过所谓的人工智能来修复s—tposting，结果非常成功。', ref:'不过让我们出于讨论目的，假设科技公司试图用所谓的人工智能来解决垃圾帖子的问题大获成功。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_66', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Suppose that the filtering algorithms are so excellent that everyone comes to trust them.', mt:'假设过滤算法非常出色，以至于每个人都信任它们。', ref:'假设过滤算法非常出色，赢得所有人的信任。', tags:["准确性"] },
  { k:'seg_6_初赛_67', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Even then, the underlying economic incentives would remain the same.', mt:'即使如此，潜在的经济激励仍将保持不变。', ref:'即便如此，最基本的经济刺激机制也仍然保持不变 。', tags:["准确性"] },
  { k:'seg_6_初赛_68', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The likely result would be that the next best way to drive cranky traffic would come to the fore, but the overall result would be similar.', mt:'可能的结果是，下一个最好的驱动暴躁交通的方法会浮出水面，但总体结果会类似。', ref:'那么可能的结果是，下一个制造挑拨情绪流量的最优方法将脱颖而出，但最后的结果都是殊途同归。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_69', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'As an example of a next-best source of crankiness, consider how Russian intelligence services have been identified by US intelligence as meddlers in the US elections.', mt:'作为下一个最好的不满情绪的例子，考虑俄罗斯情报机构被美国情报界确定为干预美国选举的干扰者。', ref:'这方面的一个典型例子就是俄罗斯情报机构，想一想他们是如何被美国情报机构认定为干预美国选举的幕后黑手。', tags:["准确性"] },
  { k:'seg_6_初赛_70', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The method was not just to shitpost but to “weaponize” WikiLeaks to selectively distribute information that harmed only one candidate.', mt:'这种方法不仅仅是为了发表无意义的帖子， 而是为了“武器化”维基解密，有选择性地发布只对一个候选人有害的信息。', ref:'除了发垃圾帖子，他们的方法还包括将维基解密“ 武器化”，有选择地传播只对一个候选人不利的信息。', tags:["准确性"] },
  { k:'seg_6_初赛_71', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Suppose the tech companies implement ethical filters to block malicious selective leaking.', mt:'假设科技公司实施道德过滤器来阻止恶意的选择性泄漏。', ref:'假设科技公司通过道德过滤算法来阻止恶意的选择性传播，', tags:["准确性"] },
  { k:'seg_6_初赛_72', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Next up might be the subconscious generation of paranoia toward someone or something, in order to lock in attention.', mt:'接下来可能是潜意识地对某人或某事产生偏执，以锁定注意力。', ref:'那么后果可能会是——为了留住关注而养蛊出一批无意识中对某些人或某些事产生偏执的人。', tags:["准确性"] },
  { k:'seg_6_初赛_73', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'If the companies implement filters to prevent that, there will always be some other method-in-', mt:'如果公司实施过滤器以防止这种情况，总会有其他等待的方法。', ref:'就算科技公司通过过滤算法来防止这种情况，还会有其他化解之策在暗处伺机而动。', tags:["准确性"] },
  { k:'seg_6_初赛_74', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'How much control of our society do we want to demand from algorithms?', mt:'我们想要从算法那里要求多少对我们社会的控制权？', ref:'我们想要求算法对社会实施多大的控制？', tags:["准确性"] },
  { k:'seg_6_初赛_75', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Where does it end?', mt:'它在哪里结束？', ref:'到哪里是个头？', tags:["准确性"] },
  { k:'seg_6_初赛_76', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'Remember, well before we urged the tech companies to do something about fake news, we had demanded they do something about hate speech and organized harassment.', mt:'记住，在我们敦促科技公司采取措施打击虚假新闻之前，我们已经要求他们采取措施打击仇恨言论和有组织的骚扰行为。', ref:'别忘了，在我们敦促科技公司整治假新闻之前，也曾经要求他们整治仇恨言论和有组织的骚扰行为。', tags:["准确性"] },
  { k:'seg_6_初赛_77', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'The companies started booting certain users, but did society become any more temperate as a result?', mt:'公司开始踢出某些用户，但社会是否因此变得更加温和了呢？', ref:'为此科技公司清除了一批用户，但社会因此而变得温和了吗？', tags:["准确性","风格"] },
  { k:'seg_6_初赛_78', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'At some point, even if moral automation can be implemented, it might still be necessary to appeal to the old demigod of economic incentives.', mt:'在某个时候，即使可以实现道德自动化，仍然可能需要呼吁经济激励的老半神。', ref:'即使将来有一天道德自动化成为现实，我们可能仍然需要求助于经济激励这尊旧的半神。', tags:["准确性"] },
  { k:'seg_6_初赛_79', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'There are alternatives to the current economics of social media.', mt:'当前社交媒体的经济模式有替代方案。', ref:'目前社交媒体的盈利方式是有其他模式可选的。', tags:["准确性"] },
  { k:'seg_6_初赛_80', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'For instance, people could get paid for their content over Facebook and pay for content from others, and Facebook could take a cut.', mt:'例如，人们可以通过Facebook获得他们的内容的报酬，并为其他人的内容付费，Facebook可以从中抽取一部分。', ref:'例如，用户在脸书上可以有偿发布内容，同时为他人发布的内容付费，而脸书则可以从中抽成。', tags:["准确性"] },
  { k:'seg_6_初赛_81', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'We know that might work because something like it was tried in experiments like Second Life.', mt:'我们知道这可能有效，因为像Second Life这样的实验已经尝试过类似的事情。', ref:'我们知道这种模式可能行得通，是因为《第二人生 》游戏平台就曾做过类似的尝试。', tags:["准确性"] },
  { k:'seg_6_初赛_82', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'There are undoubtedly other solutions to consider as well.', mt:'毫无疑问，还有其他解决方案需要考虑。', ref:'当然除此之外还有其他可能的解决方法。', tags:["准确性","风格"] },
  { k:'seg_6_初赛_83', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'I advocate an empirical approach.', mt:'我主张采用经验主义方法。', ref:'我主张通过试验来找方法。', tags:["准确性"] },
  { k:'seg_6_初赛_84', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'We should be brave about trying out solutions, such as paying people for their data, but also brave about accepting results, even if they are disappointing.', mt:'我们应该勇于尝试解决方案，例如支付人们的数据，但也应该勇于接受结果，即使它们令人失望。', ref:'我们应该勇敢尝试各种解决方法，比如为他人的数据付费，但同时也要勇于接受其结果，即使这些结果令我们大失所望。', tags:["准确性"] },
  { k:'seg_6_初赛_85', ed:'6', stage:'初赛', dir:'英译汉', eng:'GPT-3.5-turbo', src:'We must not give up.', mt:'我们不能放弃。', ref:'我们绝不能放弃。', tags:["准确性"] },
  { k:'seg_7_决赛_1', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园', mt:'He Garden', ref:'Heyuan Garden', tags:["准确性"] },
  { k:'seg_7_决赛_2', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园作为一处有意设计的景观，有其明确的立意、构思、 布局，虽历经百余年的沧桑变化，其整体特征至今仍清晰可辨，将其置于中国古典园林体系中审视，仍独具特色。', mt:'As a deliberately designed landscape, He Garden has its clear intentions, concepts, and layout. Despite over a century of changes, its overall characteristics are still clearly discernible. When viewed within the context of the Chinese classical garden system, it remains unique.', ref:'As a designed landscape, Heyuan Garden has its clear concept, design and layout. Although it has been subject to more than one hundred years of change, its overall characteristics are still clearly identifiable. The character of Heyuan Garden demonstrates many innovations in the craft of landscape gardening.', tags:["准确性"] },
  { k:'seg_7_决赛_3', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'由于地处中国南方和北方之间，扬州的园林风格融合了北方园林与江南私家园林的特征，展现出独特的面貌。', mt:'Due to its location between southern and northern China, the garden style of Yangzhou combines the characteristics of northern gardens and private gardens in the Jiangnan region, showcasing a unique appearance.', ref:'Due to its location between southern and northern China, Yangzhou\'s garden style combines the characteristics of northern gardens and private gardens in the Jiangnan area, showing a unique look.', tags:["准确性"] },
  { k:'seg_7_决赛_4', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'著名园林专家陈从周先生指出：“扬州园林综合了南北的特色，自成一格，雄伟中寓明秀，得雅健之致。”', mt:'The famous garden expert Mr. Chen Congzhou pointed out: "The gardens of Yangzhou combine the characteristics of both the north and the south, forming their own unique style. They are majestic yet elegant, achieving a refined and vigorous charm."', ref:'The famous garden expert Chen Congzhou pointed out: "The gardens of Yangzhou combine the characteristics of both the North and the South, forming a unique style of their own. They entail dainty gracefulness in magnificent bodies—or, in literary jargon, write subtle heartthrobs with a robust brush."', tags:["准确性"] },
  { k:'seg_7_决赛_5', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'扬州园林多与住宅很好地结合，大多园林中部建造水池， 水池旁边堆叠假山，厅堂位于水池边的重要位置，周围点缀亭台楼阁等建筑，并以花墙山石、树木花卉形成园林之间的间隔，创造具有层次变化的景色。 清代中叶，扬州园林的主人大多为富商，园林不仅是他们居住的场所，更是展示富有、追求风雅的社交空间，因此在风格、材料和工艺上极为注重奢华，建筑高敞华丽，花木品类丰富，室内外装修精致，叠石筑山的造诣尤其突出 。', mt:'The gardens of Yangzhou are often well integrated with residences, with most gardens featuring a pond in the center. Beside the pond, rockeries are stacked, and halls are located in important positions by the pond. The surroundings are adorned with pavilions, towers, and other buildings, with flower walls, rocks, trees, and flowers creating intervals between the gardens, thus creating scenery with layered variations. In the mid-Qing Dynasty, most of the owners of the gardens in Yangzhou were wealthy merchants. The gardens were not only their residences but also social spaces to showcase their wealth and pursuit of elegance. Therefore, great attention was paid to luxury in terms of style, materials, and craftsmanship. The buildings were tall and magnificent, the variety of flowers and plants was abundant, the interior and exterior decorations were exquisite, and the skill in rockery construction was particularly outstanding.', ref:'Yangzhou gardens are well integrated with residential buildings. Most of the large gardens in Yangzhou feature a pond in the centre with rockwork around it while pavilions become architectural centrepieces. The relationship between ponds and pavilions must be carefully choreographed. The scenery in large gardens is segmented with walls, rockwork and plants to conjure up multi-layered and variegated views. Exotic rocks are erected by the pond, pavilions and belvederes are scattered but ultimately connected by a circuitous walkway. In the mid-Qing Dynasty, most of the owners of Yangzhou gardens were wealthy merchants. The gardens were not only their living spaces but also social venues to showcase their wealth and pursuit of elegance. As a result, great emphasis was placed on luxury in style, materials, craftsmanship. The architecture was grand and ornate, the variety of plants and flowers was abundant, the interior and exterior decorations were exquisite, and the art of rock stacking and mountain building was particularly remarkable.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_6', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'清代中叶，扬州园林的主人大多为富商，园林不仅是他们居住的场所，更是展示富有、追求风雅的社交空间，因此在风格、材料和工艺上极为注重奢华，建筑高敞华丽，花木品类丰富，室内外装修精致，叠石筑山的造诣尤其突出 。', mt:'In the mid-Qing Dynasty, most of the owners of the gardens in Yangzhou were wealthy merchants. The gardens were not only their residences but also social spaces to showcase their wealth and pursuit of elegance. Therefore, great attention was paid to luxury in terms of style, materials, and craftsmanship. The buildings were tall and magnificent, the variety of flowers and plants was abundant, the interior and exterior decorations were exquisite, and the skill in rockery construction', ref:'In the mid-Qing Dynasty, most of the owners of Yangzhou gardens were wealthy merchants. The gardens were not only their living spaces but also social venues to showcase their wealth and pursuit of elegance. As a result, great emphasis was placed on luxury in style, materials, craftsmanship. The architecture was grand and ornate, the variety of plants and flowers was abundant, the interior and exterior decorations were exquisite, and the art of rock stacking and mountain building was', tags:["准确性","风格"] },
  { k:'seg_7_决赛_7', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'清代乾隆年间成书的《扬州画舫录》就有“扬州以名园胜，名园以叠石胜”的评价。', mt:'The "Yangzhou Huafang Lu," written during the Qianlong period of the Qing Dynasty, contains the evaluation "Yangzhou is renowned for its famous gardens, and the famous gardens are renowned for their rockeries."', ref:'Yangzhou Huafang Lu (The record of the painted pleasure boats of Yangzhou) written during the Qianlong reign of the Qing Dynasty, records that, "Yangzhou is renowned for its famous gardens, and these gardens are celebrated for their rock formations."', tags:["准确性","语言规范"] },
  { k:'seg_7_决赛_8', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'此外，清代的扬州是中国对外贸易的主要商业城市之一， 商业上的交往使得许多西方园林、建筑的做法传入并被吸收到扬州园林之中，形成了私家园林中西合璧的独特风貌 。', mt:'In addition, during the Qing Dynasty, Yangzhou was one of the main commercial cities for foreign trade in China. The commercial interactions led to the introduction and incorporation of many Western garden and architectural practices into Yangzhou gardens, creating a unique blend of Chinese and Western styles in private gardens.', ref:'In addition, during the Qing Dynasty, Yangzhou was one of China\'s major commercial cities for foreign trade. This commercial interaction led to the introduction and assimilation of many Western gardening and architectural practices into the gardens of Yangzhou, resulting in a unique blend of Eastern and Western styles in private gardens.', tags:["准确性"] },
  { k:'seg_7_决赛_9', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园作为一处晚清扬州私家住宅园林，具有以下突出特征 。', mt:'He Garden, as a private residential garden in late Qing Dynasty Yangzhou, has the following prominent features.', ref:'Heyuan Garden, as a private residential garden in the late Qing Dynasty Yangzhou, possesses the following prominent characteristics.', tags:["准确性"] },
  { k:'seg_7_决赛_10', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'寄情山水，以小寓', mt:'Finding solace in nature, expressing the grand through the small.', ref:'Idealised miniature landscape and showing the large in the small', tags:["准确性","语言规范"] },
  { k:'seg_7_决赛_11', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'营造园林意境是中国古典园林审美的最高标准，园林中的山池花木、亭台楼阁，每一处景物都需要传达造园者的情感和精神追求。', mt:'Creating a garden atmosphere is the highest standard of aesthetics in Chinese classical gardens. Every scene in the garden, including mountains, ponds, flowers, trees, pavilions, and towers, needs to convey the emotions and spiritual pursuits of the garden\'s creator.', ref:'To create an artistic conception is the highest standard of Chinese classical garden aesthetics. The artificial mountains, ponds, plants, and buildings need to convey the emotional and spiritual interests of the garden owners.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_12', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园的整体构思和园林营建充分体现了中国古典园林的这一特性，园林意境突出、景观象征性丰富。', mt:'The overall design and construction of He Garden fully embody this characteristic of Chinese classical gardens, with a prominent artistic conception and rich symbolic landscapes.', ref:'In this way Chinese gardens are idealised miniature (natural) landscapes. The overall concept and construction of Heyuan Garden fully embodies this characteristic of Chinese classical gardens, with outstanding artistic conception and rich symbolic landscapes.', tags:["准确性","术语"] },
  { k:'seg_7_决赛_13', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'园主何维键在任时目睹清朝衰败屈从外强，辞官卸任后建造园林以寄情山水，并将其命名为“寄啸山庄”以表达对清廷朝政的不满。', mt:'When the garden owner He Weijian witnessed the decline of the Qing Dynasty and its submission to foreign powers, he resigned from his official position and built a garden to find solace in nature. He named it "Jixiao Villa" to express his dissatisfaction with the Qing court\'s governance.', ref:'When He Weijian was in office, he witnessed the decline of the Qing government and its submission to foreign powers. After resigning, he built a garden as a retreat, and named it Whistling Scholar\'s Mountain Retreat to express his dissatisfaction with the government.', tags:["准确性"] },
  { k:'seg_7_决赛_14', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'所谓“山庄”，即是一座以古代“海上仙山”传说为蓝本营建的园林。', mt:'The so-called "mountain villa" is a garden built based on the ancient legend of the "immortal mountains on the sea."', ref:'The so-called "mountain retreat" is a garden built according to the Chinese ancient legend of "sacred mountains in the sea".', tags:["准确性","语言规范"] },
  { k:'seg_7_决赛_15', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园的主花园利用水池象征茫茫大海，池西堆筑湖石假山象征海上仙山，假山突出水岸，山上种植两株高大挺拔的白皮松，增加了神山的意境。', mt:'The main garden of He Garden uses a pond to symbolize the vast ocean. To the west of the pond, a rockery made of lake stones symbolizes the fairy mountain in the sea. The rockery protrudes from the water\'s edge, and two tall and straight white pines are planted on the mountain, enhancing the mystical atmosphere of the mountain.', ref:'The main garden uses the pond to symbolize the sea. The artificial mountain in the west of the pond symbolises the sacred mountains in the sea. The artificial mountain stands out from the waterfront, with two tall white bark pines planted on the mountain, enhancing the atmosphere of the "sacred mountains".', tags:["准确性","风格"] },
  { k:'seg_7_决赛_16', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'水池中心建造方亭，被称为“小方壶”，具有海上神山仙阁的寓意。', mt:'A square pavilion was built in the center of the pool, called "Little Fanghu," symbolizing a fairy pavilion on a mythical mountain in the sea.', ref:'A square pavilion stands in the east of the pond. lt is called "Xiao Fanghu" (the small square pot, and "Fanghu" is said to be the name of a sacred mountain, one of the three sacred mountains of the Bohai Sea in Chinese mythology) in Chinese traditional garden, symbolising the dwelling place for immortals.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_17', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园东北部还利用“旱园水作”的手法，即利用卵石的纹理变化铺装园林地面，形成“无水但有水意”的景观，地面上有四面通透的建筑，营造船浮于海的意象，与整个园林海上仙山的境界融为一体。', mt:'The northeastern part of He Garden also uses the technique of "dry garden with water effects," which utilizes the texture changes of pebbles to decorate the garden ground, creating a landscape that is "without water but with the sense of water." There are buildings with open views on all sides on the ground, creating the imagery of a boat floating on the sea, blending seamlessly with the entire garden\'s realm of an immortal mountain on the sea.', ref:'In addition, the northeastern part of Heyuan Garden uses the method of "hanyuan shuizuo" (a water-less garden is made to look like water-bound), which uses pavement texture changes to form an imagination of watery landscape with little or no water. A hall with windows on four sides sits in the court. With the ground at the foot of the hall\'s stairway paved with a mixture of pebbles, broken bricks and tiles in patterns, it aims to create the appearance of a ship floating on the sea.', tags:["准确性","风格","语言规范"] },
  { k:'seg_7_决赛_18', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'此外，在整个何园中，利用花窗泄景、半壁亭台、贴墙作山、环阁凿池等手法，都是希望创造以小寓大，在有限中创造无限的景观效果。', mt:'In addition, throughout He Garden, techniques such as using flower windows to reveal scenery, half-wall pavilions, building mountains against walls, and digging pools around pavilions are all aimed at creating a grand effect in a small space, creating infinite scenery within limited confines.', ref:'In addition, Heyuan Garden also uses "borrowed- view" lattice windows, half-wall pavilions, wall- mounting mountains, ring-shaped chiseled pools, to create unlimited landscape effects in limited spaces.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_19', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'院落重重，以园环居何园是一处典型的中国古典住宅园林，园林坐北朝南面积约为1.15万平方米，其中建筑面积约为6000平方米，具有清代中后期私家园林建筑密度较高的特征。', mt:'Courtyards upon courtyards, surrounded by gardens. Heyuan is a typical Chinese classical residential garden. The garden faces south and covers an area of approximately 11,500 square meters, with a building area of about 6,000 square meters, characterized by the high density of private garden buildings from the mid to late Qing Dynasty.', ref:'Full of courtyards, gardens surrounding residential spaces Heyuan Garden is a typical Chinese classical residential garden. The garden faces south and covers an area of about 11,500 square metres, including a construction area of about 6,000 square metres. The high density of buildings is a feature of the private gardens in the middle and late Qing dynasty.', tags:["准确性","语言规范"] },
  { k:'seg_7_决赛_20', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园是一处典型的中国古典住宅园林，园林坐北朝南面积约为1.15万平方米，其中建筑面积约为6000平方米，具有清代中后期私家园林建筑密度较高的特征。', mt:'Heyuan is a typical Chinese classical residential garden. The garden faces south and covers an area of approximately 11,500 square meters, with a building area of about 6,000 square meters, characterized by the high density of private garden buildings from the mid to late Qing Dynasty.', ref:'residential garden. The garden faces south and covers an area of about 11,500 square metres, including a construction area of about 6,000 square metres. The high density of buildings is a feature of the private gardens in the middle and late Qing dynasty. The external space of Heyuan Garden is mainly', tags:["准确性"] },
  { k:'seg_7_决赛_21', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园主要通过院落来组织空间，利用围墙将园林划分成十余个大小不同的庭院，再通过门洞、长廊、花窗等串连交通和引导视线，借助池山、植物创造景观层次，减弱建筑带来的限定感，营造无限的自然境界。', mt:'Heyuan mainly organizes space through courtyards, using walls to divide the garden into more than ten courtyards of different sizes. It then connects and guides the view through doorways, long corridors, and flower windows, creating landscape layers with ponds, hills, and plants to reduce the sense of limitation brought by buildings and create an infinite natural realm.', ref:'The external space of Heyuan Garden is mainly made up of courtyards. More than ten courtyards of different sizes are created via using walls. Circulation is facilitated through doorways, long covered walkways, lattice windows and other elements to guide the line of sight. Ponds, rockeries and plants are used to soften the sense of enclosure established by the architecture and to create an infinite natural real.', tags:["准确性"] },
  { k:'seg_7_决赛_22', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'整个园林以园居院落为中心，北部布置东、西两座花园， 西南有赏月楼小花园，东南有片石山房花园，形成了居住空间居中、山水游赏空间环绕的整体格局。', mt:'The entire garden is centered around a residential courtyard, with two gardens arranged to the north, one to the east and one to the west. In the southwest, there is a small garden with a moon- viewing pavilion, and in the southeast, there is a garden with a rockery. This creates an overall layout where the living space is in the center, surrounded by scenic areas for enjoying the landscape.', ref:'The residential area is in the centre of the complex, with East and West gardens arranged in the north, Shangyue Building (Moon-Viewing Building) yard in the southwest, and the Small-Rock Mountain Retreat garden in the southeast. This forms the overall pattern of living spaces surrounded by gardens.', tags:["准确性","术语"] },
  { k:'seg_7_决赛_23', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'这极大丰富了住宅园林的景观变化，不但继承了中国传统住宅园林“前宅后园”或“宅旁设园”的基本传统，又具有独特性和创造性。', mt:'This greatly enriched the landscape variation of residential gardens, not only inheriting the basic tradition of Chinese traditional residential gardens with "front residence and back garden" or "garden beside the residence," but also possessing uniqueness and creativity.', ref:'The layout positively enriches the landscape experience of the living spaces. Heyuan Garden not only inherits the basic principles of traditional Chinese residential gardens, such as "front-house- back-garden" or "garden-beside-house" but also has its own unique and creative qualities.', tags:["准确性","语言规范"] },
  { k:'seg_7_决赛_24', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'立体交通，居游两宜', mt:'Three-dimensional transportation, suitable for both living and traveling', ref:'The three-dimensional walking system providing spaces for both living and sightseeing', tags:["准确性"] },
  { k:'seg_7_决赛_25', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园在处理居与游的关系方面具有独到之处，除了“以园环居”的布局特征之外，另一创造便是全园的立体交通。', mt:'Heyuan Garden has unique features in handling the relationship between residence and leisure. In addition to the layout characteristic of "surrounding the residence with the garden," another innovation is the three-dimensional transportation throughout the entire garden.', ref:'Heyuan Garden is unique in dealing with the relationship between residence and recreation. In addition to the "residential-area-surrounded-by- gardens" layout, another creative aspect is the three-dimensional walking system—the Double- Level Covered Walkway.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_26', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园在建造之初就设计了复道回廊，解决了园林内部相互联络的问题，串连了园林的主体建筑和花园，同时提供了半室外的遮风避雨的空间，满足居住者在园内的日常行走需要。', mt:'At the time of its construction, He Garden was designed with a double-decked corridor, solving the problem of internal communication within the garden. It connected the main buildings and the garden, while also providing a semi-outdoor space for shelter from wind and rain, meeting the daily walking needs of the residents within the garden.', ref:'When Heyuan Garden was built, the owner designed a double-floored covered walkway to solve the problem of interconnecting different sections. The main buildings and yards were connected via the walkway. The walkway provides a semi-outdoor sheltered space for the residents during their daily movement around the complex.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_27', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'复道回廊不仅平面上曲折迂回，立面上也高低错落，创造了重要的观景线路和视角，形成了独特的景观体验，行走在回廊里仿佛置身中国卷轴画中，景观画面依次展开，引人入胜。', mt:'The covered walkways and corridors not only twist and turn on the horizontal plane but also vary in height on the vertical plane, creating important viewing routes and perspectives. This forms a unique landscape experience, making one feel as if they are walking within a Chinese scroll painting, with the scenic views unfolding one after another, captivating the viewer.', ref:'The walkway not only follows a complex route in plan, but changes in height. The complex spatial arrangement creates varied view lines and perspectives, creating a unique landscape experience. Walking along these pathways, the visitor seems to be in a Chinese scroll painting, with fascinating landscape images unfolding before them.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_28', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'复道回廊本身也是重要的景观界面，西园中的回廊高两层，环抱水池，加以栏杆、花窗的多样变化，营造了精致典雅的园林立面。', mt:'The covered walkways and corridors themselves are also important landscape interfaces. The corridors in the western garden are two stories high, surrounding the pool, with various changes in railings and flower windows, creating an exquisite and elegant garden facade.', ref:'The Double-Level Walkway itself also forms an important landscape interface. The cloister in the West Garden is two storeys high, encircling the pond, with varied railings and lattice windows creating a refined and elegant garden facade.', tags:["准确性","语言规范"] },
  { k:'seg_7_决赛_29', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'长廊是中国传统园林中的重要元素，而何园在继承传统的同时又有所创新，以复道回廊为核心的立体交通系统在中国传统私家园林中别具一格，是江南园林中的孤例。', mt:'The long corridor is an important element in traditional Chinese gardens, and He Garden, while inheriting tradition, also innovates. Its three- dimensional transportation system, centered on the double-decked corridor, is unique among traditional private gardens in China and stands as a singular example in Jiangnan gardens.', ref:'The covered walkway is an important element in Chinese traditional gardens. Heyuan Garden inherits this tradition while at the same time innovating. The three-dimensional walking system centred on the Double-Level Walkway is unique in traditional Chinese private gardens and is a unique example in Jiangnan gardens.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_30', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'中西合璧，以人为本', mt:'East meets West, people-oriented', ref:'The combination of Chinese and Western styles for a people-oriented design', tags:["准确性"] },
  { k:'seg_7_决赛_31', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'晚清时期，随着中西方文化交流的增多，扬州的园林建筑也受到西方影响。 何园主人何维键曾在海关任职并有与洋人共事的经历，因此他在建造何园的时候引入了许多西洋元素，将其与中国传统园林的形制相互融合，更好地满足居住和游赏的需求 。', mt:'During the late Qing Dynasty, with the increase in cultural exchanges between China and the West, the garden architecture in Yangzhou was also influenced by the West. The owner of He Garden, He Weijian, once worked at customs and had experience working with foreigners. Therefore, when he built He Garden, he introduced many Western elements and integrated them with the traditional Chinese garden style to better meet the needs of living and sightseeing.', ref:'In the late Qing dynasty, with the increase of cultural exchange between China and Western countries, Yangzhou gardens were also influenced by the West. When building Heyuan Garden, He Jianwei, who had once worked in customs, dealing with foreigners, introduced many Western elements, integrating them with the qualities of traditional Chinese gardens to better satisfy living and recreation demands.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_32', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园主人何维键曾在海关任职并有与洋人共事的经历，因此他在建造何园的时候引入了许多西洋元素，将其与中国传统园林的形制相互融合，更好地满足居住和游赏的需求 。', mt:'The owner of He Garden, He Weijian, once worked at customs and had experience working with foreigners. Therefore, when he built He Garden, he introduced many Western elements and integrated them with the traditional Chinese garden style to better meet the needs of living and sightseeing.', ref:'When building Heyuan Garden, He Jianwei, who had once worked in customs, dealing with foreigners, introduced many Western elements, integrating them with the qualities of traditional Chinese gardens to better satisfy living and recreation demands.', tags:["准确性","风格"] },
  { k:'seg_7_决赛_33', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'这些西洋元素主要体现在西洋楼、煦春堂等建筑上，比如利用百叶窗、壁炉、地下通风穴道等西式元素优化西洋楼的建筑功能，在煦春堂引入玻璃、金属栏杆等新材料作为园林的装饰，形成了新的建筑美学特征。', mt:'These Western elements are mainly reflected in buildings such as the Western-style buildings and Xuchun Hall. For example, Western elements like shutters, fireplaces, and underground ventilation tunnels are used to optimize the functionality of the Western-style buildings. In Xuchun Hall, new materials such as glass and metal railings are introduced as garden decorations, forming new architectural aesthetic features.', ref:'These Western elements were mainly embodied in the buildings. For example, the use of Western-style elements such as blinds, fireplaces, and underground ventilation spaces improved the function of the Western-Style Building. New materials such as glass and metal railings were also introduced to Xuchun Hall (Cosy-Spring Hall) as decorations, which created a new building aesthetic.', tags:["准确性","风格","术语"] },
  { k:'seg_7_决赛_34', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'这些元素虽然与中国传统园林的审美有所不同，但无疑是清代晚期西方风格影响下中国古典园林风格的真实写照， 从园林发展历史的角度看来，何园是一个十分珍贵的样本 。', mt:'Although these elements differ from the aesthetics of traditional Chinese gardens, they undoubtedly reflect the true style of classical Chinese gardens under the influence of Western styles in the late Qing Dynasty. From the perspective of garden development history, He Garden is a very precious example.', ref:'These characteristics may differ from traditional aesthetic standards of Chinese garden design, but, undoubtedly, this approach accurately reflected Chinese classical garden style as influenced by the West in the late Qing dynasty. From the perspective of garden development history, Heyuan Garden is a very precious example.', tags:["准确性","风格"] },
  { k:'seg_7_初赛_1', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'What Does It Really Mean to Learn?', mt:'真正的学习意味着什么？', ref:'学习究竟意味着什么？', tags:["准确性"] },
  { k:'seg_7_初赛_2', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I read “Middlemarch” for the first time during my sophomore year of college.', mt:'我在大学二年级时第一次读了《米德尔马契》。', ref:'在我大二的那一年，我第一次读了《米德尔马契》。', tags:["准确性"] },
  { k:'seg_7_初赛_3', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I didn’t get it.', mt:'我没明白。', ref:'但我没读懂。', tags:["准确性"] },
  { k:'seg_7_初赛_4', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Why would Dorothea, a young and intelligent woman, marry that annoying old man?', mt:'为什么多萝西娅，一个年轻聪明的女人，会嫁给那个讨厌的老头？', ref:'为什么多萝西娅又年轻又聪明，却偏要嫁给那个烦人的老头？', tags:["准确性"] },
  { k:'seg_7_初赛_5', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'How could she be so stupid?', mt:'她怎么会这么愚蠢？', ref:'她怎么可以犯傻到如此地步？', tags:["准确性"] },
  { k:'seg_7_初赛_6', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'No one else in the class seemed to get it, either, and this pushed our professor over the edge.', mt:'班上没有其他人似乎明白，这让我们的教授崩溃了。', ref:'全班同学似乎也都不明所以，这几乎令我们的教授抓狂。', tags:["准确性"] },
  { k:'seg_7_初赛_7', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“Of course you don’t understand,” he roared, swilling a Diet Coke.', mt:'“你当然不明白，”他咆哮着，喝了一口健怡可乐。', ref:'你们现在当然看不懂，”他大声嚷道，灌了一口无糖可乐 。', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_8', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“Trust me, you’ll read this book again when you’re forty, after your first divorce, and you’ll say, ‘Oh, I see!’ ”', mt:'“相信我，当你四十岁，经历了第一次离婚后再读这本书时，你会说，‘哦，我明白了！’”', ref:'“相信我，等你40岁的时候，离了第一次婚，再把这本书读一遍，你会说，‘哦，我明白了！’”', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_9', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Arguably, it’s one of the tragedies of humanities education that so much of it occurs between the ages of eighteen and twenty-two.', mt:'可以说，人文学科教育的悲剧之一在于它的大部分发生在十八到二十二岁之间。', ref:'绝大部分的人文教育发生在18至22岁的年龄区间，这可以说是人文教育的悲哀之一。', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_10', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We don’t teach people to drive at twelve, when they’re carless; why should we make them read novels about life’s regrets when they have none?', mt:'我们不会在十二岁时教人开车，因为他们没有车；为什么我们要让他们读关于人生遗憾的小说，而他们却没有遗憾？', ref:'如果说我们不教12岁的孩童如何驾驶，是因为他们还没车，那为何我们要在人们还未有人生遗憾之时，让他们通过阅读小说体味人生的遗憾？', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_11', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Yet there’s a theory behind the assignment of “Middlemarch” to sophomores: it’s that knowledge acquired too early gets stored away.', mt:'然而，将《米德尔马契》分配给二年级学生背后有一个理论：那就是过早获得的知识会被储存起来。', ref:'虽然如此，给大二学生布置《米德尔马契》的阅读任务自有其背后的逻辑：早年所获的知识会储藏在那里，以备不时之需。', tags:["准确性","风格"] },
  { k:'seg_7_初赛_12', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Patterns of thinking established now will be retraced later; ideas encountered first in art will prime us for the rest of life.', mt:'现在建立的思维模式将会在以后重现；首先在艺术中遇到的想法将为我们的一生做好准备。', ref:'思维方式一旦建立便可供循环利用；在人文艺术中汲取的养料可滋养我们的余生。', tags:["准确性"] },
  { k:'seg_7_初赛_13', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'This sounds chancy and vague, until you reflect on the fact that knowledge almost never arrives at the moment of its application. You take a class in law school today only to argue a complicated case years later; you learn C.P.R. years before saving a drowning man; you read online about how to deter a charging bear, because you never know.', mt:'这听起来不确定且模糊，直到你反思知识几乎从不会在应用的那一刻到来。 你今天在法学院上课只是为了几年后辩论一个复杂的案件；你在多年之前学习心肺复苏术是为了在未来拯救一个溺水的人；你在网上阅读如何阻止一只冲过来的熊，因为你永远不知道什么时候会用到。', ref:'乍听之下，这一观点不免投机和模糊，但倘若你发现了知识不会在其应用之时突然涌现的真相，你的想法就会改变 。 你现在在法律系学习的课程，要在数年后当你为一个复杂的案子辩护时才有用武之地；你所学的心肺复苏术，要在数年后搭救溺水者时才能派上用场；你上网学习如何阻止一只爆冲的熊，因为你无从知晓哪天是否会用到。', tags:["准确性"] },
  { k:'seg_7_初赛_14', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'You take a class in law school today only to argue a complicated case years later; you learn C.P.R. years before saving a drowning man; you read online about how to deter a charging bear, because you never know.', mt:'你今天在法学院上课只是为了几年后辩论一个复杂的案件；你在多年之前学习心肺复苏术是为了在未来拯救一个溺水的人；你在网上阅读如何阻止一只冲过来的熊，因为你永远不知道什么时候会用到。', ref:'你现在在法律系学习的课程，要在数年后当你为一个复杂的案子辩护时才有用武之地；你所学的心肺复苏术，要在数年后搭救溺水者时才能派上用场；你上网学习如何阻止一只爆冲的熊，因为你无从知晓哪天是否会用到。', tags:["准确性"] },
  { k:'seg_7_初赛_15', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'In the mid-twentieth century, Toyota pioneered a methodology called just-in-time manufacturing, according to which car parts were constructed and delivered as close as possible to the hour of assembly.', mt:'在二十世纪中期，丰田开创了一种称为准时制生产的方法，根据这种方法，汽车零部件尽可能接近装配时间进行制造和交付。', ref:'早在上世纪中叶，丰田便开创了一种可称之为“一切刚好 ”的生产方式。', tags:["准确性"] },
  { k:'seg_7_初赛_16', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'This was maximally efficient because it reduced waste and the cost of storage.', mt:'这非常高效，因为它减少了浪费和存储成本。', ref:'在此方式的指导下，汽车零组件的制造和交付都力图在组装前就位。该方式非常高效，因为它降低了浪费，节约了仓储成本。', tags:["准确性"] },
  { k:'seg_7_初赛_17', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But the human mind doesn’t work that way.', mt:'但是人类的思维方式并不是那样的。', ref:'但人脑并不按此方法运行。', tags:["准确性","风格"] },
  { k:'seg_7_初赛_18', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Knowledge must often molder in our mental warehouses for decades until we figure out what to do with it.', mt:'知识常常需要在我们的精神仓库中发霉几十年，直到我们弄清楚如何处理它。', ref:'知识要在我们脑海中储藏数年，甚至开始腐坏后，我们才能明白如何运用它。', tags:["准确性"] },
  { k:'seg_7_初赛_19', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Leslie Valiant, an eminent computer scientist who teaches at Harvard, sees this as a strength.', mt:'莱斯利·瓦连特（Leslie Valiant）是哈佛大学的一位杰出计算机科学家，他认为这是一个优势。', ref:'在哈佛大学执教的著名计算机科学家莱斯利·瓦利安特（Leslie Valiant）将此视为一种优势。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_20', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'He calls our ability to learn over the long term “educability,” and in his new book, “The Importance of Being Educable,” he argues that it’s key to our success.', mt:'他称我们长期学习的能力为“可教育性”，并在他的新书 《可教育性的重要性》中指出，这是我们成功的关键。', ref:'他称我们这种历久弥新的学习能力为“通识”（educability）1 ，并在他的新书《触类旁通的重要性》 中将之认定为我们获取成功的关键。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_21', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'When we think about what makes our minds special, we tend to focus on intelligence.', mt:'当我们思考是什么让我们的思想变得特别时，我们往往会关注智力。', ref:'当我们思索大脑的独特性源自何物时，我们通常会将之归因于“智识”。', tags:["准确性"] },
  { k:'seg_7_初赛_22', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But if we want to grasp reality in all its complexity, Valiant writes, then “cleverness is not enough.”', mt:'但如果我们想要理解现实的复杂性，瓦里安特写道，那么“聪明是不够的。”', ref:'然而，瓦利安特写道，如果我们希望真正把握现实的复杂性，仅有“智识”是远不足够的。', tags:["准确性","语言规范","风格"] },
  { k:'seg_7_初赛_23', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We need to build capacious and flexible theories about the world—theories that will serve us in new, unanticipated, and strange circumstances—and we do that by gathering diverse kinds of knowledge, often in a slow, additive, serendipitous way, and knitting them together.', mt:'我们需要建立关于世界的宽广而灵活的理论——这些理论将在新的、未预料到的和奇怪的情况下为我们服务 ——我们通过收集各种各样的知识，通常以一种缓慢、 累积、偶然的方式，并将它们编织在一起。', ref:'我们需要构建起广阔而又灵活的世界观，这些观念能让我们在全新的环境中应对不可预见甚至出乎意料的情况。这种世界观的形成需要我们搜集各种知识，以一种缓慢、叠加、偶然的方式将知识融会贯通。', tags:["准确性","风格"] },
  { k:'seg_7_初赛_24', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Through this process, we acquire systems of beliefs that are broader and richer than the ones we can create through direct personal experience.', mt:'通过这个过程，我们获得了比通过直接个人经验所能创造的更广泛和丰富的信仰体系。', ref:'在此过程中构建的价值体系，相较于以我们个人一手经验为基础而形成的价值体系相比，要更广泛和丰富。', tags:["准确性","风格"] },
  { k:'seg_7_初赛_25', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant won the 2010 Turing Award, his discipline’s version of the Nobel Prize, for developing ideas that underpin artificial intelligence and distributed computation, in which many computers work together to solve problems.', mt:'英勇赢得了2010年的图灵奖，这是他所在领域的诺贝尔奖，因其在人工智能和分布式计算（即多台计算机协同解决问题）方面的发展理念而获奖。', ref:'瓦利安特于2010年获得图灵奖，该奖项是他专业领域内的诺贝尔奖，用以支持人工智能和分布式计算技术的发展，该项技术依靠多台计算机协同合作解决问题。', tags:["准确性"] },
  { k:'seg_7_初赛_26', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'In his book, he contrasts A.I.’s way of learning with ours.', mt:'在他的书中，他对比了人工智能的学习方式和我们的学习方式。', ref:'瓦利安特在书中对比了人工智能和人类的学习方法。', tags:["准确性"] },
  { k:'seg_7_初赛_27', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'An A.I. can be astonishingly smart, and even think intuitively, kind of like a person.', mt:'人工智能可以非常聪明，甚至可以像人一样直觉地思考。', ref:'人工智能可以智能得出奇，甚至能像人类一样凭直觉思考 。', tags:["准确性"] },
  { k:'seg_7_初赛_28', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But A.I. systems, Valiant argues, are not as flexible as human minds because they are not yet educable.', mt:'但瓦连特认为，人工智能系统不如人类大脑灵活，因为它们还不能被教育。', ref:'虽然如此，瓦利安特认为人工智能系统并无人脑灵活，因为人工智能并不具有触类旁通的能力。', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_29', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Even the most state-of-the-art A.I.s learn through a rigid process, in which they are trained, at great expense, and don’t really get any smarter after that, no matter how much new information they ingest.', mt:'即使是最先进的人工智能也是通过一个严格的过程来学习的，在这个过程中，它们经过高成本的训练，并且在那之后无论摄取多少新信息，它们实际上都不会变得更聪明。', ref:'我们用最严苛的方式，付出巨大的代价训练人工智能，使其获得最前沿的知识，但在此之后，无论消化吸收多少新信息，人工智能也并不会变得更智能。', tags:["准确性","语言规范","风格"] },
  { k:'seg_7_初赛_30', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It’s as though their minds freeze on graduation day.', mt:'仿佛他们的思维在毕业那天冻结了。', ref:'它们的思维仿佛在训练完成获得“毕业”那一刻便停滞不前了。', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_31', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Yet human beings constantly improve their own minds through an unfolding, open-ended process that connects newly acquired facts and ideas to ones collected long ago.', mt:'然而，人类通过一个不断展开、开放的过程，不断改进自己的思维，将新获得的事实和想法与很久以前收集的知识联系起来。', ref:'与之相反，人脑常常进化，能以一种开放渐进的方式将新知与旧识贯通起来。', tags:["准确性"] },
  { k:'seg_7_初赛_32', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We “combine pieces of knowledge gained years apart” into “theories of considerable complexity that have many and disparate parts.”', mt:'我们“将相隔多年的知识片段结合起来”，形成“包含许多不同部分的复杂理论”。', ref:'我们“能将数年前习得的知识碎片”融汇成“统摄众多复杂组成部分的理论体系”。', tags:["准确性"] },
  { k:'seg_7_初赛_33', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant says that he tries not to use the word “intelligent” to describe people; instead, he is drawn to “valuable abilities that somehow involve learning and are not well captured by conventional notions of IQ.”', mt:'英勇说他尽量不使用“聪明”这个词来形容人；相反，他更倾向于使用“有价值的能力，这些能力在某种程度上涉及学习，并且不容易被传统的智商概念所捕捉。”', ref:'瓦利安特说他尽量不用“聪明”这个词去形容别人（事实上，如果听到别人用这个词，他甚至会不知所措）。瓦利安特更倾向于其它和学习相关的宝贵素质，而这些素质并不能简单化为“智商”。', tags:["准确性","风格","语言规范"] },
  { k:'seg_7_初赛_34', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'An educable mind, he writes, can learn from books, lectures, conversations, experiences, and Zen koans—from anything, really—and notice when relevant aspects of almost forgotten knowledge reveal themselves. We admire aspects of someone’s educability when we say that they are a quick study, or identify them as “coachable,” but what really makes them educable is that they apply insights “for purposes not foreseen at the time of the study or the coaching”; educability is something like “street smarts”—a term which connotes the “uncanny ability to negotiate the practicalities of life”—and is closely related to having common sense.', mt:'他写道，一个可教育的心灵可以从书籍、讲座、对话、经验和禅宗公案中学习——实际上可以从任何事物中学习 ——并注意到几乎被遗忘的知识的相关方面何时显现出来。 我们在称赞某人的可教育性时，会说他们是一个学习很快的人，或者称他们为“可教导的”，但真正使他们可教育的是他们能够将见解应用于“在学习或指导时未预见的目的”；可教育性有点像“街头智慧”——这个词意味着“非凡的处理生活实际问题的能力”——并且与常识密切相关。', ref:'他写道，这种触类旁通的思维可令人从任何东西中汲取知识，包括书本、讲座、谈话、经历、甚至禅宗的公案，并从几乎已被忘却的知识中寻找共通之处。 当我们评价某人上手很快，或者认定某人“孺子可教 ”时，我们实际上是在称赞他的“通识”能力。究其根本 ，原因在于他们能化用所学的知识，尽管这些知识在被获取的当下并无特定用途。“通识”接近于一种“街头智慧 ”，指代一种能与生存法则斡旋的能力，一种利用“常识 ”的能力。', tags:["准确性","术语","风格","语言规范"] },
  { k:'seg_7_初赛_35', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'we say that they are a quick study, or identify them as “coachable,” but what really makes them educable is that they apply insights “for purposes not foreseen at the time of the study or the coaching”; educability is something like “street smarts”—a term which connotes the “uncanny ability to negotiate the practicalities of life”—and is closely related to having common sense.', mt:'我们在称赞某人的可教育性时，会说他们是一个学习很快的人，或者称他们为“可教导的”，但真正使他们可教育的是他们能够将见解应用于“在学习或指导时未预见的目的”；可教育性有点像“街头智慧”——这个词意味着“非凡的处理生活实际问题的能力”——并且与常识密切相关。', ref:'当我们评价某人上手很快，或者认定某人“孺子可教 ”时，我们实际上是在称赞他的“通识”能力。究其根本 ，原因在于他们能化用所学的知识，尽管这些知识在被获取的当下并无特定用途。“通识”接近于一种“街头智慧 ”，指代一种能与生存法则斡旋的能力，一种利用“常识 ”的能力。', tags:["准确性","术语","风格"] },
  { k:'seg_7_初赛_36', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'When people strike us as particularly “well- educated,” this might mean that they’ve had lots of school, Valiant writes, but it could also mean that they’re exceptionally educable, with the ability to “take good advantage of whatever educational opportunities arise, whether formal or informal.”', mt:'当人们给我们留下“受过良好教育”的印象时，这可能意味着他们上过很多学，Valiant写道，但这也可能意味着他们特别容易受教育，能够“充分利用任何出现的教育机会，无论是正式的还是非正式的。”', ref:'瓦利安特写道，当我们惊叹某些人的“高知”时，我们或许在称赞他们所接受的众多教育，但也可能在赞叹他们融会贯通知识的出色能力，这种能力“可以助其把握住无论正式与否的任何教育机会”。', tags:["准确性","语言规范","风格"] },
  { k:'seg_7_初赛_37', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant suggests that we value educability in doctors.', mt:'英勇建议我们重视医生的可教育性。', ref:'瓦利安特还指出，我们也重视医生的“通识”能力。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_38', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Imagine that you feel a pain in your side.', mt:'想象一下你感到侧腹疼痛。', ref:'试想一下，倘若你感到侧腹疼痛，', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_39', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Is it appendicitis?', mt:'是阑尾炎吗？', ref:'但这就意味着患上阑尾炎了吗？', tags:["准确性"] },
  { k:'seg_7_初赛_40', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It would be unwise, he writes, to rely on what you know about the disease, based on what a few people who’ve had it have told you; you’d want to talk to a physician who’s seen a thousand cases.', mt:'他写道，依赖你从几个得过这种病的人那里了解到的情况是不明智的；你应该去咨询一个见过上千病例的医生。', ref:'瓦利安特继续写道，仅依赖曾经的病患分享的信息远非明智之举；你应向一位诊疗过上千个病例的医生问诊。', tags:["准确性","风格"] },
  { k:'seg_7_初赛_41', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'A medical A.I. could also train by looking at thousands of cases; in fact, “if it has seen a million cases, a situation well beyond individual human experience, then it may make predictions that are stunningly better than our intuitions can even comprehend.”', mt:'一个医疗人工智能也可以通过查看成千上万的病例进行训练；事实上，“如果它已经看过一百万个病例，这种情况远远超出个人的经验，那么它可能会做出比我们的直觉甚至无法理解的惊人预测。”', ref:'我们可以让医疗人工智能分析成千上万个病例，以此达到训练的目的；事实上，“如果它分析过上百万个病例，便能积累远超人类个体所能企及的经验，那么它所做的判断可能会比我们所做的好得多，甚至好到我们的智商都无法理解的地步。”', tags:["准确性"] },
  { k:'seg_7_初赛_42', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'And yet “the reason we go to doctors is not just that they have seen a thousand cases of a disease,” Valiant argues.', mt:'然而，瓦利安特认为，“我们去看医生的原因不仅仅是因为他们见过成千上万的病例。”', ref:'然而，“我们向医生求医问诊，并非因为他们诊疗过上千个病人，”瓦利安特认为，', tags:["准确性","风格"] },
  { k:'seg_7_初赛_43', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“It is that we believe doctors deliver further results.”', mt:'“我们相信医生会带来更多的成果。”', ref:'“而因为我们相信医生能够提供更多的建议”。', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_44', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'The basis of that extra value is educability.', mt:'这种额外价值的基础是可教育性。', ref:'这种附加价值的基础便是“通识”。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_45', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant doesn’t get into details, but we can imagine for ourselves the value that a hypothetical doctor’s educability might provide.', mt:'英勇没有详细说明，但我们可以自己想象一个假设的医生的可教育性可能带来的价值。', ref:'瓦利安特并未提供更多细节，但我们大可想象此例中该医生的“通识”能力所能带来的价值。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_46', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Such a doctor might draw on a range of ideas and connections spanning years of learning.', mt:'这样的医生可能会利用多年学习中积累的一系列想法和联系。', ref:'该医生或许会融通多年学习过程中的所思所想。', tags:["准确性"] },
  { k:'seg_7_初赛_47', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'She learned about appendicitis in medical school, of course—and quickly concludes that you don’t have it.', mt:'她在医学院学过阑尾炎，当然——很快得出结论你没有得阑尾炎。', ref:'毋庸置疑，她在医学院学习过诊治阑尾炎，并迅速得出你没得阑尾炎的结论。', tags:["准确性"] },
  { k:'seg_7_初赛_48', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But maybe her brother happens to be an avid cyclist, and she notices you drinking from a water bottle emblazoned with a logo she recognizes from his bike.', mt:'但也许她的兄弟恰好是一个狂热的骑行者，而她注意到你正在喝水瓶上的标志是她从他自行车上认出来的。', ref:'但也许，她的兄弟是狂热的骑行爱好者，她注意到你喝水瓶子上的标志和他自行车的标志别无二异。', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_49', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Wasn’t there an article online about how dangerous the city’s bike lanes have become?', mt:'网上不是有一篇关于城市自行车道变得多么危险的文章吗？', ref:'而且是不是有一篇网传文章，报道了这座城市的自行车道已变得如何危险？', tags:["准确性"] },
  { k:'seg_7_初赛_50', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'More generally, she’s also developed a new theory: she ought to ask more questions about the particulars of her patients’ lives.', mt:'更广泛地说，她还提出了一个新理论：她应该更多地询问患者生活的细节。', ref:'此外，她还发展出一套理论：她应询问患者，获取更多有关其生活的细节。', tags:["准确性"] },
  { k:'seg_7_初赛_51', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'She asks if you’re a cyclist, discovers that you are, and eventually pinpoints the real issue—a bruised rib acquired in a fall, which you’ve not allowed to heal properly.', mt:'她问你是否是骑自行车的人，发现你是，最终找到了真正的问题——在一次摔倒中受伤的肋骨，你没有让它好好愈合。', ref:'她于是询问你是否骑自行车，得知你的确是骑行爱好者的事实后，她终于发现了问题的源头。原来是因为你曾摔倒，并使肋骨受伤过，而受伤的肋骨并未充分康复。', tags:["准确性"] },
  { k:'seg_7_初赛_52', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Being educable, the doctor actually regards your case as an opportunity to learn, and is a better physician for it.', mt:'由于具有可教育性，这位医生实际上将你的病例视为一个学习的机会，并因此成为一名更好的医生。', ref:'作为一位拥有“通识”的医生，她把你的病况视为学习的机会，同时她也成为了更适合诊治你病情的医生。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_53', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'That’s a rather schematic, explicit example of educability.', mt:'这就是一个相当简明、明确的可教育性的例子。', ref:'这个例子清晰明了，是“通识”的代表性例证，但与此同时瓦利安特似乎还在描述一些更为精细且更具力量的东西 。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_54', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'To a degree, the connections, recombinations, and new applications of knowledge involved in being educable are useful precisely because they aren’t obvious.', mt:'在某种程度上，受教育所涉及的知识连接、重组和新应用之所以有用，正是因为它们并不显而易见。', ref:'在某种程度上，知识的连接、重组以及新应用均是“通识 ”的体现，而它们发挥用途的关键所在便是其潜移默化的能力。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_55', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It’s interesting to see one’s mind through the lens of educability.', mt:'通过可教育性的视角来看待一个人的思想是很有趣的。', ref:'通过“通识”的视角来看待自己的思维是件十分有趣的事情。', tags:["准确性","术语"] },
  { k:'seg_7_初赛_56', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It makes you wonder what other cross-pollinations have occurred.', mt:'这让你不禁想知道还有哪些其他的交叉授粉发生过。', ref:'这让人不禁想知道还有哪些关联贯通的现象发生过。', tags:["准确性"] },
  { k:'seg_7_初赛_57', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant thinks it might be useful to promote educability as an ideal. We could try to figure out how to measure and teach it in schools, or to encourage it in adults; at a time when accelerating technological change means there’s always more to learn, we might seek to create a more educable society in general.', mt:'英勇认为促进可教育性作为一种理想可能是有用的。 我们可以尝试研究如何在学校中测量和教授它，或者在成年人中鼓励它；在技术变革加速的时代，这意味着总有更多的东西需要学习，我们可能会寻求总体上创造一个更具教育性的社会。', ref:'瓦利安特认为，如果把“通识”当作是一种理念来推行的话，或许大有裨益。 我们可以尝试找出如何在学校衡量和传授“通识”的方法，同时向成年人推广“通识”；在科技发展日新月异的当下，知识的获取永无止境，因此我们更应当寻求创造一个更具通识性的社会。', tags:["准确性","术语","风格"] },
  { k:'seg_7_初赛_58', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We could try to figure out how to measure and teach it in schools, or to encourage it in adults; at a time when accelerating technological change means there’s always more to learn, we might seek to create a more educable society in general.', mt:'我们可以尝试研究如何在学校中测量和教授它，或者在成年人中鼓励它；在技术变革加速的时代，这意味着总有更多的东西需要学习，我们可能会寻求总体上创造一个更具教育性的社会。', ref:'我们可以尝试找出如何在学校衡量和传授“通识”的方法，同时向成年人推广“通识”；在科技发展日新月异的当下，知识的获取永无止境，因此我们更应当寻求创造一个更具通识性的社会。', tags:["准确性","术语","风格"] },
  { k:'seg_7_初赛_59', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'After reading his book, I thought, on a less exalted scale, about how I might improve my own educability.', mt:'读完他的书后，我想，虽然规模较小，但我如何才能提高自己的可教育性。', ref:'读罢书后，我从一个更务实的角度思考了如何提高我“通识”能力的方式。', tags:["准确性","术语","风格"] },
  { k:'seg_7_初赛_60', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I concluded that I would seek to learn about a wider range of subjects, and simply try more things, trusting that my mind would someday knit it all together.', mt:'我决定要学习更广泛的学科，并尝试更多的事情，相信我的大脑有一天会把这一切联系起来。', ref:'我的结论是我会寻求学习更广泛的科目，尝试更多的东西，寄希望于我的脑子在某天可以将其融会贯通。', tags:["准确性"] },
  { k:'seg_7_初赛_61', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I also figured that it couldn’t hurt to remind myself of what I’d already learned.', mt:'我也觉得提醒自己已经学到的东西不会有什么坏处。', ref:'我也明白，我也可以付诸于曾经的所学来提醒自己。', tags:["准确性"] },
  { k:'seg_7_初赛_62', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Down in the basement, a few big bookshelves hold my reading from college and graduate school.', mt:'在地下室里，有几个大书架放着我大学和研究生时期的书 。', ref:'地下室的几个大书架上，放着我大学和研究生阶段所读的书，', tags:["准确性","语言规范"] },
  { k:'seg_7_初赛_63', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“Middlemarch” is there, along with many other books that I didn’t understand then but have come to value with the passage of time.', mt:'《米德尔马契》在那里，还有许多其他我当时不理解但随着时间的推移逐渐珍视的书。', ref:'《米德尔马契》便是其中的一本，当然还有其他我当时读不懂的书。但随着时间的流逝，我开始发现了这些书的价值。', tags:["准确性"] },
  { k:'seg_7_初赛_64', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Reading widely about things that don’t seem immediately or practically useful, in the hope that what you learn now may prove meaningful later—that’s pretty much the definition of a liberal-arts education.', mt:'广泛阅读那些看起来没有直接或实际用途的东西，希望你现在学到的东西以后可能会有意义——这几乎就是文科教育的定义。', ref:'广泛阅读那些看似当下并无实际用处的内容，以求在日后发挥用途，这或许便是通识教育的真谛。', tags:["准确性","术语","风格"] },
  { k:'seg_7_初赛_65', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Who knew that one of its best defenders would turn out to be a computer scientist?', mt:'谁知道它最好的捍卫者之一竟然会是一个计算机科学家呢？', ref:'但又有谁能料到这一方式的捍卫者竟是一位计算机科学家呢？', tags:["准确性","风格"] },
  { k:'seg_8_决赛_1', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'近代上海地方建筑特征', mt:'Modern Architectural Features of Shanghai', ref:'The Features of Local Shanghai Architecture', tags:["准确性"] },
  { k:'seg_8_决赛_2', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海近代建筑有着强烈的地方特征。', mt:'Modern architecture in Shanghai exhibits strong local characteristics.', ref:'Shanghai’s architecture has distinctive local traits', tags:["准确性"] },
  { k:'seg_8_决赛_3', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'这种地方特征不论是居住在上海的本地人还是来上海的外地人都能感觉到。', mt:'This local characteristic can be felt by both native residents of Shanghai and visitors from other regions.', ref:'that both long-time residents and newly arrived visitors can discern.', tags:["准确性"] },
  { k:'seg_8_决赛_4', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'它建立在上海悠久的历史中形成的地方文化传统的基础之上，更与近代100年里上海特殊的城市经历密不可分，与近代上海人的社会心态、生活方式、行为准则和价值观念紧紧相关，反过来它更是近代上海特殊的城市文化的一个不可缺少的重要组成部分。', mt:'It is rooted in the local cultural traditions shaped by Shanghai\'s long history and is deeply intertwined with the city\'s unique experiences over the past century. Closely linked to the social mentality, lifestyle, behavioral norms, and values of modern Shanghainese, it has, in turn, become an indispensable and vital component of Shanghai\'s distinctive urban culture.', ref:'Built upon the local culture and traditions accumulated over Shanghai’s long history, they are even more intimately tied to the unique century of change the city underwent during the early modern period. These traits are closely related to the people of the city, their mentality, their way of life, their behavioral standards, and their system of values. Conversely, Shanghai’s distinctive local architecture is also an essential component of this unique urban culture.', tags:["准确性"] },
  { k:'seg_8_决赛_5', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海近代建筑的地方特征概括起来讲，就是注重功利，追求时尚；中西合璧，兼容并蓄。', mt:'The local characteristics of modern architecture in Shanghai can be summarized as follows: a focus on practicality, a pursuit of trends; a blend of Chinese and Western styles, embracing diversity.', ref:'These distinctive local traits include the dynamic coexistence of both fashion and utility, as well as the open-minded synthesis of Chinese and Western aspects.', tags:["准确性","术语"] },
  { k:'seg_8_决赛_6', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'注重功利，追求时尚', mt:'Focus on utility, pursue trends', ref:'Fashion and Utility', tags:["术语"] },
  { k:'seg_8_决赛_7', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'注重功利是商品经济社会中人们社会价值观的一个重要表现，它表现在社会文化的各个方面，自然也会通过建筑表现出来。', mt:'The emphasis on utilitarianism is an important manifestation of people\'s social values in a commodity economy society. It is reflected in various aspects of social culture and naturally also expressed through architecture.', ref:'An emphasis on utility is one of the principal social values found in a commodity economy. It is typically expressed throughout the various aspects of a society’s culture, and it is therefore only natural that it should emerge in architecture.', tags:["准确性","术语","语言规范"] },
  { k:'seg_8_决赛_8', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'早在上海开埠以前，相对于中国其他城市而言，上海的商品经济就已相当发达，并对传统的上海地方文化带来了深刻的影响。', mt:'Long before Shanghai became a trading port, its commodity economy was already quite developed compared to other Chinese cities, profoundly influencing the traditional local culture of Shanghai.', ref:'Compared with China’s other cities, Shanghai’s commodity economy was already fairly well developed even before its opening, a fact that had a profound influence on the city’s traditional local culture.', tags:["准确性"] },
  { k:'seg_8_决赛_9', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海开埠后，现代西方资本主义经济进入上海，使上海迅速成为中国近代商品经济最发达的城市，这使得近代上海社会的各个方面都表现出一种以“利益第一”的社会价值观代替中国传统“重义轻利”社会价值观的倾向。', mt:'After Shanghai opened its port, modern Western capitalist economy entered the city, rapidly transforming it into the most developed hub of modern commodity economy in China. This shift led to a noticeable trend in various aspects of Shanghai society, where the traditional Chinese value of "emphasizing righteousness over profit" was gradually replaced by a new social ethos that prioritized "profit first."', ref:'After the opening and the arrival of Western capitalism, Shanghai quickly became the city with the most developed commodity economy in China. Across various aspects of Shanghai’s society, this led to the displacement of traditional Chinese values, which tended to place “principle before profit,” with a new “profit-first” value system.', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_10', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'“利，时之大义矣”成为一种社会共识。', mt:'Profit is the supreme principle of the times" has become a social consensus.', ref:'The people of Shanghai came to an understanding that “profit is the new guiding principle of our times.”', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_11', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'正是在这样一种社会心态下，以赢利为目的的上海近代建筑业产生了。 建筑作为一种普通的商品被大量地建造起来，为了“利 ”，可以不顾中国官府和外国领事两方都坚持的“华洋分居”原则而建造大量商品住宅吸引华人进入租界；为了“ 利”，可以将租界的煤气管、自来水管、电线电缆接到华界，让“低等”的华人与“高等”的洋人同时享受现代文明；为了“利”，上海才会出现高楼成群，建筑密布的拥挤的城市风貌，反映在建筑设计上，就是一切从实际出发，精打细算，讲求实惠。 追求时尚也是近代上海发达的商品经济社会中又一种突出的社会心态。', mt:'It was under such a social mentality that the profit- driven modern construction industry in Shanghai emerged. Architecture, as a common commodity, was constructed in large quantities. For the sake of "profit," developers disregarded the "separation of Chinese and foreigners" principle upheld by both the Chinese authorities and foreign consulates, building numerous commercial residences to attract Chinese into the concessions. For the sake of "profit," gas pipes, water mains, and electrical cables from the concessions were extended into Chinese districts, allowing "lower-class" Chinese to enjoy modern amenities alongside "upper-class" foreigners. For the sake of "profit," Shanghai developed its crowded urban landscape of towering buildings and dense construction. This pragmatism was reflected in architectural design—everything was based on practicality, meticulous calculation, and a focus on tangible benefits. The pursuit of fashion is another prominent social mentality in the modern, prosperous commodity economy of Shanghai."', ref:'It was precisely this new outlook that produced the city’s profit-driven construction industry, transforming buildings into everyday commodities and leading to their construction in ever-larger numbers. For “profit,” builders ignored the principle of Chinese-foreign separation set down by the Chinese government and foreign consulates in order to build the large quantities of commodity housing that attracted Chinese residents to the concessions. For “profit,” the concessions’ gas, water, and power infrastructure was extended into Chinese district, enabling the “lower class” Chinese and “upper class” foreigners to share the benefits of modern civilization. For “profit,” high-rise and high-density buildings became characteristic of Shanghai’s urban environment. Reflected in the design of the built environment, these features were all calculated to achieve maximum profit from the city’s prevailing circumstances. The pursuit of fashion was another prominent feature of the mentality engendered by Shanghai’s developed commodity economy.', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_决赛_12', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'建筑作为一种普通的商品被大量地建造起来，为了“利 ”，可以不顾中国官府和外国领事两方都坚持的“华洋分居”原则而建造大量商品住宅吸引华人进入租界；为了“ 利”，可以将租界的煤气管、自来水管、电线电缆接到华界，让“低等”的华人与“高等”的洋人同时享受现代文明；为了“利”，上海才会出现高楼成群，建筑密布的拥挤的城市风貌，反映在建筑设计上，就是一切从实际出发，精打细算，讲求实惠。', mt:'Architecture, as a common commodity, was constructed in large quantities. For the sake of "profit," developers disregarded the "separation of Chinese and foreigners" principle upheld by both the Chinese authorities and foreign consulates, building numerous commercial residences to attract Chinese into the concessions. For the sake of "profit," gas pipes, water mains, and electrical cables from the concessions were extended into Chinese districts, allowing "lower-class" Chinese to enjoy modern amenities alongside "upper-class" foreigners. For the sake of "profit," Shanghai developed its crowded urban landscape of towering buildings and dense construction. This pragmatism was reflected in architectural design—everything was based on practicality, meticulous calculation, and a focus on tangible benefits.', ref:'transforming buildings into everyday commodities and leading to their construction in ever-larger numbers. For “profit,” builders ignored the principle of Chinese-foreign separation set down by the Chinese government and foreign consulates in order to build the large quantities of commodity housing that attracted Chinese residents to the concessions. For “profit,” the concessions’ gas, water, and power infrastructure was extended into Chinese district, enabling the “lower class” Chinese and “upper class” foreigners to share the benefits of modern civilization. For “profit,” high-rise and high-density buildings became characteristic of Shanghai’s urban environment. Reflected in the design of the built environment, these features were all calculated to achieve maximum profit from the city’s prevailing circumstances.', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_13', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'追求时尚也是近代上海发达的商品经济社会中又一种突出的社会心态。', mt:'The pursuit of fashion is another prominent social mentality in the modern, prosperous commodity economy of Shanghai."', ref:'The pursuit of fashion was another prominent feature of the mentality engendered by Shanghai’s developed commodity economy.', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_14', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'“以新为美”表现在近代社会的各个方面，戏剧、文学、 服装、建筑无不如此。', mt:'The pursuit of novelty as beauty" manifests in every aspect of modern society, be it theater, literature, fashion, or architecture.', ref:'Theater, literature, fashion, and architecture all embodied the city’s new maxim, “new is beautiful.”', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_15', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'1876年，当上海修筑了第一条铁路淞沪铁路而遭到清政府的强烈反对，并决定将其赎买及拆毁时，上海的老百姓却都竞相观望、乘坐，以求一睹为快、一坐为快。', mt:'In 1876, when the first railway in Shanghai, the Songhu Railway, was constructed and faced strong opposition from the Qing government, which decided to buy it back and dismantle it, the local residents of Shanghai eagerly flocked to see and ride it, eager to witness and experience the novelty.', ref:'After the construction of China’s first railroad in 1876, the Wusong-Shanghai Line, the Qing government, which was fiercely opposed to the newfangled contraption, decided to buy the line and destroy it. The people of Shanghai, however, flocked to the newly built wonder, vying for a seat or even a glimpse of the train.', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_决赛_16', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'通车之际,“铁路两旁观者云集，欲搭坐者已繁杂不可计数 ”,“坐车者尽面带喜色，旁观者亦皆喝彩”。', mt:'At the time of the opening, "spectators gathered on both sides of the railway, with countless eager to board,""those on the train wore joyful expressions, while the onlookers cheered."', ref:'While it was operational, “the railroad was crowded with onlookers on both sides, and innumerable passengers crowded the train looking for seats.” As the train moved, “the passengers all sat with looks of delight, and the bystanders raised a cheer.”', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_决赛_17', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'对于新事物，上海人有一种特别的接受能力，反映在建筑上，就是对“新”的追求始终不断。', mt:'Shanghai people have a unique ability to embrace new things, which is reflected in their architecture through a constant pursuit of the "new."', ref:'The people of Shanghai were uniquely disposed to welcome all that was “new.” As far as architecture was concerned, this outlook expressed itself in the unbridled pursuit of novelty.', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_18', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'新材料、新结构、新设备往往会作为一种骄傲而大肆宣传，新式样更是不断出现，不断翻新。', mt:'New materials, new structures, and new equipment are often touted with pride, while new styles constantly emerge and evolve.', ref:'New materials, new structures, and new amenities often became points of pride that made a big splash when they first appeared. To an even greater extent, new architectural styles were continually being discovered and renewed.', tags:["准确性"] },
  { k:'seg_8_决赛_19', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'在一个竞争激烈的商品社会里，不能不断地推陈出新就会有随时被社会淘汰的危险。', mt:'In a fiercely competitive consumer society, failing to continuously innovate and bring forth new ideas carries the risk of being left behind at any moment.', ref:'Amidst the intense competition of a commodity- driven society, those who could not maintain a regime of continuous reinvention risked being weeded out over time.', tags:["准确性"] },
  { k:'seg_8_决赛_20', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'因此，不论是业主还是设计者，都把追求时尚看成是其事业能够继续发展的保证。', mt:'Therefore, both property owners and designers regard pursuing fashion as a guarantee for the continued development of their careers.', ref:'Thus, both developers and designers saw the pursuit of fashion as a guarantee for the continued development of their enterprises.', tags:["准确性","风格"] },
  { k:'seg_8_决赛_21', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'而每一次新式样的出现，每一种新设备、新技术的运用， 也都会引起社会的轰动，都会引起社会的竞相效仿。', mt:'And every time a new style emerges, every new device or application of new technology, it causes a social sensation and sparks widespread imitation.', ref:'Moreover, the first appearance of every new style, amenity, or technology always caused a sensation in Shanghai society, and competitors immediately vied to imitate it.', tags:["准确性"] },
  { k:'seg_8_决赛_22', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海近代的建筑也正因为如此，才会呈现出丰富多彩、始终新意不断的发展局面。', mt:'The modern architecture of Shanghai has thus developed into a vibrant and ever-innovative landscape.', ref:'It is for this reason that Shanghai’s architecture is so richly varied and so powerfully invigorated with the continual reinvention of the new.', tags:["风格","准确性"] },
  { k:'seg_8_决赛_23', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'中西合璧，兼容并蓄', mt:'Combining Chinese and Western elements, embracing diversity', ref:'Open-mindedness and Chinese-Western Synthesis', tags:["准确性","风格"] },
  { k:'seg_8_决赛_24', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'由于上海近代建筑是产生在东西方两种异质文化相碰撞的过程中，因而就不可避免地会反映出一种中西合璧的现象 。', mt:'Since modern architecture in Shanghai emerged from the collision of two distinct cultures, East and West, it inevitably reflects a fusion of Chinese and Western elements.', ref:'Given that Shanghai’s modern architectural development has occurred as the result of a collision between the differing cultural values of East and West, it was unavoidable that there should be some resulting synthesis of Chinese and Western elements.', tags:["准确性"] },
  { k:'seg_8_决赛_25', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海地方文化中特有的、吸百家之长兼容并蓄的能力使得这种中西合璧现象表现得尤为突出。', mt:'The unique ability of Shanghai\'s local culture to absorb and integrate the strengths of various schools makes this fusion of Chinese and Western elements particularly prominent.', ref:'The special open-mindedness with which the city welcomed the strengths of new arrivals meant that this synthesis became particularly pronounced in Shanghai.', tags:["准确性","风格"] },
  { k:'seg_8_决赛_26', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'事实上，上海近代建筑中“东西合璧”从西方建筑进入上海的第一天就已开始。', mt:'In fact, the "fusion of East and West" in Shanghai\'s modern architecture began the very day Western architecture first arrived in the city.', ref:'In fact, this phenomenon had begun as soon as Western architecture arrived in the city,', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_27', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'早期“康白度式”(Compradoric Style)建筑即能说明这一点。', mt:'The early "Compradoric Style" architecture can illustrate this point.', ref:'as is illustrated by the early “Compradoric style.”', tags:["准确性","语言规范"] },
  { k:'seg_8_决赛_28', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'虽然它在中国人的眼里是“洋房”，但却是中国的工匠用中国的建筑材料，用中国的传统的建造方式建造起来的。', mt:'Although it is considered a "Western-style house" in the eyes of the Chinese, it was actually built by Chinese craftsmen using Chinese construction materials and traditional Chinese building methods.', ref:'Though Compradoric-style buildings were decidedly Western in the eyes of locals, they were actually built by Chinese artisans using Chinese materials and traditional Chinese construction methods.', tags:["准确性"] },
  { k:'seg_8_决赛_29', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'当然，这种早期的不同建筑文化的融合是非主动的、无意识的。', mt:'Certainly, this early fusion of different architectural cultures was passive and unconscious.', ref:'Of course, this early example of architectural assimilation was by no means intentional.', tags:["准确性","风格"] },
  { k:'seg_8_决赛_30', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'以后，随着西方文化的不断涌人，两种不同文化的融合成为一种必然，建筑中开始从设计上主动地表现出这种不同文化的融合。', mt:'In the future, with the continuous influx of Western culture, the fusion of these two distinct cultures became inevitable. Architecture began to actively reflect this cultural integration in its designs.', ref:'With the unchecked tide of Western culture flooding into the city, this intercultural integration became an inevitability, and buildings started to be purposely designed to display this cultural fusion.', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_决赛_31', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'里弄住宅是数量最大、最典型的例子。', mt:'Lane houses are the most numerous and typical example.', ref:'Lilong residences are the most numerous and typical example.', tags:["准确性"] },
  { k:'seg_8_决赛_32', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'这种近代上海的新型居住建筑，自从产生的第一天起就打上了中西合璧的烙印。 从早期里弄看，它们的形式似乎并未摆脱传统的中国民居，然而它的总体连排式布局却来源于欧洲。', mt:'This new type of residential architecture in modern Shanghai has been marked by a fusion of Chinese and Western styles since its very inception. From the early alleyways, their form does not seem to break away from traditional Chinese residences, yet their overall row-house layout originates from Europe.', ref:'From its very first appearance in the city, this new form of housing epitomized the synthesis of Chinese and Western architecture. While the formal properties of the early lilong still seemed closely related to traditional Chinese dwellings, their overall arrangement in long rows was fully European in origin.', tags:["准确性","风格"] },
  { k:'seg_8_决赛_33', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'从早期里弄看，它们的形式似乎并未摆脱传统的中国民居，然而它的总体连排式布局却来源于欧洲。', mt:'From the early alleyways, their form does not seem to break away from traditional Chinese residences, yet their overall row-house layout originates from Europe.', ref:'While the formal properties of the early lilong still seemed closely related to traditional Chinese dwellings, their overall arrangement in long rows was fully European in origin.', tags:["准确性","风格"] },
  { k:'seg_8_决赛_34', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'早期里弄最有特色的地方——石库门，其门框、黑门板、 铜门环都不无中国传统建筑特征，而门上的三角形或圆弧形的门楣装饰则多为十足的西式图案。', mt:'The most distinctive feature of early alleyway houses—the Shikumen—lies in its door frames, black wooden doors, and brass knockers, all of which embody traditional Chinese architectural elements. Meanwhile, the triangular or arched lintel decorations above the doors often showcase distinctly Western- style patterns.', ref:'Many of the most characteristic features of these early lilong —the shikumen , the doorframe, the black door, and the copper doorknocker—were all typical of traditional Chinese architecture. Yet, the decorative lintel and its triangular or circular form were fully Western.', tags:["准确性"] },
  { k:'seg_8_决赛_35', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'更为重要的是，这种建筑类型本身既非任何一种中国传统的居住建筑，也不是对任何一种西方建筑的模仿。', mt:'More importantly, this type of architecture is neither a traditional Chinese residential building nor an imitation of any Western architectural style.', ref:'Even more importantly, this building type was neither a variety of traditional Chinese residential architecture nor an import of Western architecture.', tags:["准确性"] },
  { k:'seg_8_决赛_36', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'它是一种融合了中西建筑特征而产生的一种上海特有的中西合璧的新建筑。', mt:'It is a new type of architecture unique to Shanghai, blending Chinese and Western architectural features to create a harmonious fusion of both styles.', ref:'Rather, it was a wholly new type of synthetic building, peculiar to Shanghai and produced from the integration of Chinese and Western architectural features.', tags:["准确性"] },
  { k:'seg_8_决赛_37', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'当然，上海近代建筑中西合璧现象远不止于里弄住宅。', mt:'Of course, the fusion of Chinese and Western elements in Shanghai\'s modern architecture extends far beyond the alleyway residences.', ref:'Shanghai’s architectural synthesis of China and the West certainly did not stop at the lilong .', tags:["准确性"] },
  { k:'seg_8_决赛_38', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'在教堂、学校、医院及小住宅、办公楼、电影院等各种建筑类型，都普遍存在着这种现象。', mt:'This phenomenon is commonly found in various types of buildings, including churches, schools, hospitals, small residences, office buildings, and movie theaters.', ref:'Every type of architecture built in Shanghai—including churches, schools, hospitals, villas, office buildings, and cinemas—all of them exhibited this phenomenon.', tags:["准确性"] },
  { k:'seg_8_决赛_39', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'这种中西合璧现象取决于近代上海整个社会意识形态中东西方两种文化从对立逐步走向认同。', mt:'This phenomenon of blending Chinese and Western elements stems from the gradual shift from opposition to mutual recognition between Eastern and Western cultures in the ideological landscape of modern Shanghai.', ref:'This synthesis depended on a larger ideological transformation that gradually took place in Shanghai, from cultural antagonism between China and the West toward mutual understanding.', tags:["准确性"] },
  { k:'seg_8_决赛_40', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'事实上，上海建筑中的不中不西、半中半西、又中又西的不纯性存在于近代上海社会和文化中的各个方面，正是这样一种特有的中西合璧形成了上海近代建筑的最大特征。', mt:'In fact, the hybrid nature of Shanghai\'s architecture—neither purely Chinese nor purely Western, but a blend of both—permeates every aspect of modern Shanghai society and culture. It is precisely this unique fusion of East and West that defines the most distinctive feature of Shanghai\'s modern architecture.', ref:'In reality, the impure nature of Shanghai’s architecture—neither Western nor Chinese, half- Western and half-Chinese, both Western and Chinese—was characteristic of all aspects of the city’s social and cultural existence. This peculiar synthesis of China and the West is indeed the most unique feature of Shanghai’s architectural history.', tags:["准确性","风格"] },
  { k:'seg_8_初赛_1', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'E-Taste Technology: The Taste Revolution in the Digital Age', mt:'味觉科技：数字时代的味觉革命', ref:'电子味觉技术：数字时代的味觉革命', tags:["准确性"] },
  { k:'seg_8_初赛_2', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'In the rapidly evolving landscape of sensory technology, one innovation stands poised to transform our relationship with food and flavor: e- taste.', mt:'在快速发展的感官技术领域，一项创新有望改变我们与食物和风味的关系：电子味觉。', ref:'感官技术发展日新月异，有项新技术正蓄势待发，或将彻底改变我们与食物和味道之间的关系，这便是“电子味觉”。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_3', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Short for “electronic taste”, e-taste technology represents a groundbreaking fusion of neuroscience, artificial intelligence, and digital engineering, aimed at simulating, enhancing, and even creating entirely new taste experiences through electronic devices.', mt:'“电子味觉”的缩写，电子味觉技术代表了神经科学、 人工智能和数字工程的突破性融合，旨在通过电子设备模拟、增强甚至创造全新的味觉体验。', ref:'电子味觉（e-taste）是“electronic taste”的简称，代表着神经科学、人工智能与数字工程的突破性融合，旨在通过电子设备模拟、增强，甚至创造全新的味觉体验 。', tags:["准确性","术语","语言规范"] },
  { k:'seg_8_初赛_4', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'As we venture further into the digital age, e-taste is not just a futuristic concept—it is becoming a tangible reality with profound implications for industries ranging from food and beverage to healthcare and entertainment.', mt:'随着我们进一步进入数字时代，电子味觉不仅仅是一个未来概念——它正在成为一个具有深远影响的现实，涉及从食品饮料到医疗保健和娱乐等多个行业。', ref:'随着我们迈入数字时代，电子味觉不再只是未来想象， 而正成为切实可行的现实，且对餐饮、医疗乃至娱乐等多个行业带来深远影响。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_5', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'At its core, e-taste technology seeks to replicate the complex process of human taste perception.', mt:'电子味觉技术的核心是复制人类味觉感知的复杂过程。', ref:'电子味觉技术的核心目标是再现人类复杂的味觉感知过程。', tags:["准确性"] },
  { k:'seg_8_初赛_6', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Taste, as we know it, is a multifaceted sensory experience involving the detection of five primary flavors—sweet, sour, salty, bitter, and umami—by taste buds on the tongue.', mt:'我们所知的味觉是一种多方面的感官体验，涉及舌头上的味蕾对五种基本味道的检测——甜、酸、咸、苦和鲜味。', ref:'我们所说的“味道”是一个多维度的感官体验，涉及舌尖上的味蕾对五种基本味道——甜、酸、咸、苦、鲜的感知。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_7', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'However, the full experience of flavor also incorporates smell, texture, temperature, and even visual cues, making it a highly intricate phenomenon to replicate artificially.', mt:'然而，完整的风味体验还包括气味、质地、温度甚至视觉线索，这使得人工复制成为一个高度复杂的现象。', ref:'然而，完整的味道体验还包括嗅觉、口感、温度，甚至视觉线索，这导致人工再现变得异常复杂。', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_初赛_8', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'E-taste technology addresses this challenge by employing a combination of electrochemical sensors, neural interfaces, and machine learning algorithms to decode and simulate taste signals.', mt:'电子味觉技术通过结合电化学传感器、神经接口和机器学习算法来解码和模拟味觉信号，从而应对这一挑战。', ref:'为应对这一挑战，电子味觉技术结合了电化学传感器、 神经接口和机器学习算法来解析并模拟味觉信号。', tags:["准确性"] },
  { k:'seg_8_初赛_9', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The journey of e-taste began in the early 2000s, when researchers first experimented with “electronic tongues”—devices designed to mimic the human taste system for industrial applications, such as quality control in food production.', mt:'电子味觉的旅程始于21世纪初，当时研究人员首次尝试“电子舌头”——一种旨在模仿人类味觉系统的设备， 用于食品生产中的质量控制等工业应用。', ref:'21世纪初，研究人员开始研究电子味觉，并首次尝试开发“电子舌头”这类装置，通过模拟人类味觉系统，应用于工业场景，例如食品生产中的质量控制。', tags:["准确性","术语","风格"] },
  { k:'seg_8_初赛_10', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'These early systems used arrays of chemical sensors to detect and analyze the composition of liquids, providing a rudimentary form of taste profiling. However, they lacked the ability to translate these detections into a human-like taste experience.', mt:'这些早期系统使用化学传感器阵列来检测和分析液体的成分，提供了一种初步的味觉分析。然而，它们无法将这些检测结果转化为类似人类的味觉体验。', ref:'这些早期系统利用化学传感器阵列对液体成分进行检测和分析，从而实现了初步的味觉分析，但却无法将检测结果转化为人类可感知的味觉体验。', tags:["准确性"] },
  { k:'seg_8_初赛_11', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'It wasn’t until advancements in neural decoding and brain-computer interfaces (BCIs) emerged that the possibility of directly stimulating the brain’s taste centers became feasible.', mt:'直到神经解码和脑机接口（BCI）技术的进步出现，直接刺激大脑味觉中心的可能性才变得可行。', ref:'直到神经解码与脑机接口技术取得突破，直接刺激大脑味觉中枢才有可能实现。', tags:["准确性"] },
  { k:'seg_8_初赛_12', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Today’s e-taste devices operate on the principle of neural modulation.', mt:'如今的电子味觉设备基于神经调制的原理运作。', ref:'当今，电子味觉设备基于神经调控原理运作。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_13', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'By using non-invasive methods such as transcranial magnetic stimulation (TMS) or invasive techniques like implanted electrodes, these devices can activate specific neural pathways associated with taste perception. For instance, a user might wear a headset that delivers precise magnetic pulses to the gustatory cortex, the brain region responsible for processing taste.', mt:'通过使用非侵入性方法，如经颅磁刺激（TMS），或侵入性技术，如植入电极，这些设备可以激活与味觉感知相关的特定神经通路。 例如，用户可能会佩戴一个向负责处理味觉的大脑区域 ——味觉皮层——传递精确磁脉冲的头戴设备。', ref:'这些设备通过“非侵入性技术”，如经颅磁刺激（TMS），或是“侵入性技术”，如植入电极，便可激活与味觉感知相关的大脑神经通路。 例如，用户可以佩戴一种头戴装置，向大脑负责处理味觉信号的“味觉皮层”释放精准的磁脉冲。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_14', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'For instance, a user might wear a headset that delivers precise magnetic pulses to the gustatory cortex, the brain region responsible for processing taste.', mt:'例如，用户可能会佩戴一个向负责处理味觉的大脑区域 ——味觉皮层——传递精确磁脉冲的头戴设备。', ref:'例如，用户可以佩戴一种头戴装置，向大脑负责处理味觉信号的“味觉皮层”释放精准的磁脉冲。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_15', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'When calibrated correctly, these pulses can evoke sensations of sweetness, saltiness, or other flavors without any physical ingestion.', mt:'当正确校准时，这些脉冲可以在没有任何物理摄入的情况下唤起甜味、咸味或其他风味的感觉。', ref:'经校准设备后，这些脉冲可以在人类不摄入任何食物的前提下，引发“甜”“咸”等各种味觉感受。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_16', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'This technology, while still in its nascent stages, has already shown promise in controlled laboratory settings.', mt:'这项技术虽然仍处于起步阶段，但已经在受控的实验室环境中显示出前景。', ref:'这项技术虽仍处于早期开发阶段，但在实验室环境中已初见成效。', tags:["准确性"] },
  { k:'seg_8_初赛_17', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Beyond mere simulation, e-taste technology is also being integrated with artificial intelligence to create personalized taste experiences.', mt:'除了模拟之外，电子味觉技术还与人工智能结合，以创造个性化的味觉体验。', ref:'电子味觉技术不仅可以模拟味觉，同时也在与人工智能融合，进而打造个性化的味觉体验。', tags:["准确性"] },
  { k:'seg_8_初赛_18', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Imagine a scenario where an AI-powered e-taste device learns your flavor preferences over time, adjusting its stimulations to enhance your enjoyment of certain foods or even to help you explore new tastes.', mt:'想象一下，一个由人工智能驱动的电子味觉设备随着时间的推移学习你的口味偏好，调整其刺激以增强你对某些食物的享受，甚至帮助你探索新的味道。', ref:'设想以下场景：AI驱动的电子味觉设备能随着时间了解你的口味偏好，并相应调整刺激参数，以增强你对特定食物的喜好，甚至引导你尝试新口味。', tags:["准确性"] },
  { k:'seg_8_初赛_19', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Such applications could revolutionize the culinary world, allowing chefs to craft “digital recipes” that users can experience without the need for physical ingredients.', mt:'这样的应用可能会彻底改变烹饪世界，允许厨师制作“ 数字食谱”，用户无需物理食材即可体验。', ref:'这类设备有望彻底变革烹饪艺术，助力厨师创作出“数字食谱”，用户则无需品尝真实食材即可体验相应菜品的风味。', tags:["准确性","风格"] },
  { k:'seg_8_初赛_20', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Moreover, e-taste could play a pivotal role in addressing global food challenges, such as reducing sugar or salt intake by providing the perception of these flavors without their actual consumption, thereby promoting healthier diets.', mt:'此外，电子味觉可以在应对全球食品挑战中发挥关键作用，例如通过提供这些风味的感知而不实际摄入，从而减少糖或盐的摄入，促进更健康的饮食。', ref:'此外，电子味觉还可能在应对全球饮食挑战中发挥关键作用，例如，可通过模拟甜味或咸味，让人无需实际摄入过多糖分或盐分便可获得相应味觉体验，从而推动更健康的饮食习惯。', tags:["准确性"] },
  { k:'seg_8_初赛_21', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The potential applications of e-taste extend far beyond the dining table.', mt:'电子味觉的潜在应用远远超出了餐桌。', ref:'电子味觉的应用潜力远不止于餐饮。', tags:["准确性"] },
  { k:'seg_8_初赛_22', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'In the medical field, e-taste technology holds promise for patients suffering from taste disorders, such as ageusia (loss of taste) or dysgeusia (distorted taste).', mt:'在医学领域，电子味觉技术为患有味觉障碍的患者，如味觉丧失（味觉缺失）或味觉扭曲（味觉障碍），带来了希望。', ref:'在医学领域，它对患有味觉丧失、味觉紊乱等味觉障碍的患者具有治疗前景。', tags:["准确性","术语","语言规范","风格"] },
  { k:'seg_8_初赛_23', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'By directly stimulating the brain’s taste centers, e- taste devices could help restore or compensate for impaired taste functions, improving the quality of life for individuals affected by these conditions.', mt:'通过直接刺激大脑的味觉中心，电子味觉设备可以帮助恢复或补偿受损的味觉功能，从而改善受这些病症影响的个体的生活质量。', ref:'电子味觉设备通过直接刺激大脑味觉中枢，有望恢复或弥补受损的味觉功能，提升患者的生活质量。', tags:["准确性","术语"] },
  { k:'seg_8_初赛_24', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Additionally, e-taste could be used in conjunction with virtual reality (VR) to create immersive multisensory experiences.', mt:'此外，电子味觉可以与虚拟现实（VR）结合使用，创造沉浸式的多感官体验。', ref:'此外，它还可以与虚拟现实结合，打造沉浸式的多感官体验。', tags:["准确性","术语"] },
  { k:'seg_8_初赛_25', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'For example, in a VR game, players might not only see and hear their environment but also taste virtual foods, adding a new layer of realism to digital worlds.', mt:'例如，在VR游戏中，玩家不仅可以看见和听见周围环境，还可以品尝虚拟食物，为数字世界增添了一层新的真实感。', ref:'例如，在一款虚拟现实游戏中，玩家不仅可以“看到”并“听到”虚拟世界，还能“尝到”其中的美食，为数字场景增添味觉层面的真实感。', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_初赛_26', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'However, the path to widespread adoption of e- taste technology is fraught with challenges.', mt:'然而，电子味觉技术的广泛应用之路充满了挑战。', ref:'然而，广泛应用电子味觉技术仍然存在诸多挑战。', tags:["准确性"] },
  { k:'seg_8_初赛_27', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'One of the primary technical hurdles is achieving precise and consistent taste simulation.', mt:'主要的技术障碍之一是实现精确且一致的味觉模拟。', ref:'技术上最主要的难题之一是实现精确、一致的味觉模拟 。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_28', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The human taste system is incredibly nuanced, with individual differences in taste perception influenced by genetics, culture, and even mood.', mt:'人类的味觉系统极其复杂，个体之间的味觉感知差异受到遗传、文化甚至情绪的影响。', ref:'人类味觉系统极其细腻，不同个体之间的味觉感知受基因、文化乃至情绪影响而存在巨大差异。', tags:["准确性"] },
  { k:'seg_8_初赛_29', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Replicating this variability in a controlled manner requires sophisticated algorithms and a deep understanding of neurobiology.', mt:'以可控的方式复制这种变异性需要复杂的算法和对神经生物学的深入理解。', ref:'要在可控条件下再现这种差异性，需要极其复杂的算法以及对神经生物学的深入理解。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_30', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Furthermore, ensuring the safety and comfort of neural stimulation methods is paramount, as improper use could lead to adverse effects such as headaches, dizziness, or even long-term neural damage.', mt:'此外，确保神经刺激方法的安全性和舒适性至关重要， 因为使用不当可能导致头痛、头晕甚至长期的神经损伤等不良反应。', ref:'此外，确保神经刺激方式的安全性与舒适性至关重要， 操作不当可能引发头痛、眩晕，甚至长期神经损伤。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_31', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Ethical considerations also loom large in the development of e-taste technology.', mt:'伦理问题在电子味觉技术的发展中也显得尤为重要。', ref:'与此同时，在电子味觉技术的发展过程中，伦理问题也日益突出。', tags:["准确性","风格"] },
  { k:'seg_8_初赛_32', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The ability to manipulate taste perception raises questions about consent and autonomy, particularly in scenarios where e-taste might be used to alter food preferences or consumption habits without the user’s full understanding. Privacy concerns are another issue, as e-taste devices could potentially collect sensitive data about users’ eating habits, preferences, and even health conditions. Ensuring that this data is handled responsibly and transparently will be crucial to building public trust in the technology.', mt:'操纵味觉感知的能力引发了关于同意和自主性的问题， 特别是在电子味觉可能被用于在用户不完全理解的情况下改变食物偏好或消费习惯的场景中。 隐私问题是另一个问题，因为电子味觉设备可能会收集有关用户饮食习惯、偏好甚至健康状况的敏感数据。 确保这些数据以负责任和透明的方式处理，对于建立公众对该技术的信任至关重要。', ref:'操控味觉感知的能力引发了有关知情同意和个人自主权的问题，尤其在用户未充分了解的情况下改变其食物偏好或饮食习惯时，这一问题尤为突出。 隐私问题也备受关注，因为电子味觉设备可能收集关于用户饮食习惯、口味偏好乃至健康状况的敏感数据。 因此，数据处理的透明度和安全性或将成为赢得公众信任的关键。', tags:["准确性","术语","风格"] },
  { k:'seg_8_初赛_33', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Privacy concerns are another issue, as e-taste devices could potentially collect sensitive data about users’ eating habits, preferences, and even health conditions.', mt:'隐私问题是另一个问题，因为电子味觉设备可能会收集有关用户饮食习惯、偏好甚至健康状况的敏感数据。', ref:'隐私问题也备受关注，因为电子味觉设备可能收集关于用户饮食习惯、口味偏好乃至健康状况的敏感数据。', tags:["准确性","风格"] },
  { k:'seg_8_初赛_34', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Ensuring that this data is handled responsibly and transparently will be crucial to building public trust in the technology.', mt:'确保这些数据以负责任和透明的方式处理，对于建立公众对该技术的信任至关重要。', ref:'因此，数据处理的透明度和安全性或将成为赢得公众信任的关键。', tags:["准确性"] },
  { k:'seg_8_初赛_35', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Moreover, there is the risk of over-reliance on artificial taste experiences, which could diminish the appreciation for natural flavors and traditional culinary practices.', mt:'此外，还存在过度依赖人工味觉体验的风险，这可能会削弱对天然风味和传统烹饪实践的欣赏。', ref:'此外，过度依赖人工味觉体验也可能削弱人们对自然风味和传统烹饪的欣赏。', tags:["准确性"] },
  { k:'seg_8_初赛_36', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'As e-taste becomes more sophisticated, it may blur the lines between real and artificial, leading to philosophical debates about the authenticity of sensory experiences.', mt:'随着电子味觉变得更加复杂，它可能会模糊真实与人工之间的界限，从而引发关于感官体验真实性的哲学辩论 。', ref:'随着电子味觉日益先进，真实与人工之间的界限可能会日渐模糊，进而引发关于感官体验真实性的哲学争论。', tags:["准确性","风格"] },
  { k:'seg_8_初赛_37', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Will a digitally simulated taste ever truly match the richness of a naturally grown ingredient?', mt:'数字模拟的味觉是否真的能与天然食材的丰富性相媲美？', ref:'数字模拟出的味道是否真能与天然食材的丰富性相媲美？', tags:["准确性"] },
  { k:'seg_8_初赛_38', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'And if it does, what does that mean for the future of food production and consumption?', mt:'如果能够做到，这对未来的食品生产和消费意味着什么？', ref:'如果可以，那我们未来的食物生产和消费方式又将何去何从？', tags:["准确性"] },
  { k:'seg_8_初赛_39', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Despite these challenges, the momentum behind e- taste technology is undeniable.', mt:'尽管存在这些挑战，电子味觉技术的势头不可否认。', ref:'尽管面临这些挑战，电子味觉技术的发展势头不可小觑 。', tags:["准确性"] },
  { k:'seg_8_初赛_40', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Major tech companies and startups alike are investing heavily in research and development, with some prototypes already entering the consumer market.', mt:'型科技公司和初创企业都在大力投资研发，一些原型已经进入消费市场。', ref:'多家大型科技公司与初创企业正积极投入研发，部分原型产品已进入消费市场。', tags:["准确性"] },
  { k:'seg_8_初赛_41', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'For instance, a Japanese company recently unveiled a “taste display” that uses ion electrophoresis to stimulate the tongue, creating basic taste sensations.', mt:'例如，一家日本公司最近推出了一种“味觉显示器”， 它使用离子电泳来刺激舌头，产生基本的味觉感受。', ref:'例如，一家日本公司最近发布了一款“味觉显示器”， 通过离子电泳刺激舌头，营造基础味觉感受。', tags:["准确性"] },
  { k:'seg_8_初赛_42', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'While still rudimentary, such innovations signal a growing interest in bringing e-taste to the masses.', mt:'虽然仍处于初级阶段，但此类创新表明人们对将电子味觉推向大众的兴趣日益增长。', ref:'虽然目前仍较为原始，但这些技术创新表明，电子味觉正逐步走向大众市场。', tags:["准确性","语言规范","风格"] },
  { k:'seg_8_初赛_43', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Looking ahead, the future of e-taste is likely to be shaped by its integration with other emerging technologies.', mt:'展望未来，电子味觉的发展可能会受到其与其他新兴技术整合的影响。', ref:'展望未来，电子味觉技术可能将与其他新兴技术深度融合。', tags:["准确性"] },
  { k:'seg_8_初赛_44', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The convergence of e-taste with augmented reality (AR), for example, could lead to “augmented dining” experiences, where digital overlays enhance the flavor of physical foods in real time.', mt:'例如，电子味觉与增强现实（AR）的结合可能会带来“ 增强用餐”体验，其中数字叠加实时增强物理食物的风味。', ref:'例如，将电子味觉与增强现实（AR）融合，可实现“增强用餐”体验，即通过数字风味实时叠加于真实食物上，提升味觉感受。', tags:["准确性","语言规范"] },
  { k:'seg_8_初赛_45', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Similarly, pairing e-taste with generative AI could enable the creation of entirely new flavors that have never been experienced before, pushing the boundaries of culinary creativity.', mt:'同样，将电子味觉与生成式AI结合，可能会创造出前所未有的全新风味，推动烹饪创意的边界。', ref:'再如，与生成式人工智能配对，甚至可能创造出前所未有的全新风味，突破传统烹饪创意的边界。', tags:["准确性","术语","风格"] },
  { k:'seg_8_初赛_46', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'As we stand on the brink of this taste revolution, it is clear that e-taste technology has the potential to redefine our relationship with food and flavor.', mt:'当我们站在这场味觉革命的门槛上时，很明显，电子味觉技术有潜力重新定义我们与食物和风味的关系。', ref:'面对当下这场味觉革命，电子味觉显然有望重塑人类与食物、与味道之间的关系。', tags:["准确性"] },
  { k:'seg_8_初赛_47', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Whether it will be embraced as a tool for enhancing human experience or viewed with skepticism remains to be seen.', mt:'它是否会被视为增强人类体验的工具，还是会受到怀疑，仍有待观察。', ref:'它究竟会成为增强人类感官体验的利器，还是被公众质疑的科技手段？', tags:["准确性","风格"] },
  { k:'seg_8_初赛_48', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'What is certain, however, is that e-taste is not just a fleeting trend—it is a glimpse into the future of sensory technology, where the digital and the physical converge in ways previously unimaginable.', mt:'然而，可以肯定的是，电子味觉不仅仅是一个短暂的趋势——它是对未来感官技术的一瞥，在这个未来中，数字与物理以前所未有的方式融合。', ref:'答案尚未可知。但可以肯定的是，电子味觉绝非昙花一现，而是感官科技未来的预演，在数字与现实之间搭建起前所未有的桥梁。', tags:["准确性"] }
];
